def _prewarm_libxml2() -> None:
    """P7.6d: libxml2 frueh initialisieren (SEGV-Fix).

    Verhindert eine Race-Condition zwischen GTK/librsvg (SVG-Icons,
    QFileDialog) und QtWebEngine. Beide laden libxml2 und rufen
    xmlInitParser() parallel auf, was zu SEGV fuehren kann.
    Idempotent; no-op falls libxml2 fehlt.
    """
    try:
        import ctypes
        ctypes.CDLL("libxml2.so.2").xmlInitParser()
    except (OSError, AttributeError):
        pass


_prewarm_libxml2()


def _ensure_secure_config_dirs() -> list[str]:
    """P7.7: AppKonstanten.*_DIR mit Mode 0o700 anlegen bzw. korrigieren.

    Best-effort, silent. Nur Verzeichnisse, die dem aktuellen User
    gehoeren werden angepasst (root-owned Leichen bleiben unberuehrt).
    Rueckgabe: Liste von Problem-Strings (leer wenn alles OK).
    """
    problems: list[str] = []
    names = (
        "KONFIG_DIR", "LOG_DIR", "REPORT_DIR", "CAPTURE_DIR",
        "EXPORT_DIR", "TEMP_DIR", "BACKUP_DIR", "CACHE_DIR",
        "WORDLIST_DIR", "PLUGIN_DIR", "PROJECTS_DIR", "MAP_TILE_DIR",
    )
    try:
        uid = os.getuid() if hasattr(os, "getuid") else -1
    except (OSError, AttributeError):
        uid = -1
    for name in names:
        d = getattr(AppKonstanten, name, None)
        if d is None:
            continue
        p = Path(d)
        try:
            if not p.exists():
                p.mkdir(parents=True, exist_ok=True, mode=0o700)
            if not p.is_dir():
                problems.append(name + ": kein Verzeichnis")
                continue
            try:
                st = p.stat()
            except OSError as e:
                problems.append(name + ": stat: " + str(e))
                continue
            if uid != -1 and st.st_uid != uid:
                # Fremd-Owner (z. B. root-Leiche) -> nicht anfassen
                continue
            mode = st.st_mode & 0o777
            if mode != 0o700:
                try:
                    os.chmod(p, 0o700)
                except OSError as e:
                    problems.append(name + ": chmod: " + str(e))
        except OSError as e:
            problems.append(name + ": " + str(e))
    return problems


