def apply_arch_fixes() -> None:
    """Arch-Linux/X11-Fixes für Qt6.

    Verhindert Abstürze unter sudo/Wayland durch:
    - DISPLAY-Fallback (:0, :1, …)
    - XAUTHORITY-Suche (User, SUDO_USER, gdm, lightdm)
    - Software-Rendering (bereits oben gesetzt, NICHT überschreiben)
    - Deaktivierte Qt-QPA-Warnungen
    """
    os.environ["QT_QPA_PLATFORM"] = "xcb"
    os.environ["QT_AUTO_SCREEN_SCALE_FACTOR"] = "0"
    os.environ["QT_SCALE_FACTOR"] = "1"
    os.environ["QT_XCB_NO_MITSHM"] = "1"
    os.environ["QT_LOGGING_RULES"] = "qt.qpa.*=false"

    display = os.environ.get("DISPLAY")
    if not display:
        for d in (":0", ":1", ":0.0", ":1.0"):
            os.environ["DISPLAY"] = d
            print(f"[System] Setting DISPLAY to: {d}")
            break

    sudo_user = os.environ.get("SUDO_USER")
    current_user = os.environ.get("USER") or os.environ.get("LOGNAME")
    xauth_paths: list[str] = []

    if sudo_user:
        xauth_paths.append(f"/home/{sudo_user}/.Xauthority")
        xauth_paths.append("/run/user/1000/gdm/Xauthority")
    if current_user:
        xauth_paths.append(f"/home/{current_user}/.Xauthority")
        xauth_paths.append(os.path.expanduser("~/.Xauthority"))
    xauth_paths.extend(
        [
            "/run/user/1000/.Xauthority",
            "/var/run/lightdm/root/:0",
            "/root/.Xauthority",
            "/tmp/.Xauthority",
        ]
    )

    xauth_found = False
    for path in xauth_paths:
        if os.path.exists(path):
            os.environ["XAUTHORITY"] = path
            xauth_found = True
            print(f"[System] XAUTHORITY: {path}")
            break
    if not xauth_found:
        print("[System] XAUTHORITY: Not found (using default)")

    print(f"[System] DISPLAY: {os.environ.get('DISPLAY')}")
    print(f"[System] QT_QPA_PLATFORM: {os.environ.get('QT_QPA_PLATFORM')}")


# v37-R34 P65a: zentraler GUI-Main-Window-Lookup (vorher 14x dupliziert)
def _find_gui_main_window():
    """Sucht die WLANUltimateGUI in der QApplication.

    Nur Top-Level-Widgets mit 'interface_manager'. SelfTestTab
    behaelt seine eigene _find_gui-Variante.
    """
    try:
        app = QApplication.instance()
        if not app:
            return None
        for w in app.topLevelWidgets():
            if hasattr(w, "interface_manager"):
                return w
    except (AttributeError, RuntimeError):
        pass
    return None


# v37-R34 P65b: HTML-Basic-Escape (vorher 6x dupliziert)
def _html_esc_basic(s):
    """Escaped &, <, > fuer HTML. Laesst " unangetastet.

    Fuer Attributwerte mit " die erweiterte Variante in
    HtmlReportGenerator._esc nutzen.
    """
    return (
        str(s or "")
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
    )


# v37-R34 P65f: Signal-Emit mit Fehlerschutz (vorher 2x dupliziert)
def _safe_emit_signal(logger, signal, *args) -> None:
    """signal.emit(*args) mit Debug-Log statt Crash.

    RuntimeError tritt auf, wenn das QObject-Thread-Affinity nicht
    stimmt; TypeError bei Argument-Mismatch; AttributeError wenn das
    Signal-Objekt beschaedigt ist. Alles landet im Debug-Log.
    """
    try:
        signal.emit(*args)
    except (RuntimeError, TypeError, AttributeError) as exc:
        try:
            logger.debug(f"Signal-Emit: {exc}")
        except (AttributeError, RuntimeError):
            pass


class OllamaClient:
    """Robuster HTTP-Client für die Ollama-API."""

    def __init__(
        self,
        host: str = "http://192.168.6.99:11434",
        timeout: int = 30,
        max_retries: int = 2,
        retry_delay: float = 1.0,
        debug: bool = False,
        user_agent: str = "WLAN-Security-Suite/9.0",
    ) -> None:
        host = host.rstrip("/")

        if ":3000" in host:
            self._openwebui_url: str | None = host
            self._is_openwebui = True
        else:
            self._openwebui_url = None
            self._is_openwebui = False

        self.host = host
        self.timeout = timeout
        self.max_retries = max_retries
        self.retry_delay = retry_delay
        self.user_agent = user_agent

        self._logger = logging.getLogger(f"{__name__}.OllamaClient")
        if debug:
            self._logger.setLevel(logging.DEBUG)

        self._available = REQUESTS_AVAILABLE
        self._session: Any = None
        self._consecutive_failures = 0
        self._max_consecutive_failures = 3

        if not self._available:
            self._logger.warning(
                "Requests-Bibliothek nicht installiert. "
                "Ollama-Funktionen deaktiviert. "
                "Install: pip install requests"
            )
        else:
            self._session = requests.Session()
            self._session.headers.update({"User-Agent": self.user_agent})

    def _build_url(self, endpoint: str) -> str:
        """Baut vollständige URL inkl. OpenWebUI-Prefix."""
        prefix = "/ollama" if self._is_openwebui else ""
        return f"{self.host}{prefix}{endpoint}"

    def _request_with_retry(
        self,
        method: str,
        endpoint: str,
        json_data: dict[str, Any] | None = None,
        stream: bool = False,
        **kwargs: Any,
    ) -> Any | None:
        """HTTP-Anfrage mit Retry + Circuit-Breaker."""
        if not self._available or self._session is None:
            return None

        if self._consecutive_failures >= self._max_consecutive_failures:
            self._logger.debug(
                "Ollama-Client deaktiviert nach %d Fehlern.",
                self._consecutive_failures,
            )
            return None

        url = self._build_url(endpoint)
        attempt = 0

        while attempt <= self.max_retries:
            try:
                self._logger.debug(
                    "Request: %s %s (attempt %d)", method, url, attempt + 1
                )
                mu = method.upper()
                if mu == "GET":
                    resp = self._session.get(url, timeout=self.timeout, **kwargs)
                elif mu == "POST":
                    if stream:
                        resp = self._session.post(
                            url,
                            json=json_data,
                            stream=True,
                            timeout=self.timeout,
                            **kwargs,
                        )
                    else:
                        resp = self._session.post(
                            url,
                            json=json_data,
                            timeout=self.timeout,
                            **kwargs,
                        )
                elif mu == "DELETE":
                    resp = self._session.delete(
                        url,
                        json=json_data,
                        timeout=self.timeout,
                        **kwargs,
                    )
                else:
                    raise ValueError(f"Unsupported method: {method}")

                resp.raise_for_status()
                self._logger.debug("Request succeeded (status %d)", resp.status_code)
                self._consecutive_failures = 0
                return resp

            except requests.exceptions.ConnectionError as e:
                self._logger.warning("Connection error: %s", e)
            except requests.exceptions.Timeout as e:
                self._logger.warning("Timeout: %s", e)
            except requests.exceptions.RequestException as e:
                self._logger.error("Request failed (kein Retry): %s", e)
                break
            except (ValueError, AttributeError) as e:
                self._logger.exception("Programmierfehler: %s", e)
                break

            attempt += 1
            if attempt <= self.max_retries:
                delay = self.retry_delay * (2 ** (attempt - 1))
                self._logger.debug(
                    "Retry %d/%d after %.1fs",
                    attempt,
                    self.max_retries,
                    delay,
                )
                time.sleep(delay)

        self._consecutive_failures += 1
        if self._consecutive_failures >= self._max_consecutive_failures:
            self._logger.info(
                "Ollama-Server nicht erreichbar — Client deaktiviert "
                "nach %d Fehlversuchen.",
                self._consecutive_failures,
            )
        return None

    def get_models(self) -> list[str]:
        """Liste der lokal verfügbaren Modellnamen."""
        if not self._available:
            return []
        resp = self._request_with_retry("GET", "/api/tags")
        if resp is None:
            return []
        try:
            data = resp.json()
            return [m.get("name", "") for m in data.get("models", []) if m.get("name")]
        except (json.JSONDecodeError, AttributeError, KeyError) as e:
            self._logger.error("Fehler beim Parsen der Modelliste: %s", e)
            return []

    def get_model_details(self, model_name: str) -> dict[str, Any] | None:
        """Detaillierte Informationen zu einem Modell."""
        if not self._available:
            return None
        resp = self._request_with_retry(
            "POST", "/api/show", json_data={"model": model_name}
        )
        if resp is None:
            return None
        try:
            return resp.json()
        except (json.JSONDecodeError, AttributeError) as e:
            self._logger.error("Fehler beim Parsen der Modelldetails: %s", e)
            return None

    def pull_model(
        self,
        model_name: str,
        callback: Callable[[dict[str, Any]], None] | None = None,
        timeout: int | None = None,
    ) -> bool:
        """Lädt ein Modell von der Registry (blockierend, streaming)."""
        if not self._available or self._session is None:
            return False
        if timeout is None:
            timeout = max(self.timeout * 5, 120)

        url = self._build_url("/api/pull")
        payload = {"model": model_name, "stream": True}

        try:
            with self._session.post(
                url, json=payload, stream=True, timeout=timeout
            ) as resp:
                resp.raise_for_status()
                for line in resp.iter_lines():
                    if not line:
                        continue
                    try:
                        data = json.loads(line.decode("utf-8"))
                    except (json.JSONDecodeError, UnicodeDecodeError):
                        continue
                    if callback:
                        callback(data)
                    if data.get("status") == "success":
                        return True
                    if data.get("error"):
                        self._logger.error("Pull error: %s", data["error"])
                        return False
        except requests.exceptions.RequestException as e:
            self._logger.error("Pull failed: %s", e)
            return False
        return False

    def delete_model(self, model_name: str) -> bool:
        """Löscht ein Modell lokal."""
        if not self._available:
            return False
        resp = self._request_with_retry(
            "DELETE",
            "/api/delete",
            json_data={"model": model_name},
        )
        return resp is not None

    def generate(
        self,
        prompt: str,
        model: str,
        temperature: float = 0.7,
        num_predict: int = 1024,
        repeat_penalty: float = 1.1,
        top_k: int = 40,
        top_p: float = 0.9,
        stream: bool = False,
        on_token: Callable[[str], None] | None = None,
        **kwargs: Any,
    ) -> str | None:
        """Generiert eine Antwort für einen Prompt.

        Args:
            on_token: Optionaler Callback, wird pro Stream-Chunk
                aufgerufen. Fehler im Callback werden geloggt,
                blockieren aber nicht den Stream.
        """
        if not self._available or self._session is None:
            return None

        payload: dict[str, Any] = {
            "model": model,
            "prompt": prompt,
            "stream": stream,
            "options": {
                "temperature": temperature,
                "num_predict": num_predict,
                "repeat_penalty": repeat_penalty,
                "top_k": top_k,
                "top_p": top_p,
                **kwargs,
            },
        }

        url = self._build_url("/api/generate")

        try:
            if stream:
                full_response: list[str] = []
                with self._session.post(
                    url,
                    json=payload,
                    stream=True,
                    timeout=self.timeout,
                ) as resp:
                    resp.raise_for_status()
                    for line in resp.iter_lines():
                        if not line:
                            continue
                        try:
                            data = json.loads(line.decode("utf-8"))
                        except (
                            json.JSONDecodeError,
                            UnicodeDecodeError,
                        ):
                            continue
                        if "response" in data:
                            chunk = data["response"]
                            full_response.append(chunk)
                            if on_token is not None:
                                try:
                                    on_token(chunk)
                                except (
                                    RuntimeError,
                                    ValueError,
                                    TypeError,
                                ) as _cb_exc:
                                    self._logger.debug(
                                        "on_token-Callback fehlgeschlagen: %s",
                                        _cb_exc,
                                    )
                        if data.get("done", False):
                            break
                return "".join(full_response)

            resp = self._session.post(url, json=payload, timeout=self.timeout)
            resp.raise_for_status()
            return resp.json().get("response", "")

        except requests.exceptions.RequestException as e:
            self._logger.error("Generierungsfehler: %s", e)
            return None

    def chat(
        self,
        messages: list[dict[str, str]],
        model: str,
        temperature: float = 0.7,
        num_predict: int = 1024,
        stream: bool = False,
        **kwargs: Any,
    ) -> str | None:
        """Führt einen Chat mit Konversationsverlauf durch."""
        if not self._available or self._session is None:
            return None

        payload: dict[str, Any] = {
            "model": model,
            "messages": messages,
            "stream": stream,
            "options": {
                "temperature": temperature,
                "num_predict": num_predict,
                **kwargs,
            },
        }

        url = self._build_url("/api/chat")

        try:
            if stream:
                full_response: list[str] = []
                with self._session.post(
                    url,
                    json=payload,
                    stream=True,
                    timeout=self.timeout,
                ) as resp:
                    resp.raise_for_status()
                    for line in resp.iter_lines():
                        if not line:
                            continue
                        try:
                            data = json.loads(line.decode("utf-8"))
                        except (
                            json.JSONDecodeError,
                            UnicodeDecodeError,
                        ):
                            continue
                        msg = data.get("message") or {}
                        if "content" in msg:
                            full_response.append(msg["content"])
                        if data.get("done", False):
                            break
                return "".join(full_response)

            resp = self._session.post(url, json=payload, timeout=self.timeout)
            resp.raise_for_status()
            return resp.json().get("message", {}).get("content", "")

        except requests.exceptions.RequestException as e:
            self._logger.error("Chat-Fehler: %s", e)
            return None

    def is_available(self) -> bool:
        """Schneller Erreichbarkeits-Test."""
        if not self._available or self._session is None:
            return False
        try:
            resp = self._session.get(self._build_url("/api/tags"), timeout=5)
            return resp.status_code == 200
        except requests.exceptions.RequestException:
            return False

    def __repr__(self) -> str:
        return (
            f"<OllamaClient host={self.host} timeout={self.timeout} "
            f"available={self._available}>"
        )


