class OllamaMemory:
    """v37-R34 P52: Persistente Session-Memory fuer KI-Analysen.

    Speichert Analyse-Historie in ~/.wlan_ultimate/cache/ollama/memory.json.
    Erkennt bereits analysierte Reports (per Hash) und warnt vor
    Dupletten-Vorschlaegen.
    """

    VERSION = 1
    MAX_ENTRIES = 100
    HEAD_CHARS = 200

    @staticmethod
    def _path() -> Path:
        cache_dir = AppKonstanten.CACHE_DIR / "ollama"
        cache_dir.mkdir(parents=True, exist_ok=True)
        return cache_dir / "memory.json"

    @classmethod
    def _empty(cls) -> dict:
        return {"version": cls.VERSION, "entries": []}

    @classmethod
    def load(cls) -> list:
        """Liest Memory-Eintraege; bei Fehler leere Liste."""
        try:
            path = cls._path()
            if not path.exists():
                return []
            data = json.loads(path.read_text(encoding="utf-8"))
            if not isinstance(data, dict):
                return []
            entries = data.get("entries", [])
            if not isinstance(entries, list):
                return []
            return [e for e in entries if isinstance(e, dict)]
        except (OSError, ValueError, TypeError, KeyError):
            return []

    @classmethod
    def save(cls, entries: list) -> None:
        """Schreibt Memory; FIFO-Truncate auf MAX_ENTRIES."""
        try:
            if len(entries) > cls.MAX_ENTRIES:
                entries = entries[-cls.MAX_ENTRIES:]
            path = cls._path()
            data = {"version": cls.VERSION, "entries": entries}
            path.write_text(
                json.dumps(data, ensure_ascii=False, indent=2),
                encoding="utf-8",
            )
        except (OSError, ValueError, TypeError):
            pass

    @staticmethod
    def hash_report(text: str) -> str:
        """SHA256 des Report-Texts (normalisiert)."""
        if not text:
            return ""
        norm = " ".join(text.split())
        return hashlib.sha256(norm.encode("utf-8")).hexdigest()[:16]

    @classmethod
    def record(cls, report_hash: str, mode: str, model: str,
               result: str, applied: bool = True) -> None:
        """Speichert eine Analyse in der Memory."""
        if not report_hash:
            return
        entries = cls.load()
        entries = [
            e for e in entries
            if not (e.get("report_hash") == report_hash
                    and e.get("mode") == mode)
        ]
        result = result or ""
        entry = {
            "ts": time.time(),
            "report_hash": report_hash,
            "mode": mode,
            "model": model,
            "result_len": len(result),
            "result_head": result[: cls.HEAD_CHARS],
            "findings_count": result.count("\n- ") + result.count("\n## "),
            "applied": bool(applied),
        }
        entries.append(entry)
        cls.save(entries)

    @classmethod
    def lookup(cls, report_hash: str):
        """Findet den letzten Eintrag zu einem Report-Hash."""
        if not report_hash:
            return None
        for e in reversed(cls.load()):
            if e.get("report_hash") == report_hash:
                return e
        return None

    @classmethod
    def format_recent(cls, limit: int = 10) -> str:
        """Markdown-Block der letzten N Eintraege."""
        entries = cls.load()
        lines = ["## memory (letzte Analysen)"]
        if not entries:
            lines.append("(keine Eintraege)")
            return "\n".join(lines)
        for e in entries[-limit:]:
            ts = e.get("ts", 0)
            try:
                from datetime import datetime as _dt
                when = _dt.fromtimestamp(float(ts)).strftime("%Y-%m-%d %H:%M")
            except (ValueError, TypeError, OSError):
                when = "?"
            lines.append(
                f"  [{when}] {e.get('mode', '?')} "
                f"(model={e.get('model', '?')}, "
                f"hash={e.get('report_hash', '?')}, "
                f"applied={e.get('applied', '?')})"
            )
            head = (e.get("result_head") or "").strip().replace("\n", " ")
            if head:
                lines.append(f"      -> {head[:120]}")
        return "\n".join(lines)

    @classmethod
    def clear(cls) -> None:
        """Loescht alle Memory-Eintraege."""
        cls.save([])




def _lrv_classify_line(content: str) -> str:
    """v37-R34 P58: Klassifiziert eine Code-Zeile.

    Rueckgabe: 'definition' | 'usage/other' | 'control' | 'import'
             | 'decorator' | 'comment/empty'.
    """
    s = content.strip()
    if not s or s.startswith("#"):
        return "comment/empty"
    if s.startswith(("class ", "def ", "async def ")):
        return "definition"
    # X: TYPE = ... (Modul- oder Klassen-Level)
    if re.match(r"^[A-Za-z_]\w*\s*:\s*\w.*=", s):
        # v37-R34 P58d: Kwargs sind keine Definitionen
        if content.rstrip().endswith((",", ")", "]")):
            return "usage/other"
        return "definition"
    # X = ... (Modul-Level)
    if re.match(r"^[A-Za-z_]\w*\s*=\s*", s):
        # v37-R34 P58d: Kwargs sind keine Definitionen
        if content.rstrip().endswith((",", ")", "]")):
            return "usage/other"
        return "definition"
    # Eingerueckt: self.X: TYPE = ... / X: TYPE = ...
    if re.match(r"^\s+[A-Za-z_]\w*\s*:\s*\w.*=", content):
        return "definition"
    # Eingerueckt: self.X = ... / cls.X = ... (haeufigste Form!)
    if re.match(r"^\s+(self|cls)\.[A-Za-z_]\w*\s*(:[^=]+)?=\s*", content):
        # v37-R34 P58d: Kwargs sind keine Definitionen
        if content.rstrip().endswith((",", ")", "]")):
            return "usage/other"
        return "definition"
    # Eingerueckt: X = ... (lokale Variablen)
    if re.match(r"^\s+[A-Za-z_]\w*\s*=\s*", content):
        # v37-R34 P58c: Kwargs (NAME=...,) sind keine Definitionen
        if content.rstrip().endswith((",", ")", "]")):
            return "usage/other"
        return "definition"
    if re.match(r"^\s*(return|yield|raise|pass|continue|break)\b", s):
        return "control"
    if re.match(r"^\s*(import|from)\s+", s):
        return "import"
    if re.match(r"^\s*@\w+", s):
        return "decorator"
    return "usage/other"


def _lrv_verify_report(report: str, wfile: Path = Path("w.py")) -> tuple:
    """v37-R34 P58: Line-Reference Verification.

    Extrahiert Zeilenverweise ('Zeile N', 'Z. N', 'line N') aus dem
    KI-Report, liest die tatsaechliche Zeile aus w.py und haengt einen
    Verifikations-Anhang an.

    Rueckgabe: (verifizierter_report: str, stats: dict)
    """
    stats = {"total": 0, "verified": 0, "missing": 0, "definitions": 0}
    if not report:
        return report, stats

    patterns = (
        r"[Zz]eile\s+(\d+)",
        r"[Zz]eilen\s+(\d+)",
        r"\bZ\.\s*(\d+)",
        r"\bline\s+(\d+)",
        r"[Zz]eilennummern?\s*:?\s*(\d+)",
    )
    nums: list = []
    seen: set = set()
    for pat in patterns:
        for m in re.finditer(pat, report):
            try:
                n = int(m.group(1))
            except (ValueError, IndexError):
                continue
            if n > 0 and n not in seen:
                seen.add(n)
                nums.append(n)

    # v37-R34 P58b: Bare-Number-Listen nach "Zeilen:"/"Zeile:"-Labels
    # erkennen (KI-Format: "- 299\n- 383\n- 2956").
    list_ctx = re.compile(
        r"(?:Zeilen?|Lines?|Relevante\s+Zeilen)\**\s*:\**\s*\n"
        r"((?:\s*[-*]\s*\d+\s*\n?)+)",
        re.IGNORECASE,
    )
    for block in list_ctx.finditer(report):
        for num_m in re.finditer(r"\d+", block.group(1)):
            try:
                n = int(num_m.group(0))
            except ValueError:
                continue
            if n > 0 and n not in seen:
                seen.add(n)
                nums.append(n)

    # v37-R34 P59a: Komma-separierte Liste direkt nach "Zeilen:" bis EOL
    # (KI-Format: "**Zeilen:** 299, 3001, 3004, 3010").
    inline_ctx = re.compile(
        r"(?:Zeilen?|Lines?|Zeilennummern?)\**\s*:\**\s*"
        r"((?:\d+\s*,\s*)*\d+)",
        re.IGNORECASE,
    )
    for block in inline_ctx.finditer(report):
        for num_m in re.finditer(r"\d+", block.group(1)):
            try:
                n = int(num_m.group(0))
            except ValueError:
                continue
            if n > 0 and n not in seen:
                seen.add(n)
                nums.append(n)

    stats["total"] = len(nums)
    if not nums:
        # v37-R34 P58b: Signal, wenn KI Zeilenverweise behauptet,
        # aber Format nicht maschinenlesbar ist.
        if re.search(r"Zeilen?|Lines?", report, re.IGNORECASE):
            annex = (
                "\n---\n"
                "## Anhang: Zeilen-Verifikation (LRV, P58b)\n"
                "\n"
                "**HINWEIS:** Der Report enthaelt Zeilenverweise, aber "
                "keine maschinenlesbaren ('Zeile N' oder Liste nach "
                "'Zeilen:'). LRV konnte nichts pruefen.\n"
                "Format wuenschenswert: 'Zeile 299' direkt im Text.\n"
            )
            return report + annex, stats
        return report, stats

    try:
        src_lines = wfile.read_text(encoding="utf-8").splitlines()
    except OSError:
        return report, stats

    max_line = len(src_lines)
    annex: list = [
        "",
        "---",
        "## Anhang: Zeilen-Verifikation (LRV, P58)",
        "",
    ]
    for n in sorted(nums):
        if 1 <= n <= max_line:
            content = src_lines[n - 1].rstrip()
            kind = _lrv_classify_line(content)
            annex.append(f"- Zeile {n} [{kind}]: `{content[:120]}`")
            stats["verified"] += 1
            if kind == "definition":
                stats["definitions"] += 1
        else:
            annex.append(
                f"- Zeile {n}: (ausserhalb w.py, max {max_line})"
            )
            stats["missing"] += 1
    annex.append("")
    return report + "\n".join(annex), stats




def _enforce_consistency(report: str) -> tuple:
    """v37-R34 P59b: Entfernt Findings aus Sektion 3, die auch in Sektion 4 stehen.

    Erkennt:
      ## 3. Warnungen AKTIV ...
      ## 4. Bereits behoben ...

    Innerhalb der Sektionen werden Finding-Header nach den Mustern
    '### NAME', '**NAME**' oder '- **NAME**' erkannt. Taucht derselbe
    Name in beiden Sektionen auf, wird er in Sektion 3 durch einen
    Hinweis ersetzt. Rueckgabe: (neuer_report, n_moves).
    """
    if not report or "## 3." not in report or "## 4." not in report:
        return report, 0

    sec3_pat = re.compile(
        r"(##\s*3\.[^\n]*\n)(.*?)(?=##\s*4\.|$)",
        re.DOTALL,
    )
    sec4_pat = re.compile(
        r"(##\s*4\.[^\n]*\n)(.*?)(?=##\s*5\.|$)",
        re.DOTALL,
    )
    m3 = sec3_pat.search(report)
    m4 = sec4_pat.search(report)
    if not m3 or not m4:
        return report, 0

    sec3_body = m3.group(2)
    sec4_body = m4.group(2)

    def _extract_names(body: str) -> set:
        names: set = set()
        # ### NAME
        for m in re.finditer(r"^###\s+([A-Za-z_][\w.]*)", body, re.MULTILINE):
            names.add(m.group(1))
        # **NAME** oder **NAME:**
        for m in re.finditer(r"\*\*([A-Za-z_][\w.]*)\*\*", body):
            names.add(m.group(1))
        # - `NAME` (Backtick)
        for m in re.finditer(r"`([A-Za-z_][\w.]*)`", body):
            names.add(m.group(1))
        return names

    names3 = _extract_names(sec3_body)
    names4 = _extract_names(sec4_body)
    overlap = names3 & names4
    # Modul-Standardbegriffe ausfiltern
    overlap.discard("FAIL")
    overlap.discard("WARN")
    overlap.discard("INFO")
    if not overlap:
        return report, 0

    new3_body = sec3_body
    moved = 0
    for name in sorted(overlap):
        # Finde den Finding-Block in Sektion 3: ### NAME ... bis naechster ###
        # oder bis Ende
        block_pat = re.compile(
            rf"^###\s+{re.escape(name)}\s*\n"
            rf"(?:.*?)(?=^###\s|\Z)",
            re.MULTILINE | re.DOTALL,
        )
        if block_pat.search(new3_body):
            new3_body = block_pat.sub(
                f"### {name}\n"
                f"*(nach Sektion 4 verschoben — "
                f"Konsistenz-Regel P59b)*\n\n",
                new3_body,
                count=1,
            )
            moved += 1
            continue
        # Alternative 1: Bullet-Zeile "- **NAME**" entfernen
        bullet_pat = re.compile(
            rf"^\s*-\s*\*\*{re.escape(name)}\*\*[^\n]*\n",
            re.MULTILINE,
        )
        if bullet_pat.search(new3_body):
            new3_body = bullet_pat.sub(
                f"- **{name}**: (nach Sektion 4 verschoben)\n",
                new3_body,
                count=1,
            )
            moved += 1
            continue
        # Alternative 2: Bullet "- `NAME`" (Backtick) entfernen
        tick_pat = re.compile(
            rf"^\s*-\s*`{re.escape(name)}`[^\n]*\n",
            re.MULTILINE,
        )
        if tick_pat.search(new3_body):
            new3_body = tick_pat.sub(
                f"- `{name}`: (nach Sektion 4 verschoben)\n",
                new3_body,
                count=1,
            )
            moved += 1

    if moved == 0:
        return report, 0

    new_report = (
        report[:m3.start()]
        + m3.group(1)
        + new3_body
        + report[m3.end():]
    )
    return new_report, moved




def _check_completeness(report: str) -> tuple:
    """v37-R34 P60c: Warnt, wenn KI 'nichts gefunden' behauptet,
    aber LRV-Anhang Definitions-Zeilen zeigt, die im Report nicht
    zitiert werden.

    Rueckgabe: (neuer_report, warnung_text oder "")
    """
    if not report:
        return report, ""
    marker = "## Anhang: Zeilen-Verifikation (LRV"
    idx = report.find(marker)
    if idx < 0:
        return report, ""
    body = report[:idx]
    annex = report[idx:]

    claims = re.compile(
        r"keine\s+Definition|nicht\s+gefunden|fehlt\b|"
        r"ohne\s+Definition|nicht\s+definiert|keine\s+explizite",
        re.IGNORECASE,
    )
    if not claims.search(body):
        return report, ""

    def_lines = re.findall(
        r"- Zeile (\d+) \[definition\]: `([^`]{0,100})`",
        annex,
    )
    if not def_lines:
        return report, ""

    warn = (
        "\n---\n"
        "## COMPLETENESS-WARNUNG (P60c)\n"
        "\n"
        "Der Report behauptet, etwas fehle. Der LRV-Anhang zeigt "
        "jedoch Definitions-Zeilen, die im Report NICHT zitiert "
        "werden:\n"
        "\n"
    )
    for n, c in def_lines[:5]:
        warn += f"- Zeile {n} [definition]: `{c}`\n"
    warn += (
        "\n"
        "Bitte manuell pruefen, ob die KI diese Zeilen uebersehen hat.\n"
    )
    return report + warn, warn


class AIContextBridge:
    """v37-R34 P42b: SSOT-Inspektor fuer KI-Audits.

    Liefert einen Markdown-Block mit dem aktuellen Zustand des Skripts.
    Nur lesende Operationen. Kein Schreibzugriff, keine Shell-Ausfuehrung.
    """

    @staticmethod
    def snapshot(
        sections: list[str] | None = None,
        log_lines: int = 80,
        max_chars: int = 12000,
    ) -> str:
        """Sammelt Sektionen und gibt Markdown-Block zurueck."""
        if sections is None:
            sections = [
                "runtime",
                "config",
                "selftest",
                "tools",
                "db",
                "logs",
                "memory",
                "wfile",
            ]
        parts: list[str] = ["=== SCRIPT-CONTEXT-SNAPSHOT ==="]
        for name in sections:
            try:
                method = getattr(AIContextBridge, f"_section_{name}", None)
                if method is None:
                    parts.append(f"## {name}\n(unbekannte Sektion)")
                    continue
                if name == "logs":
                    body = method(log_lines)
                else:
                    body = method()
                if len(body) > max_chars:
                    body = body[:max_chars] + "...(gekuerzt)"
                parts.append(body)
            except (OSError, ValueError, RuntimeError, AttributeError) as exc:
                parts.append(f"## {name}\n(fehlerhaft: {exc})")
        parts.append("=== ENDE SNAPSHOT ===")
        return "\n\n".join(parts)

    @staticmethod
    def _section_runtime() -> str:
        import os
        import platform
        lines = ["## runtime"]
        lines.append(f"python: {sys.version.split()[0]}")
        lines.append(f"platform: {platform.platform()}")
        lines.append(f"cwd: {os.getcwd()}")
        lines.append(f"uid: {os.getuid() if hasattr(os, 'getuid') else '?'}")
        return "\n".join(lines)

    @staticmethod
    def _section_config() -> str:
        lines = ["## config (ai.*)"]
        try:
            km = KonfigurationsManager()
        except (OSError, ValueError, RuntimeError) as exc:
            lines.append(f"(KonfigurationsManager nicht verfuegbar: {exc})")
            return "\n".join(lines)
        for key in (
            "ollama_host",
            "ollama_model",
            "ollama_mode",
            "ollama_num_ctx",
            "ollama_max_tokens",
            "ollama_temperature",
            "ollama_timeout",
            "ollama_cache_enabled",
            "ollama_streaming",
        ):
            val = km.get(f"ai.{key}", "(nicht gesetzt)")
            lines.append(f"  ai.{key} = {val}")
        return "\n".join(lines)

    @staticmethod
    def _section_selftest() -> str:
        lines = ["## selftest"]
        fn = globals().get("run_selftest_categories")
        if fn is None:
            lines.append("(run_selftest_categories nicht verfuegbar)")
            return "\n".join(lines)
        try:
            rep = fn()
        except (OSError, ValueError, RuntimeError) as exc:
            lines.append(f"(SelfTest-Fehler: {exc})")
            return "\n".join(lines)
        try:
            lines.append(f"Aggregate: {rep.overall().value}")
            lines.append(f"Score:     {rep.score()}/100")
            lines.append(f"Summary:   {rep.summary_line()}")
            sc = rep.severity_counts()
            lines.append(
                f"Counts:    OK={sc.get('OK', 0)} "
                f"WARN={sc.get('WARN', 0)} "
                f"FAIL={sc.get('FAIL', 0)} "
                f"SKIP={sc.get('SKIP', 0)}"
            )
        except (AttributeError, KeyError, TypeError):
            pass
        return "\n".join(lines)

    @staticmethod
    def _section_tools() -> str:
        lines = ["## tools"]
        checker = globals().get("ExternalToolChecker")
        if checker is None:
            lines.append("(ExternalToolChecker nicht verfuegbar)")
            return "\n".join(lines)
        try:
            result = checker.check()
        except (OSError, ValueError, RuntimeError) as exc:
            lines.append(f"(Tool-Check-Fehler: {exc})")
            return "\n".join(lines)
        ok = sum(1 for v in result.values() if v.get("ok"))
        lines.append(f"verfuegbar: {ok}/{len(result)}")
        for name, info in sorted(result.items()):
            if not info.get("ok"):
                lines.append(f"  FEHLT: {name} - {info.get('desc', '')}")
        return "\n".join(lines)

    @staticmethod
    def _section_db() -> str:
        lines = ["## db"]
        store = globals().get("CentralStore")
        if store is None:
            lines.append("(CentralStore nicht verfuegbar)")
            return "\n".join(lines)
        try:
            stats = store().stats()
        except (OSError, ValueError, RuntimeError) as exc:
            lines.append(f"(DB-Fehler: {exc})")
            return "\n".join(lines)
        lines.append(f"path: {stats.get('path', '?')}")
        for tbl, cnt in (stats.get("tables") or {}).items():
            lines.append(f"  {tbl}: {cnt} rows")
        return "\n".join(lines)

    @staticmethod
    def _section_logs(n: int = 80) -> str:
        """v37-R34 P49: Log-Zeilen seit letzter w.py-Aenderung.

        Zeitfilter: Eintraege aelter als w.py-mtime sind historisch
        und werden in einer separaten Zeile gezaehlt (nicht gemeldet).
        Zeitstempel werden via time.mktime als Lokalzeit interpretiert.
        """
        lines = ["## logs (nach letzter w.py-Aenderung)"]
        try:
            log_path = (
                Path.home()
                / ".wlan_ultimate"
                / "logs"
                / "wlan_ultimate.log"
            )
            if not log_path.exists():
                lines.append("(Log-Datei nicht gefunden)")
                return "\n".join(lines)

            wfile_mtime = 0.0
            try:
                wfile_mtime = Path("w.py").stat().st_mtime
            except OSError:
                pass

            with log_path.open("r", encoding="utf-8", errors="replace") as fh:
                all_lines = fh.readlines()

            def _line_ts(line: str) -> float:
                """Log-Zeitstempel -> Unix-Timestamp (Lokalzeit)."""
                if len(line) < 19 or line[4] != "-":
                    return 0.0
                try:
                    import time as _time
                    return _time.mktime(
                        _time.strptime(line[:19], "%Y-%m-%d %H:%M:%S")
                    )
                except (ValueError, TypeError, OverflowError):
                    return 0.0

            recent = [
                ln for ln in all_lines
                if _line_ts(ln) >= wfile_mtime
            ]
            historical_errors = [
                ln for ln in all_lines
                if "[ERROR" in ln and 0 < _line_ts(ln) < wfile_mtime
            ]
            recent_errors = [
                ln for ln in recent if "[ERROR" in ln
            ]
            recent_warns = [
                ln for ln in recent if "[WARNING" in ln
            ]

            lines.append(
                f"Filter: nur Eintraege nach w.py-mtime "
                f"({wfile_mtime:.0f})"
            )
            lines.append(
                f"AKTUELL: ERROR={len(recent_errors)}, "
                f"WARN={len(recent_warns)}"
            )
            lines.append(
                f"HISTORISCH (aeltere ERROR): "
                f"{len(historical_errors)} - bereits behandelt, "
                f"NICHT melden"
            )
            if recent_errors:
                lines.append("--- aktuelle ERROR-Zeilen ---")
                for ln in recent_errors[-10:]:
                    lines.append(ln.rstrip())
            else:
                lines.append("(keine aktuellen ERROR-Zeilen)")
        except (OSError, ValueError) as exc:
            lines.append(f"(Log-Fehler: {exc})")
        return "\n".join(lines)

    @staticmethod
    def _section_memory() -> str:
        """v37-R34 P52: Aktuelle Session-Memory."""
        try:
            mem = globals().get("OllamaMemory")
            if mem is None:
                return "## memory\n(OllamaMemory nicht verfuegbar)"
            return mem.format_recent(limit=10)
        except (OSError, ValueError, RuntimeError, AttributeError) as exc:
            return f"## memory\n(fehlerhaft: {exc})"

    @staticmethod
    def _section_wfile() -> str:
        import ast as _ast_local
        lines = ["## wfile"]
        wpath = Path("w.py")
        if not wpath.exists():
            lines.append("(w.py nicht gefunden)")
            return "\n".join(lines)
        try:
            size = wpath.stat().st_size
            src = wpath.read_text(encoding="utf-8")
            loc = src.count("\n") + 1
            lines.append(f"size: {size:,} Bytes")
            lines.append(f"loc:  {loc:,}")
            try:
                _ast_local.parse(src)
                lines.append("ast: OK")
            except SyntaxError as exc:
                lines.append(f"ast: FEHLER - {exc}")
        except (OSError, ValueError) as exc:
            lines.append(f"(Datei-Fehler: {exc})")
        return "\n".join(lines)

    # ── Tool-Calling (P43) ──────────────────────────────────────

    _QUERY_RE = re.compile(r"<QUERY>\s*(.+?)\s*</QUERY>", re.DOTALL)
    _STRIP_CHARS = '"' + "'"

    @classmethod
    def extract_queries(cls, text: str) -> list[str]:
        """v37-R34 P43: Extrahiert <QUERY>...</QUERY>-Anfragen aus Antwort."""
        if not text:
            return []
        return [m.group(1).strip() for m in cls._QUERY_RE.finditer(text)]

    @classmethod
    def execute_query(cls, query: str, max_lines: int = 30) -> str:
        """v37-R34 P43: Fuehrt eine lesende Query aus (Whitelist)."""
        q = (query or "").strip()
        if not q:
            return "(leere Query)"

        m = re.fullmatch(r"grep\((.+)\)", q, re.DOTALL)
        if m:
            return cls._q_grep(m.group(1).strip(cls._STRIP_CHARS), max_lines)

        m = re.fullmatch(r"grep_lines\((.+?)(?:,\s*(\d+))?\)", q, re.DOTALL)
        if m:
            pattern = m.group(1).strip(cls._STRIP_CHARS)
            n = int(m.group(2)) if m.group(2) else max_lines
            return cls._q_grep(pattern, n)

        m = re.fullmatch(r"slice\(\s*(\d+)\s*,\s*(\d+)\s*\)", q)
        if m:
            return cls._q_slice(int(m.group(1)), int(m.group(2)))

        m = re.fullmatch(r"logs_tail\(\s*(\d+)\s*\)", q)
        if m:
            return cls._section_logs(int(m.group(1)))

        m = re.fullmatch(r"logs_errors\(\s*(\d+)\s*\)", q)
        if m:
            return cls._q_logs_errors(int(m.group(1)))

        m = re.fullmatch(r"count\((.+)\)", q, re.DOTALL)
        if m:
            return cls._q_count(m.group(1).strip(cls._STRIP_CHARS))

        m = re.fullmatch(r"config_get\((.+)\)", q, re.DOTALL)
        if m:
            return cls._q_config_get(m.group(1).strip(cls._STRIP_CHARS))

        return (
            f"(Unbekannte Query: {q[:80]})\n"
            "Verfuegbar: grep(PAT), grep_lines(PAT,N), slice(A,B), "
            "logs_tail(N), logs_errors(N), count(PAT), config_get(KEY)"
        )

    @staticmethod
    def _q_grep(pattern: str, max_lines: int) -> str:
        try:
            wpath = Path("w.py")
            src = wpath.read_text(encoding="utf-8")
            rx = re.compile(pattern)
        except (OSError, re.error) as exc:
            return f"(grep-Fehler: {exc})"
        hits: list[str] = []
        for i, line in enumerate(src.splitlines(), 1):
            if rx.search(line):
                hits.append(f"{i}: {line[:150]}")
                if len(hits) >= max_lines:
                    break
        if not hits:
            return f"(keine Treffer fuer {pattern})"
        return f"grep({pattern}) -> {len(hits)} Treffer\n" + "\n".join(hits)

    @staticmethod
    def _q_slice(start: int, end: int) -> str:
        try:
            lines = Path("w.py").read_text(encoding="utf-8").splitlines()
        except OSError as exc:
            return f"(slice-Fehler: {exc})"
        start = max(1, start)
        end = min(len(lines), end)
        body = "\n".join(
            f"{i}: {lines[i-1][:180]}" for i in range(start, end + 1)
        )
        return f"slice({start},{end}) -> {end - start + 1} Zeilen\n{body}"

    @staticmethod
    def _q_logs_errors(n: int) -> str:
        """v37-R34 P50: ERROR-Zeilen seit letzter w.py-Aenderung.

        Historische Eintraege (aelter als w.py-mtime) werden nur
        gezaehlt, nicht aufgelistet - sie sind bereits behandelt.
        """
        try:
            log_path = (
                Path.home() / ".wlan_ultimate" / "logs" / "wlan_ultimate.log"
            )
            with log_path.open("r", encoding="utf-8", errors="replace") as fh:
                lines = fh.readlines()
        except OSError as exc:
            return f"(logs-Fehler: {exc})"

        wfile_mtime = 0.0
        try:
            wfile_mtime = Path("w.py").stat().st_mtime
        except OSError:
            pass

        def _line_ts(line: str) -> float:
            if len(line) < 19 or line[4] != "-":
                return 0.0
            try:
                import time as _time
                return _time.mktime(
                    _time.strptime(line[:19], "%Y-%m-%d %H:%M:%S")
                )
            except (ValueError, TypeError, OverflowError):
                return 0.0

        all_errors = [ln for ln in lines if "[ERROR" in ln]
        recent_errors = [
            ln.rstrip() for ln in all_errors
            if _line_ts(ln) >= wfile_mtime
        ]
        historical = [
            ln for ln in all_errors
            if 0 < _line_ts(ln) < wfile_mtime
        ]

        tail = recent_errors[-n:] if n > 0 else recent_errors
        head = (
            f"logs_errors({n}) -> AKTUELL={len(recent_errors)}, "
            f"HISTORISCH={len(historical)} "
            f"(aeltere werden nicht gemeldet)"
        )
        if not tail:
            return head + "\n(keine aktuellen ERROR-Zeilen)"
        return head + "\n" + "\n".join(tail)

    @staticmethod
    def _q_count(pattern: str) -> str:
        try:
            src = Path("w.py").read_text(encoding="utf-8")
            rx = re.compile(pattern)
        except (OSError, re.error) as exc:
            return f"(count-Fehler: {exc})"
        cnt = sum(1 for ln in src.splitlines() if rx.search(ln))
        return f"count({pattern}) -> {cnt} Zeilen mit Treffer"

    @staticmethod
    def _q_config_get(key: str) -> str:
        try:
            km = KonfigurationsManager()
            val = km.get(key, "(nicht gesetzt)")
        except (OSError, ValueError, RuntimeError) as exc:
            return f"(config-Fehler: {exc})"
        return f"config.get({key}) -> {val}"






