@dataclass
class DeviceFingerprint:
    """Vollständiger Fingerprint eines entdeckten Geräts."""

    device_id: str
    mac: str
    device_type: str = "wlan"
    category: DeviceCategory = DeviceCategory.UNKNOWN
    category_confidence: int = 0

    first_seen: float = field(default_factory=time.time)
    last_seen: float = field(default_factory=time.time)
    sighting_count: int = 0

    signals: list[int] = field(default_factory=list)
    median_signal: int = 0
    signal_std: float = 0.0

    name: str = ""
    vendor: str = ""
    vendor_confidence: int = 0
    model: str = ""
    firmware: str = ""

    capabilities: CapabilityProfile = field(default_factory=CapabilityProfile)

    channel: int = 0
    frequency: float = 0.0
    bssid: str = ""
    hidden: bool = False

    ble_manufacturer_data: dict = field(default_factory=dict)
    ble_service_uuids: list[str] = field(default_factory=list)
    ble_appearance: int = 0
    ble_tx_power: int = 0

    iot_category: str = ""
    iot_protocols: list[str] = field(default_factory=list)

    ie_data: dict = field(default_factory=dict)
    tags: list[str] = field(default_factory=list)
    notes: str = ""

    def to_dict(self) -> dict[str, Any]:
        """JSON-safe Repräsentation."""
        d = asdict(self)
        d["category"] = self.category.value
        d["capabilities"] = asdict(self.capabilities)
        return d

    def update_signal(self, rssi: int) -> None:
        """Fügt einen RSSI-Wert hinzu und aktualisiert Statistiken."""
        try:
            s = int(rssi)
        except (TypeError, ValueError):
            return
        self.signals.append(s)
        if len(self.signals) > 100:
            self.signals = self.signals[-100:]
        self.sighting_count += 1
        self.last_seen = time.time()
        if self.signals:
            sorted_sig = sorted(self.signals)
            self.median_signal = sorted_sig[len(sorted_sig) // 2]
            avg = sum(self.signals) / len(self.signals)
            var = sum((x - avg) ** 2 for x in self.signals) / len(self.signals)
            self.signal_std = round(var**0.5, 2)


class DeviceClassifier:
    """Klassifiziert Geräte anhand IEs, BLE-Adverts und Signaturen."""

    BLE_APPEARANCE = {
        0x0000: DeviceCategory.UNKNOWN,
        0x0040: DeviceCategory.LAPTOP,  # Generic Computer
        0x0080: DeviceCategory.SMARTPHONE,  # Generic Phone
        0x00C0: DeviceCategory.WATCH,  # Generic Watch
        0x0180: DeviceCategory.WATCH,  # Sports Watch
        0x01C0: DeviceCategory.SPEAKER,  # Generic Speaker
        0x0400: DeviceCategory.TRACKER,  # Generic Tag
        0x0440: DeviceCategory.TRACKER,  # Location Tracker
        0x0480: DeviceCategory.MEDICAL,  # Medical
        0x0800: DeviceCategory.UNKNOWN,  # Generic
        0x0840: DeviceCategory.LAPTOP,  # Generic PC
        0x0880: DeviceCategory.SMARTPHONE,  # Generic Phone
        0x0941: DeviceCategory.HEADPHONES,  # Headphones
        0x0942: DeviceCategory.SPEAKER,  # Portable Audio
        0x0944: DeviceCategory.SPEAKER,  # Loudspeaker
        0x0C00: DeviceCategory.CAR,  # Vehicle
        0x0C40: DeviceCategory.CAR,  # Car
        0x1440: DeviceCategory.UNKNOWN,  # Generic
    }

    WPS_DEVICE_TYPES = {
        1: DeviceCategory.SMARTPHONE,
        2: DeviceCategory.SMARTPHONE,
        3: DeviceCategory.LAPTOP,
        4: DeviceCategory.SPEAKER,
        5: DeviceCategory.PRINTER,
        6: DeviceCategory.CAMERA,
        7: DeviceCategory.SPEAKER,
        8: DeviceCategory.UNKNOWN,
        9: DeviceCategory.UNKNOWN,
        10: DeviceCategory.UNKNOWN,
        11: DeviceCategory.IOT_DEVICE,
    }

    VENDOR_CATEGORIES = {
        "Apple, Inc.": DeviceCategory.SMARTPHONE,
        "Samsung Electronics": DeviceCategory.SMARTPHONE,
        "Xiaomi Communications": DeviceCategory.IOT_DEVICE,
        "Philips Lighting": DeviceCategory.IOT_DEVICE,
        "Sonos, Inc.": DeviceCategory.SPEAKER,
        "Nest Labs Inc.": DeviceCategory.IOT_DEVICE,
        "Amazon Technologies": DeviceCategory.SPEAKER,
        "Google, Inc.": DeviceCategory.SPEAKER,
        "Raspberry Pi Foundation": DeviceCategory.IOT_DEVICE,
        "Hewlett Packard": DeviceCategory.PRINTER,
        "Canon Inc.": DeviceCategory.PRINTER,
        "Seiko Epson": DeviceCategory.PRINTER,
    }

    @classmethod
    def classify_from_ie(
        cls,
        ie_data: dict,
        vendor: str = "",
        ssid: str = "",
    ) -> tuple[DeviceCategory, int]:
        """Klassifiziert ein WLAN-Gerät aus IE-Daten.

        Returns:
            ``(category, confidence 0-100)``
        """
        scores: dict[DeviceCategory, int] = defaultdict(int)

        # 1. Vendor-basiert
        if vendor:
            for vkey, cat in cls.VENDOR_CATEGORIES.items():
                if vkey.lower() in vendor.lower():
                    scores[cat] += 40
                    break

        # 2. WPS Device Type
        wps = ie_data.get("wps")
        if wps:
            device_name = str(wps.get("device_name", "")).lower()
            manufacturer = str(wps.get("manufacturer", "")).lower()

            if any(k in device_name for k in ("phone", "iphone", "smartphone")):
                scores[DeviceCategory.SMARTPHONE] += 50
            if any(k in device_name for k in ("camera", "cam", "ipcam")):
                scores[DeviceCategory.CAMERA] += 60
            if any(k in device_name for k in ("printer", "print")):
                scores[DeviceCategory.PRINTER] += 60
            if any(k in device_name for k in ("tv", "television", "chromecast")):
                scores[DeviceCategory.SPEAKER] += 30
            if any(k in device_name for k in ("watch", "band")):
                scores[DeviceCategory.WATCH] += 50

            if "sonos" in manufacturer:
                scores[DeviceCategory.SPEAKER] += 70
            if "philips" in manufacturer or "hue" in manufacturer:
                scores[DeviceCategory.IOT_DEVICE] += 70
            if "raspberry" in manufacturer:
                scores[DeviceCategory.IOT_DEVICE] += 60

        # 3. SSID-basiert
        ssid_l = (ssid or "").lower()
        if any(k in ssid_l for k in ("iphone", "ipad", "android", "pixel", "galaxy")):
            scores[DeviceCategory.SMARTPHONE] += 30
        if any(k in ssid_l for k in ("fritzbox", "speedport", "telekom", "router")):
            scores[DeviceCategory.WLAN_AP] += 60
        if any(k in ssid_l for k in ("hp-", "canon", "epson", "brother")):
            scores[DeviceCategory.PRINTER] += 50
        if any(k in ssid_l for k in ("hue", "wemo", "smart plug", "tplink")):
            scores[DeviceCategory.IOT_DEVICE] += 50

        if not scores:
            return DeviceCategory.WLAN_AP, 30

        best_cat = max(scores, key=lambda k: scores[k])
        confidence = min(100, scores[best_cat])
        return best_cat, confidence

    @classmethod
    def classify_from_ble(
        cls,
        name: str,
        manufacturer_data: dict,
        service_uuids: list[str],
        appearance: int,
    ) -> tuple[DeviceCategory, int]:
        """Klassifiziert ein BLE-Gerät."""
        # 1. Appearance
        if appearance in cls.BLE_APPEARANCE:
            cat = cls.BLE_APPEARANCE[appearance]
            if cat != DeviceCategory.UNKNOWN:
                return cat, 90

        # 2. Name-basiert
        name_l = (name or "").lower()
        if any(k in name_l for k in ("airpods", "buds", "headphone")):
            return DeviceCategory.HEADPHONES, 95
        if any(k in name_l for k in ("watch", "band", "fit")):
            return DeviceCategory.WATCH, 85
        if any(k in name_l for k in ("iphone", "pixel", "galaxy", "phone")):
            return DeviceCategory.SMARTPHONE, 80
        if any(k in name_l for k in ("speaker", "sound", "audio")):
            return DeviceCategory.SPEAKER, 75
        if any(k in name_l for k in ("tracker", "tag", "airtag", "tile")):
            return DeviceCategory.TRACKER, 90
        if any(k in name_l for k in ("car", "auto", "vehicle")):
            return DeviceCategory.CAR, 80
        if any(k in name_l for k in ("mi ", "xiaomi", "huawei")):
            return DeviceCategory.SMARTPHONE, 60

        # 3. Manufacturer Data
        if 0x004C in manufacturer_data:  # Apple
            return DeviceCategory.SMARTPHONE, 70
        if 0x0075 in manufacturer_data:  # Samsung
            return DeviceCategory.SMARTPHONE, 70

        # 4. Service UUIDs
        wearable_uuids = {
            "0000180d-0000-1000-8000-00805f9b34fb",
            "0000180f-0000-1000-8000-00805f9b34fb",
        }
        for u in service_uuids:
            if u.lower() in wearable_uuids:
                return DeviceCategory.WATCH, 60

        return DeviceCategory.UNKNOWN, 20


