# 19. Kismet-Parität — Log-Format, Statistiken, GPS-NMEA
# ══════════════════════════════════════════════════════════════════════
class KismetLogger:
    """Kismet-kompatibles Log-Format.

    Format::

        timestamp\ttype\tbssid\tssid\tchannel\tsignal\tencryption

    Wird von Tools wie Kismet-Reader, Wigle.net etc. erkannt.
    Schreibt drei Dateien:
    - ``*.kismet``   (Tab-separierte Netzwerk-Liste)
    - ``*.netxml``   (XML für Kismet-kompatible Reader)
    - ``*.gpsxml``   (GPS-Punkte für Kartierung)
    """

    def __init__(self, log_dir: str | Path | None = None) -> None:
        base_dir = (
            Path(log_dir) if log_dir else (Path.home() / ".wlan_ultimate" / "kismet")
        )
        try:
            base_dir.mkdir(parents=True, exist_ok=True)
            self.log_dir = base_dir
        except (OSError, PermissionError):
            self.log_dir = Path(tempfile.gettempdir()) / "wlan_kismet"
            self.log_dir.mkdir(parents=True, exist_ok=True)

        ts = datetime.now().strftime("%Y%m%d_%H%M%S")
        self.main_log = self.log_dir / f"Kismet-{ts}.kismet"
        self.netxml = self.log_dir / f"Kismet-{ts}.netxml"
        self.gpsxml = self.log_dir / f"Kismet-{ts}.gpsxml"

        self.logger = logging.getLogger("wlan_ultimate.KismetLogger")
        self._lock = threading.RLock()
        self._header_written = False
        self._netxml_header_written = False
        self._closed = False
        self._write_headers()

    def _write_headers(self) -> None:
        """Schreibt Datei-Header (Kismet-Format)."""
        try:
            with open(self.main_log, "w", encoding="utf-8") as f:
                f.write("# Kismet log v1.0 " "(WLAN Ultimate Security Suite)\n")
                f.write(
                    "# Network\tBSSID\tSSID\tChannel\tSignal\t"
                    "Encryption\tFirst\tLast\n"
                )
            with open(self.netxml, "w", encoding="utf-8") as f:
                f.write('<?xml version="1.0" encoding="UTF-8"?>\n')
                f.write(
                    '<detection-run xmlns="http://kismetwireless.net/'
                    'kismetml/1.0">\n'
                )
            self._header_written = True
            self._netxml_header_written = True
        except OSError as exc:
            self.logger.warning("Kismet-Header: %s", exc)

    def log_network(
        self,
        bssid: str,
        ssid: str,
        channel: int,
        signal: int,
        encryption: str = "",
        gps: dict[str, Any] | None = None,
    ) -> None:
        """Schreibt einen Netzwerk-Eintrag."""
        with self._lock:
            try:
                now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                line = "\t".join(
                    [
                        "NET",
                        str(bssid),
                        str(ssid or ""),
                        str(channel),
                        str(signal),
                        str(encryption),
                        now,
                        now,
                    ]
                )
                with open(self.main_log, "a", encoding="utf-8") as f:
                    f.write(line + "\n")
            except OSError as exc:
                self.logger.debug("Kismet write: %s", exc)

    def log_gps(
        self,
        lat: float,
        lon: float,
        alt: float,
        speed: float,
        heading: float,
    ) -> None:
        """Schreibt einen GPS-Punkt."""
        with self._lock:
            try:
                now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                with open(self.gpsxml, "a", encoding="utf-8") as f:
                    f.write(
                        f'<gps-point time="{now}" lat="{lat}" '
                        f'lon="{lon}" alt="{alt}" speed="{speed}" '
                        f'heading="{heading}"/>\n'
                    )
            except OSError as exc:
                self.logger.debug("Kismet GPS write: %s", exc)

    def write_network_detail(
        self,
        bssid: str,
        ssid: str,
        channel: int,
        encryption: str,
        signal: int,
    ) -> None:
        """Schreibt detaillierten Netzwerk-Block ins netxml."""
        with self._lock:
            if not self._netxml_header_written:
                return
            try:
                with open(self.netxml, "a", encoding="utf-8") as f:
                    f.write('<wireless-network type="infrastructure">\n')
                    f.write(f"  <BSSID>{bssid}</BSSID>\n")
                    f.write(f'  <SSID>{ssid or ""}</SSID>\n')
                    f.write(f"  <channel>{channel}</channel>\n")
                    f.write(f"  <encryption>{encryption}</encryption>\n")
                    f.write(f"  <signal_dbm>{signal}</signal_dbm>\n")
                    f.write("</wireless-network>\n")
            except OSError as exc:
                self.logger.debug("Kismet netxml write: %s", exc)

    def close(self) -> None:
        """Schließt das netxml-Dokument sauber."""
        if self._closed:
            return
        with self._lock:
            try:
                with open(self.netxml, "a", encoding="utf-8") as f:
                    f.write("</detection-run>\n")
                self._closed = True
            except OSError as exc:
                self.logger.debug("Kismet close: %s", exc)

    def get_paths(self) -> dict[str, str]:
        """Liefert alle Pfade als Dict."""
        return {
            "kismet": str(self.main_log),
            "netxml": str(self.netxml),
            "gpsxml": str(self.gpsxml),
        }

    def __enter__(self) -> KismetLogger:
        return self

    def __exit__(self, *args: Any) -> None:
        self.close()


class ChannelStats:
    """Kanal-Statistiken mit Zeitverlauf.

    Verfolgt pro Kanal: Pakete, Netzwerke, Signal-Statistik.
    Thread-safe.
    """

    def __init__(self) -> None:
        self._lock = threading.RLock()
        self._per_channel: dict[int, dict[str, Any]] = defaultdict(
            lambda: {
                "packets": 0,
                "networks": set(),
                "signal_sum": 0,
                "signal_count": 0,
                "signal_min": 0,
                "signal_max": -100,
                "first_seen": 0.0,
                "last_seen": 0.0,
            }
        )

    def record(
        self,
        channel: int | None,
        bssid: str | None = None,
        signal: int | None = None,
    ) -> None:
        """Erfasst einen Paketempfang auf einem Kanal."""
        if not channel:
            return
        with self._lock:
            e = self._per_channel[channel]
            e["packets"] += 1
            now = time.time()
            if not e["first_seen"]:
                e["first_seen"] = now
            e["last_seen"] = now
            if bssid:
                e["networks"].add(str(bssid).lower())
            if signal is not None:
                try:
                    s = int(signal)
                    e["signal_sum"] += s
                    e["signal_count"] += 1
                    if s < e["signal_min"] or e["signal_min"] == 0:
                        e["signal_min"] = s
                    e["signal_max"] = max(e["signal_max"], s)
                except (ValueError, TypeError):
                    pass

    def summary(self) -> list[dict[str, Any]]:
        """Zusammenfassung pro Kanal (sortiert)."""
        with self._lock:
            out: list[dict[str, Any]] = []
            for ch, e in sorted(self._per_channel.items()):
                if not e["packets"]:
                    continue
                avg = e["signal_sum"] / e["signal_count"] if e["signal_count"] else 0
                out.append(
                    {
                        "channel": ch,
                        "packets": e["packets"],
                        "networks": len(e["networks"]),
                        "signal_avg": round(avg, 1),
                        "signal_min": e["signal_min"],
                        "signal_max": e["signal_max"],
                        "duration_s": round(e["last_seen"] - e["first_seen"], 1),
                    }
                )
            return out

    def top_channels(self, n: int = 5) -> list[dict[str, Any]]:
        """Top-N Kanäle nach Paketanzahl."""
        s = self.summary()
        s.sort(key=lambda x: x["packets"], reverse=True)
        return s[:n]

    def clear(self) -> None:
        """Leert die Statistik."""
        with self._lock:
            self._per_channel.clear()

    def total_packets(self) -> int:
        """Gesamtpakete über alle Kanäle."""
        with self._lock:
            return sum(e["packets"] for e in self._per_channel.values())


class NmeaTracker:
    """NMEA-Parser für GPS-Tracking.

    Nutzt ``pynmea2`` falls verfügbar, sonst eigenen Parser.
    Unterstützt $GPGGA (Position) und $GPRMC (Geschwindigkeit).
    Thread-safe.
    """

    def __init__(self, logger: logging.Logger | None = None) -> None:
        self.logger = logger or logging.getLogger("wlan_ultimate.NmeaTracker")
        self.lat: float = 0.0
        self.lon: float = 0.0
        self.alt: float = 0.0
        self.speed_kmh: float = 0.0
        self.heading: float = 0.0
        self.sats: int = 0
        self.hdop: float = 99.9
        self.fix: bool = False
        self.utc_time: str = ""
        self._lock = threading.RLock()
        self._lines_ok: int = 0
        self._lines_err: int = 0

    def parse_line(self, line: str) -> bool:
        """Parst eine NMEA-Zeile (z. B. ``$GPGGA,...``).

        Returns:
            True, wenn die Zeile erfolgreich geparst wurde.
        """
        if not line or not isinstance(line, str):
            self._lines_err += 1
            return False
        if not line.startswith("$"):
            self._lines_err += 1
            return False
        try:
            if PYNMEA2_AVAILABLE:
                ok = self._parse_pynmea(line)
            else:
                ok = self._parse_manual(line)
            if ok:
                self._lines_ok += 1
            else:
                self._lines_err += 1
            return ok
        except (ValueError, AttributeError, IndexError):
            self._lines_err += 1
            return False

    def _parse_pynmea(self, line: str) -> bool:
        """Parser via pynmea2-Bibliothek."""
        try:
            msg = pynmea2.parse(line)
        except (ValueError, AttributeError):
            return False
        with self._lock:
            if isinstance(msg, pynmea2.GGA):
                try:
                    self.lat = float(msg.latitude)
                    self.lon = float(msg.longitude)
                    self.alt = float(msg.altitude or 0.0)
                    self.sats = int(msg.num_sats or 0)
                    self.hdop = float(msg.horizontal_dil or 99.9)
                    self.fix = int(msg.gps_qual or 0) > 0
                    self.utc_time = str(msg.timestamp or "")
                    return True
                except (ValueError, AttributeError):
                    return False
            if isinstance(msg, pynmea2.RMC):
                try:
                    self.lat = float(msg.latitude)
                    self.lon = float(msg.longitude)
                    spd = float(msg.spd_over_grnd or 0.0)
                    self.speed_kmh = spd * 1.852
                    self.heading = float(msg.true_course or 0.0)
                    return True
                except (ValueError, AttributeError):
                    return False
        return False

    def _parse_manual(self, line: str) -> bool:
        """Fallback-Parser ohne pynmea2."""
        parts = line.split(",")
        if line.startswith("$GPGGA") and len(parts) >= 10:
            try:
                if parts[2] and parts[4]:
                    lat = float(parts[2][:2]) + float(parts[2][2:]) / 60.0
                    if parts[3] == "S":
                        lat = -lat
                    lon = float(parts[4][:3]) + float(parts[4][3:]) / 60.0
                    if parts[5] == "W":
                        lon = -lon
                    with self._lock:
                        self.lat, self.lon = lat, lon
                        self.alt = float(parts[9]) if parts[9] else 0.0
                        self.sats = int(parts[7]) if parts[7] else 0
                        self.hdop = float(parts[8]) if parts[8] else 99.9
                        self.fix = int(parts[6] or 0) > 0
                        self.utc_time = parts[1]
                    return True
            except (ValueError, IndexError):
                return False
        return False

    def get_position(self) -> tuple[float, float, float]:
        """Aktuelle Position als ``(lat, lon, alt)``."""
        with self._lock:
            return (self.lat, self.lon, self.alt)

    def has_fix(self) -> bool:
        """True, wenn GPS-Fix vorhanden."""
        with self._lock:
            return self.fix

    def to_dict(self) -> dict[str, Any]:
        """JSON-safe Repräsentation."""
        with self._lock:
            return {
                "lat": self.lat,
                "lon": self.lon,
                "alt": self.alt,
                "speed_kmh": self.speed_kmh,
                "heading": self.heading,
                "sats": self.sats,
                "hdop": self.hdop,
                "fix": self.fix,
                "utc_time": self.utc_time,
                "lines_ok": self._lines_ok,
                "lines_err": self._lines_err,
            }


class CrackPipeline:
    """Aircrack-ng-kompatible Crack-Pipeline.

    Pipeline::

        capture → convert → crack → result

    Nutzt externe Tools (``hcxpcapngtool``, ``hashcat``).
    """

    def __init__(self, logger: logging.Logger | None = None) -> None:
        self.logger = logger or logging.getLogger("wlan_ultimate.CrackPipeline")
        self._active: dict[str, Any] = {}

    def _get_runner(self) -> Any | None:
        """Lazy-Lookup des CommandRunner (Import-Reihenfolge)."""
        return globals().get("CommandRunner")

    def convert_pcap(
        self, pcap_path: str | Path, out_format: str = "22000"
    ) -> tuple[Path | None, str]:
        """Konvertiert ``.cap``/``.pcapng`` zu ``.22000`` (hashcat).

        Args:
            pcap_path: Pfad zur Capture-Datei
            out_format: Ziel-Format (``"22000"`` oder ``"hccapx"``)

        Returns:
            ``(pfad, status_meldung)``
        """
        pcap_path = Path(pcap_path)
        if not pcap_path.exists():
            return None, "Datei fehlt"

        if out_format == "22000":
            out = pcap_path.with_suffix(".22000")
        elif out_format == "hccapx":
            out = pcap_path.with_suffix(".hccapx")
        else:
            return None, "Unbekanntes Format"

        runner = self._get_runner()
        tool = "hcxpcapngtool"

        if runner is not None:
            try:
                rc, _, _ = runner.run(
                    ["which", tool],
                    subsystem="crack",
                    soft_fail=True,
                    timeout=3,
                )
                if rc != 0:
                    return None, f"{tool} nicht gefunden"
            except (
                FileNotFoundError,
                subprocess.SubprocessError,
                OSError,
            ):
                return None, f"{tool} nicht ausführbar"
        else:
            if shutil.which(tool) is None:
                return None, f"{tool} nicht gefunden"

        if runner is not None:
            try:
                runner.run(
                    [tool, "-o", str(out), str(pcap_path)],
                    subsystem="crack",
                    tag="convert",
                    soft_fail=True,
                    timeout=60,
                )
            except (
                FileNotFoundError,
                subprocess.SubprocessError,
                OSError,
            ) as e:
                return None, f"Konvertierung fehlgeschlagen: {e}"

        if out.exists() and out.stat().st_size > 0:
            return out, "OK"
        return None, "Konvertierung fehlgeschlagen (leeres Output)"

    def crack_with_hashcat(
        self,
        hash_file: str | Path,
        wordlist: str | Path,
        hash_mode: str = "22000",
        timeout: int = 600,
    ) -> dict[str, Any]:
        """Startet hashcat mit gegebener Wortliste.

        Args:
            hash_file: Hash-Datei (.22000 / .hccapx)
            wordlist: Pfad zur Wortliste
            hash_mode: hashcat ``-m`` (22000 für WPA-PBKDF2-PMKID+EAPOL)
            timeout: Max. Laufzeit in Sekunden

        Returns:
            dict mit ``success``, ``password``, ``returncode``,
            ``stdout``, ``error``
        """
        hash_file = Path(hash_file)
        wordlist = Path(wordlist)
        result: dict[str, Any] = {
            "success": False,
            "returncode": -1,
            "password": None,
            "stdout": "",
            "error": "",
        }

        if not hash_file.exists():
            result["error"] = "Hash-Datei fehlt"
            return result
        if not wordlist.exists():
            result["error"] = "Wortliste fehlt"
            return result

        runner = self._get_runner()
        if runner is None and shutil.which("hashcat") is None:
            result["error"] = "hashcat nicht installiert"
            return result

        out_file = Path("/tmp/hashcat_out.txt")
        try:
            if out_file.exists():
                out_file.unlink()
        except OSError:
            pass

        cmd = [
            "hashcat",
            "-m",
            str(hash_mode),
            "-a",
            "0",
            "--force",
            "--quiet",
            "--potfile-disable",
            "--outfile-format=2",
            "-o",
            str(out_file),
            str(hash_file),
            str(wordlist),
        ]

        if runner is not None:
            try:
                rc, stdout, err = runner.run(
                    cmd,
                    subsystem="crack",
                    tag="hashcat",
                    soft_fail=True,
                    timeout=timeout,
                )
                result["returncode"] = rc
                result["stdout"] = (stdout or "")[:500]
                if rc != 0 and err:
                    result["error"] = err[:200]
            except (
                FileNotFoundError,
                subprocess.SubprocessError,
                OSError,
            ) as e:
                result["error"] = str(e)[:200]
                return result
        else:
            try:
                proc = subprocess.run(
                    cmd,
                    capture_output=True,
                    text=True,
                    timeout=timeout,
                    check=False,
                )
                result["returncode"] = proc.returncode
                result["stdout"] = (proc.stdout or "")[:500]
                if proc.returncode != 0 and proc.stderr:
                    result["error"] = proc.stderr[:200]
            except (
                FileNotFoundError,
                subprocess.TimeoutExpired,
                subprocess.SubprocessError,
                OSError,
            ) as e:
                result["error"] = str(e)[:200]
                return result

        if out_file.exists():
            try:
                text = out_file.read_text(encoding="utf-8").strip()
                if text:
                    pwd = text.split(":")[-1].strip()
                    if pwd:
                        result["success"] = True
                        result["password"] = pwd
            except OSError as e:
                self.logger.debug("hashcat outfile: %s", e)
            try:
                out_file.unlink()
            except OSError:
                pass

        return result

    def full_pipeline(
        self,
        pcap_path: str | Path,
        wordlist: str | Path,
    ) -> dict[str, Any]:
        """Komplette Pipeline: convert → crack.

        Returns:
            dict mit ``steps``, ``success``, ``password``
        """
        result: dict[str, Any] = {"steps": []}

        converted, msg = self.convert_pcap(pcap_path, "22000")
        if not converted:
            result["steps"].append(
                {
                    "step": "convert",
                    "ok": False,
                    "msg": msg,
                }
            )
            result["success"] = False
            return result

        result["steps"].append(
            {
                "step": "convert",
                "ok": True,
                "file": str(converted),
            }
        )

        crack_res = self.crack_with_hashcat(converted, wordlist)
        result["steps"].append(
            {
                "step": "crack",
                "result": crack_res,
            }
        )
        result["success"] = crack_res.get("success", False)
        result["password"] = crack_res.get("password")
        return result

    def pmkid_to_22000(self, pcapng_path: str | Path) -> Path | None:
        """Konvertiert hcxdumptool-PMKID-Output zu ``.22000``."""
        pcapng_path = Path(pcapng_path)
        if not pcapng_path.exists():
            return None

        out = pcapng_path.with_suffix(".22000")
        runner = self._get_runner()

        if runner is None and shutil.which("hcxpcapngtool") is None:
            return None

        if runner is not None:
            try:
                rc, _, _ = runner.run(
                    ["which", "hcxpcapngtool"],
                    subsystem="crack",
                    soft_fail=True,
                    timeout=3,
                )
                if rc != 0:
                    return None
                runner.run(
                    ["hcxpcapngtool", "-o", str(out), str(pcapng_path)],
                    subsystem="crack",
                    tag="pmkid-conv",
                    soft_fail=True,
                    timeout=30,
                )
            except (
                FileNotFoundError,
                subprocess.SubprocessError,
                OSError,
            ):
                return None
        else:
            try:
                subprocess.run(
                    ["hcxpcapngtool", "-o", str(out), str(pcapng_path)],
                    capture_output=True,
                    timeout=30,
                    check=False,
                )
            except (
                FileNotFoundError,
                subprocess.TimeoutExpired,
                subprocess.SubprocessError,
                OSError,
            ):
                return None

        if out.exists() and out.stat().st_size > 0:
            return out
        return None


class WordlistManager:
    """Verwaltet verfügbare Wortlisten.

    Sucht in Standard-Pfaden (Kali, SecLists, rockyou) sowie in
    ``~/.wlan_ultimate/wordlists/``.
    """

    COMMON_PATHS = [
        "/usr/share/wordlists/rockyou.txt",
        "/usr/share/wordlists/rockyou.txt.gz",
        "/usr/share/wordlists/fasttrack.txt",
        "/usr/share/wordlists/wpa.txt",
        "/usr/share/seclists/Passwords/Common-Credentials/"
        "10-million-password-list-top-1000000.txt",
        "/usr/share/seclists/Passwords/Common-Credentials/" "10k-most-common.txt",
        "/usr/share/seclists/Passwords/Leaked-Databases/" "rockyou.txt.tar.gz",
        "/usr/share/seclists/Passwords/WiFi-WPA/" "probable-v2-wpa-top4800.txt",
    ]

    def __init__(self) -> None:
        self.logger = logging.getLogger("wlan_ultimate.WordlistManager")

    def discover(self) -> list[dict[str, Any]]:
        """Findet alle verfügbaren Wortlisten.

        Returns:
            Liste von ``{path, name, size_mb, compressed}``
        """
        found: list[dict[str, Any]] = []
        for p in self.COMMON_PATHS:
            path = Path(p)
            if path.exists():
                try:
                    size_mb = path.stat().st_size / (1024 * 1024)
                    found.append(
                        {
                            "path": str(path),
                            "name": path.name,
                            "size_mb": round(size_mb, 1),
                            "compressed": (path.suffix in (".gz", ".tar.gz")),
                        }
                    )
                except OSError:
                    continue

        try:
            own = Path.home() / ".wlan_ultimate" / "wordlists"
            if own.exists():
                for f in own.glob("*"):
                    if f.is_file():
                        try:
                            size_mb = f.stat().st_size / (1024 * 1024)
                            found.append(
                                {
                                    "path": str(f),
                                    "name": f.name,
                                    "size_mb": round(size_mb, 1),
                                    "compressed": (f.suffix in (".gz", ".tar.gz")),
                                }
                            )
                        except OSError:
                            continue
        except OSError:
            pass

        return found

    def get_default(self) -> str | None:
        """Erste gefundene rockyou-Wortliste (oder erste andere)."""
        wl = self.discover()
        for w in wl:
            if "rockyou" in w["name"].lower():
                return w["path"]
        return wl[0]["path"] if wl else None

    def count(self) -> int:
        """Anzahl gefundener Wortlisten."""
        return len(self.discover())


# ══════════════════════════════════════════════════════════════════════
# 20. AdapterController
# ══════════════════════════════════════════════════════════════════════
# ══════════════════════════════════════════════════════════════════
# v8.2: AdapterController-Singleton
# ══════════════════════════════════════════════════════════════════
_ADAPTER_CONTROLLER_LOCK = threading.Lock()
_ADAPTER_CONTROLLER_INSTANCE = None


def get_adapter_controller():
    """Prozessweite Singleton-Instanz."""
    global _ADAPTER_CONTROLLER_INSTANCE
    with _ADAPTER_CONTROLLER_LOCK:
        if _ADAPTER_CONTROLLER_INSTANCE is None:
            _ADAPTER_CONTROLLER_INSTANCE = AdapterController()
        return _ADAPTER_CONTROLLER_INSTANCE


class AdapterController:
    """Vollständige Steuerung eines WLAN-Adapters.

    Features:
    - Modus: managed, monitor, AP, adhoc, mesh
    - Kanal + Bandbreite
    - TX-Power (0-30 dBm) mit Readback-Verifikation
    - Power-Save on/off
    - Regulatory Domain
    - Auto-Optimize für Pentesting
    """

    MODES = ["managed", "monitor", "AP", "adhoc", "mesh"]

    def __init__(self, logger: logging.Logger | None = None) -> None:
        self.logger = logger or logging.getLogger("wlan_ultimate.AdapterController")

    def _get_runner(self) -> Any | None:
        """Lazy-Lookup des CommandRunner."""
        return globals().get("CommandRunner")

    def _run(
        self,
        cmd: list[str],
        subsystem: str = "driver",
        tag: str = "adapter",
        timeout: float = 3.0,
    ) -> tuple[int, str, str]:
        """Führt ein Kommando aus (CommandRunner bevorzugt)."""
        runner = self._get_runner()
        if runner is not None:
            try:
                return runner.run(
                    cmd,
                    subsystem=subsystem,
                    tag=tag,
                    soft_fail=True,
                    timeout=timeout,
                )
            except (
                FileNotFoundError,
                subprocess.SubprocessError,
                OSError,
            ) as e:
                return -1, "", str(e)
        try:
            proc = subprocess.run(
                cmd,
                capture_output=True,
                text=True,
                timeout=timeout,
                check=False,
            )
            return proc.returncode, proc.stdout, proc.stderr
        except (
            FileNotFoundError,
            subprocess.TimeoutExpired,
            subprocess.SubprocessError,
            OSError,
        ) as e:
            return -1, "", str(e)

    def get_status(self, iface: str) -> dict[str, Any]:
        """Aktueller Adapter-Status (live gelesen)."""
        s: dict[str, Any] = {
            "iface": iface,
            "mode": "unknown",
            "channel": 0,
            "freq_mhz": 0,
            "width_mhz": 0,
            "txpower_dbm": 0,
            "powersave": "unbekannt",
            "regdomain": "00",
            "mac": "",
            "up": False,
            "errors": [],
        }

        try:
            rc, out, _ = self._run(["iw", "dev", iface, "info"], tag="status")
            if rc == 0:
                for line in out.splitlines():
                    ls = line.strip()
                    if ls.startswith("type "):
                        s["mode"] = ls.split(None, 1)[1].strip()
                    elif ls.startswith("channel "):
                        m = re.search(
                            r"channel\s+(\d+)\s*\((\d+)\s*MHz\)",
                            ls,
                        )
                        if m:
                            s["channel"] = int(m.group(1))
                            s["freq_mhz"] = int(m.group(2))
                        m2 = re.search(r"width:\s*(\d+)\s*MHz", ls)
                        if m2:
                            s["width_mhz"] = int(m2.group(1))
                    elif ls.startswith("addr "):
                        s["mac"] = ls.split(None, 1)[1].strip()
        except Exception as e:
            s["errors"].append(f"iw dev: {e}")

        try:
            rc, out, _ = self._run(
                ["iw", "dev", iface, "get", "txpower"],
                tag="tx-status",
            )
            m = re.search(r"([\d.]+)\s*dBm", out)
            if m:
                s["txpower_dbm"] = int(float(m.group(1)))
        except Exception as e:
            s["errors"].append(f"txpower: {e}")

        try:
            rc, out, _ = self._run(
                ["iw", "dev", iface, "get", "power_save"],
                tag="ps-status",
            )
            if "on" in out.lower():
                s["powersave"] = "AN"
            elif "off" in out.lower():
                s["powersave"] = "AUS"
        except Exception as e:
            s["errors"].append(f"powersave: {e}")

        try:
            rc, out, _ = self._run(["iw", "reg", "get"], tag="reg-status")
            for line in out.splitlines():
                if line.startswith("country"):
                    parts = line.split()
                    if len(parts) >= 2:
                        s["regdomain"] = parts[1].rstrip(":").strip()
                        break
        except Exception as e:
            s["errors"].append(f"reg: {e}")

        try:
            rc, out, _ = self._run(["ip", "link", "show", iface], tag="link-status")
            s["up"] = "state UP" in out
        except Exception as e:
            s["errors"].append(f"ip link: {e}")

        return s

    def set_mode(self, iface: str, mode: str) -> tuple[bool, str]:
        """Modus wechseln: managed, monitor, AP, adhoc, mesh."""
        if mode not in self.MODES:
            return False, f"Ungültiger Modus: {mode}"
        try:
            self._run(
                ["ip", "link", "set", iface, "down"],
                tag="mode-down",
            )
            rc, _, err = self._run(
                ["iw", "dev", iface, "set", "type", mode],
                tag="mode",
            )
            if rc != 0:
                return False, (err or "")[:100]
            self._run(
                ["ip", "link", "set", iface, "up"],
                tag="mode-up",
            )
            return True, f"Modus={mode}"
        except Exception as e:
            return False, str(e)

    def set_channel(
        self, iface: str, channel: int, width: int = 20
    ) -> tuple[bool, str]:
        """Kanal + Bandbreite setzen (V2b: ueber ChannelScheduler)."""
        sched = get_channel_scheduler()
        try:
            with sched.acquire(
                iface, channel,
                holder="adapter-ctl",
                priority=ChannelPriority.MANUAL,
                width=width,
            ):
                return True, f"Kanal {channel}"
        except ChannelBusy as exc:
            return False, f"Kanal {channel} belegt: {exc}"
        except RuntimeError as exc:
            return False, str(exc)[:80]

    def _read_tx_power_dbm(self, iface: str) -> int | None:
        """Liest die aktuelle TX-Power in dBm (mit Fallback-Chain).

        Reihenfolge:
        1. ``iw dev <iface> get txpower``
        2. ``iw dev <iface> info`` (Zeile "txpower X dBm")
        3. ``iwconfig <iface>`` (Zeile "Tx-Power= X dBm")

        Returns:
            int dBm oder None bei nicht lesbar.
        """
        # 1. iw dev ... get txpower
        rc, out, _ = self._run(
            ["iw", "dev", iface, "get", "txpower"],
            tag="tx-read-1",
        )
        if rc == 0 and out:
            m = re.search(r"([\d.]+)\s*dBm", out)
            if m:
                try:
                    return int(float(m.group(1)))
                except ValueError:
                    pass

        # 2. iw dev ... info
        rc, out, _ = self._run(["iw", "dev", iface, "info"], tag="tx-read-2")
        if rc == 0 and out:
            m = re.search(r"txpower\s+([\d.]+)\s*dBm", out)
            if m:
                try:
                    return int(float(m.group(1)))
                except ValueError:
                    pass

        # 3. iwconfig
        rc, out, _ = self._run(["iwconfig", iface], tag="tx-read-3")
        if rc == 0 and out:
            m = re.search(r"Tx-Power[=:]\s*([\d.]+)\s*dBm", out)
            if m:
                try:
                    return int(float(m.group(1)))
                except ValueError:
                    pass

        return None

    def set_tx_power(
        self, iface: str, dbm: int, verify: bool = True
    ) -> tuple[bool, str]:
        """TX-Power setzen mit band-aware Verifikation.

        Verhalten:
        - 2.4 GHz hat HW-Limit 20 dBm, 5 GHz hat 30 dBm.
        - Bei "requested > Band-Max" wird auf Band-Max akzeptiert.
        - Bei echtem Fehler (deutlich unter Band-Max) -> False.
        - Wenn Readback nicht lesbar: als OK akzeptieren (manche
          Adapter liefern kein Readback im managed mode).

        Returns:
            ``(ok, message)``
        """
        try:
            dbm = max(0, min(30, int(dbm)))
            rc, _, err = self._run(
                [
                    "iw",
                    "dev",
                    iface,
                    "set",
                    "txpower",
                    "fixed",
                    str(dbm * 100),
                ],
                tag="tx",
            )
            if rc != 0:
                return False, (err or "")[:80]

            if not verify:
                return True, f"TX={dbm} dBm"

            # etwas mehr Zeit fuer Readback
            time.sleep(0.5)

            actual = self._read_tx_power_dbm(iface)

            # Readback nicht lesbar -> OK mit Hinweis
            if actual is None:
                return True, (
                    f"TX={dbm} dBm gesetzt (kein Readback verfuegbar; "
                    f"Adapter im managed mode?)"
                )

            # Perfekter Match
            if abs(actual - dbm) <= 1:
                return True, f"TX={actual} dBm"

            # Band-Max pruefen
            band_max = self.get_current_band_max(iface)
            if band_max is not None and actual >= band_max - 1:
                hint = ""
                if band_max < dbm:
                    best = self.find_best_channel_for_max_tx(iface)
                    if best and best[1] > band_max:
                        hint = (
                            f" - Band-Max={band_max} dBm. "
                            f"Fuer {best[1]} dBm zu Kanal {best[0]} "
                            f"wechseln (5 GHz)"
                        )
                    else:
                        hint = f" - Band-Max={band_max} dBm"
                return True, f"TX={actual} dBm{hint}"

            # Echter Fehler
            bm = band_max if band_max is not None else "?"
            return False, (f"TX={actual} statt {dbm} dBm (Band-Max={bm})")
        except Exception as e:
            return False, str(e)

    # ==================================================================
    # Band-aware TX-Power-Helfer (v37-R19i)
    # ==================================================================
    def _get_phy_name(self, iface: str) -> str | None:
        """Ermittelt ``phyX`` zu einem Interface-Namen."""
        rc, out, _ = self._run(["iw", "dev", iface, "info"], tag="phy-lookup")
        if rc != 0:
            return None
        for line in out.splitlines():
            m = re.search(r"wiphy\s+(\d+)", line)
            if m:
                return f"phy{m.group(1)}"
        return None

    def get_band_max_dbm(self, iface: str) -> dict[int, int]:
        """Parst ``iw phy info`` und liefert max_dbm je Frequenz.

        Returns:
            ``{freq_mhz: max_dbm, ...}`` - leer bei Fehler.
        """
        phy = self._get_phy_name(iface)
        if not phy:
            return {}

        rc, out, _ = self._run(
            ["iw", "phy", phy, "info"],
            tag="phy-info",
            timeout=5.0,
        )
        if rc != 0:
            return {}

        result: dict[int, int] = {}
        for line in out.splitlines():
            # Format: "        * 2412.0 MHz [1] (20.0 dBm)"
            m = re.match(
                r"\s*\*\s*(\d+)\.\d+\s*MHz\s*\[(\d+)\]\s*" r"\(([\d.]+)\s*dBm\)",
                line,
            )
            if m:
                freq = int(m.group(1))
                dbm = int(float(m.group(3)))
                result[freq] = dbm
        return result

    def get_current_band_max(self, iface: str) -> int | None:
        """Aktueller Kanal -> max erlaubte TX-Power."""
        rc, out, _ = self._run(["iw", "dev", iface, "info"], tag="cur-ch")
        if rc != 0:
            return None
        freq: int | None = None
        for line in out.splitlines():
            m = re.search(r"channel\s+\d+\s*\((\d+)\s*MHz\)", line)
            if m:
                freq = int(m.group(1))
                break
        if not freq:
            return None
        band_map = self.get_band_max_dbm(iface)
        return band_map.get(freq)

    def find_best_channel_for_max_tx(self, iface: str) -> tuple[int, int] | None:
        """Findet den Kanal mit der hoechsten max-TX-Power.

        Beruecksichtigt nur Frequenzen mit gueltigem Kanal in
        AppKonstanten (d. h. überspringt Nicht-WiFi-Frequenzen wie
        5075/5080 MHz, die iw phy info mitliefert).

        Returns:
            ``(channel, max_dbm)`` oder ``None``.
        """
        band_map = self.get_band_max_dbm(iface)
        if not band_map:
            return None

        best_score: tuple[int, int] | None = None
        best_channel: int | None = None
        best_dbm: int = 0

        for freq, dbm in band_map.items():
            ch = AppKonstanten.frequency_to_channel(freq)
            if ch is None:
                continue
            # Score: hoehere dBm gewinnen; bei Gleichstand hoehere Freq
            # (5 GHz/UNII-3 vor 2.4 GHz bevorzugt)
            score = (dbm, freq)
            if best_score is None or score > best_score:
                best_score = score
                best_channel = ch
                best_dbm = dbm

        if best_channel is None:
            return None
        return (best_channel, best_dbm)

    def optimize_for_max_tx(self, iface: str) -> list[tuple[str, bool, str]]:
        """Wechselt auf Kanal mit hoechster max-TX-Power + setzt Max.

        Fuehrt folgende Schritte aus:
        1. RegDomain auf BO (Bolivia = max TX, keine DFS-Pflicht)
        2. Monitor-Modus aktivieren
        3. Power-Save off
        4. Auf Best-Channel wechseln (typisch 5 GHz UNII-3)
        5. TX-Power auf Band-Max setzen

        Praktisch: 2.4 GHz capped auf 20 dBm, 5 GHz bis 30 dBm.

        Returns:
            Liste von ``(step, ok, message)``
        """
        results: list[tuple[str, bool, str]] = []

        # 1. RegDomain
        ok, msg = self.set_regdomain("BO")
        results.append(("RegDomain -> BO", ok, msg))

        # 2. Monitor-Modus
        ok, msg = self.set_mode(iface, "monitor")
        results.append(("Mode -> monitor", ok, msg))
        if not ok:
            return results

        # 3. Power-Save off
        ok, msg = self.set_power_save(iface, False)
        results.append(("PowerSave off", ok, msg))

        # 4. Best-Channel
        best = self.find_best_channel_for_max_tx(iface)
        if not best:
            results.append(("Best-Channel", False, "kein Kanal gefunden"))
            return results
        channel, max_dbm = best
        ok, msg = self.set_channel(iface, channel)
        results.append((f"Channel -> {channel}", ok, msg))
        if not ok:
            return results

        # 5. TX
        ok, msg = self.set_tx_power(iface, max_dbm, verify=True)
        results.append((f"TX -> {max_dbm} dBm", ok, msg))

        return results

    def set_power_save(self, iface: str, enabled: bool) -> tuple[bool, str]:
        """Power-Save on/off."""
        try:
            state = "on" if enabled else "off"
            rc, _, _ = self._run(
                ["iw", "dev", iface, "set", "power_save", state],
                tag="ps",
            )
            return (rc == 0), f"PowerSave={state}"
        except Exception as e:
            return False, str(e)

    def set_regdomain(self, country: str) -> tuple[bool, str]:
        """Regulatory Domain setzen (z. B. 'BO', 'US', 'DE')."""
        try:
            rc, _, err = self._run(
                ["iw", "reg", "set", str(country)],
                tag="reg",
            )
            if rc == 0:
                return True, f"Reg={country}"
            return False, (err or "")[:60]
        except Exception as e:
            return False, str(e)

    def optimize_for_pentest(
        self,
        iface: str,
        reg: str = "BO",
        tx: int = 30,
        channel: int = 6,
    ) -> list[tuple[str, bool, str]]:
        """Alles-in-einem: RegDomain + Monitor + Powersave + TX + Kanal.

        Returns:
            Liste von ``(name, ok, meldung)``
        """
        results: list[tuple[str, bool, str]] = []

        ok, msg = self.set_regdomain(reg)
        results.append(("RegDomain", ok, msg))

        ok, msg = self.set_mode(iface, "monitor")
        results.append(("Mode", ok, msg))

        ok, msg = self.set_power_save(iface, False)
        results.append(("PowerSave", ok, msg))

        ok, msg = self.set_tx_power(iface, tx, verify=True)
        results.append(("TX", ok, msg))

        if channel:
            ok, msg = self.set_channel(iface, channel)
            results.append(("Channel", ok, msg))

        return results


