# ----------------------------------------------------------------
# A. InjectionTester — VM-aware Injection-Diagnose
# ----------------------------------------------------------------
class InjectionTester:
    """Testet Injection realistisch statt naiv-broadcast.

    In VMs (VBox-NAT) scheitert der klassische Broadcast-Test, obwohl
    die Hardware injection-fähig ist. Dieser Tester erkennt das und
    testet stattdessen gezielt gegen einen bekannten AP.
    """

    def __init__(self, logger=None):
        self.logger = logger or logging.getLogger("wlan_ultimate.InjectionTester")
        self.last_report: dict = {}

    @staticmethod
    def _detect_vm() -> dict:
        """Erkennt Virtualisierung und NAT."""
        out = {
            "is_vm": False,
            "virt_type": "none",
            "nat_hint": False,
            "iface": None,
            "subnet": None,
        }
        try:
            r = subprocess.run(
                ["systemd-detect-virt"], capture_output=True, text=True, timeout=3
            )
            if r.returncode == 0 and r.stdout.strip() != "none":
                out["is_vm"] = True
                out["virt_type"] = r.stdout.strip()
        except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
            pass
        # NAT-Heuristik: 10.0.2.x auf eth0/ensX = VBox-NAT
        try:
            r = subprocess.run(
                ["ip", "-4", "route", "show", "default"],
                capture_output=True,
                text=True,
                timeout=3,
            )
            for line in (r.stdout or "").splitlines():
                m = re.search(r"default via (\S+).*dev (\S+)", line)
                if m:
                    out["iface"] = m.group(2)
                    if m.group(1).startswith("10.0.2."):
                        out["nat_hint"] = True
        except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
            pass
        return out

    def test_injection(
        self, iface: str, known_bssids: list = None, channel: int = None
    ) -> dict:
        """Führt Injection-Test durch. known_bssids = Liste von BSSIDs,
        die während des Scans gesehen wurden. Wenn vorhanden, wird
        gezielt dagegen getestet statt Broadcast.
        """
        report = {
            "ok": False,
            "method": None,
            "detail": "",
            "recommendation": "",
            "vm_info": self._detect_vm(),
        }

        # 1) Basis-Checks
        if shutil.which("aireplay-ng") is None:
            report["detail"] = "aireplay-ng fehlt"
            report["recommendation"] = "sudo apt install aircrack-ng"
            self.last_report = report
            return report

        # 2) Interface-Status
        try:
            r = subprocess.run(
                ["iw", "dev", iface, "info"], capture_output=True, text=True, timeout=3
            )
            if "type monitor" not in r.stdout.lower():
                report["detail"] = f"{iface} ist nicht im Monitor-Modus"
                report["recommendation"] = (
                    f"sudo ip link set {iface} down && "
                    f"sudo iw dev {iface} set type monitor && "
                    f"sudo ip link set {iface} up"
                )
                self.last_report = report
                return report
        except (FileNotFoundError, subprocess.TimeoutExpired, OSError) as e:
            report["detail"] = str(e)
            self.last_report = report
            return report

        # 3) Kanal setzen (wichtig!) — V2c via ChannelScheduler
        if channel:
            try:
                with get_channel_scheduler().acquire(
                    iface, channel,
                    holder="inj-test",
                    priority=ChannelPriority.CAPTURE,
                ):
                    time.sleep(0.3)
            except (ChannelBusy, RuntimeError):
                pass

        # 4) Broadcast-Test — nur wenn KEIN NAT
        vm = report["vm_info"]
        if not vm["nat_hint"]:
            ok, detail = self._broadcast_test(iface)
            if ok:
                report["ok"] = True
                report["method"] = "broadcast"
                report["detail"] = detail
                self.last_report = report
                return report
            report["detail"] = f"Broadcast-Test fehlgeschlagen: {detail}"

        # 5) Fallback: gezielter Test gegen bekannten AP
        if known_bssids:
            for bssid in known_bssids[:3]:  # max 3 probieren
                ok, detail = self._targeted_test(iface, bssid)
                if ok:
                    report["ok"] = True
                    report["method"] = "targeted"
                    report["detail"] = detail
                    self.last_report = report
                    return report
            report["detail"] = (
                "Auch gezielter Test fehlgeschlagen. "
                "Wahrscheinlich fehlt echte WLAN-Verbindung zur Aussenwelt."
            )
        else:
            report["detail"] = (
                "Kein Broadcast möglich (VM/NAT) und keine "
                "bekannten BSSIDs zum gezielten Test vorhanden."
            )

        # 6) Empfehlung basierend auf VM-Status
        if vm["nat_hint"]:
            report["recommendation"] = (
                "VM läuft im NAT-Modus. Für Injection-Tests brauchst du "
                "entweder: (a) VM-Netzwerk auf 'Netzwerkbrücke' umstellen, "
                "oder (b) Adapter per USB-Passthrough an VM binden mit "
                "physischem Monitor-Interface."
            )
        elif vm["is_vm"]:
            report["recommendation"] = (
                f"VM erkannt ({vm['virt_type']}). Injection in VMs "
                "hängt stark vom USB-Passthrough ab. Wenn Scan läuft, "
                "ist die Hardware OK — Injection ist separat zu testen "
                "mit einem echten Ziel im selben Layer-2."
            )
        else:
            report["recommendation"] = (
                "Kein Broadcast-Erfolg, aber auch keine VM. Prüfe "
                "Antenne (fest?) und Kanal (richtig?)."
            )

        self.last_report = report
        return report

    def _broadcast_test(self, iface: str) -> tuple:
        try:
            r = subprocess.run(
                ["aireplay-ng", "--test", iface],
                capture_output=True,
                text=True,
                timeout=30,
            )
            out = (r.stdout or "") + (r.stderr or "")
            if "Injection is working" in out:
                return True, "Broadcast-Injection OK"
            return False, out.strip().splitlines()[-1] if out else "kein Output"
        except subprocess.TimeoutExpired:
            return False, "Timeout (30s)"
        except (FileNotFoundError, OSError) as e:
            return False, str(e)

    def _targeted_test(self, iface: str, bssid: str) -> tuple:
        """Sendet Deauth an bekannten AP — Erfolg wenn rc=0."""
        try:
            r = subprocess.run(
                ["aireplay-ng", "-0", "1", "-a", bssid, iface],
                capture_output=True,
                text=True,
                timeout=15,
            )
            out = (r.stdout or "") + (r.stderr or "")
            if r.returncode == 0 and "Sending DeAuth" in out:
                return True, f"Gezielter Deauth an {bssid} gesendet (rc=0)"
            # manche Versionen: "DeAuth code: 7"
            if "DeAuth" in out or "Deauth" in out:
                return True, f"Deauth an {bssid}: {out.strip().splitlines()[-1]}"
            return False, out.strip()[:120] if out else "kein Output"
        except subprocess.TimeoutExpired:
            return False, "Timeout (15s)"
        except (FileNotFoundError, OSError) as e:
            return False, str(e)

    def format_report(self, report: dict) -> str:
        vm = report.get("vm_info") or {}
        lines = []
        lines.append("═" * 60)
        lines.append("  INJECTION-TEST")
        lines.append("═" * 60)
        lines.append(f"  VM:           {vm.get('virt_type', 'n/a')}")
        if vm.get("nat_hint"):
            lines.append("  NAT-Modus:    JA (Broadcasts blockiert)")
        lines.append(
            f"  Ergebnis:     {'✅ ' if report['ok'] else '❌ '}"
            f"{report.get('method', '-')}"
        )
        lines.append(f"  Detail:       {report.get('detail', '-')}")
        if report.get("recommendation"):
            lines.append("")
            lines.append("  💡 Empfehlung:")
            for line in report["recommendation"].split(". "):
                if line.strip():
                    lines.append(f"     {line.strip()}.")
        lines.append("═" * 60)
        return "\n".join(lines)


