# ----------------------------------------------------------------
# A. ClientHistoryTracker — Verlauf pro MAC
# ----------------------------------------------------------------
class ClientHistoryTracker:
    """Zeichnet Signal-Verlauf und AP-Wechsel auf.

    Läuft als eigener Thread, liest zyklisch aus dem Mapper und
    speichert pro MAC einen Ringpuffer (Signal) und ein Event-Log
    (AP-Wechsel).
    """

    RING_SIZE = 300  # 5 Min bei 1 Hz
    POLL_INTERVAL = 2.0

    def __init__(self, mapper=None, persist=None, logger=None):
        self.mapper = mapper
        self.persist = persist
        self.logger = logger or logging.getLogger("wlan_ultimate.ClientHistoryTracker")
        self._lock = threading.RLock()
        self._hist: dict = {}  # mac -> deque[(ts, rssi)]
        self._ap_switches: dict = {}  # mac -> list[{ts, from, to}]
        self._last_ap: dict = {}  # mac -> bssid
        self._running = False
        self._stop = threading.Event()
        self._thread = None

    def start(self) -> None:
        if self._running:
            return
        self._running = True
        self._stop.clear()
        self._thread = threading.Thread(
            target=_thread_wrap(self._loop, "client-history-tracker"),
            daemon=True,
            name="ClientHistoryTracker",
        )
        self._thread.start()

    def stop(self) -> None:
        self._running = False
        self._stop.set()
        if self._thread and self._thread.is_alive():
            try:
                self._thread.join(timeout=3.0)
            except RuntimeError:
                pass
        self._thread = None

    def feed(self, mac: str, rssi: int, bssid: str | None = None) -> None:
        if not mac:
            return
        mac = mac.lower()
        now = time.time()
        with self._lock:
            buf = self._hist.setdefault(mac, deque(maxlen=self.RING_SIZE))
            buf.append((now, int(rssi)))
            if bssid:
                prev = self._last_ap.get(mac)
                if prev is None:
                    self._last_ap[mac] = bssid
                    self._ap_switches.setdefault(mac, []).append(
                        {
                            "ts": now,
                            "from": None,
                            "to": bssid,
                        }
                    )
                elif prev != bssid:
                    self._ap_switches.setdefault(mac, []).append(
                        {
                            "ts": now,
                            "from": prev,
                            "to": bssid,
                        }
                    )
                    self._last_ap[mac] = bssid
        # Persistenz
        if self.persist is not None:
            try:
                self.persist.save_traffic(bssid or "", mac, 0, 0)
                # zusätzlich RSSI-History schreiben
                if (
                    hasattr(self.persist, "store")
                    and self.persist.store is not None
                    and self.persist.store._conn is not None
                ):
                    with self.persist.store._lock, self.persist.store._conn:
                        self.persist.store._conn.execute(
                            "INSERT INTO client_rssi_history"
                            "(mac, ts, rssi) VALUES(?,?,?)",
                            (mac, now, int(rssi)),
                        )
            except Exception:
                pass

    def history(self, mac: str) -> list:
        with self._lock:
            return list(self._hist.get(mac.lower(), []))

    def ap_switches(self, mac: str) -> list:
        with self._lock:
            return list(self._ap_switches.get(mac.lower(), []))

    def stats(self) -> dict:
        with self._lock:
            return {
                "clients": len(self._hist),
                "samples": sum(len(b) for b in self._hist.values()),
            }

    def _loop(self) -> None:
        """Liest zyklisch aus Mapper und speichert Signal-Verlauf."""
        while not self._stop.is_set():
            self._stop.wait(self.POLL_INTERVAL)
            if self._stop.is_set():
                break
            if self.mapper is None:
                continue
            try:
                pairs = self.mapper.get_confident_pairs()
            except (AttributeError, TypeError):
                continue
            for p in pairs:
                try:
                    self.feed(p["client"], int(p.get("signal", -100)), p.get("bssid"))
                except (KeyError, TypeError, ValueError):
                    pass


# ----------------------------------------------------------------
# B. ClientMiniChart — matplotlib
# ----------------------------------------------------------------
class ClientMiniChart(QWidget):
    """Mini-Diagramm für Signal-Verlauf. Fallback auf Text bei
    fehlendem matplotlib."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self._has_mpl = MATPLOTLIB_VERFÜGBAR
        self._canvas = None
        self._ax = None
        self._build_ui()

    def _build_ui(self):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)

        if self._has_mpl:
            try:
                fig = Figure(figsize=(5, 2.2), facecolor="#1a1a1a")
                canvas = FigureCanvas(fig)
                ax = fig.add_subplot(111)
                ax.set_facecolor("#1a1a1a")
                ax.tick_params(colors="#bdc3c7", labelsize=7)
                for spine in ax.spines.values():
                    spine.set_color("#444")
                ax.set_ylabel("dBm", color="#bdc3c7", fontsize=8)
                ax.set_ylim(-95, -25)
                ax.grid(True, alpha=0.2, color="#555")
                canvas.setMinimumHeight(160)
                layout.addWidget(canvas)
                self._canvas = canvas
                self._ax = ax
                self._fig = fig
            except (ImportError, RuntimeError, ValueError):
                self._has_mpl = False
                self._fallback_ui(layout)
        else:
            self._fallback_ui(layout)

    def _fallback_ui(self, layout):
        self._text = QLabel("(matplotlib nicht verfügbar)")
        self._text.setStyleSheet(
            "color:#bdc3c7;font-family:monospace;padding:6px;" "background:#1a1a1a;"
        )
        self._text.setAlignment(
            Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter
        )
        layout.addWidget(self._text)

    def update_series(self, history: list) -> None:
        if not history:
            if self._has_mpl and self._ax:
                self._ax.clear()
                self._ax.set_facecolor("#1a1a1a")
                self._ax.set_ylim(-95, -25)
                self._ax.grid(True, alpha=0.2, color="#555")
                self._ax.text(
                    0.5,
                    0.5,
                    "Keine Daten",
                    color="#7f8c8d",
                    ha="center",
                    transform=self._ax.transAxes,
                )
                if self._canvas:
                    self._canvas.draw_idle()
            elif not self._has_mpl and hasattr(self, "_text"):
                self._text.setText("(noch keine Signal-Daten)")
            return

        # Auf letzten 60 Werte begrenzen
        recent = history[-60:]
        xs = [h[0] for h in recent]
        ys = [h[1] for h in recent]
        t0 = xs[0]
        xs = [x - t0 for x in xs]

        if self._has_mpl and self._ax:
            try:
                self._ax.clear()
                self._ax.set_facecolor("#1a1a1a")
                self._ax.plot(xs, ys, color="#2a82da", linewidth=1.4)
                self._ax.fill_between(xs, ys, -95, color="#2a82da", alpha=0.15)
                self._ax.set_ylim(-95, -25)
                self._ax.grid(True, alpha=0.2, color="#555")
                self._ax.set_ylabel("dBm", color="#bdc3c7", fontsize=8)
                self._ax.tick_params(colors="#bdc3c7", labelsize=7)
                for spine in self._ax.spines.values():
                    spine.set_color("#444")
                if self._canvas:
                    self._canvas.draw_idle()
            except (RuntimeError, ValueError, TypeError):
                pass
        elif hasattr(self, "_text"):
            # Textbalken
            lines = []
            for ts, rssi in recent[-20:]:
                bars = int(max(0, (rssi + 95) / 70 * 40))
                lines.append(f"{rssi:>4} dBm |" + "#" * bars)
            self._text.setText(chr(10).join(lines))


