class HandshakeFromClientDialog(QDialog):
    """Bestätigungsdialog mit Parametern für gezielten Deauth."""

    def __init__(
        self,
        parent,
        client_mac,
        bssid,
        ssid,
        channel,
        pmf_required=False,
        pmf_capable=False,
    ):
        super().__init__(parent)
        self.setWindowTitle("Handshake von Client abfangen")
        self.setMinimumSize(500, 420)
        self.client_mac = client_mac
        self.bssid = bssid
        self.ssid = ssid
        self.channel = channel
        self.result_params: dict = {}
        self._build(pmf_required, pmf_capable)

    def _build(self, pmf_required, pmf_capable):
        layout = QVBoxLayout(self)

        title = QLabel("<h3>Handshake abfangen</h3>")
        title.setTextFormat(Qt.TextFormat.RichText)
        layout.addWidget(title)

        # Zielbox
        tgt = QLabel(
            f"<table cellpadding=4>"
            f"<tr><td><b>SSID:</b></td>"
            f"<td>{self._esc(self.ssid or '<hidden>')}</td></tr>"
            f"<tr><td><b>BSSID:</b></td>"
            f"<td>{self.bssid}</td></tr>"
            f"<tr><td><b>Ziel-Client:</b></td>"
            f"<td>{self.client_mac}</td></tr>"
            f"<tr><td><b>Kanal:</b></td>"
            f"<td>{self.channel}</td></tr>"
            f"</table>"
        )
        tgt.setTextFormat(Qt.TextFormat.RichText)
        tgt.setStyleSheet("background:#2d2d2d;color:#bdc3c7;padding:8px;border-radius:4px;")
        layout.addWidget(tgt)

        # PMF-Warnung
        if pmf_required:
            warn = QLabel(
                "<b>⚠️  PMF (802.11w) ist REQUIRED.</b><br>"
                "Deauth wird den Client NICHT trennen. "
                "Nutzung des PMKID-Modus empfohlen."
            )
            warn.setTextFormat(Qt.TextFormat.RichText)
            warn.setStyleSheet(
                "background:#3d1a1a;color:#f39c12;padding:8px;" "border-radius:4px;"
            )
            warn.setWordWrap(True)
            layout.addWidget(warn)
        elif pmf_capable:
            info = QLabel("PMF capable — Client kann evtl. Deauth ignorieren.")
            info.setStyleSheet("color:#f39c12;font-size:9pt;")
            layout.addWidget(info)

        # Modus
        form = QFormLayout()
        self.mode_combo = QComboBox()
        self.mode_combo.addItem("⚡ Gezielter Deauth + Capture (empfohlen)", "deauth")
        self.mode_combo.addItem("🔍 Passiv (nur mitlauschen)", "passiv")
        self.mode_combo.addItem("🔑 PMKID-Capture (clientless)", "pmkid")
        if pmf_required:
            self.mode_combo.setCurrentIndex(2)
        form.addRow("Modus:", self.mode_combo)

        self.deauth_count = QSpinBox()
        self.deauth_count.setRange(5, 100)
        self.deauth_count.setValue(15)
        self.deauth_count.setSuffix(" Frames")
        form.addRow("Deauth-Anzahl:", self.deauth_count)

        self.rounds = QSpinBox()
        self.rounds.setRange(1, 10)
        self.rounds.setValue(5)
        self.rounds.setSuffix(" Runden")
        form.addRow("Retry-Runden:", self.rounds)

        self.timeout_per_round = QSpinBox()
        self.timeout_per_round.setRange(5, 60)
        self.timeout_per_round.setValue(20)
        self.timeout_per_round.setSuffix(" s")
        form.addRow("Timeout / Runde:", self.timeout_per_round)

        layout.addLayout(form)

        # Bestätigungshinweis
        note = QLabel(
            "⚠️  Nur gegen autorisierte Netzwerke verwenden! "
            "Deauth ist in Deutschland nach § 148 TKG strafbar."
        )
        note.setStyleSheet("color:#e74c3c;font-size:9pt;padding:4px;")
        note.setWordWrap(True)
        layout.addWidget(note)

        btns = QDialogButtonBox(
            QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel
        )
        btns.button(QDialogButtonBox.StandardButton.Ok).setText("▶  Starten")
        btns.accepted.connect(self._on_accept)
        btns.rejected.connect(self.reject)
        layout.addWidget(btns)

    def _on_accept(self):
        self.result_params = {
            "mode": self.mode_combo.currentData(),
            "deauth_count": self.deauth_count.value(),
            "rounds": self.rounds.value(),
            "timeout_per_round": self.timeout_per_round.value(),
        }
        self.accept()

    @staticmethod
    def _esc(s):
        # v37-R34 P65b: delegiert an Modul-Helper
        return _html_esc_basic(s)


# ----------------------------------------------------------------
# D. MultiClientHandshakeCapture — Sammel-Capture
# ----------------------------------------------------------------
class MultiClientHandshakeCapture(QThread):
    """Versucht Handshake über alle Clients eines APs.

    Sequenziell: pro Client Deauth + Warten auf EAPOL. Stoppt beim
    ersten Erfolg. Bricht bei PMF required ab.
    """

    log_line = pyqtSignal(str, str)
    progress = pyqtSignal(int, int)  # (idx, total)
    finished_ok = pyqtSignal(str, str)  # (client_mac, cap_path)
    failed = pyqtSignal(str)

    def __init__(
        self,
        clients: list,
        bssid: str,
        ssid: str,
        channel: int,
        iface: str,
        attack_ctrl,
        pmf_required: bool = False,
        per_client_timeout: int = 15,
        parent=None,
    ):
        super().__init__(parent)
        self.clients = list(clients)
        self.bssid = bssid
        self.ssid = ssid
        self.channel = channel
        self.iface = iface
        self.attack_ctrl = attack_ctrl
        self.pmf_required = pmf_required
        self.per_client_timeout = per_client_timeout
        self._abort = threading.Event()

    def abort(self):
        self._abort.set()

    def _log(self, msg, level="INFO"):
        self.log_line.emit(str(msg)[:300], level)

    def run(self):
        if self.pmf_required:
            self._log("PMF required — Sammel-Deauth nicht möglich", "ERR")
            self.failed.emit("PMF required. Nutze PMKID-Modus.")
            return

        if not self.clients:
            self.failed.emit("Keine Clients in Liste.")
            return

        self._log(f"Starte Sammel-Capture über {len(self.clients)} " f"Clients", "OK")
        total = len(self.clients)

        # Kanal sicherstellen — V2c via ChannelScheduler (CAPTURE-Prio)
        try:
            with get_channel_scheduler().acquire(
                self.iface, self.channel,
                holder="multi-capture",
                priority=ChannelPriority.CAPTURE,
            ):
                pass
        except (ChannelBusy, RuntimeError):
            pass

        # Airodump starten
        cap_dir = AppKonstanten.CAPTURE_DIR
        cap_dir.mkdir(parents=True, exist_ok=True)
        ts = datetime.now().strftime("%Y%m%d_%H%M%S")
        prefix = cap_dir / f"multi_{self.bssid.replace(':', '')}_{ts}"
        airoses = f"multi_{int(time.time())}"
        try:
            self.attack_ctrl._run_tool_with_session(
                airoses,
                "airodump-ng",
                [
                    "-c",
                    str(self.channel),
                    "--bssid",
                    self.bssid,
                    "-w",
                    str(prefix),
                    "--output-format",
                    "pcapng",
                    self.iface,
                ],
            )
            self._log("airodump-ng gestartet", "OK")
        except Exception as e:
            self._log(f"airodump-ng: {e}", "ERR")
            self.failed.emit(f"airodump-ng: {e}")
            return

        try:
            for idx, client in enumerate(self.clients, 1):
                if self._abort.is_set():
                    self._log("Abbruch", "WARN")
                    break
                self.progress.emit(idx, total)
                self._log(f"── Client {idx}/{total}: {client}", "INFO")

                # Deauth an genau diesen Client
                try:
                    self.attack_ctrl.run_deauth(
                        self.iface, self.bssid, client, count=15
                    )
                except Exception as e:
                    self._log(f"Deauth: {e}", "WARN")

                # Warten auf EAPOL
                seen = self._wait_capture(prefix, self.per_client_timeout)
                if seen:
                    self._log(f"✅ Handshake von {client}", "OK")
                    self.finished_ok.emit(client, str(seen))
                    return
                else:
                    self._log(f"kein Handshake von {client}", "WARN")

            # Nichts gefunden
            self._log("Alle Clients versucht — ohne Handshake", "WARN")
            self.failed.emit(
                "Kein Handshake von einem der "
                f"{len(self.clients)} Clients. "
                "Möglicherweise keine aktiven Verbindungen gerade."
            )
        finally:
            try:
                self.attack_ctrl.tool_manager.stop_tool(airoses)
            except (AttributeError, RuntimeError, OSError):
                pass

    def _wait_capture(self, prefix: Path, timeout: int):
        start = time.time()
        while time.time() - start < timeout:
            if self._abort.is_set():
                return None
            for pat in ("*.cap", "*.pcap", "*.pcapng"):
                for f in prefix.parent.glob(prefix.name + pat):
                    try:
                        if f.stat().st_size > 500:
                            return f
                    except OSError:
                        continue
            time.sleep(0.5)
        return None


