# ----------------------------------------------------------------
# 1. WordlistResolver
# ----------------------------------------------------------------
class WordlistResolver:
    """Findet verfügbare Wortlisten und generiert Top-10K aus rockyou."""

    CANDIDATES = [
        "/usr/share/wordlists/rockyou.txt",
        "/usr/share/wordlists/top10k.txt",
        "/usr/share/wordlists/fasttrack.txt",
        "/usr/share/wordlists/wpa.txt",
        "/usr/share/seclists/Passwords/WiFi-WPA/" "probable-v2-wpa-top4800.txt",
        "/usr/share/seclists/Passwords/Common-Credentials/"
        "10-million-password-list-top-1000000.txt",
        "/usr/share/seclists/Passwords/Common-Credentials/" "10k-most-common.txt",
        "/usr/share/seclists/Passwords/Leaked-Databases/" "rockyou.txt",
    ]

    @classmethod
    def discover(cls) -> list:
        """Liefert Liste von dicts: {path, name, size_mb, is_default}."""
        out = []
        for p in cls.CANDIDATES:
            path = Path(p)
            if path.is_file():
                try:
                    size_mb = path.stat().st_size / (1024 * 1024)
                except OSError:
                    size_mb = 0.0
                out.append(
                    {
                        "path": str(path),
                        "name": path.name,
                        "size_mb": round(size_mb, 1),
                        "is_default": "rockyou" in path.name.lower(),
                    }
                )
        return out

    @classmethod
    def ensure_top10k(cls) -> str | None:
        """Generiert /usr/share/wordlists/top10k.txt aus rockyou,
        falls noch nicht vorhanden. Läuft schnell (~30 s)."""
        top = Path("/usr/share/wordlists/top10k.txt")
        if top.is_file() and top.stat().st_size > 10000:
            return str(top)
        rockyou = Path("/usr/share/wordlists/rockyou.txt")
        if not rockyou.is_file():
            return None
        try:
            with rockyou.open("rb") as src, top.open("wb") as dst:
                for i, line in enumerate(src):
                    if i >= 10000:
                        break
                    dst.write(line)
            return str(top)
        except (OSError, PermissionError):
            # Fallback: nach /tmp
            try:
                tmp_top = Path("/tmp/top10k.txt")
                with rockyou.open("rb") as src, tmp_top.open("wb") as dst:
                    for i, line in enumerate(src):
                        if i >= 10000:
                            break
                        dst.write(line)
                return str(tmp_top)
            except OSError:
                return None


# ----------------------------------------------------------------
# 2. CrackOrchestrator
# ----------------------------------------------------------------
class CrackOrchestrator(QThread):
    """Crackt eine .cap/.22000-Datei mit Auto-Fallback.

    Reihenfolge:
      1. Konvertieren .cap -> .22000 (via hcxpcapngtool)
      2. hashcat versuchen
      3. Bei OpenCL/LLVM-Fehler -> aircrack-ng (CPU-only, immer da)
    """

    log_line = pyqtSignal(str, str)
    progress = pyqtSignal(int, str)  # (percent, info)
    found = pyqtSignal(str)  # password
    failed = pyqtSignal(str)  # reason

    def __init__(self, cap_path: str, wordlist: str, parent=None):
        super().__init__(parent)
        self.cap_path = str(cap_path)
        self.wordlist = str(wordlist)
        self._abort = threading.Event()
        self._proc = None

    def abort(self):
        self._abort.set()
        if self._proc is not None:
            try:
                self._proc.terminate()
            except (OSError, RuntimeError):
                pass

    def _log(self, msg, level="INFO"):
        self.log_line.emit(str(msg)[:300], level)

    def run(self):
        try:
            # 1. Hashdatei bauen
            hash_file = self._prepare_hash()
            if not hash_file:
                self.failed.emit("Kein crackbarer Handshake in der Capture-Datei.")
                return

            self._log(f"Hashdatei: {hash_file}", "OK")

            # 2. hashcat versuchen
            self._log("Versuche hashcat (GPU/OpenCL) …", "INFO")
            pw = self._try_hashcat(hash_file)
            if pw:
                self.found.emit(pw)
                return
            if self._abort.is_set():
                self.failed.emit("Abgebrochen")
                return

            # 3. Fallback aircrack-ng (kein OpenCL)
            self._log(
                "hashcat nicht verfügbar/nicht erfolgreich — "
                "wechsle zu aircrack-ng (CPU-only)",
                "WARN",
            )
            pw = self._try_aircrack()
            if pw:
                self.found.emit(pw)
                return

            self.failed.emit(
                "Passwort nicht in Wortliste gefunden. "
                "Größere Liste versuchen "
                "(rockyou.txt statt top10k)."
            )
        except Exception as exc:
            self.logger_exc(exc)
            self.failed.emit(f"Interner Fehler: {exc}")

    def logger_exc(self, exc):
        try:
            logging.getLogger("wlan_ultimate.CrackOrchestrator").exception(
                "Crack: %s", exc
            )
        except Exception:
            pass

    def _prepare_hash(self) -> str | None:
        """Konvertiert .cap zu .22000. Nutzt existierende Datei wenn
        schon konvertiert."""
        cap = Path(self.cap_path)
        if not cap.is_file():
            return None
        # Wenn schon .22000
        if cap.suffix == ".22000":
            return str(cap)
        out = Path("/tmp") / (cap.stem + ".22000")
        if out.is_file() and out.stat().st_size > 0:
            return str(out)
        tool = shutil.which("hcxpcapngtool")
        if not tool:
            self._log("hcxpcapngtool nicht gefunden", "WARN")
            return None
        try:
            r = subprocess.run(
                [tool, "-o", str(out), str(cap)],
                capture_output=True,
                text=True,
                timeout=60,
            )
            if out.is_file() and out.stat().st_size > 0:
                # Prüfen ob "EAPOL pairs written: 1" oder ähnliches
                txt = (r.stdout or "") + (r.stderr or "")
                if "EAPOL pairs written" in txt and ", 0" in txt:
                    # Möglicherweise trotzdem leer
                    for line in txt.splitlines():
                        if "written to 22000 hash file" in line:
                            m = re.search(r":\s*(\d+)", line)
                            if m and int(m.group(1)) == 0:
                                return None
                return str(out)
            return None
        except (FileNotFoundError, subprocess.TimeoutExpired, OSError) as e:
            self._log(f"hcxpcapngtool: {e}", "ERR")
            return None

    def _try_hashcat(self, hash_file: str) -> str | None:
        tool = shutil.which("hashcat")
        if not tool:
            return None
        cmd = [
            tool,
            "-m",
            "22000",
            "-a",
            "0",
            "--force",
            "--potfile-disable",
            "--status",
            "--status-timer",
            "5",
            hash_file,
            self.worklist_safe(),
        ]
        try:
            proc = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                bufsize=1,
            )
            self._proc = proc
            output_buf = []
            for line in proc.stdout or []:
                if self._abort.is_set():
                    proc.terminate()
                    return None
                output_buf.append(line)
                stripped = line.strip()
                # OpenCL/LLVM-Fehler -> sofort aufgeben
                if any(
                    k in stripped
                    for k in (
                        "LLVM ERROR",
                        "out of memory",
                        "CL_OUT_OF_HOST_MEMORY",
                        "CL_OUT_OF_RESOURCES",
                        "clCreateKernel",
                    )
                ):
                    self._log(f"hashcat-Problem: {stripped}", "WARN")
                    proc.terminate()
                    try:
                        proc.wait(timeout=3)
                    except (subprocess.TimeoutExpired, OSError):
                        proc.kill()
                    return None
                # Progress
                m = re.search(r"Progress\.+:\s*(\d+)/(\d+)", stripped)
                if m:
                    pct = int(int(m.group(1)) / max(1, int(m.group(2))) * 100)
                    self.progress.emit(pct, f"hashcat {pct}%")
                # Recovered
                if "Recovered........:" in stripped:
                    self._log(stripped, "INFO")
            proc.wait(timeout=10)
            # Aus potfile lesen geht nicht (deaktiviert), also --show
            r2 = subprocess.run(
                [tool, "-m", "22000", hash_file, "--show"],
                capture_output=True,
                text=True,
                timeout=10,
            )
            for line in (r2.stdout or "").splitlines():
                if ":" in line:
                    pw = line.rsplit(":", 1)[-1].strip()
                    if pw:
                        return pw
            return None
        except (FileNotFoundError, subprocess.TimeoutExpired, OSError) as e:
            self._log(f"hashcat: {e}", "WARN")
            return None

    def worklist_safe(self) -> str:
        return self.wordlist

    def _try_aircrack(self) -> str | None:
        tool = shutil.which("aircrack-ng")
        if not tool:
            return None
        cmd = [
            tool,
            "-w",
            self.wordlist,
            "-b",
            self._extract_bssid(),
            self.cap_path,
        ]
        # Wenn BSSID unbekannt, ohne -b
        if not cmd[3]:
            cmd = [tool, "-w", self.wordlist, self.cap_path]
        try:
            proc = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                bufsize=1,
            )
            self._proc = proc
            for line in proc.stdout or []:
                if self._abort.is_set():
                    proc.terminate()
                    return None
                stripped = line.strip()
                if "KEY FOUND" in stripped:
                    m = re.search(r"KEY FOUND!\s*\[\s*([^\]]+)\]", stripped)
                    if m:
                        pw = m.group(1).strip()
                        self._log(f"GEFUNDEN: {pw}", "OK")
                        proc.terminate()
                        return pw
                m = re.search(r"\[\d+:\d+:\d+\]\s+(\d+)/(\d+)\s+keys", stripped)
                if m:
                    pct = int(int(m.group(1)) / max(1, int(m.group(2))) * 100)
                    self.progress.emit(pct, f"aircrack {pct}%")
            try:
                proc.wait(timeout=5)
            except subprocess.TimeoutExpired:
                proc.kill()
            return None
        except (FileNotFoundError, subprocess.TimeoutExpired, OSError) as e:
            self._log(f"aircrack: {e}", "WARN")
            return None

    def _extract_bssid(self) -> str:
        """Liest die BSSID aus dem Dateinamen (hs_<BSSID>_...)."""
        name = Path(self.cap_path).stem
        m = re.search(r"hs_([0-9a-f]{12})", name.lower())
        if m:
            h = m.group(1)
            return ":".join(h[i : i + 2] for i in range(0, 12, 2))
        return ""


# ----------------------------------------------------------------
# 3. RootFileCopier
# ----------------------------------------------------------------
class RootFileCopier:
    """Kopiert Dateien aus /root/... nach ~/SUDO_USER/."""

    @staticmethod
    def detect_user_home() -> Path | None:
        sudo_user = os.environ.get("SUDO_USER", "").strip()
        if sudo_user and sudo_user != "root":
            home = Path(f"/home/{sudo_user}")
            if home.is_dir():
                return home
        # Fallback: aktueller User
        try:
            home = Path.home()
            if home.is_dir() and str(home) != "/root":
                return home
        except (RuntimeError, OSError):
            pass
        return None

    @classmethod
    def copy_to_user(cls, src_path: str, subdir: str = "captures") -> str | None:
        src = Path(src_path)
        if not src.is_file():
            return None
        home = cls.detect_user_home()
        if not home:
            return None
        target_dir = home / ".wlan_ultimate" / subdir
        try:
            target_dir.mkdir(parents=True, exist_ok=True)
            dst = target_dir / src.name
            shutil.copy2(src, dst)
            # Ownership setzen
            try:
                import pwd

                sudo_user = os.environ.get("SUDO_USER", "")
                if sudo_user:
                    pw = pwd.getpwnam(sudo_user)
                    os.chown(str(dst), pw.pw_uid, pw.pw_gid)
                    os.chown(str(target_dir), pw.pw_uid, pw.pw_gid)
            except (KeyError, PermissionError, OSError):
                pass
            return str(dst)
        except (OSError, PermissionError):
            return None


