            ("arp-scan", "arp-scan", "ARP-Discovery"),
            ("mtr", "mtr-tiny", "Path-Analyzer"),
            ("dig", "dnsutils", "DNS"),
            ("whois", "whois", "Domain"),
            ("curl", "curl", "HTTP"),
            ("openssl", "openssl", "TLS"),
