# ----------------------------------------------------------------
# A. ProjectManager — Projekt als ZIP speichern/laden
# ----------------------------------------------------------------
class ProjectManager:
    """Speichert kompletten Projekt-Stand als ZIP."""

    EXTENSION = ".wlanultimate"
    FORMAT_VERSION = 1

    @classmethod
    def save_project(cls, gui, path) -> tuple[bool, str]:
        """Speichert GUI-State + Capture-Dateien + Notizen als ZIP."""
        try:
            import zipfile

            path = Path(path)
            if path.suffix != cls.EXTENSION:
                path = path.with_suffix(cls.EXTENSION)

            # Metadata
            networks = []
            for n in getattr(gui, "aktuelle_netzwerke", []) or []:
                try:
                    networks.append(
                        {
                            "bssid": n.bssid,
                            "ssid": n.ssid,
                            "kanal": n.kanal,
                            "signal_stärke": n.signal_stärke,
                            "verschlüsselung": n.verschlüsselung,
                            "wps_aktiv": bool(n.wps_aktiv),
                            "hersteller": getattr(n, "hersteller", ""),
                        }
                    )
                except (AttributeError, TypeError):
                    continue

            targets = list(getattr(gui, "markierte_ziele", set()) or set())

            # Sessions (aus AttackController)
            sessions = []
            try:
                ac = getattr(gui, "attack_ctrl", None)
                if ac is not None:
                    for sid in ac.get_active_sessions():
                        sessions.append({"id": sid})
            except (AttributeError, TypeError):
                pass

            # Timeline
            timeline = []
            try:
                tracker = getattr(gui, "_timeline_tracker", None)
                if tracker is not None:
                    timeline = tracker.get_all()[-500:]
            except (AttributeError, TypeError):
                pass

            # Topologie
            topology = []
            try:
                mapper = getattr(gui, "_client_ap_mapper", None)
                if mapper is not None:
                    topology = mapper.get_confident_pairs()
            except (AttributeError, TypeError):
                pass

            meta = {
                "version": cls.FORMAT_VERSION,
                "created": datetime.now().isoformat(),
                "networks": networks,
                "targets": targets,
                "sessions": sessions,
                "timeline": timeline,
                "topology": topology,
            }

            # ZIP erstellen
            with zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED) as zf:
                zf.writestr("project.json", json.dumps(meta, indent=2, default=str))
                # Captures einpacken
                cap_dir = AppKonstanten.CAPTURE_DIR
                if cap_dir.is_dir():
                    for f in (
                        list(cap_dir.glob("*.cap"))
                        + list(cap_dir.glob("*.pcapng"))
                        + list(cap_dir.glob("*.22000"))
                    ):
                        try:
                            zf.write(f, f"captures/{f.name}")
                        except (OSError, ValueError):
                            pass
                # Root-Captures
                root_cap = Path("/root/.wlan_ultimate/captures")
                if root_cap.is_dir():
                    for f in list(root_cap.glob("*.cap")) + list(
                        root_cap.glob("*.pcapng")
                    ):
                        try:
                            zf.write(f, f"captures/{f.name}")
                        except (OSError, ValueError):
                            pass

            size_kb = path.stat().st_size / 1024
            return True, f"Gespeichert: {path.name} ({size_kb:.0f} KB)"
        except (OSError, ValueError, TypeError) as e:
            return False, f"Fehler: {e}"

    @classmethod
    def load_project(cls, gui, path) -> tuple[bool, str, dict]:
        """Lädt Projekt und wendet auf GUI an."""
        try:
            import zipfile

            path = Path(path)
            if not path.is_file():
                return False, f"Datei nicht gefunden: {path}", {}

            with zipfile.ZipFile(path, "r") as zf:
                try:
                    meta_raw = zf.read("project.json")
                    meta = json.loads(meta_raw)
                except (KeyError, json.JSONDecodeError) as e:
                    return False, f"project.json fehlt/kaputt: {e}", {}

                # Captures auspacken
                cap_dir = AppKonstanten.CAPTURE_DIR
                cap_dir.mkdir(parents=True, exist_ok=True)
                n_cap = 0
                for name in zf.namelist():
                    if not name.startswith("captures/"):
                        continue
                    if name.endswith("/"):
                        continue
                    try:
                        target = cap_dir / Path(name).name
                        with zf.open(name) as src, target.open("wb") as dst:
                            shutil.copyfileobj(src, dst)
                        n_cap += 1
                    except (OSError, ValueError):
                        pass

            # GUI anwenden
            try:
                targets = meta.get("targets", [])
                gui.markierte_ziele = set(targets)
            except (AttributeError, TypeError):
                pass

            # Netzwerke in DB
            try:
                db = getattr(gui, "db_manager", None)
                for net_data in meta.get("networks", []):
                    if db is None:
                        break
                    try:
                        net = WLANNetzwerk.from_dict(net_data)
                        db.speichere_netzwerk(net)
                    except (KeyError, TypeError, ValueError):
                        pass
            except (AttributeError, TypeError):
                pass

            return (
                True,
                (
                    f"Geladen: {path.name} "
                    f"({len(meta.get('networks', []))} "
                    f"Netzwerke, {n_cap} Captures)"
                ),
                meta,
            )
        except (OSError, zipfile.BadZipFile, ValueError) as e:
            return False, f"Fehler: {e}", {}


