# ----------------------------------------------------------------
# A. KeyStore — persistente WPA-Keys
# ----------------------------------------------------------------
class KeyStore:
    """Speichert gecrackte WPA-Passwörter in der CentralStore-DB."""

    def __init__(self, store=None, logger=None):
        self.logger = logger or logging.getLogger("wlan_ultimate.KeyStore")
        self.store = store
        if self.store is None:
            try:
                self.store = get_store()
            except (NameError, AttributeError):
                self.store = None
        self._ensure_schema()

    def _ensure_schema(self):
        if self.store is None or self.store._conn is None:
            return
        try:
            with self.store._lock, self.store._conn:
                self.store._conn.executescript("""
                    CREATE TABLE IF NOT EXISTS wpa_keys (
                        bssid TEXT PRIMARY KEY,
                        ssid TEXT,
                        password TEXT NOT NULL,
                        source TEXT,
                        added REAL,
                        last_used REAL);
                    CREATE INDEX IF NOT EXISTS idx_wpa_ssid
                        ON wpa_keys(ssid);
                """)
        except Exception as e:
            self.logger.debug("KeyStore-Schema: %s", e)

    def save(self, bssid: str, password: str, ssid: str = "", source: str = "") -> bool:
        if self.store is None or self.store._conn is None:
            return False
        if not bssid or not password:
            return False
        bssid = bssid.lower()
        now = time.time()
        try:
            with self.store._lock, self.store._conn:
                self.store._conn.execute(
                    "INSERT OR REPLACE INTO wpa_keys"
                    "(bssid, ssid, password, source, added, last_used)"
                    " VALUES(?,?,?,?,?,?)",
                    (bssid, ssid, password, source or "manual", now, now),
                )
            return True
        except Exception as e:
            self.logger.debug("KeyStore.save: %s", e)
            return False

    def get(self, bssid: str) -> str | None:
        if self.store is None or self.store._conn is None:
            return None
        try:
            with self.store._lock:
                cur = self.store._conn.execute(
                    "SELECT password FROM wpa_keys WHERE bssid=?", (bssid.lower(),)
                )
                row = cur.fetchone()
                if row:
                    # last_used aktualisieren
                    try:
                        self.store._conn.execute(
                            "UPDATE wpa_keys SET last_used=? " "WHERE bssid=?",
                            (time.time(), bssid.lower()),
                        )
                        self.store._conn.commit()
                    except Exception:
                        pass
                    return row["password"]
        except Exception:
            pass
        return None

    def get_full(self, bssid: str) -> dict | None:
        if self.store is None or self.store._conn is None:
            return None
        try:
            with self.store._lock:
                cur = self.store._conn.execute(
                    "SELECT * FROM wpa_keys WHERE bssid=?", (bssid.lower(),)
                )
                row = cur.fetchone()
                return dict(row) if row else None
        except Exception:
            return None

    def list_all(self) -> list:
        if self.store is None or self.store._conn is None:
            return []
        try:
            with self.store._lock:
                cur = self.store._conn.execute(
                    "SELECT * FROM wpa_keys ORDER BY last_used DESC"
                )
                return [dict(r) for r in cur]
        except Exception:
            return []

    def delete(self, bssid: str) -> bool:
        if self.store is None or self.store._conn is None:
            return False
        try:
            with self.store._lock, self.store._conn:
                self.store._conn.execute(
                    "DELETE FROM wpa_keys WHERE bssid=?", (bssid.lower(),)
                )
            return True
        except Exception:
            return False

    def count(self) -> int:
        if self.store is None or self.store._conn is None:
            return 0
        try:
            with self.store._lock:
                cur = self.store._conn.execute("SELECT COUNT(*) FROM wpa_keys")
                return int(cur.fetchone()[0])
        except Exception:
            return 0


# ----------------------------------------------------------------
# B. HandshakeLibrary — alle Captures mit Status
# ----------------------------------------------------------------
class HandshakeLibrary:
    """Verwaltet alle jemals erfassten Handshakes."""

    STATUS_CAPTURED = "captured"
    STATUS_CRACKED = "cracked"
    STATUS_FAILED = "failed"

    def __init__(self, store=None, logger=None):
        self.logger = logger or logging.getLogger("wlan_ultimate.HandshakeLibrary")
        self.store = store
        if self.store is None:
            try:
                self.store = get_store()
            except (NameError, AttributeError):
                self.store = None
        self._ensure_schema()

    def _ensure_schema(self):
        if self.store is None or self.store._conn is None:
            return
        try:
            with self.store._lock, self.store._conn:
                self.store._conn.executescript("""
                    CREATE TABLE IF NOT EXISTS handshake_library (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        bssid TEXT,
                        ssid TEXT,
                        cap_file TEXT UNIQUE,
                        cap_size INTEGER,
                        eapol_count INTEGER,
                        status TEXT,
                        password TEXT,
                        notes TEXT,
                        first_seen REAL,
                        last_used REAL);
                    CREATE INDEX IF NOT EXISTS idx_hs_bssid
                        ON handshake_library(bssid);
                    CREATE INDEX IF NOT EXISTS idx_hs_status
                        ON handshake_library(status);
                """)
        except Exception as e:
            self.logger.debug("HandshakeLibrary-Schema: %s", e)

    def add_capture(
        self, bssid: str, ssid: str, cap_file: str, eapol_count: int = 0
    ) -> bool:
        if self.store is None or self.store._conn is None:
            return False
        cap_file = str(cap_file)
        try:
            size = Path(cap_file).stat().st_size
        except OSError:
            size = 0
        now = time.time()
        try:
            with self.store._lock, self.store._conn:
                self.store._conn.execute(
                    "INSERT OR IGNORE INTO handshake_library"
                    "(bssid, ssid, cap_file, cap_size, eapol_count,"
                    " status, first_seen, last_used)"
                    " VALUES(?,?,?,?,?,?,?,?)",
                    (
                        bssid.lower(),
                        ssid,
                        cap_file,
                        size,
                        eapol_count,
                        self.STATUS_CAPTURED,
                        now,
                        now,
                    ),
                )
            return True
        except Exception as e:
            self.logger.debug("add_capture: %s", e)
            return False

    def mark_cracked(self, cap_file: str, password: str) -> bool:
        if self.store is None or self.store._conn is None:
            return False
        try:
            with self.store._lock, self.store._conn:
                self.store._conn.execute(
                    "UPDATE handshake_library"
                    " SET status=?, password=?, last_used=?"
                    " WHERE cap_file=?",
                    (self.STATUS_CRACKED, password, time.time(), str(cap_file)),
                )
            return True
        except Exception:
            return False

    def mark_failed(self, cap_file: str, note: str = "") -> bool:
        if self.store is None or self.store._conn is None:
            return False
        try:
            with self.store._lock, self.store._conn:
                self.store._conn.execute(
                    "UPDATE handshake_library"
                    " SET status=?, notes=?, last_used=?"
                    " WHERE cap_file=?",
                    (self.STATUS_FAILED, note[:200], time.time(), str(cap_file)),
                )
            return True
        except Exception:
            return False

    def list_all(self) -> list:
        if self.store is None or self.store._conn is None:
            return []
        try:
            with self.store._lock:
                cur = self.store._conn.execute(
                    "SELECT * FROM handshake_library" " ORDER BY last_used DESC"
                )
                return [dict(r) for r in cur]
        except Exception:
            return []

    def delete(self, cap_file: str) -> bool:
        if self.store is None or self.store._conn is None:
            return False
        try:
            with self.store._lock, self.store._conn:
                self.store._conn.execute(
                    "DELETE FROM handshake_library WHERE cap_file=?", (str(cap_file),)
                )
            return True
        except Exception:
            return False

    def count_by_status(self) -> dict:
        if self.store is None or self.store._conn is None:
            return {}
        try:
            with self.store._lock:
                cur = self.store._conn.execute(
                    "SELECT status, COUNT(*) AS n"
                    " FROM handshake_library GROUP BY status"
                )
                return {r["status"]: r["n"] for r in cur}
        except Exception:
            return {}


# ----------------------------------------------------------------
# C. HandshakeLibTab — Übersicht mit Aktionen
