class APDetailDialog(QDialog):
    """Zeigt alles über einen Access Point."""

    def __init__(
        self,
        parent,
        bssid,
        networks=None,
        mapper=None,
        traffic=None,
        keystore=None,
        library=None,
        history=None,
    ):
        super().__init__(parent)
