# ----------------------------------------------------------------
# A. ScheduledScannerTab — Auto-Scan-Planer
# ----------------------------------------------------------------
class ScheduledScannerTab(QWidget):
    """Auto-Scan mit Live-Countdown und Log."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setMinimumSize(860, 680)
        self._scheduler = None
        self._build_ui()
        self._timer = QTimer(self)
        self._timer.timeout.connect(self._on_tick)
        self._timer.start(1000)

    def _build_ui(self):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(8, 8, 8, 8)

        header = QLabel("⏰  Auto-Scan-Planer")
        header.setStyleSheet(
            "font-size:16px;font-weight:bold;color:#2a82da;padding:4px;"
        )
        layout.addWidget(header)

        info = QLabel(
            "Startet den WLAN-Scan automatisch alle N Minuten. "
            "Nützlich für Langzeit-Überwachung: neue APs werden "
            "automatisch erfasst."
        )
        info.setStyleSheet(
            "background:#2d2d2d;color:#bdc3c7;padding:8px;"
            "border-radius:4px;font-size:9pt;"
        )
        info.setWordWrap(True)
        layout.addWidget(info)

        # Konfiguration
        g = QGroupBox("Einstellungen")
        gl = QFormLayout(g)
        self.interval_spin = QSpinBox()
        self.interval_spin.setRange(1, 720)
        self.interval_spin.setValue(10)
        self.interval_spin.setSuffix(" Minuten")
        gl.addRow("Intervall:", self.interval_spin)

        self.duration_spin = QSpinBox()
        self.duration_spin.setRange(10, 600)
        self.duration_spin.setValue(30)
        self.duration_spin.setSuffix(" s Scan-Dauer")
        gl.addRow("Scan-Dauer:", self.duration_spin)

        self.stop_after_spin = QSpinBox()
        self.stop_after_spin.setRange(0, 1000)
        self.stop_after_spin.setValue(0)
        self.stop_after_spin.setSpecialValueText("(unbegrenzt)")
        self.stop_after_spin.setSuffix(" Scans")
        gl.addRow("Max. Scans:", self.stop_after_spin)

        layout.addWidget(g)

        # Status
        self.status_frame = QFrame()
        self.status_frame.setStyleSheet(
            "background:#1a1a1a;color:#bdc3c7;border:1px solid #444;"
            "border-radius:6px;padding:12px;"
        )
        sf = QVBoxLayout(self.status_frame)

        self.lbl_status = QLabel("⏹  Inaktiv")
        self.lbl_status.setStyleSheet("font-size:14pt;font-weight:bold;color:#7f8c8d;")
        sf.addWidget(self.lbl_status)

        self.lbl_countdown = QLabel("—")
        self.lbl_countdown.setStyleSheet(
            "font-family:monospace;font-size:32pt;" "color:#2a82da;font-weight:bold;"
        )
        self.lbl_countdown.setAlignment(Qt.AlignmentFlag.AlignCenter)
        sf.addWidget(self.lbl_countdown)

        self.lbl_runs = QLabel("Scans: 0")
        self.lbl_runs.setStyleSheet("color:#bdc3c7;font-family:monospace;")
        self.lbl_runs.setAlignment(Qt.AlignmentFlag.AlignCenter)
        sf.addWidget(self.lbl_runs)

        layout.addWidget(self.status_frame)

        # Buttons
        row = QHBoxLayout()
        self.btn_start = QPushButton("▶  Auto-Scan starten")
        self.btn_start.setStyleSheet(
            "background:#27ae60;color:white;font-weight:bold;"
            "padding:10px;font-size:11pt;"
        )
        self.btn_start.clicked.connect(self._on_start)
        row.addWidget(self.btn_start)

        self.btn_stop = QPushButton("⏹  Stoppen")
        self.btn_stop.setEnabled(False)
        self.btn_stop.clicked.connect(self._on_stop)
        row.addWidget(self.btn_stop)

        self.btn_run_now = QPushButton("⚡ Jetzt scannen")
        self.btn_run_now.clicked.connect(self._on_run_now)
        row.addWidget(self.btn_run_now)
        row.addStretch()
        layout.addLayout(row)

        # Log
        log_lbl = QLabel("📜 Log")
        log_lbl.setStyleSheet("color:#2a82da;font-weight:bold;padding:8px 4px 4px 4px;")
        layout.addWidget(log_lbl)

        self.log = QPlainTextEdit()
        self.log.setReadOnly(True)
        self.log.setStyleSheet(
            "background:#0d1117;color:#d4d4d4;" "font-family:monospace;font-size:9pt;"
        )
        layout.addWidget(self.log, 1)

    def _find_gui(self):
        # v37-R34 P65a: delegiert an Modul-Helper
        return _find_gui_main_window()

    def _log(self, msg):
        try:
            ts = datetime.now().strftime("%H:%M:%S")
            self.log.appendPlainText(f"[{ts}] {msg}")
        except (AttributeError, RuntimeError):
            pass

    def _on_start(self):
        gui = self._find_gui()
        if not gui:
            QMessageBox.warning(self, "Fehler", "GUI nicht gefunden.")
            return
        interval = self.interval_spin.value()
        duration = self.duration_spin.value()
        # Scan-Dauer in GUI setzen
        try:
            if hasattr(gui, "scan_duration"):
                gui.scan_duration.setValue(duration)
        except (AttributeError, RuntimeError):
            pass
        self._scheduler = ScheduledScanner(gui_ref=gui, interval_min=interval)
        self._scheduler.log.connect(self._log)
        self._scheduler.start()
        self.btn_start.setEnabled(False)
        self.btn_stop.setEnabled(True)
        self.lbl_status.setText("✅ Auto-Scan läuft")
        self.lbl_status.setStyleSheet("font-size:14pt;font-weight:bold;color:#27ae60;")
        self.log.clear()
        self._log(f"Scheduler gestartet: alle {interval} Min")

    def _on_stop(self):
        try:
            if self._scheduler is not None:
                self._scheduler.abort()
                self._scheduler.wait(3000)
                self._scheduler = None
        except (AttributeError, RuntimeError):
            pass
        self.btn_start.setEnabled(True)
        self.btn_stop.setEnabled(False)
        self.lbl_status.setText("⏹  Inaktiv")
        self.lbl_status.setStyleSheet("font-size:14pt;font-weight:bold;color:#7f8c8d;")
        self.lbl_countdown.setText("—")
        self._log("Scheduler gestoppt")

    def _on_run_now(self):
        gui = self._find_gui()
        if not gui:
            return
        self._log("Manueller Scan …")
        try:
            gui.starte_scan()
        except (AttributeError, RuntimeError) as e:
            self._log(f"Fehler: {e}")

    def _on_tick(self):
        if self._scheduler is None:
            return
        try:
            elapsed = time.time() - getattr(self._scheduler, "_last_run", time.time())
            remaining = max(0, int(self._scheduler.interval_s - elapsed))
            m, s = divmod(remaining, 60)
            self.lbl_countdown.setText(f"{m:02d}:{s:02d}")
            self.lbl_runs.setText(f"Scans: {getattr(self._scheduler, '_runs', 0)}")
        except (AttributeError, RuntimeError):
            pass


# ----------------------------------------------------------------
# B. NetworkDiffTab — Zwei Snapshots vergleichen
# ----------------------------------------------------------------
class NetworkDiffTab(QWidget):
    """Vergleicht zwei Netzwerk-Listen."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setMinimumSize(860, 680)
        self._snapshot_a = None
        self._snapshot_b = None
        self._build_ui()

    def _build_ui(self):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(8, 8, 8, 8)

        header = QLabel("🔀  Netzwerk-Diff — zwei Scans vergleichen")
        header.setStyleSheet(
            "font-size:16px;font-weight:bold;color:#2a82da;padding:4px;"
        )
        layout.addWidget(header)

        info = QLabel(
            "Erst Snapshot A, dann später Snapshot B aufnehmen. "
            "Das Tool zeigt was neu, weg oder verändert ist — "
            "perfekt um Roaming zu erkennen."
        )
        info.setStyleSheet(
            "background:#2d2d2d;color:#bdc3c7;padding:8px;"
            "border-radius:4px;font-size:9pt;"
        )
        info.setWordWrap(True)
        layout.addWidget(info)

        # Snapshot-Auswahl
        row = QHBoxLayout()
        b_a = QPushButton("📸 Snapshot A")
        b_a.setStyleSheet(
            "background:#2a82da;color:white;font-weight:bold;" "padding:8px;"
        )
        b_a.clicked.connect(lambda: self._take_snapshot("A"))
        row.addWidget(b_a)

        b_b = QPushButton("📸 Snapshot B")
        b_b.setStyleSheet(
            "background:#2a82da;color:white;font-weight:bold;" "padding:8px;"
        )
        b_b.clicked.connect(lambda: self._take_snapshot("B"))
        row.addWidget(b_b)

        b_cmp = QPushButton("🔀 Vergleichen")
        b_cmp.setStyleSheet(
            "background:#27ae60;color:white;font-weight:bold;" "padding:8px;"
        )
        b_cmp.clicked.connect(self._compare)
        row.addWidget(b_cmp)

        b_clear = QPushButton("🗑 Zurücksetzen")
        b_clear.clicked.connect(self._reset)
        row.addWidget(b_clear)
        row.addStretch()
        layout.addLayout(row)

        # Snapshot-Status
        self.lbl_a = QLabel("A: nicht aufgenommen")
        self.lbl_b = QLabel("B: nicht aufgenommen")
        for lbl in (self.lbl_a, self.lbl_b):
            lbl.setStyleSheet(
                "background:#1a1a1a;padding:6px;border-radius:4px;"
                "font-family:monospace;color:#bdc3c7;"
            )
            layout.addWidget(lbl)

        # Ergebnisse
        self.tabs = QTabWidget()

        # Neu
        w1 = QWidget()
        l1 = QVBoxLayout(w1)
        self.new_table = QTableWidget(0, 4)
        self.new_table.setHorizontalHeaderLabels(["SSID", "BSSID", "Kanal", "Signal"])
        self.new_table.horizontalHeader().setSectionResizeMode(
            QHeaderView.ResizeMode.Stretch
        )
        self.new_table.setStyleSheet(
            "background:#0d1117;color:#d4d4d4;" "font-family:monospace;font-size:9pt;"
        )
        self.new_table.horizontalHeader().setStyleSheet(
            "background:#2d2d2d;color:#27ae60;"
        )
        l1.addWidget(self.new_table)
        self.tabs.addTab(w1, "🆕 Neu")

        # Weg
        w2 = QWidget()
        l2 = QVBoxLayout(w2)
        self.gone_table = QTableWidget(0, 4)
        self.gone_table.setHorizontalHeaderLabels(["SSID", "BSSID", "Kanal", "Signal"])
        self.gone_table.horizontalHeader().setSectionResizeMode(
            QHeaderView.ResizeMode.Stretch
        )
        self.gone_table.setStyleSheet(
            "background:#0d1117;color:#d4d4d4;" "font-family:monospace;font-size:9pt;"
        )
        self.gone_table.horizontalHeader().setStyleSheet(
            "background:#2d2d2d;color:#e74c3c;"
        )
        l2.addWidget(self.gone_table)
        self.tabs.addTab(w2, "❌ Weg")

        # Verändert
        w3 = QWidget()
        l3 = QVBoxLayout(w3)
        self.changed_table = QTableWidget(0, 5)
        self.changed_table.setHorizontalHeaderLabels(
            ["SSID", "BSSID", "Δ Signal", "Δ Kanal", "Kanal neu"]
        )
        self.changed_table.horizontalHeader().setSectionResizeMode(
            QHeaderView.ResizeMode.Stretch
        )
        self.changed_table.setStyleSheet(
            "background:#0d1117;color:#d4d4d4;" "font-family:monospace;font-size:9pt;"
        )
        self.changed_table.horizontalHeader().setStyleSheet(
            "background:#2d2d2d;color:#f39c12;"
        )
        l3.addWidget(self.changed_table)
        self.tabs.addTab(w3, "🔄 Verändert")

        layout.addWidget(self.tabs, 1)

        self.status_label = QLabel("Bereit.")
        self.status_label.setStyleSheet(
            "background:#1a1a1a;padding:6px;border-radius:4px;"
            "font-family:monospace;color:#bdc3c7;"
        )
        layout.addWidget(self.status_label)

    def _find_gui(self):
        # v37-R34 P65a: delegiert an Modul-Helper
        return _find_gui_main_window()

    def _take_snapshot(self, which: str):
        gui = self._find_gui()
        if not gui:
            return
        snap = {}
        for n in getattr(gui, "aktuelle_netzwerke", []) or []:
            try:
                snap[n.bssid.lower()] = {
                    "ssid": n.ssid,
                    "kanal": n.kanal,
                    "signal": n.signal_stärke,
                }
            except (AttributeError, TypeError):
                continue
        if which == "A":
            self._snapshot_a = snap
            self.lbl_a.setText(
                f"A: {len(snap)} Netzwerke " f"({datetime.now().strftime('%H:%M:%S')})"
            )
        else:
            self._snapshot_b = snap
            self.lbl_b.setText(
                f"B: {len(snap)} Netzwerke " f"({datetime.now().strftime('%H:%M:%S')})"
            )
        self.status_label.setText(f"Snapshot {which}: {len(snap)} Netzwerke")

    def _compare(self):
        if self._snapshot_a is None or self._snapshot_b is None:
            QMessageBox.warning(self, "Fehlende Snapshots", "Erst A und B aufnehmen.")
            return
        a = self._snapshot_a
        b = self._snapshot_b
        keys_a = set(a.keys())
        keys_b = set(b.keys())
        new_keys = keys_b - keys_a
        gone_keys = keys_a - keys_b
        common = keys_a & keys_b

        # Neu
        self.new_table.setRowCount(0)
        for k in sorted(new_keys):
            n = b[k]
            r = self.new_table.rowCount()
            self.new_table.insertRow(r)
            self.new_table.setItem(r, 0, QTableWidgetItem(str(n.get("ssid", "") or "")))
            self.new_table.setItem(r, 1, QTableWidgetItem(k))
            self.new_table.setItem(r, 2, QTableWidgetItem(str(n.get("kanal", 0))))
            self.new_table.setItem(r, 3, QTableWidgetItem(f"{n.get('signal', 0)} dBm"))

        # Weg
        self.gone_table.setRowCount(0)
        for k in sorted(gone_keys):
            n = a[k]
            r = self.gone_table.rowCount()
            self.gone_table.insertRow(r)
            self.gone_table.setItem(
                r, 0, QTableWidgetItem(str(n.get("ssid", "") or ""))
            )
            self.gone_table.setItem(r, 1, QTableWidgetItem(k))
            self.gone_table.setItem(r, 2, QTableWidgetItem(str(n.get("kanal", 0))))
            self.gone_table.setItem(r, 3, QTableWidgetItem(f"{n.get('signal', 0)} dBm"))

        # Verändert
        self.changed_table.setRowCount(0)
        for k in sorted(common):
            na = a[k]
            nb = b[k]
            dsig = nb.get("signal", 0) - na.get("signal", 0)
            dkan = nb.get("kanal", 0) - na.get("kanal", 0)
            if abs(dsig) < 3 and dkan == 0:
                continue
            r = self.changed_table.rowCount()
            self.changed_table.insertRow(r)
            self.changed_table.setItem(
                r, 0, QTableWidgetItem(str(nb.get("ssid", "") or ""))
            )
            self.changed_table.setItem(r, 1, QTableWidgetItem(k))
            sig_item = QTableWidgetItem(f"{dsig:+d} dBm")
            if dsig > 0:
                sig_item.setForeground(QBrush(QColor(39, 174, 96)))
            elif dsig < 0:
                sig_item.setForeground(QBrush(QColor(231, 76, 60)))
            self.changed_table.setItem(r, 2, sig_item)
            self.changed_table.setItem(r, 3, QTableWidgetItem(f"{dkan:+d}"))
            self.changed_table.setItem(r, 4, QTableWidgetItem(str(nb.get("kanal", 0))))

        self.status_label.setText(
            f"🆕 {len(new_keys)}  ·  ❌ {len(gone_keys)}  ·  "
            f"🔄 {self.changed_table.rowCount()}"
        )

    def _reset(self):
        self._snapshot_a = None
        self._snapshot_b = None
        self.lbl_a.setText("A: nicht aufgenommen")
        self.lbl_b.setText("B: nicht aufgenommen")
        self.new_table.setRowCount(0)
        self.gone_table.setRowCount(0)
        self.changed_table.setRowCount(0)
        self.status_label.setText("Zurückgesetzt.")


# ----------------------------------------------------------------
# C. HeatmapTab — 2D-Signal-Heatmap
# ----------------------------------------------------------------
class HeatmapTab(QWidget):
    """2D-Heatmap: Kanäle vs. Signalstärke."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setMinimumSize(800, 600)
        self._build_ui()
        self._timer = QTimer(self)
        self._timer.timeout.connect(self.refresh)
        self._timer.start(5000)

    def _build_ui(self):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(8, 8, 8, 8)

        header = QLabel("🌡️  Signal-Heatmap")
        header.setStyleSheet(
            "font-size:16px;font-weight:bold;color:#2a82da;padding:4px;"
        )
        layout.addWidget(header)

        info = QLabel(
            "Zeigt alle APs als Punkte: X = Kanal, Y = Signal. "
            "Farbe = Sicherheits-Score (grün=sicher, rot=offen). "
            "Größe = Sichtungen."
        )
        info.setStyleSheet(
            "background:#2d2d2d;color:#bdc3c7;padding:6px;"
            "border-radius:4px;font-size:9pt;"
        )
        info.setWordWrap(True)
        layout.addWidget(info)

        # Buttons
        row = QHBoxLayout()
        b_ref = QPushButton("🔄 Aktualisieren")
        b_ref.clicked.connect(self.refresh)
        row.addWidget(b_ref)
        b_save = QPushButton("💾 Als PNG speichern")
        b_save.clicked.connect(self._save_png)
        row.addWidget(b_save)
        row.addStretch()
        layout.addLayout(row)

        # Chart
        self.host = QWidget()
        hl = QVBoxLayout(self.host)
        hl.setContentsMargins(0, 0, 0, 0)
        layout.addWidget(self.host, 1)

        self._canvas = None
        self._fig = None
        self._init_chart()

        self.status_label = QLabel("Warte auf Netzwerke …")
        self.status_label.setStyleSheet("color:#7f8c8d;padding:4px;")
        layout.addWidget(self.status_label)

    def _init_chart(self):
        if not MATPLOTLIB_VERFÜGBAR:
            self.host.layout().addWidget(QLabel("(matplotlib nicht verfügbar)"))
            return
        try:
            fig = Figure(figsize=(10, 5), facecolor="#1e1e1e")
            canvas = FigureCanvas(fig)
            self.host.layout().addWidget(canvas)
            self._canvas = canvas
            self._fig = fig
        except (ImportError, RuntimeError, ValueError):
            pass

    def refresh(self):
        if self._fig is None:
            return
        gui = None
        try:
            app = QApplication.instance()
            if app:
                for w in app.topLevelWidgets():
                    if hasattr(w, "interface_manager"):
                        gui = w
                        break
        except (AttributeError, RuntimeError):
            pass
        if not gui:
            return
        nets = list(getattr(gui, "aktuelle_netzwerke", []) or [])
        if not nets:
            self.status_label.setText("Keine Netzwerke.")
            return

        try:
            self._fig.clear()
            ax = self._fig.add_subplot(111)
            ax.set_facecolor("#1e1e1e")
            ax.tick_params(colors="#bdc3c7", labelsize=9)
            for spine in ax.spines.values():
                spine.set_color("#444")
            ax.grid(True, alpha=0.2, color="#555")
            ax.set_xlabel("Kanal", color="#bdc3c7", fontsize=10)
            ax.set_ylabel("Signal (dBm)", color="#bdc3c7", fontsize=10)

            # Gruppiert nach Band
            xs_24, ys_24, cs_24, ss_24 = [], [], [], []
            xs_5, ys_5, cs_5, ss_5 = [], [], [], []
            xs_6, ys_6, cs_6, ss_6 = [], [], [], []
            for n in nets:
                ch = int(getattr(n, "kanal", 0) or 0)
                sig = int(getattr(n, "signal_stärke", -100) or -100)
                score = 0
                try:
                    score = n.get_sicherheits_score()
                except (AttributeError, TypeError):
                    pass
                # Farbe
                if score >= 70:
                    c = "#27ae60"
                elif score >= 40:
                    c = "#f39c12"
                else:
                    c = "#e74c3c"
                size = max(30, min(400, score * 4 + 30))
                if 1 <= ch <= 14:
                    xs_24.append(ch)
                    ys_24.append(sig)
                    cs_24.append(c)
                    ss_24.append(size)
                elif 36 <= ch <= 177:
                    xs_5.append(ch)
                    ys_5.append(sig)
                    cs_5.append(c)
                    ss_5.append(size)
                elif ch >= 200:
                    xs_6.append(ch)
                    ys_6.append(sig)
                    cs_6.append(c)
                    ss_6.append(size)
            if xs_24:
                ax.scatter(
                    xs_24,
                    ys_24,
                    c=cs_24,
                    s=ss_24,
                    alpha=0.7,
                    edgecolors="#1e1e1e",
                    label="2.4 GHz",
                    marker="o",
                )
            if xs_5:
                ax.scatter(
                    xs_5,
                    ys_5,
                    c=cs_5,
                    s=ss_5,
                    alpha=0.7,
                    edgecolors="#1e1e1e",
                    label="5 GHz",
                    marker="s",
                )
            if xs_6:
                ax.scatter(
                    xs_6,
                    ys_6,
                    c=cs_6,
                    s=ss_6,
                    alpha=0.7,
                    edgecolors="#1e1e1e",
                    label="6 GHz",
                    marker="^",
                )
            ax.set_ylim(-100, -20)
            legend = ax.legend(
                loc="lower right", fontsize=9, facecolor="#2d2d2d", edgecolor="#444"
            )
            for text in legend.get_texts():
                text.set_color("#bdc3c7")
            if self._canvas:
                self._canvas.draw_idle()
            self.status_label.setText(
                f"{len(nets)} Netzwerke · "
                f"2.4G={len(xs_24)} 5G={len(xs_5)} 6G={len(xs_6)}"
            )
        except (RuntimeError, ValueError, TypeError) as e:
            self.status_label.setText(f"Fehler: {e}")

    def _save_png(self):
        if self._fig is None:
            return
        fn, _ = QFileDialog.getSaveFileName(
            self, "Heatmap speichern", "heatmap.png", "PNG (*.png)"
        )
        if not fn:
            return
        try:
            self._fig.savefig(fn, dpi=120, facecolor="#1e1e1e", bbox_inches="tight")
            QMessageBox.information(self, "Gespeichert", f"Datei: {fn}")
        except (OSError, ValueError) as e:
            QMessageBox.warning(self, "Fehler", str(e))


# ----------------------------------------------------------------
# D. TimelineVizTab — Grafische Zeitleiste
# ----------------------------------------------------------------
