# ----------------------------------------------------------------
# A. SecurityTab — WPA3 / PMF / Enterprise Details
# ----------------------------------------------------------------
class SecurityAnalyzer:
    """Klassifiziert Netzwerke nach Sicherheits-Features."""

    @classmethod
    def analyze(cls, network) -> dict:
        """Liefert dict mit allen Sicherheits-Merkmalen."""
        enc = str(getattr(network, "verschlüsselung", "") or "").upper()
        cipher = str(getattr(network, "cipher", "") or "").upper()
        akm = getattr(network, "akm", "") or ""
        if isinstance(akm, (list, tuple)):
            akm_str = ",".join(str(a) for a in akm).upper()
        else:
            akm_str = str(akm).upper()
        pmf_cap = bool(getattr(network, "mfp_capable", False))
        pmf_req = bool(getattr(network, "mfp_required", False))
        sae = bool(getattr(network, "sae", False))
        owe = bool(getattr(network, "owe", False))
        ent = bool(getattr(network, "enterprise", False))
        wps = bool(getattr(network, "wps_aktiv", False))

        # Bewertung
        if sae and pmf_req:
            level = "WPA3-Hardened"
            icon = "🟢"
            score = 95
        elif sae:
            level = "WPA3"
            icon = "🟢"
            score = 88
        elif owe:
            level = "WPA3-OWE"
            icon = "🟢"
            score = 80
        elif ent and pmf_req:
            level = "Enterprise+PMF"
            icon = "🟢"
            score = 85
        elif ent:
            level = "Enterprise"
            icon = "🟡"
            score = 70
        elif enc == "WPA2" and "CCMP" in cipher and pmf_cap:
            level = "WPA2+PMF"
            icon = "🟢"
            score = 78
        elif enc == "WPA2" and "CCMP" in cipher:
            level = "WPA2-Solid"
            icon = "🟡"
            score = 65
        elif enc == "WPA2" and "TKIP" in cipher:
            level = "WPA2-TKIP"
            icon = "🟠"
            score = 40
        elif enc == "WPA":
            level = "WPA-Legacy"
            icon = "🟠"
            score = 30
        elif enc == "WEP":
            level = "WEP"
            icon = "🔴"
            score = 10
        elif enc == "OPEN":
            level = "OPEN"
            icon = "🔴"
            score = 0
        else:
            level = enc or "?"
            icon = "⚪"
            score = 50

        # Attack-Hints
        hints = []
        if enc == "OPEN":
            hints.append("Evil-Twin/Portal")
        elif enc == "WEP":
            hints.append("WEP-Crack (5 Min)")
        elif sae and not owe:
            hints.append("WPA3-SAE (nur Online-Brute)")
        elif owe:
            hints.append("OWE (offene Auth)")
        elif ent:
            hints.append("EAP-Downgrade / Rogue-RADIUS")
        elif enc in ("WPA", "WPA2"):
            if wps and not getattr(network, "wps_lock", False):
                hints.append("WPS-Pixie")
            if not pmf_req:
                hints.append("Deauth+Handshake")
            if "TKIP" in cipher:
                hints.append("TKIP-Schwach")
        if pmf_req:
            hints.append("⚠ PMF-Req → Deauth sinnlos")
        if wps:
            hints.append("WPS aktiv")
        if not hints:
            hints.append("Standard-Recon")

        return {
            "level": level,
            "icon": icon,
            "score": score,
            "encryption": enc,
            "cipher": cipher or "-",
            "akm": akm_str or "-",
            "pmf_capable": pmf_cap,
            "pmf_required": pmf_req,
            "sae": sae,
            "owe": owe,
            "enterprise": ent,
            "wps": wps,
            "hints": hints,
        }


