class BackupTab(QWidget):
    """Backup und Restore aller Daten."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setMinimumSize(720, 560)
        self._build_ui()
        self._refresh()

    def _build_ui(self):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(8, 8, 8, 8)

        header = QLabel("💾  Backup & Restore")
        header.setStyleSheet(
            "font-size:16px;font-weight:bold;color:#2a82da;padding:4px;"
        )
        layout.addWidget(header)

        info = QLabel(
            "Sichert CentralStore, Config, Presets, Notizen und "
            "optional Captures in einem ZIP. Ideal für "
            "Neuinstallation oder Weitergabe."
        )
        info.setStyleSheet(
            "background:#2d2d2d;color:#bdc3c7;padding:8px;"
            "border-radius:4px;font-size:9pt;"
        )
        info.setWordWrap(True)
        layout.addWidget(info)

        # Status
        self.status_frame = QFrame()
        self.status_frame.setStyleSheet(
            "background:#1a1a1a;color:#bdc3c7;border:1px solid #444;"
            "border-radius:6px;padding:12px;"
        )
        sf = QVBoxLayout(self.status_frame)
        self.stats_label = QLabel("—")
        self.stats_label.setStyleSheet("font-family:monospace;color:#bdc3c7;")
        sf.addWidget(self.stats_label)
        layout.addWidget(self.status_frame)

        # Buttons
        row = QHBoxLayout()

        b_backup = QPushButton("💾 Backup erstellen")
        b_backup.setStyleSheet(
            "background:#27ae60;color:white;font-weight:bold;" "padding:10px;"
        )
        b_backup.clicked.connect(self._on_backup)
        row.addWidget(b_backup)

        b_restore = QPushButton("📂 Backup wiederherstellen")
        b_restore.setStyleSheet(
            "background:#2a82da;color:white;font-weight:bold;" "padding:10px;"
        )
        b_restore.clicked.connect(self._on_restore)
        row.addWidget(b_restore)

        b_ref = QPushButton("🔄")
        b_ref.setMaximumWidth(40)
        b_ref.clicked.connect(self._refresh)
        row.addWidget(b_ref)
        row.addStretch()
        layout.addLayout(row)

        # Info
        self.info = QPlainTextEdit()
        self.info.setReadOnly(True)
        self.info.setStyleSheet(
            "background:#0d1117;color:#d4d4d4;" "font-family:monospace;font-size:9pt;"
        )
        self.info.setPlaceholderText("Details erscheinen hier nach dem Backup …")
        layout.addWidget(self.info, 1)

    def _paths(self):
        base = Path.home() / ".wlan_ultimate"
        return {
            "config": base / "config.json",
            "store_db": base / "store.db",
            "store_wal": base / "store.db-wal",
            "store_shm": base / "store.db-shm",
            "presets": base / "presets.json",
            "filters": base / "filters.json",
            "notes": base / "notes",
            "captures": base / "captures",
            "reports": base / "reports",
            "decrypted": base / "decrypted",
            "projects": base / "projects",
            "watchlist": base / "watchlist.json",
            "mac_backup": base / "mac_backup.json",
        }

    def _fmt(self, n):
        try:
            n = float(n)
        except (ValueError, TypeError):
            return "?"
        for u in ("B", "KB", "MB", "GB"):
            if n < 1024:
                return f"{n:.1f} {u}"
            n /= 1024
        return f"{n:.1f} TB"

    def _refresh(self):
        paths = self._paths()
        lines = []
        total = 0
        for name, p in paths.items():
            if p.is_file():
                sz = p.stat().st_size
                total += sz
                lines.append(f"  ✓ {name:<12} {self._fmt(sz)}")
            elif p.is_dir():
                d_sz = sum(f.stat().st_size for f in p.rglob("*") if f.is_file())
                total += d_sz
                count = sum(1 for f in p.rglob("*") if f.is_file())
                lines.append(f"  ✓ {name:<12} {self._fmt(d_sz)} " f"({count} Dateien)")
            else:
                lines.append(f"  — {name:<12} (fehlt)")
        self.stats_label.setText(f"Gesamt: {self._fmt(total)}\n" + "\n".join(lines))

    def _on_backup(self):
        default = (
            Path.home() / "wlan_ultimate_backup_"
            f"{datetime.now().strftime('%Y%m%d_%H%M')}.zip"
        )
        fn, _ = QFileDialog.getSaveFileName(
            self, "Backup speichern", str(default), "ZIP (*.zip);;Alle (*)"
        )
        if not fn:
            return
        include_caps = QMessageBox.question(
            self,
            "Captures einbeziehen?",
            "Sollen Capture-Dateien mit ins Backup?\n" "(Kann mehrere GB groß werden.)",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No,
        )
        include_captures = include_caps == QMessageBox.StandardButton.Yes

        try:
            import zipfile

            paths = self._paths()
            excluded = set()
            if not include_captures:
                excluded = {"captures", "decrypted", "reports", "projects"}
            count = 0
            with zipfile.ZipFile(fn, "w", zipfile.ZIP_DEFLATED) as zf:
                for name, p in paths.items():
                    if name in excluded:
                        continue
                    if p.is_file():
                        zf.write(p, f"backup/{p.name}")
                        count += 1
                    elif p.is_dir():
                        for f in p.rglob("*"):
                            if f.is_file():
                                rel = f.relative_to(p.parent)
                                zf.write(f, f"backup/{rel}")
                                count += 1
            size = Path(fn).stat().st_size
            self.info.appendPlainText(
                f"✓ Backup: {fn}\n" f"  {count} Dateien, {self._fmt(size)}"
            )
            QMessageBox.information(
                self, "Backup fertig", f"{count} Dateien\n{self._fmt(size)}\n\n{fn}"
            )
        except (OSError, ValueError) as e:
            QMessageBox.warning(self, "Fehler", str(e))

    def _on_restore(self):
        fn, _ = QFileDialog.getOpenFileName(
            self, "Backup wählen", str(Path.home()), "ZIP (*.zip)"
        )
        if not fn:
            return
        reply = QMessageBox.question(
            self,
            "Restore",
            f"Backup wiederherstellen?\n\n{fn}\n\n"
            "⚠ Aktuelle Daten werden überschrieben!",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No,
        )
        if reply != QMessageBox.StandardButton.Yes:
            return
        try:
            import zipfile

            base = Path.home() / ".wlan_ultimate"
            base.mkdir(parents=True, exist_ok=True)
            count = 0
            with zipfile.ZipFile(fn, "r") as zf:
                for name in zf.namelist():
                    if not name.startswith("backup/"):
                        continue
                    rel = name[len("backup/") :]
                    if not rel:
                        continue
                    target = base / rel
                    target.parent.mkdir(parents=True, exist_ok=True)
                    try:
                        with zf.open(name) as src, target.open("wb") as dst:
                            shutil.copyfileobj(src, dst)
                        count += 1
                    except (OSError, ValueError):
                        pass
            self.info.appendPlainText(f"✓ {count} Dateien wiederhergestellt")
            QMessageBox.information(
                self,
                "Restore fertig",
                f"{count} Dateien wiederhergestellt.\n\n" "GUI neu starten empfohlen.",
            )
        except (OSError, ValueError) as e:
            QMessageBox.warning(self, "Fehler", str(e))


# ----------------------------------------------------------------
# D. NotificationCenter — Desktop-Benachrichtigungen
# ----------------------------------------------------------------
class NotificationCenter:
    """Zentrale Event-Benachrichtigungen + Desktop-Popup."""

    _instance = None

    def __init__(self, gui_ref=None):
        self.gui_ref = gui_ref
        self.logger = logging.getLogger("wlan_ultimate.NotificationCenter")
        self._callbacks = []
        self._history = []
        self._min_level = "INFO"

    @classmethod
    def get(cls):
        if cls._instance is None:
            cls._instance = NotificationCenter()
        return cls._instance

    def attach(self, gui_ref):
        self.gui_ref = gui_ref

    def on_notify(self, callback):
        if callback not in self._callbacks:
            self._callbacks.append(callback)

    def notify(self, title: str, message: str, level: str = "INFO", popup: bool = True):
        """Sendet Notification. level: INFO|WARN|ERROR|SUCCESS."""
        try:
            self._history.append(
                {
                    "ts": time.time(),
                    "title": title,
                    "message": message,
                    "level": level,
                }
            )
            if len(self._history) > 500:
                self._history = self._history[-500:]
        except (AttributeError, TypeError):
            pass

        # Log
        try:
            if level == "ERROR":
                self.logger.error(f"[NOTIF] {title}: {message}")
            elif level == "WARN":
                self.logger.warning(f"[NOTIF] {title}: {message}")
            else:
                self.logger.info(f"[NOTIF] {title}: {message}")
        except (AttributeError, RuntimeError):
            pass

        # Desktop-Popup
        if popup:
            try:
                app = QApplication.instance()
                if app:
                    for w in app.topLevelWidgets():
                        if hasattr(w, "tray_icon") and w.tray_icon:
                            icon = {
                                "ERROR": QSystemTrayIcon.MessageIcon.Critical,
                                "WARN": QSystemTrayIcon.MessageIcon.Warning,
                                "SUCCESS": QSystemTrayIcon.MessageIcon.Information,
                            }.get(level, QSystemTrayIcon.MessageIcon.Information)
                            w.tray_icon.showMessage(title, message, icon, 5000)
                            break
            except (AttributeError, RuntimeError):
                pass

        # Callbacks
        for cb in list(self._callbacks):
            try:
                cb(title, message, level)
            except Exception:
                pass

    def history(self, last_n: int = 100) -> list:
        return self._history[-last_n:]


class NotificationsTab(QWidget):
    """Zeigt Notification-Verlauf."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setMinimumSize(720, 560)
        self._build_ui()
        self._timer = QTimer(self)
        self._timer.timeout.connect(self.refresh)
        self._timer.start(3000)

    def _build_ui(self):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(8, 8, 8, 8)

        header = QLabel("🔔  Notifications")
        header.setStyleSheet(
            "font-size:16px;font-weight:bold;color:#2a82da;padding:4px;"
        )
        layout.addWidget(header)

        info = QLabel(
            "Ereignis-Verlauf. Wichtige Events (Adapter weg, "
            "Handshake fertig, Crack-Erfolg) werden auch als "
            "Desktop-Popup angezeigt."
        )
        info.setStyleSheet(
            "background:#2d2d2d;color:#bdc3c7;padding:6px;"
            "border-radius:4px;font-size:9pt;"
        )
        info.setWordWrap(True)
        layout.addWidget(info)

        # Test-Button
        row = QHBoxLayout()
        b_test = QPushButton("🔔 Test-Notification")
        b_test.clicked.connect(self._on_test)
        row.addWidget(b_test)
        b_clear = QPushButton("🗑 Leeren")
        b_clear.clicked.connect(self._on_clear)
        row.addWidget(b_clear)
        row.addStretch()
        layout.addLayout(row)

        # Tabelle
        self.table = QTableWidget(0, 4)
        self.table.setHorizontalHeaderLabels(["Zeit", "Level", "Titel", "Nachricht"])
        self.table.horizontalHeader().setSectionResizeMode(
            QHeaderView.ResizeMode.Stretch
        )
        self.table.setColumnWidth(0, 100)
        self.table.setColumnWidth(1, 90)
        self.table.setStyleSheet(
            "background:#0d1117;color:#d4d4d4;"
            "font-family:monospace;font-size:9pt;"
            "gridline-color:#2a2a2a;"
        )
        self.table.horizontalHeader().setStyleSheet("background:#2d2d2d;color:#2a82da;")
        layout.addWidget(self.table, 1)

    def refresh(self):
        center = NotificationCenter.get()
        hist = center.history(200)
        # Neueste zuerst
        hist = list(reversed(hist))
        self.table.setRowCount(0)
        for h in hist:
            row = self.table.rowCount()
            self.table.insertRow(row)
            t = datetime.fromtimestamp(h["ts"]).strftime("%H:%M:%S")
            self.table.setItem(row, 0, QTableWidgetItem(t))
            level = h.get("level", "INFO")
            litem = QTableWidgetItem(level)
            if level == "ERROR":
                litem.setForeground(QBrush(QColor(231, 76, 60)))
            elif level == "WARN":
                litem.setForeground(QBrush(QColor(243, 156, 18)))
            elif level == "SUCCESS":
                litem.setForeground(QBrush(QColor(39, 174, 96)))
            self.table.setItem(row, 1, litem)
            self.table.setItem(row, 2, QTableWidgetItem(h.get("title", "")))
            self.table.setItem(row, 3, QTableWidgetItem(h.get("message", "")))

    def _on_test(self):
        NotificationCenter.get().notify(
            "Test-Notification", "Dies ist eine Testnachricht.", "SUCCESS", popup=True
        )

    def _on_clear(self):
        center = NotificationCenter.get()
        center._history.clear()
        self.table.setRowCount(0)


