# ----------------------------------------------------------------
# A. IntegrityChecker
# ----------------------------------------------------------------
class IntegrityChecker:
    """Prüft das laufende w.py auf strukturelle Integrität."""

    @classmethod
    def check_gui_methods(cls, gui) -> dict:
        """Findet create_*_tab-Referenzen ohne passende Methode."""
        result = {
            "missing": [],
            "total_refs": 0,
            "total_defs": 0,
        }
        try:
            # Referenzen aus _create_all_tabs
            src = None
            try:
                src = Path(__file__).read_text(encoding="utf-8")
            except (OSError, NameError):
                # Fallback: sys.argv[0]
                try:
                    src = Path(sys.argv[0]).read_text(encoding="utf-8")
                except (OSError, IndexError):
                    src = ""
            if not src:
                return result
            refs = set(re.findall(r"self\.(create_\w+_tab)\b", src))
            defs = set(re.findall(r"def\s+(create_\w+_tab)\s*\(", src))
            result["total_refs"] = len(refs)
            result["total_defs"] = len(defs)
            missing = sorted(refs - defs)
            result["missing"] = missing
        except (AttributeError, TypeError, ValueError, OSError):
            pass
        return result

    @classmethod
    def check_method_attrs(cls, gui) -> list:
        """Prüft, ob alle in __init__ gesetzten _attrs existieren."""
        issues = []
        try:
            # Nur die im Konstruktor geprüften kritischen Attribute
            critical = [
                "_seen_networks",
                "_sniffers",
                "_channel_threads",
                "_lock",
                "_stop_event",
                "_pause_event",
                "_signals",
            ]
            for attr in critical:
                if not hasattr(gui, attr):
                    issues.append(f"GUI: attribut fehlt: {attr}")
        except (AttributeError, TypeError):
            pass
        return issues

    @classmethod
    def check_duplicates(cls) -> list:
        """Findet doppelte Methoden-Definitionen."""
        dups = []
        try:
            src = Path(sys.argv[0]).read_text(encoding="utf-8")
        except (OSError, IndexError):
            return dups
        # Zähle def-Methoden
        defs: dict = {}
        for m in re.finditer(r"^\s+def\s+(\w+)\s*\(", src, re.MULTILINE):
            name = m.group(1)
            defs[name] = defs.get(name, 0) + 1
        for name, n in defs.items():
            if n > 5:  # methoden die 5x vorkommen sind verdächtig
                dups.append((name, n))
        dups.sort(key=lambda x: -x[1])
        return dups


# ----------------------------------------------------------------
# B. ExternalToolChecker
# ----------------------------------------------------------------
class ExternalToolChecker:
    """Prüft externe Tools live."""

    REQUIRED = {
        "iw": "Kanal/Monitor",
        "ip": "Interface",
        "aircrack-ng": "WPA-Crack",
        "airodump-ng": "Capture",
        "aireplay-ng": "Deauth",
        "airmon-ng": "Monitor-Setup",
        "hcxdumptool": "PMKID",
        "hcxpcapngtool": "Konverter",
        "hashcat": "GPU-Crack",
        "airdecap-ng": "Decrypt",
        "tshark": "Frame-Analyse",
        "tcpdump": "Paket-Dump",
        "iwconfig": "iwconfig-Fallback",
        "wash": "WPS-Scan",
        "reaver": "WPS-PIN",
        "pixiewps": "Pixie-Dust",
        "bully": "WPS-Alt",
        "mdk4": "Flood",
        "macchanger": "MAC-Spoof",
        "hostapd": "AP-Mode",
        "dnsmasq": "DHCP/DNS",
        "bettercap": "MITM",
        "kismet": "Passiv-Scan",
        "nmap": "Port-Scan",
        "arp-scan": "ARP-Discovery",
        "mtr": "Path-Analyzer",
        "dig": "DNS",
        "whois": "WHOIS",
        "curl": "HTTP",
        "openssl": "TLS",
        "bluetoothctl": "BLE",
        "hcitool": "BLE",
        "gpsd": "GPS",
        "ethtool": "Adapter",
        "rfkill": "Funk-Sperre",
        "modprobe": "Kernel",
    }

    @classmethod
    def check(cls) -> dict:
        """Ergebnis: {name: {ok, path, desc}}."""
        result = {}
        for name, desc in cls.REQUIRED.items():
            path = shutil.which(name)
            result[name] = {
                "ok": path is not None,
                "path": path or "",
                "desc": desc,
            }
        return result

    @classmethod
    def summary(cls) -> dict:
        r = cls.check()
        total = len(r)
        ok = sum(1 for v in r.values() if v["ok"])
        return {
            "total": total,
            "ok": ok,
            "missing": total - ok,
            "detail": r,
        }


# ----------------------------------------------------------------
# C. RuntimeTabWalker
# ----------------------------------------------------------------
class RuntimeTabWalker:
    """Öffnet im Hintergrund jeden Tab und fängt Fehler."""

    @classmethod
    def walk_all_tabs(cls, gui, log_callback=None) -> list:
        """Wechselt durch alle Tabs. Gibt Fehler-Liste zurück.

        Achtung: Führt Qt-Methoden aus. Aus GUI-Thread aufrufen!
        """
        errors = []
        try:
            total = gui.tab_widget.count()
            orig_index = gui.tab_widget.currentIndex()
            for i in range(total):
                try:
                    gui.tab_widget.setCurrentIndex(i)
                    QApplication.processEvents()
                except Exception as e:
                    name = ""
                    try:
                        name = gui.tab_widget.tabText(i)
                    except (RuntimeError, AttributeError):
                        pass
                    errors.append(
                        {
                            "tab_index": i,
                            "tab_name": name,
                            "error": str(e)[:200],
                        }
                    )
                    if log_callback:
                        log_callback(f"Tab {i} ({name}): {e}")
            # Zurück zum Original
            try:
                gui.tab_widget.setCurrentIndex(orig_index)
            except (RuntimeError, AttributeError):
                pass
        except (AttributeError, RuntimeError) as e:
            errors.append(
                {
                    "tab_index": -1,
                    "tab_name": "alle",
                    "error": f"Walker-Fehler: {e}",
                }
            )
        return errors


# ----------------------------------------------------------------
# D. CodeAuditor
# ----------------------------------------------------------------
class CodeAuditor:
    """Findet toten Code und Duplikate in w.py."""

    @classmethod
    def audit(cls) -> dict:
        result = {
            "total_lines": 0,
            "total_classes": 0,
            "total_methods": 0,
            "duplicate_methods": [],
            "unused_imports": [],
            "huge_classes": [],
            "huge_methods": [],
        }
        try:
            path = Path(sys.argv[0])
            if not path.is_file():
                # Fallback __file__
                path = Path(__file__)
            src = path.read_text(encoding="utf-8")
            lines = src.split("\n")
            result["total_lines"] = len(lines)
        except (OSError, NameError, IndexError):
            return result

        # Klassen
        classes = re.findall(r"^class\s+(\w+)", src, re.MULTILINE)
        result["total_classes"] = len(classes)

        # Methoden
        methods = re.findall(r"^\s+def\s+(\w+)\s*\(", src, re.MULTILINE)
        result["total_methods"] = len(methods)

        # Duplikate
        counts: dict = {}
        for m in methods:
            counts[m] = counts.get(m, 0) + 1
        result["duplicate_methods"] = sorted(
            [(n, c) for n, c in counts.items() if c > 3], key=lambda x: -x[1]
        )[:20]

        # Riesige Klassen (mehr als 500 Zeilen)
        class_positions = []
        for m in re.finditer(r"^class\s+(\w+)", src, re.MULTILINE):
            class_positions.append((m.group(1), m.start()))
        for i, (name, start) in enumerate(class_positions):
            end = (
                class_positions[i + 1][1] if i + 1 < len(class_positions) else len(src)
            )
            sz = src[start:end].count("\n")
            if sz > 500:
                result["huge_classes"].append((name, sz))
        result["huge_classes"].sort(key=lambda x: -x[1])

        # Riesige Methoden (mehr als 100 Zeilen)
        method_positions = []
        for m in re.finditer(r"^\s+def\s+(\w+)\s*\(", src, re.MULTILINE):
            method_positions.append((m.group(1), m.start()))
        for i, (name, start) in enumerate(method_positions):
            end = (
                method_positions[i + 1][1]
                if i + 1 < len(method_positions)
                else len(src)
            )
            # Nur nächste Methode in derselben Klasse zählt,
            # aber einfache Näherung reicht
            sz = min(src[start:end].count("\n"), 500)
            if sz > 100:
                result["huge_methods"].append((name, sz))
        result["huge_methods"].sort(key=lambda x: -x[1])

        # Unbenutzte Imports (sehr simple Prüfung)
        imports = re.findall(r"^import\s+(\w+)", src, re.MULTILINE)
        imports += re.findall(r"^from\s+(\w+)\s+import", src, re.MULTILINE)
        for imp in set(imports):
            # Vorkommen außer der import-Zeile
            occurrences = len(re.findall(r"\b" + re.escape(imp) + r"\b", src))
            if occurrences <= 1:
                result["unused_imports"].append(imp)

        return result


# ----------------------------------------------------------------
# SelfTest-Gerüst (P7.1a): Severity, Report, Kategorien
# ----------------------------------------------------------------
SELFTEST_SCHEMA_VERSION = 1
SELFTEST_BAR_FULL = "\u2588"
SELFTEST_BAR_EMPTY = "\u2591"
SELFTEST_BAR_WIDTH = 24


def selftest_ascii_bar(ratio: float, width: int = SELFTEST_BAR_WIDTH) -> str:
    """Erzeugt ASCII-Balken fuer ratio in [0,1] mit fester Breite."""
    try:
        r = float(ratio)
    except (TypeError, ValueError):
        r = 0.0
    r = max(0.0, min(1.0, r))
    if width <= 0:
        return ""
    filled = round(r * width)
    return SELFTEST_BAR_FULL * filled + SELFTEST_BAR_EMPTY * (width - filled)


class SelfTestSeverity(Enum):
    """Schweregrad eines SelfTest-Ergebnisses."""
    OK = "OK"
    WARN = "WARN"
    FAIL = "FAIL"
    SKIP = "SKIP"


@dataclass
class SelfTestResult:
    """Ein einzelnes SelfTest-Ergebnis."""
    name: str
    severity: SelfTestSeverity
    detail: str = ""
    value: str = ""

    def to_dict(self) -> dict:
        return {
            "name": self.name,
            "severity": self.severity.value,
            "detail": self.detail,
            "value": self.value,
        }


@dataclass
class SelfTestCategoryResult:
    """Ergebnis einer SelfTest-Kategorie."""
    name: str
    description: str = ""
    results: list = field(default_factory=list)

    def counts(self) -> dict:
        c = {"OK": 0, "WARN": 0, "FAIL": 0, "SKIP": 0}
        for r in self.results:
            c[r.severity.value] = c.get(r.severity.value, 0) + 1
        return c

    def aggregate(self) -> SelfTestSeverity:
        sevs = {r.severity for r in self.results}
        if not sevs:
            return SelfTestSeverity.SKIP
        if SelfTestSeverity.FAIL in sevs:
            return SelfTestSeverity.FAIL
        if SelfTestSeverity.WARN in sevs:
            return SelfTestSeverity.WARN
        if sevs == {SelfTestSeverity.SKIP}:
            return SelfTestSeverity.SKIP
        return SelfTestSeverity.OK

    def score(self) -> int:
        total = 0
        bad = 0.0
        for r in self.results:
            if r.severity == SelfTestSeverity.SKIP:
                continue
            total += 1
            if r.severity == SelfTestSeverity.FAIL:
                bad += 1.0
            elif r.severity == SelfTestSeverity.WARN:
                bad += 0.5
        if total == 0:
            return 100
        return max(0, round(100 * (1 - bad / total)))

    def score_bar(self, width: int = SELFTEST_BAR_WIDTH) -> str:
        return selftest_ascii_bar(self.score() / 100.0, width)

    def histogram(self) -> dict:
        c = self.counts()
        total = sum(c.values())
        out = {}
        for k in ("OK", "WARN", "FAIL", "SKIP"):
            v = c.get(k, 0)
            ratio = (v / total) if total > 0 else 0.0
            out[k] = {
                "count": v,
                "ratio": round(ratio, 4),
                "bar": selftest_ascii_bar(ratio, 12),
            }
        return out

    def to_dict(self) -> dict:
        return {
            "name": self.name,
            "description": self.description,
            "aggregate": self.aggregate().value,
            "score": self.score(),
            "bar": self.score_bar(),
            "counts": self.counts(),
            "histogram": self.histogram(),
            "results": [r.to_dict() for r in self.results],
        }


@dataclass
class SelfTestReport:
    """Gesamtbericht über alle SelfTest-Kategorien."""
    timestamp: str = ""
    categories: list = field(default_factory=list)

    def __post_init__(self):
        if not self.timestamp:
            self.timestamp = datetime.now().isoformat(timespec="seconds")

    def overall(self) -> SelfTestSeverity:
        sevs = {c.aggregate() for c in self.categories}
        if SelfTestSeverity.FAIL in sevs:
            return SelfTestSeverity.FAIL
        if SelfTestSeverity.WARN in sevs:
            return SelfTestSeverity.WARN
        if not sevs or sevs == {SelfTestSeverity.SKIP}:
            return SelfTestSeverity.SKIP
        return SelfTestSeverity.OK

    def score(self) -> int:
        total = 0
        bad = 0.0
        for c in self.categories:
            for r in c.results:
                if r.severity == SelfTestSeverity.SKIP:
                    continue
                total += 1
                if r.severity == SelfTestSeverity.FAIL:
                    bad += 1.0
                elif r.severity == SelfTestSeverity.WARN:
                    bad += 0.5
        if total == 0:
            return 100
        return max(0, round(100 * (1 - bad / total)))

    def score_bar(self, width: int = SELFTEST_BAR_WIDTH) -> str:
        return selftest_ascii_bar(self.score() / 100.0, width)

    def severity_counts(self) -> dict:
        c = {"OK": 0, "WARN": 0, "FAIL": 0, "SKIP": 0}
        for cat in self.categories:
            for k, v in cat.counts().items():
                c[k] = c.get(k, 0) + v
        return c

    def summary_line(self) -> str:
        c = self.severity_counts()
        return (
            f"SelfTest: {self.overall().value}"
            f" | Score {self.score()}/100"
            f" | OK={c['OK']} WARN={c['WARN']}"
            f" FAIL={c['FAIL']} SKIP={c['SKIP']}"
        )

    def failing_categories(self) -> list:
        return [
            c for c in self.categories
            if c.aggregate() in (SelfTestSeverity.FAIL,
                                 SelfTestSeverity.WARN)
        ]

    def to_markdown(self) -> str:
        lines = []
        lines.append("# SelfTest-Report")
        lines.append("")
        lines.append(f"- **Zeitpunkt**: {self.timestamp}")
        lines.append(f"- **Gesamt**: `{self.overall().value}`")
        lines.append(
            f"- **Score**: `{self.score()}/100`  {self.score_bar()}"
        )
        lines.append("")
        lines.append(
            "| Kategorie | Status | Score | OK | WARN | FAIL | SKIP |"
        )
        lines.append("|---|---|---|---|---|---|---|")
        for c in self.categories:
            cnt = c.counts()
            lines.append(
                f"| {c.name} | {c.aggregate().value} | "
                f"{c.score()} | {cnt['OK']} | {cnt['WARN']} | "
                f"{cnt['FAIL']} | {cnt['SKIP']} |"
            )
        lines.append("")
        for c in self.categories:
            lines.append(
                f"## {c.name}  ({c.aggregate().value}, "
                f"Score {c.score()}/100)"
            )
            if c.description:
                lines.append(f"_{c.description}_")
            lines.append("")
            for r in c.results:
                val = f" `{r.value}`" if r.value else ""
                det = f" - {r.detail}" if r.detail else ""
                lines.append(f"- [{r.severity.value}] {r.name}{val}{det}")
            lines.append("")
        return "\n".join(lines)

    def to_csv(self) -> str:
        import io
        buf = io.StringIO()
        w = csv.writer(buf)
        w.writerow(["category", "check", "severity", "value", "detail"])
        for c in self.categories:
            for r in c.results:
                w.writerow(
                    [c.name, r.name, r.severity.value, r.value, r.detail]
                )
        return buf.getvalue()

    def to_dict(self) -> dict:
        return {
            "schema_version": SELFTEST_SCHEMA_VERSION,
            "timestamp": self.timestamp,
            "overall": self.overall().value,
            "score": self.score(),
            "bar": self.score_bar(),
            "severity_counts": self.severity_counts(),
            "categories": [c.to_dict() for c in self.categories],
        }

    def to_json(self, indent: int = 2) -> str:
        return json.dumps(self.to_dict(), indent=indent, ensure_ascii=False)

    def to_text(self) -> str:
        lines = []
        lines.append("=" * 60)
        lines.append("  SELFTEST-REPORT")
        lines.append("=" * 60)
        lines.append(f"Zeitpunkt:  {self.timestamp}")
        lines.append(
            f"Gesamt:     {self.overall().value}    "
            f"Score: {self.score()}/100  {self.score_bar()}"
        )
        _sc = self.severity_counts()
        lines.append(
            f"Bilanz:     OK={_sc['OK']}  "
            f"WARN={_sc['WARN']}  "
            f"FAIL={_sc['FAIL']}  "
            f"SKIP={_sc['SKIP']}"
        )
        lines.append("")
        for c in self.categories:
            agg = c.aggregate().value
            cnt = c.counts()
            lines.append(
                f"[{agg}] {c.name}  "
                f"Score {c.score()}/100  {c.score_bar(16)}"
            )
            lines.append(
                f"      ({cnt['OK']} OK / {cnt['WARN']} WARN / "
                f"{cnt['FAIL']} FAIL / {cnt['SKIP']} SKIP)"
            )
            if c.description:
                lines.append(f"      {c.description}")
            for r in c.results:
                val = f" = {r.value}" if r.value else ""
                det = f"  \u2014 {r.detail}" if r.detail else ""
                lines.append(f"  - [{r.severity.value:4}] {r.name}{val}{det}")
            lines.append("")
        return "\n".join(lines)



class HtmlReportGenerator:
    """Standalone-HTML-Report aus einem SelfTestReport.

    Reine String-Logik, kein GUI-Code. Ausgabe ist ein
    eigenstaendiges HTML-Dokument ohne externe Ressourcen.
    """

    _CSS = """body{font-family:monospace;background:#1a1a1a;
color:#d4d4d4;margin:0;padding:24px;}
h1{color:#2a82da;margin:0 0 4px 0;}
h2{color:#2a82da;border-bottom:1px solid #444;padding-bottom:4px;
margin-top:32px;}
.meta{color:#7f8c8d;font-size:9pt;margin:8px 0;}
.kacheln{display:flex;gap:12px;margin:16px 0;flex-wrap:wrap;}
.kachel{background:#242424;border:1px solid #444;border-radius:6px;
padding:12px 20px;min-width:80px;text-align:center;}
.kachel .zahl{font-size:20pt;font-weight:bold;display:block;}
.kachel .label{font-size:8pt;color:#7f8c8d;text-transform:uppercase;}
.OK{color:#27ae60;}
.WARN{color:#f39c12;}
.FAIL{color:#e74c3c;}
.SKIP{color:#7f8c8d;}
table{border-collapse:collapse;width:100%;margin-top:8px;}
th,td{text-align:left;padding:6px 10px;border-bottom:1px solid #333;}
th{background:#242424;color:#2a82da;}
td.sev{font-weight:bold;width:70px;}
td.val{color:#7f8c8d;font-size:9pt;}
tr:hover{background:#242424;}
.score-box{font-size:28pt;font-weight:bold;color:#2a82da;margin:8px 0;}
footer{color:#7f8c8d;font-size:8pt;margin-top:32px;
border-top:1px solid #333;padding-top:8px;}
"""

    def __init__(self, report: SelfTestReport):
        self.report = report

    @staticmethod
    def _esc(value) -> str:
        """HTML-Escaping fuer Text- und Attributwerte."""
        if value is None:
            return ""
        s = str(value)
        return (s.replace("&", "&amp;")
                 .replace("<", "&lt;")
                 .replace(">", "&gt;")
                 .replace('"', "&quot;"))

    def _kacheln(self) -> str:
        c = self.report.severity_counts()
        parts = ['<div class="kacheln">']
        for key in ("OK", "WARN", "FAIL", "SKIP"):
            parts.append(
                '<div class="kachel">'
                f'<span class="zahl {key}">{c.get(key, 0)}</span>'
                f'<span class="label">{key}</span></div>'
            )
        parts.append("</div>")
        return "\n".join(parts)

    @staticmethod
    def _svg_bar(
        y: int,
        width: int,
        height: int,
        ratio: float,
        color: str,
        label: str,
        value_text: str,
    ) -> str:
        """Eine horizontale SVG-Balkenzeile (Breite 480px)."""
        ratio = max(0.0, min(1.0, ratio))
        bar_w = int(width * ratio)
        return (
            f'<rect x="120" y="{y}" width="{width}" height="{height}"'
            ' fill="#242424" stroke="#333"/>'
            f'<rect x="120" y="{y}" width="{bar_w}" height="{height}"'
            f' fill="{color}"/>'
            f'<text x="0" y="{y + height - 4}" fill="#d4d4d4"'
            ' font-size="11" font-family="monospace">'
            f'{label}</text>'
            f'<text x="{130 + width}" y="{y + height - 4}"'
            ' fill="#7f8c8d" font-size="10" font-family="monospace">'
            f'{value_text}</text>'
        )

    def _chart_severities(self) -> str:
        """Horizontale Balken: Severity-Verteilung."""
        c = self.report.severity_counts()
        total = sum(c.values()) or 1
        colors = {
            "OK": "#27ae60",
            "WARN": "#f39c12",
            "FAIL": "#e74c3c",
            "SKIP": "#7f8c8d",
        }
        parts = [
            '<svg viewBox="0 0 640 140" width="100%" '
            'preserveAspectRatio="xMidYMid meet" '
            'xmlns="http://www.w3.org/2000/svg">'
        ]
        y = 10
        for key in ("OK", "WARN", "FAIL", "SKIP"):
            v = c.get(key, 0)
            parts.append(self._svg_bar(
                y=y, width=440, height=22,
                ratio=(v / total), color=colors[key],
                label=key, value_text=f"{v}",
            ))
            y += 30
        parts.append("</svg>")
        return "\n".join(parts)

    def _chart_category_scores(self) -> str:
        """Horizontale Balken: Score je Kategorie."""
        cats = self.report.categories
        if not cats:
            return ""
        colors = {
            "OK": "#27ae60",
            "WARN": "#f39c12",
            "FAIL": "#e74c3c",
            "SKIP": "#7f8c8d",
        }
        height = 10 + 30 * len(cats)
        parts = [
            f'<svg viewBox="0 0 640 {height}" width="100%" '
            'preserveAspectRatio="xMidYMid meet" '
            'xmlns="http://www.w3.org/2000/svg">'
        ]
        y = 10
        for cat in cats:
            name = cat.name if len(cat.name) <= 14 else cat.name[:13] + "…"
            parts.append(self._svg_bar(
                y=y, width=440, height=22,
                ratio=(cat.score() / 100.0),
                color=colors.get(cat.aggregate().value, "#7f8c8d"),
                label=self._esc(name),
                value_text=f"{cat.score()}/100",
            ))
            y += 30
        parts.append("</svg>")
        return "\n".join(parts)

    def _category_table(self, cat: SelfTestCategoryResult) -> str:
        agg = cat.aggregate().value
        parts = [
            f"<h2>{self._esc(cat.name)} "
            f'<span class="{agg}">[{agg}]</span>'
            f" &mdash; Score {cat.score()}/100</h2>"
        ]
        if cat.description:
            parts.append(
                f'<p class="meta">{self._esc(cat.description)}</p>'
            )
        parts.append("<table>")
        parts.append(
            "<tr><th>Check</th><th>Status</th>"
            "<th>Wert</th><th>Detail</th></tr>"
        )
        for r in cat.results:
            sev = r.severity.value
            parts.append(
                "<tr>"
                f"<td>{self._esc(r.name)}</td>"
                f'<td class="sev {sev}">{sev}</td>'
                f'<td class="val">{self._esc(r.value)}</td>'
                f"<td>{self._esc(r.detail)}</td>"
                "</tr>"
            )
        parts.append("</table>")
        return "\n".join(parts)

    def to_html(self) -> str:
        """Erzeugt das vollstaendige HTML-Dokument als String."""
        r = self.report
        agg = r.overall().value
        parts = [
            "<!DOCTYPE html>",
            '<html lang="de">',
            "<head>",
            '<meta charset="utf-8">',
            '<meta name="viewport" '
            'content="width=device-width,initial-scale=1">',
            f"<title>SelfTest-Report -- {self._esc(r.timestamp)}</title>",
            f"<style>{self._CSS}</style>",
            "</head>",
            "<body>",
            f"<h1>SelfTest-Report "
            f'<span class="{agg}">[{agg}]</span></h1>',
            f'<div class="meta">Zeitpunkt: {self._esc(r.timestamp)}'
            f" &middot; Schema v{SELFTEST_SCHEMA_VERSION}</div>",
            f'<div class="score-box">{r.score()}/100</div>',
            self._kacheln(),
        ]
        if self.report.categories:
            parts.append(
                '<h2 style="margin-top:24px">Verteilung</h2>'
            )
            parts.append(self._chart_severities())
            parts.append(
                '<h2 style="margin-top:24px">Kategorie-Scores</h2>'
            )
            parts.append(self._chart_category_scores())
        if not r.categories:
            parts.append("<p><em>Keine Kategorien im Report.</em></p>")
        else:
            fails = r.failing_categories()
            if fails:
                parts.append(
                    f'<p class="meta">{len(fails)} Kategorie(n) mit '
                    "WARN oder FAIL &mdash; siehe unten.</p>"
                )
            for cat in r.categories:
                parts.append(self._category_table(cat))
        parts.append(
            "<footer>Erzeugt aus SelfTestReport "
            f"(Schema v{SELFTEST_SCHEMA_VERSION})</footer>"
        )
        parts.append("</body>")
        parts.append("</html>")
        return "\n".join(parts)

    def to_file(self, path) -> None:
        """Schreibt den HTML-Report als UTF-8-Datei."""
        Path(path).write_text(self.to_html(), encoding="utf-8")


class SelfTestCategory:
    """Basisklasse für SelfTest-Kategorien."""
    NAME = "Kategorie"
    DESCRIPTION = ""

    def run(self) -> SelfTestCategoryResult:
        raise NotImplementedError


class SystemSelfTest(SelfTestCategory):
    """Prüft Systemumgebung: OS, Kernel, User, Ressourcen."""
    NAME = "System"
    DESCRIPTION = "OS, Kernel, Python, User, Ressourcen"

    def run(self) -> SelfTestCategoryResult:
        res = SelfTestCategoryResult(self.NAME, self.DESCRIPTION)
        try:
            res.results.append(SelfTestResult(
                "Betriebssystem", SelfTestSeverity.OK,
                detail=platform.platform(),
            ))
        except Exception as e:
            res.results.append(SelfTestResult(
                "Betriebssystem", SelfTestSeverity.WARN, detail=str(e)[:120],
            ))

        try:
            res.results.append(SelfTestResult(
                "Kernel", SelfTestSeverity.OK, value=platform.release(),
            ))
        except Exception as e:
            res.results.append(SelfTestResult(
                "Kernel", SelfTestSeverity.WARN, detail=str(e)[:120],
            ))

        try:
            py = (f"{sys.version_info.major}."
                  f"{sys.version_info.minor}."
                  f"{sys.version_info.micro}")
            sev = (SelfTestSeverity.OK if sys.version_info >= (3, 9)
                   else SelfTestSeverity.WARN)
            res.results.append(SelfTestResult("Python", sev, value=py))
        except Exception as e:
            res.results.append(SelfTestResult(
                "Python", SelfTestSeverity.WARN, detail=str(e)[:120],
            ))

        try:
            uid = os.getuid() if hasattr(os, "getuid") else -1
            if uid == 0:
                res.results.append(SelfTestResult(
                    "User", SelfTestSeverity.OK, value="root",
                ))
            else:
                res.results.append(SelfTestResult(
                    "User", SelfTestSeverity.WARN, value=f"uid={uid}",
                    detail="Nicht root \u2014 einige Tests ben\u00f6tigen erh\u00f6hte Rechte",
                ))
        except Exception as e:
            res.results.append(SelfTestResult(
                "User", SelfTestSeverity.WARN, detail=str(e)[:120],
            ))

        try:
            res.results.append(SelfTestResult(
                "CWD", SelfTestSeverity.OK, value=str(Path.cwd()),
            ))
        except Exception as e:
            res.results.append(SelfTestResult(
                "CWD", SelfTestSeverity.WARN, detail=str(e)[:120],
            ))

        try:
            du = shutil.disk_usage(str(Path.home()))
            free_gb = du.free / (1024 ** 3)
            if free_gb >= 1:
                sev = SelfTestSeverity.OK
            elif free_gb >= 0.2:
                sev = SelfTestSeverity.WARN
            else:
                sev = SelfTestSeverity.FAIL
            res.results.append(SelfTestResult(
                "Freier Speicher (Home)", sev, value=f"{free_gb:.1f} GiB",
            ))
        except Exception as e:
            res.results.append(SelfTestResult(
                "Freier Speicher (Home)", SelfTestSeverity.WARN,
                detail=str(e)[:120],
            ))

        return res


class ToolsSelfTest(SelfTestCategory):
    """Prüft Verfügbarkeit der externen Tools."""
    NAME = "Tools"
    DESCRIPTION = "Externe Tools (iw, aircrack-ng, hostapd, ...)"

    def run(self) -> SelfTestCategoryResult:
        res = SelfTestCategoryResult(self.NAME, self.DESCRIPTION)
        try:
            summary = ExternalToolChecker.summary()
            missing = [n for n, v in summary["detail"].items() if not v["ok"]]
            sev = (SelfTestSeverity.OK if summary["missing"] == 0
                   else SelfTestSeverity.WARN)
            res.results.append(SelfTestResult(
                "Externe Tools", sev,
                value=f"{summary['ok']}/{summary['total']} verf\u00fcgbar",
                detail=(", fehlen: " + ", ".join(missing)) if missing else "",
            ))
            for name, info in sorted(summary["detail"].items()):
                s = (SelfTestSeverity.OK if info["ok"]
                     else SelfTestSeverity.WARN)
                res.results.append(SelfTestResult(
                    f"  {name}", s,
                    detail=info.get("desc", ""),
                    value=info.get("path", "") or "",
                ))
        except Exception as e:
            res.results.append(SelfTestResult(
                "Tools", SelfTestSeverity.FAIL, detail=str(e)[:160],
            ))
        return res


def evaluate_txpower_compliance(
    tp_dbm, channel=None, reg_domain="DE"
) -> tuple:
    """P6.5: Bewertet Adapter-Ist-TX-Power gegen Reg-Domain-Limit.

    Returns (SelfTestSeverity, message). Kanal unbekannt -> konservativ
    2.4-GHz-Limit. Wird nur fuer Adapter-Defaults verwendet (nicht
    fuer vom Skript gesetzte Werte, das macht EvilTwinConfig).
    """
    try:
        tp = float(tp_dbm or 0)
    except (TypeError, ValueError):
        tp = 0.0
    if tp <= 0:
        return SelfTestSeverity.SKIP, "auto (Treiber/Reg-Domain)"

    domain = (reg_domain or "DE").upper()
    limits = {
        "DE": (20, 30),
        "BO": (30, 30),
        "US": (30, 30),
        "JP": (20, 30),
    }
    max_24, max_5 = limits.get(domain, (20, 30))

    ch = None
    try:
        if channel is not None:
            ch = int(channel)
    except (TypeError, ValueError):
        ch = None

    if ch is None:
        limit = max_24
        band = "2.4 GHz (Kanal unbekannt)"
    elif 1 <= ch <= 14:
        limit = max_24
        band = f"2.4 GHz (Kanal {ch})"
    elif ch >= 36:
        limit = max_5
        band = f"5 GHz (Kanal {ch})"
    else:
        return (
            SelfTestSeverity.SKIP,
            f"Kanal {ch} ausserhalb bekannter Baender",
        )

    if tp <= limit:
        return SelfTestSeverity.OK, (
            f"{tp:.0f} dBm <= {limit} dBm ({domain}, {band})"
        )
    return SelfTestSeverity.WARN, (
        f"{tp:.0f} dBm > {limit} dBm Limit fuer {domain} "
        f"({band}) — Adapter-Default, nicht vom Skript gesetzt"
    )


class AdapterSelfTest(SelfTestCategory):
    """Prueft WLAN-Adapter + Rollenvorschlag via AdapterCapabilities."""

    NAME = "Adapter"
    DESCRIPTION = "WLAN-Adapter (Fingerprint, Modi, Rollen)"

    def run(self) -> SelfTestCategoryResult:
        res = SelfTestCategoryResult(self.NAME, self.DESCRIPTION)
        try:
            adapters = AdapterCapabilities.detect()
        except Exception as e:
            res.results.append(SelfTestResult(
                "Adapter-Erkennung", SelfTestSeverity.FAIL,
                detail=str(e)[:160],
            ))
            return res

        if not adapters:
            res.results.append(SelfTestResult(
                "Adapter", SelfTestSeverity.FAIL,
                detail="Keine WLAN-Adapter erkannt (iw dev leer)",
            ))
            return res

        n = len(adapters)
        sev = SelfTestSeverity.OK if n >= 2 else SelfTestSeverity.WARN
        res.results.append(SelfTestResult(
            "Adapter-Anzahl", sev, value=str(n),
            detail="" if n >= 2 else "Nur ein Adapter — Deauth+AP parallel begrenzt",
        ))

        for a in adapters:
            caps = a.caps_str()
            detail = f"phy={a.phy or '?'} type={a.iftype or '?'} caps={caps}"
            if a.txpower_dbm:
                detail += f" tx={a.txpower_dbm:.0f}dBm"
            s_ = SelfTestSeverity.OK
            if not a.can_monitor and not a.can_ap:
                s_ = SelfTestSeverity.WARN
            res.results.append(SelfTestResult(
                f"  {a.fingerprint_full()}", s_,
                value=caps, detail=detail,
            ))
            # P6.6: Hinweis bei iwconfig-Fallback
            if getattr(a, "source", "iw") != "iw":
                res.results.append(SelfTestResult(
                    f"  {a.fingerprint_full()} Quelle",
                    SelfTestSeverity.WARN,
                    value=a.source,
                    detail=(
                        "Adapter via iwconfig erkannt \u2014 "
                        "Modi-Faehigkeiten evtl. unvollstaendig"
                    ),
                ))
            # P6.5: TX-Power-Compliance (Adapter-Default)
            if a.txpower_dbm and a.txpower_dbm > 0:
                sev_tp, msg_tp = evaluate_txpower_compliance(
                    a.txpower_dbm, a.channel, "DE"
                )
                res.results.append(SelfTestResult(
                    f"  {a.fingerprint_full()} TX-Power",
                    sev_tp,
                    value=f"{a.txpower_dbm:.0f} dBm",
                    detail=msg_tp,
                ))

        try:
            ap, deauth = AdapterCapabilities.suggest_roles(adapters)
            ok = bool(ap) and bool(deauth)
            res.results.append(SelfTestResult(
                "Rollen-Vorschlag",
                SelfTestSeverity.OK if ok else SelfTestSeverity.WARN,
                value=f"ap={ap or '—'} deauth={deauth or '—'}",
                detail="" if ok else "Nicht beide Rollen abdeckbar",
            ))
        except Exception as e:
            res.results.append(SelfTestResult(
                "Rollen-Vorschlag", SelfTestSeverity.WARN,
                detail=str(e)[:120],
            ))

        return res


class FilesystemSelfTest(SelfTestCategory):
    """Prueft Konfig-Verzeichnisse: Existenz, Rechte, Schreibbarkeit."""

    NAME = "Filesystem"
    DESCRIPTION = "Konfig-, Log-, Capture-, Backup-Verzeichnisse"

    _DIRS = [
        ("KONFIG_DIR", "Konfig-Wurzel"),
        ("LOG_DIR", "Logs"),
        ("REPORT_DIR", "Reports"),
        ("CAPTURE_DIR", "Captures"),
        ("EXPORT_DIR", "Exports"),
        ("TEMP_DIR", "Temp"),
        ("BACKUP_DIR", "Backups"),
        ("CACHE_DIR", "Cache"),
    ]

    def run(self) -> SelfTestCategoryResult:
        res = SelfTestCategoryResult(self.NAME, self.DESCRIPTION)

        for attr, desc in self._DIRS:
            d = getattr(AppKonstanten, attr, None)
            if d is None:
                res.results.append(SelfTestResult(
                    f"{attr} ({desc})", SelfTestSeverity.WARN,
                    detail="Konstante nicht definiert",
                ))
                continue

            p = Path(d)
            if not p.exists():
                # Nicht-FATAL — wird bei Bedarf angelegt
                res.results.append(SelfTestResult(
                    f"{attr} ({desc})", SelfTestSeverity.SKIP,
                    value=str(p), detail="existiert noch nicht",
                ))
                continue

            if not p.is_dir():
                res.results.append(SelfTestResult(
                    f"{attr} ({desc})", SelfTestSeverity.FAIL,
                    value=str(p), detail="Pfad ist kein Verzeichnis",
                ))
                continue

            # Rechte-Check
            try:
                mode = p.stat().st_mode & 0o777
                if mode & 0o077:
                    sev = SelfTestSeverity.WARN
                    det = (
                        f"Rechte {oct(mode)} — empfohlen 0o700 "
                        "(wird beim naechsten Start korrigiert)"
                    )
                else:
                    sev = SelfTestSeverity.OK
                    det = f"Rechte {oct(mode)}"
            except OSError as e:
                sev = SelfTestSeverity.WARN
                det = f"stat fehlgeschlagen: {e}"

            res.results.append(SelfTestResult(
                f"{attr} ({desc})", sev, value=str(p), detail=det,
            ))

        # Schreibtest im KONFIG_DIR (falls existiert)
        kd = getattr(AppKonstanten, "KONFIG_DIR", None)
        if kd is not None and Path(kd).is_dir():
            try:
                with tempfile.NamedTemporaryFile(
                    dir=str(kd), prefix=".selftest_", delete=True,
                ) as fh:
                    fh.write(b"ok")
                    fh.flush()
                res.results.append(SelfTestResult(
                    "Schreibtest KONFIG_DIR", SelfTestSeverity.OK,
                    value=str(kd),
                ))
            except OSError as e:
                res.results.append(SelfTestResult(
                    "Schreibtest KONFIG_DIR", SelfTestSeverity.FAIL,
                    detail=str(e)[:160],
                ))

        # Freier Platz in Home
        try:
            du = shutil.disk_usage(str(Path.home()))
            free_gb = du.free / (1024 ** 3)
            sev = (SelfTestSeverity.OK if free_gb >= 1
                   else SelfTestSeverity.WARN if free_gb >= 0.2
                   else SelfTestSeverity.FAIL)
            res.results.append(SelfTestResult(
                "Speicher frei (Home)", sev, value=f"{free_gb:.1f} GiB",
            ))
        except OSError as e:
            res.results.append(SelfTestResult(
                "Speicher frei (Home)", SelfTestSeverity.WARN,
                detail=str(e)[:120],
            ))

        return res


class PersistenceSelfTest(SelfTestCategory):
    """Prueft Persistenz: SQLite-DB (read-only), KeyStore, HandshakeLibrary."""

    NAME = "Persistenz"
    DESCRIPTION = "CentralStore-SQLite, KeyStore, HandshakeLibrary"

    def run(self) -> SelfTestCategoryResult:
        res = SelfTestCategoryResult(self.NAME, self.DESCRIPTION)

        db_path = getattr(AppKonstanten, "DATENBANK", None)
        if db_path is None:
            res.results.append(SelfTestResult(
                "DATENBANK-Konstante", SelfTestSeverity.WARN,
                detail="AppKonstanten.DATENBANK fehlt",
            ))
        else:
            p = Path(db_path)
            if not p.exists():
                res.results.append(SelfTestResult(
                    "CentralStore-DB", SelfTestSeverity.SKIP,
                    value=str(p),
                    detail="existiert noch nicht (wird beim ersten Zugriff angelegt)",
                ))
            else:
                # Read-only + quick_check — KEINE Migration, KEIN INSERT
                try:
                    uri = f"file:{p}?mode=ro"
                    conn = sqlite3.connect(uri, uri=True, timeout=2)
                    try:
                        cur = conn.execute("PRAGMA quick_check")
                        row = cur.fetchone()
                        status = (row[0] if row else "?")
                    finally:
                        conn.close()
                    sev = (SelfTestSeverity.OK if status == "ok"
                           else SelfTestSeverity.FAIL)
                    res.results.append(SelfTestResult(
                        "CentralStore-DB quick_check", sev,
                        value=str(p), detail=status,
                    ))
                except sqlite3.Error as e:
                    res.results.append(SelfTestResult(
                        "CentralStore-DB quick_check", SelfTestSeverity.FAIL,
                        value=str(p), detail=str(e)[:160],
                    ))

        # Instanziierbarkeit (idempotente Schema-Sicherung)
        for label, factory in (
            ("KeyStore", lambda: KeyStore()),
            ("HandshakeLibrary", lambda: HandshakeLibrary()),
        ):
            try:
                obj = factory()
                res.results.append(SelfTestResult(
                    f"{label} instanziierbar", SelfTestSeverity.OK,
                ))
                # leichte Nutzbarkeit
                if label == "KeyStore" and hasattr(obj, "count"):
                    try:
                        n = obj.count()
                        res.results.append(SelfTestResult(
                            f"{label}.count()", SelfTestSeverity.OK,
                            value=str(n),
                        ))
                    except Exception as e:
                        res.results.append(SelfTestResult(
                            f"{label}.count()", SelfTestSeverity.WARN,
                            detail=str(e)[:120],
                        ))
            except Exception as e:
                res.results.append(SelfTestResult(
                    f"{label} instanziierbar", SelfTestSeverity.WARN,
                    detail=str(e)[:160],
                ))

        return res


class NetworkSelfTest(SelfTestCategory):
    """Prueft Netzwerk: iptables-Chain, Orphan-Prozesse, relevante Ports.

    Read-only: fuehrt keine Aenderungen aus, killt nichts.
    """

    NAME = "Netzwerk"
    DESCRIPTION = "iptables-Chain, Orphan-Prozesse, relevante Ports"

    CHAIN = "EVILTWIN"
    ORPHAN_PATTERNS = (
        ("hostapd /tmp/evil_twin_", "hostapd"),
        ("dnsmasq -C /tmp/evil_twin_", "dnsmasq"),
    )
    RELEVANT_PORTS = (53, 80, 443, 8080)

    @staticmethod
    def _run(cmd, timeout=3):
        try:
            r = subprocess.run(
                cmd, capture_output=True, text=True,
                timeout=timeout, check=False,
            )
            return r.returncode, (r.stdout or ""), (r.stderr or "")
        except (OSError, subprocess.SubprocessError):
            return -1, "", ""

    def _check_iptables(self, res):
        rc, out, _ = self._run(
            ["iptables", "-t", "nat", "-S", self.CHAIN]
        )
        if rc != 0:
            res.results.append(SelfTestResult(
                f"iptables-Chain {self.CHAIN}",
                SelfTestSeverity.OK,
                detail="Chain nicht vorhanden (sauber)",
            ))
            return
        rules = [
            ln for ln in out.splitlines()
            if ln.strip() and not ln.strip().startswith("-N")
        ]
        if not rules:
            res.results.append(SelfTestResult(
                f"iptables-Chain {self.CHAIN}",
                SelfTestSeverity.SKIP,
                value="leer",
                detail="Chain existiert, enthaelt aber keine Regeln",
            ))
        else:
            res.results.append(SelfTestResult(
                f"iptables-Chain {self.CHAIN}",
                SelfTestSeverity.WARN,
                value=f"{len(rules)} Regel(n)",
                detail="Chain aktiv \u2014 Leak, falls kein Angriff laeuft",
            ))

    def _check_orphans(self, res):
        for pattern, label in self.ORPHAN_PATTERNS:
            rc, out, _ = self._run(["pgrep", "-af", pattern])
            lines = [ln for ln in out.splitlines() if ln.strip()]
            if rc == 0 and lines:
                res.results.append(SelfTestResult(
                    f"Orphan {label}",
                    SelfTestSeverity.WARN,
                    value=f"{len(lines)} Prozess(e)",
                    detail=lines[0][:160],
                ))
            else:
                res.results.append(SelfTestResult(
                    f"Orphan {label}",
                    SelfTestSeverity.OK,
                    detail="keine laufenden Instanzen",
                ))

    def _check_ports(self, res):
        rc, out, _ = self._run(["ss", "-tulpnH"])
        if rc != 0 or not out.strip():
            res.results.append(SelfTestResult(
                "Port-Scan (ss)", SelfTestSeverity.SKIP,
                detail="ss nicht verfuegbar oder leer",
            ))
            return
        found = {}
        for ln in out.splitlines():
            parts = ln.split()
            if len(parts) < 5:
                continue
            local = parts[4]
            m = re.search(r"[:*](\d+)$", local)
            if not m:
                continue
            port = int(m.group(1))
            if port not in self.RELEVANT_PORTS:
                continue
            m2 = re.search(r'users:\(\("([^"]+)"', ln)
            proc = m2.group(1) if m2 else "?"
            found.setdefault(port, set()).add(proc)
        for port in self.RELEVANT_PORTS:
            if port in found:
                res.results.append(SelfTestResult(
                    f"Port {port} LISTEN",
                    SelfTestSeverity.OK,
                    value=", ".join(sorted(found[port])),
                ))
            else:
                res.results.append(SelfTestResult(
                    f"Port {port} LISTEN",
                    SelfTestSeverity.SKIP,
                    detail="nicht belegt",
                ))

    def run(self) -> SelfTestCategoryResult:
        res = SelfTestCategoryResult(self.NAME, self.DESCRIPTION)
        try:
            self._check_iptables(res)
        except Exception as e:
            res.results.append(SelfTestResult(
                "iptables-Check", SelfTestSeverity.WARN,
                detail=str(e)[:160],
            ))
        try:
            self._check_orphans(res)
        except Exception as e:
            res.results.append(SelfTestResult(
                "Orphan-Check", SelfTestSeverity.WARN,
                detail=str(e)[:160],
            ))
        try:
            self._check_ports(res)
        except Exception as e:
            res.results.append(SelfTestResult(
                "Port-Check", SelfTestSeverity.WARN,
                detail=str(e)[:160],
            ))
        return res


class GuiThreadsSelfTest(SelfTestCategory):
    """Prueft Qt-GUI-Kontext, Threading-Zustand und Diagnostic-Log.

    Read-only: veraendert keine Threads, keine GUI-Zustaende.
    """

    NAME = "GUI/Threads"
    DESCRIPTION = "QApplication, Thread-Anzahl, Diagnostic-Log"

    LOG_PATH = Path.home() / ".wlan_ultimate" / "logs" / "wlan_ultimate.log"

    def _check_qapp(self, res):
        try:
            app = QApplication.instance()
        except Exception as e:
            res.results.append(SelfTestResult(
                "QApplication.instance()", SelfTestSeverity.WARN,
                detail=str(e)[:120],
            ))
            return
        if app is not None:
            res.results.append(SelfTestResult(
                "QApplication", SelfTestSeverity.OK,
                detail=type(app).__name__,
            ))
        else:
            res.results.append(SelfTestResult(
                "QApplication", SelfTestSeverity.SKIP,
                detail="keine Qt-App-Instanz (Headless/Test-Kontext)",
            ))

    def _check_threads(self, res):
        try:
            n = threading.active_count()
            sev = (SelfTestSeverity.OK if n <= 20
                   else SelfTestSeverity.WARN)
            res.results.append(SelfTestResult(
                "Thread-Anzahl", sev, value=str(n),
                detail="" if n <= 20
                else "Viele Threads aktiv \u2014 auf Leak pruefen",
            ))
            non_main = [
                t for t in threading.enumerate()
                if t is not threading.main_thread()
            ]
            for t in non_main[:12]:
                res.results.append(SelfTestResult(
                    f"  Thread {t.name}", SelfTestSeverity.SKIP,
                    detail=f"daemon={t.daemon} alive={t.is_alive()}",
                ))
        except Exception as e:
            res.results.append(SelfTestResult(
                "Thread-Anzahl", SelfTestSeverity.WARN,
                detail=str(e)[:120],
            ))

    def _check_diag_log(self, res):
        try:
            if not self.LOG_PATH.exists():
                res.results.append(SelfTestResult(
                    "Diagnostic-Log", SelfTestSeverity.SKIP,
                    detail=f"kein Log unter {self.LOG_PATH}",
                ))
                return
            rep = DiagnosticReport(self.LOG_PATH)
            rep.scan(since_hours=24)
            n = len(rep.entries)
            sev = (SelfTestSeverity.OK if n < 100
                   else SelfTestSeverity.WARN)
            res.results.append(SelfTestResult(
                "Diagnostic-Log (24h)", sev,
                value=f"{n} Eintrag/Eintraege",
                detail=str(self.LOG_PATH),
            ))
        except Exception as e:
            res.results.append(SelfTestResult(
                "Diagnostic-Log", SelfTestSeverity.WARN,
                detail=str(e)[:120],
            ))

    def run(self) -> SelfTestCategoryResult:
        res = SelfTestCategoryResult(self.NAME, self.DESCRIPTION)
        self._check_qapp(res)
        self._check_threads(res)
        self._check_diag_log(res)
        return res


class ConfigSelfTest(SelfTestCategory):
    """Prueft EvilTwinConfig: Konstruktion, Defaults, Scope, Resolve.

    Read-only: instanziiert nur die dataclass, veraendert nichts.
    """

    NAME = "Config"
    DESCRIPTION = "EvilTwinConfig-Defaults, Scope-Check, iface-Aufloesung"

    _DEFAULT_CHECKS = (
        ("iptables_chain",
         lambda v: v == "EVILTWIN",
         "EVILTWIN"),
        ("portal_port",
         lambda v: isinstance(v, int) and 1 <= v <= 65535,
         "1..65535"),
        ("gateway_ip",
         lambda v: isinstance(v, str) and v.count(".") == 3,
         "IPv4-Form"),
        ("dhcp_range_start",
         lambda v: isinstance(v, str) and v.count(".") == 3,
         "IPv4-Form"),
        ("dhcp_range_end",
         lambda v: isinstance(v, str) and v.count(".") == 3,
         "IPv4-Form"),
        ("duration_sec",
         lambda v: isinstance(v, int) and v > 0,
         "> 0"),
    )

    def _check_construct(self, res):
        try:
            cfg = EvilTwinConfig()
        except Exception as e:
            res.results.append(SelfTestResult(
                "EvilTwinConfig()", SelfTestSeverity.FAIL,
                detail=str(e)[:160],
            ))
            return None
        res.results.append(SelfTestResult(
            "EvilTwinConfig()", SelfTestSeverity.OK,
        ))
        for fname, ok_fn, expect in self._DEFAULT_CHECKS:
            val = getattr(cfg, fname, None)
            if val is None:
                res.results.append(SelfTestResult(
                    f"Default {fname}", SelfTestSeverity.WARN,
                    detail="Feld fehlt",
                ))
                continue
            try:
                ok = bool(ok_fn(val))
            except Exception:
                ok = False
            res.results.append(SelfTestResult(
                f"Default {fname}",
                SelfTestSeverity.OK if ok else SelfTestSeverity.WARN,
                value=str(val),
                detail="" if ok else f"erwartet: {expect}",
            ))
        return cfg

    def _check_scope_off(self, res):
        try:
            cfg = EvilTwinConfig(scope_mode="off")
            allowed, msg = cfg.check_scope()
            res.results.append(SelfTestResult(
                "check_scope(off)",
                SelfTestSeverity.OK if allowed else SelfTestSeverity.WARN,
                detail=(msg or "erlaubt")[:160],
            ))
        except Exception as e:
            res.results.append(SelfTestResult(
                "check_scope(off)", SelfTestSeverity.WARN,
                detail=str(e)[:160],
            ))

    def _check_resolve_empty(self, res):
        try:
            cfg = EvilTwinConfig()
            ok, err = cfg.resolve_ifaces()
            if ok and not err:
                res.results.append(SelfTestResult(
                    "resolve_ifaces(leer)", SelfTestSeverity.OK,
                ))
            else:
                res.results.append(SelfTestResult(
                    "resolve_ifaces(leer)", SelfTestSeverity.WARN,
                    detail=(err or "unerwartetes Ergebnis")[:160],
                ))
        except Exception as e:
            res.results.append(SelfTestResult(
                "resolve_ifaces(leer)", SelfTestSeverity.WARN,
                detail=str(e)[:160],
            ))

    def _check_adapter_api(self, res):
        try:
            methods = ("detect", "resolve", "suggest_roles", "render_report")
            missing = [m for m in methods
                       if not hasattr(AdapterCapabilities, m)]
            if missing:
                res.results.append(SelfTestResult(
                    "AdapterCapabilities-API", SelfTestSeverity.FAIL,
                    detail="fehlend: " + ", ".join(missing),
                ))
            else:
                res.results.append(SelfTestResult(
                    "AdapterCapabilities-API", SelfTestSeverity.OK,
                    detail="detect/resolve/suggest_roles/render_report",
                ))
        except Exception as e:
            res.results.append(SelfTestResult(
                "AdapterCapabilities-API", SelfTestSeverity.WARN,
                detail=str(e)[:120],
            ))

    def run(self) -> SelfTestCategoryResult:
        res = SelfTestCategoryResult(self.NAME, self.DESCRIPTION)
        self._check_construct(res)
        self._check_scope_off(res)
        self._check_resolve_empty(res)
        self._check_adapter_api(res)
        return res


class LogHealthAnalyzer:
    """Read-only Auswertung von wlan_ultimate.log fuer SelfTest/Reports."""

    LINE_RE = re.compile(
        r"^(?P<ts>\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2},\d{3})"
        r"\s+\[(?P<level>[A-Z]+)\]\s+"
        r"(?P<logger>[^:\s]+):(?P<lineno>\d+)\s+"
        r"[\u2013-]\s+(?P<msg>.*)$"
    )

    MAX_LINES = 200_000

    # P7.8: Test-Artefakte aus pytest-Laeufen herausfiltern
    _TEST_ARTIFACT_MARKERS = (
        "[DIAG-THREAD] unit-test:",
        "[DIAG-CTX] ctx-test:",
        "[DIAG-CTX] ctx-swallow:",
    )

    def __init__(self, log_path=None):
        if log_path is None:
            log_path = (
                Path.home() / ".wlan_ultimate" / "logs"
                / "wlan_ultimate.log"
            )
        self.log_path = Path(log_path)
        self.entries = []
        self.total_lines = 0
        self.parse_errors = 0
        self.test_artifacts = 0
        self.truncated = False

    @classmethod
    def _is_test_artifact(cls, msg: str) -> bool:
        """True, wenn msg ein pytest-Artefakt ist (kein echter Fehler)."""
        if not msg:
            return False
        return any(
            marker in msg for marker in cls._TEST_ARTIFACT_MARKERS
        )

    def exists(self) -> bool:
        try:
            return self.log_path.is_file()
        except OSError:
            return False

    def size_bytes(self) -> int:
        try:
            return self.log_path.stat().st_size
        except OSError:
            return 0

    def mtime(self) -> float:
        try:
            return self.log_path.stat().st_mtime
        except OSError:
            return 0.0

    def scan(self) -> None:
        """Liest die Log-Datei read-only. Idempotent, nie werfend.

        P7.8: pytest-Artefakte (unit-test/ctx-test/ctx-swallow) werden
        nicht in self.entries aufgenommen, sondern in self.test_artifacts
        gezaehlt. total_lines zaehlt weiterhin alle Zeilen.
        """
        self.entries = []
        self.total_lines = 0
        self.parse_errors = 0
        self.test_artifacts = 0
        self.truncated = False
        if not self.exists():
            return
        try:
            raw = self.log_path.read_text(
                encoding="utf-8", errors="replace"
            )
        except OSError:
            return
        for ln in raw.splitlines():
            self.total_lines += 1
            if self.total_lines > self.MAX_LINES:
                self.truncated = True
                break
            m = self.LINE_RE.match(ln)
            if not m:
                continue
            try:
                ts = datetime.strptime(
                    m.group("ts"), "%Y-%m-%d %H:%M:%S,%f"
                ).astimezone()
            except ValueError:
                self.parse_errors += 1
                continue
            msg = m.group("msg")
            if self._is_test_artifact(msg):
                self.test_artifacts += 1
                continue
            self.entries.append({
                "ts": ts,
                "level": m.group("level"),
                "logger": m.group("logger"),
                "lineno": int(m.group("lineno")),
                "msg": msg,
            })

    def level_counts(self) -> dict:
        c = defaultdict(int)
        for e in self.entries:
            c[e["level"]] += 1
        return dict(c)

    def top_modules(self, n: int = 5) -> list:
        c = defaultdict(int)
        for e in self.entries:
            if e["level"] in ("ERROR", "CRITICAL"):
                c[e["logger"]] += 1
        return sorted(c.items(), key=lambda kv: -kv[1])[:n]

    def top_messages(self, n: int = 5) -> list:
        c = defaultdict(int)
        for e in self.entries:
            if e["level"] in ("ERROR", "CRITICAL"):
                msg = e["msg"]
                if len(msg) > 90:
                    msg = msg[:90] + "\u2026"
                c[msg] += 1
        return sorted(c.items(), key=lambda kv: -kv[1])[:n]

    def _newest(self):
        if not self.entries:
            return None
        try:
            return max(e["ts"] for e in self.entries)
        except ValueError:
            return None

    def count_in_window(self, hours: int = 24,
                        levels=("ERROR", "CRITICAL")) -> int:
        newest = self._newest()
        if newest is None:
            return 0
        cutoff = newest - timedelta(hours=hours)
        return sum(
            1 for e in self.entries
            if e["ts"] >= cutoff and e["level"] in levels
        )

    def count_in_previous_window(self, hours: int = 24,
                                 levels=("ERROR", "CRITICAL")) -> int:
        newest = self._newest()
        if newest is None:
            return 0
        hi = newest - timedelta(hours=hours)
        lo = newest - timedelta(hours=2 * hours)
        return sum(
            1 for e in self.entries
            if lo <= e["ts"] < hi and e["level"] in levels
        )

    def last_entry_age_hours(self):
        newest = self._newest()
        if newest is None:
            return None
        return (
            datetime.now().astimezone() - newest
        ).total_seconds() / 3600.0

    def health_score(self) -> int:
        """0..100, aus Level-Verteilung der letzten 24h."""
        errs = self.count_in_window(24, ("ERROR",))
        crits = self.count_in_window(24, ("CRITICAL",))
        warns = self.count_in_window(24, ("WARNING",))
        score = 100
        score -= min(40, errs * 5)
        score -= min(30, crits * 10)
        score -= min(10, warns // 10)
        return max(0, min(100, score))


class LogAnalysisSelfTest(SelfTestCategory):
    """Zusammenfassende Analyse von wlan_ultimate.log.

    Read-only. Ergaenzt die Diagnostic-Log-Pruefung in GuiThreadsSelfTest
    um Level-Verteilung, Modul-/Meldungs-Haeufungen und Trend.
    """

    NAME = "Log-Analyse"
    DESCRIPTION = (
        "wlan_ultimate.log: Health, Level, Top-Module, Trend, DIAG"
    )

    def _check_file(self, res, an):
        if not an.exists():
            res.results.append(SelfTestResult(
                "Log-Datei", SelfTestSeverity.SKIP,
                value=str(an.log_path),
                detail="existiert noch nicht",
            ))
            return False
        size = an.size_bytes()
        if size < 1024:
            size_str = f"{size} B"
        elif size < 1024 ** 2:
            size_str = f"{size / 1024:.1f} KiB"
        else:
            size_str = f"{size / (1024 ** 2):.2f} MiB"
        res.results.append(SelfTestResult(
            "Log-Datei", SelfTestSeverity.OK,
            value=size_str, detail=str(an.log_path),
        ))
        age = an.last_entry_age_hours()
        if age is None:
            res.results.append(SelfTestResult(
                "Log-Alter", SelfTestSeverity.SKIP,
                detail="keine parsebaren Eintraege",
            ))
        else:
            sev = (SelfTestSeverity.OK if age < 168
                   else SelfTestSeverity.WARN)
            res.results.append(SelfTestResult(
                "Letzter Eintrag vor",
                sev,
                value=f"{age:.1f} h",
                detail="" if age < 168
                else "> 7 Tage alt \u2014 Logrotation pruefen",
            ))
        return True

    def _check_levels(self, res, an):
        c = an.level_counts()
        if not c:
            res.results.append(SelfTestResult(
                "Level-Verteilung", SelfTestSeverity.SKIP,
                detail="keine Eintraege",
            ))
            return
        detail_parts = [
            f"{len(an.entries)} parsebar",
            f"{an.parse_errors} unlesbar",
        ]
        if an.test_artifacts:
            detail_parts.append(
                f"{an.test_artifacts} Test-Artefakte gefiltert"
            )
        if an.truncated:
            detail_parts.append("truncated")
        res.results.append(SelfTestResult(
            "Zeilen gesamt", SelfTestSeverity.OK,
            value=str(an.total_lines),
            detail=", ".join(detail_parts),
        ))
        order = ("DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL")
        summary = "  ".join(
            f"{lv}={c.get(lv, 0)}" for lv in order if lv in c
        )
        res.results.append(SelfTestResult(
            "Level-Verteilung", SelfTestSeverity.OK, value=summary,
        ))

    def _check_errors(self, res, an):
        errs = an.count_in_window(24, ("ERROR",))
        crits = an.count_in_window(24, ("CRITICAL",))
        warns = an.count_in_window(24, ("WARNING",))

        sev_err = (SelfTestSeverity.OK if errs == 0
                   else SelfTestSeverity.WARN if errs <= 10
                   else SelfTestSeverity.FAIL)
        res.results.append(SelfTestResult(
            "Fehler (24h)", sev_err, value=str(errs),
            detail="" if errs == 0 else "ERROR-Level Eintraege",
        ))
        sev_crit = (SelfTestSeverity.OK if crits == 0
                    else SelfTestSeverity.FAIL)
        res.results.append(SelfTestResult(
            "Kritisch (24h)", sev_crit, value=str(crits),
        ))
        sev_warn = (SelfTestSeverity.OK if warns < 50
                    else SelfTestSeverity.WARN)
        res.results.append(SelfTestResult(
            "Warnungen (24h)", sev_warn, value=str(warns),
        ))

        prev = an.count_in_previous_window(24, ("ERROR", "CRITICAL"))
        trend = "=" if prev == errs + crits else (
            "\u2191" if errs + crits > prev else "\u2193"
        )
        sev_tr = (SelfTestSeverity.OK if trend != "\u2191"
                  else SelfTestSeverity.WARN)
        res.results.append(SelfTestResult(
            "Trend Fehler (24h vs. 24h davor)",
            sev_tr,
            value=f"{errs + crits} vs {prev}  {trend}",
        ))

        score = an.health_score()
        sev_h = (SelfTestSeverity.OK if score >= 90
                 else SelfTestSeverity.WARN if score >= 60
                 else SelfTestSeverity.FAIL)
        res.results.append(SelfTestResult(
            "Log-Health-Score", sev_h, value=f"{score}/100",
        ))

    def _check_top(self, res, an):
        mods = an.top_modules(5)
        if mods:
            items = ", ".join(f"{m}({n})" for m, n in mods)
            res.results.append(SelfTestResult(
                "Top-Module (Fehler)", SelfTestSeverity.OK,
                value=items,
            ))
        msgs = an.top_messages(3)
        for i, (m, n) in enumerate(msgs, 1):
            res.results.append(SelfTestResult(
                f"  Top-Meldung #{i}", SelfTestSeverity.OK,
                value=f"{n}\u00d7", detail=m,
            ))

    def _check_diag(self, res, an):
        try:
            rep = DiagnosticReport(an.log_path)
            rep.scan(since_hours=24)
            n = len(rep.entries)
            sev = (SelfTestSeverity.OK if n < 20
                   else SelfTestSeverity.WARN if n < 100
                   else SelfTestSeverity.FAIL)
            res.results.append(SelfTestResult(
                "DIAG-Eintraege (24h)", sev,
                value=str(n),
                detail="EXC/THREAD/CTX aus DiagnosticHook",
            ))
        except Exception as e:
            res.results.append(SelfTestResult(
                "DIAG-Eintraege (24h)", SelfTestSeverity.WARN,
                detail=str(e)[:120],
            ))

    def run(self) -> SelfTestCategoryResult:
        res = SelfTestCategoryResult(self.NAME, self.DESCRIPTION)
        try:
            an = LogHealthAnalyzer()
            an.scan()
        except Exception as e:
            res.results.append(SelfTestResult(
                "Log-Analyse", SelfTestSeverity.FAIL,
                detail=str(e)[:160],
            ))
            return res
        if not self._check_file(res, an):
            return res
        try:
            self._check_levels(res, an)
        except Exception as e:
            res.results.append(SelfTestResult(
                "Level-Verteilung", SelfTestSeverity.WARN,
                detail=str(e)[:120],
            ))
        try:
            self._check_errors(res, an)
        except Exception as e:
            res.results.append(SelfTestResult(
                "Fehler-Analyse", SelfTestSeverity.WARN,
                detail=str(e)[:120],
            ))
        try:
            self._check_top(res, an)
        except Exception as e:
            res.results.append(SelfTestResult(
                "Top-Analyse", SelfTestSeverity.WARN,
                detail=str(e)[:120],
            ))
        self._check_diag(res, an)
        return res


def build_diagnostic_bundle(log_tail_lines: int = 200) -> str:
    """Erzeugt ein einzelnes Text-Bundle fuer Bug-Reports.

    Read-only. Enthaelt: SelfTest-Report, Log-Health, Umgebung, Log-Tail.
    """
    try:
        n_tail = max(0, min(int(log_tail_lines), 5000))
    except (TypeError, ValueError):
        n_tail = 200

    out = []
    sep = "=" * 72
    dash = "-" * 72

    out.append(sep)
    out.append("  WLAN Ultimate Security Suite \u2014 Diagnose-Bundle")
    out.append(sep)
    out.append(
        "Erzeugt: " + datetime.now().isoformat(timespec="seconds")
    )
    out.append("")

    # 1. SelfTest-Report
    out.append(dash)
    out.append("  SELFTEST-REPORT")
    out.append(dash)
    try:
        rep = run_selftest_categories()
        out.append(rep.to_text())
    except Exception as e:
        out.append("[SelfTest-Report fehlgeschlagen: " + str(e)[:200] + "]")
    out.append("")

    # 2. Log-Health
    out.append(dash)
    out.append("  LOG-HEALTH")
    out.append(dash)
    try:
        an = LogHealthAnalyzer()
        an.scan()
        out.append("Log:           " + str(an.log_path))
        out.append("Groesse:       " + str(an.size_bytes()) + " B")
        out.append(
            "Zeilen:        " + str(an.total_lines)
            + " (" + str(len(an.entries)) + " parsebar, "
            + str(an.parse_errors) + " unlesbar)"
        )
        out.append("Health-Score:  " + str(an.health_score()) + "/100")
        out.append(
            "Fehler 24h:    "
            + str(an.count_in_window(24, ("ERROR",)))
        )
        out.append(
            "Kritisch 24h:  "
            + str(an.count_in_window(24, ("CRITICAL",)))
        )
        out.append("")
        out.append("Level-Verteilung:")
        for lv, cnt in sorted(an.level_counts().items()):
            out.append("  " + lv.ljust(10) + " " + str(cnt))
        out.append("")
        out.append("Top-Module (Fehler):")
        for m, c in an.top_modules(10):
            out.append("  " + str(c).rjust(5) + "  " + m)
        out.append("")
        out.append("Top-Meldungen (Fehler):")
        for m, c in an.top_messages(5):
            out.append("  " + str(c).rjust(5) + "  " + m)
    except Exception as e:
        out.append("[Log-Health fehlgeschlagen: " + str(e)[:200] + "]")
    out.append("")

    # 3. Umgebung
    out.append(dash)
    out.append("  UMGEBUNG")
    out.append(dash)
    try:
        out.append("OS:      " + platform.platform())
        out.append("Kernel:  " + platform.release())
        out.append("Python:  " + sys.version.split()[0])
        uid = os.getuid() if hasattr(os, "getuid") else -1
        out.append("User:    uid=" + str(uid))
    except Exception as e:
        out.append("[Umgebung: " + str(e)[:200] + "]")
    out.append("")
    try:
        ads = AdapterCapabilities.detect()
        if ads:
            out.append("Adapter:")
            for a in ads:
                out.append("  " + a.describe())
        else:
            out.append("Adapter: (keine erkannt)")
    except Exception as e:
        out.append("[Adapter: " + str(e)[:200] + "]")
    out.append("")

    # 4. Log-Tail
    out.append(dash)
    out.append("  LOG-TAIL (letzte " + str(n_tail) + " Zeilen)")
    out.append(dash)
    try:
        if n_tail > 0:
            an2 = LogHealthAnalyzer()
            if an2.exists():
                txt = an2.log_path.read_text(
                    encoding="utf-8", errors="replace"
                )
                tail = txt.splitlines()[-n_tail:]
                out.extend(tail)
            else:
                out.append("(kein Log vorhanden)")
        else:
            out.append("(Tail deaktiviert)")
    except Exception as e:
        out.append("[Log-Tail: " + str(e)[:200] + "]")
    out.append("")
    out.append(sep)
    out.append("  ENDE DIAGNOSE-BUNDLE")
    out.append(sep)
    return "\n".join(out)


def run_selftest_categories(categories=None) -> SelfTestReport:
    """F\u00fchrt die \u00fcbergebenen Kategorien aus.

    Default: [SystemSelfTest(), ToolsSelfTest(), AdapterSelfTest(),
              FilesystemSelfTest(), PersistenceSelfTest(),
              NetworkSelfTest(), GuiThreadsSelfTest(),
              ConfigSelfTest(), LogAnalysisSelfTest()].
    """
    if categories is None:
        categories = [
            SystemSelfTest(),
            ToolsSelfTest(),
            AdapterSelfTest(),
            FilesystemSelfTest(),
            PersistenceSelfTest(),
            NetworkSelfTest(),
            GuiThreadsSelfTest(),
            ConfigSelfTest(),
            LogAnalysisSelfTest(),
        ]
    rep = SelfTestReport()
    for cat in categories:
        try:
            rep.categories.append(cat.run())
        except Exception as e:
            rep.categories.append(SelfTestCategoryResult(
                name=getattr(cat, "NAME", "?"),
                description=getattr(cat, "DESCRIPTION", ""),
                results=[SelfTestResult(
                    "Kategorie-Ausf\u00fchrung", SelfTestSeverity.FAIL,
                    detail=str(e)[:160],
                )],
            ))
    return rep


