# ----------------------------------------------------------------
# A. RuntimeErrorTracker
# ----------------------------------------------------------------
class RuntimeErrorTracker:
    """Sammelt Exceptions über die gesamte Laufzeit."""

    _instance = None
    _lock = threading.RLock()
    MAX_ERRORS = 500

    def __init__(self):
        self._errors: deque = deque(maxlen=self.MAX_ERRORS)
        self._counts: dict = {}
        self._installed = False

    @classmethod
    def get(cls):
        with cls._lock:
            if cls._instance is None:
                cls._instance = RuntimeErrorTracker()
            return cls._instance

    def install_hook(self):
        """Installiert sys.excepthook und threading.excepthook."""
        if self._installed:
            return
        self._installed = True
        try:
            self._orig_sys_hook = sys.excepthook
            sys.excepthook = self._sys_hook
        except (AttributeError, RuntimeError):
            pass
        try:
            self._orig_thread_hook = threading.excepthook
            threading.excepthook = self._thread_hook
        except (AttributeError, RuntimeError):
            pass

    def _sys_hook(self, exc_type, exc_val, exc_tb):
        try:
            self.record("main", exc_type, exc_val, exc_tb)
        except (AttributeError, RuntimeError, TypeError):
            pass
        try:
            if hasattr(self, "_orig_sys_hook"):
                self._orig_sys_hook(exc_type, exc_val, exc_tb)
        except (AttributeError, TypeError):
            pass

    def _thread_hook(self, args):
        try:
            self.record(
                getattr(args.thread, "name", "thread"),
                args.exc_type,
                args.exc_value,
                args.exc_traceback,
            )
        except (AttributeError, TypeError):
            pass
        try:
            if hasattr(self, "_orig_thread_hook"):
                self._orig_thread_hook(args)
        except (AttributeError, TypeError):
            pass

    def record(self, source: str, exc_type, exc_val, exc_tb):
        """Manuelles Erfassen."""
        import traceback as _tb

        tb_str = ""
        try:
            tb_str = "".join(_tb.format_tb(exc_tb or []))
        except (AttributeError, TypeError):
            pass
        entry = {
            "ts": time.time(),
            "source": source,
            "type": getattr(exc_type, "__name__", str(exc_type)),
            "message": str(exc_val)[:300],
            "traceback": tb_str[:2000],
        }
        with self._lock:
            self._errors.append(entry)
            key = entry["type"] + ":" + entry["source"]
            self._counts[key] = self._counts.get(key, 0) + 1

    def recent(self, last_n: int = 50) -> list:
        with self._lock:
            return list(self._errors)[-last_n:]

    def grouped(self) -> list:
        """Gruppiert nach Typ:Source, sortiert nach Häufigkeit."""
        with self._lock:
            items = sorted(self._counts.items(), key=lambda x: -x[1])
            return items

    def total(self) -> int:
        with self._lock:
            return len(self._errors)

    def clear(self):
        with self._lock:
            self._errors.clear()
            self._counts.clear()


# ----------------------------------------------------------------
# B. LogAnalyzer
# ----------------------------------------------------------------
class LogAnalyzer:
    """Analysiert Log-Dateien auf Muster, Häufungen, Trends."""

    NOISE_PATTERNS = [
        r"\[STATS\] raw=",
        r"\[watchdog\] ▶ iw dev",
        r"\[watchdog\] ~ rc=1",
        r"\[BEACON-OK\] #",
        r"RAW-ANALYSE",
    ]

    @classmethod
    def analyze(cls, path: Path, hours: int = 24) -> dict:
        result = {
            "total_lines": 0,
            "errors": 0,
            "warnings": 0,
            "infos": 0,
            "by_module": {},
            "top_errors": [],
            "repeated_patterns": [],
            "time_span_hours": 0,
            "oldest": None,
            "newest": None,
        }
        try:
            if not path.is_file():
                return result
            cutoff = time.time() - hours * 3600
            error_msgs: dict = {}
            module_counts: dict = {}
            line_re = re.compile(
                r"^(\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}:\d{2})\s+" r"\[(\w+)\s*\]\s+([^:]+)"
            )
            noise_re = [re.compile(p) for p in cls.NOISE_PATTERNS]

            with path.open("r", encoding="utf-8", errors="replace") as f:
                for line in f:
                    result["total_lines"] += 1
                    # Noise filtern
                    if any(rx.search(line) for rx in noise_re):
                        continue
                    m = line_re.match(line)
                    if not m:
                        continue
                    ts_str, level, module = m.groups()
                    try:
                        ts = (
                            _dt.datetime.strptime(
                                ts_str, "%Y-%m-%d %H:%M:%S"
                            )
                            .astimezone()
                            .timestamp()
                        )
                    except (ValueError, TypeError):
                        continue
                    if ts < cutoff:
                        continue
                    if result["oldest"] is None:
                        result["oldest"] = ts
                    result["newest"] = ts
                    level = level.strip().upper()
                    module = module.strip()

                    if level == "ERROR" or level == "CRITICAL":
                        result["errors"] += 1
                        key = module + ":" + line.split("]")[-1].strip()[:100]
                        error_msgs[key] = error_msgs.get(key, 0) + 1
                    elif level == "WARNING":
                        result["warnings"] += 1
                    else:
                        result["infos"] += 1
                    module_counts[module] = module_counts.get(module, 0) + 1

            if result["oldest"] and result["newest"]:
                result["time_span_hours"] = round(
                    (result["newest"] - result["oldest"]) / 3600, 1
                )

            # Top-Module
            result["by_module"] = sorted(module_counts.items(), key=lambda x: -x[1])[
                :15
            ]

            # Top-Errors
            result["top_errors"] = sorted(error_msgs.items(), key=lambda x: -x[1])[:15]

            # Wiederkehrende Patterns
            result["repeated_patterns"] = result["top_errors"]

        except (OSError, ValueError, TypeError):
            pass
        return result


# ----------------------------------------------------------------
# C. CrashReporter
# ----------------------------------------------------------------
class CrashReporter:
    """Speichert Crash-Snapshots bei Exceptions."""

    @staticmethod
    def save(tracker: RuntimeErrorTracker) -> Path | None:
        try:
            base = Path.home() / ".wlan_ultimate" / "crashes"
            base.mkdir(parents=True, exist_ok=True)
            ts = datetime.now().strftime("%Y%m%d_%H%M%S")
            path = base / f"crash_{ts}.json"
            data = {
                "generated": datetime.now().isoformat(),
                "python": sys.version,
                "platform": sys.platform,
                "cwd": os.getcwd(),
                "total_errors": tracker.total(),
                "errors": tracker.recent(100),
                "grouped": tracker.grouped()[:30],
            }
            path.write_text(json.dumps(data, indent=2, default=str), encoding="utf-8")
            return path
        except (OSError, TypeError, ValueError):
            return None


# ----------------------------------------------------------------
# D. SystemHealth
# ----------------------------------------------------------------
class SystemHealth:
    """CPU, RAM, Disk, Netzwerk - Live-Werte."""

    @classmethod
    def check(cls) -> dict:
        out = {
            "cpu_percent": 0.0,
            "ram_total_mb": 0,
            "ram_used_mb": 0,
            "ram_percent": 0.0,
            "disk_total_gb": 0.0,
            "disk_used_gb": 0.0,
            "disk_percent": 0.0,
            "load_avg": (0.0, 0.0, 0.0),
            "uptime_s": 0.0,
        }
        try:
            out["load_avg"] = os.getloadavg()
        except (AttributeError, OSError):
            pass
        try:
            out["uptime_s"] = float(Path("/proc/uptime").read_text().split()[0])
        except (OSError, ValueError, IndexError):
            pass
        # CPU
        try:
            import psutil

            out["cpu_percent"] = psutil.cpu_percent(interval=0.1)
            mem = psutil.virtual_memory()
            out["ram_total_mb"] = int(mem.total / 1048576)
            out["ram_used_mb"] = int(mem.used / 1048576)
            out["ram_percent"] = mem.percent
            du = shutil.disk_usage(Path.home())
            out["disk_total_gb"] = round(du.total / 1e9, 1)
            out["disk_used_gb"] = round(du.used / 1e9, 1)
            out["disk_percent"] = round(du.used / du.total * 100, 1)
        except (ImportError, OSError, AttributeError):
            # Fallback ohne psutil
            try:
                meminfo = Path("/proc/meminfo").read_text()
                vals = {}
                for line in meminfo.splitlines():
                    parts = line.split(":")
                    if len(parts) == 2:
                        v = parts[1].strip().split()
                        if v:
                            try:
                                vals[parts[0]] = int(v[0])
                            except (ValueError, IndexError):
                                pass
                total = vals.get("MemTotal", 0)
                avail = vals.get("MemAvailable", 0)
                if total:
                    out["ram_total_mb"] = total // 1024
                    out["ram_used_mb"] = (total - avail) // 1024
                    out["ram_percent"] = round((total - avail) / total * 100, 1)
            except (OSError, ValueError, IndexError):
                pass
        try:
            du = shutil.disk_usage(Path.home())
            out["disk_total_gb"] = round(du.total / 1e9, 1)
            out["disk_used_gb"] = round(du.used / 1e9, 1)
            out["disk_percent"] = round(du.used / du.total * 100, 1)
        except OSError:
            pass
        return out


# ----------------------------------------------------------------
# E. HardwareLint
# ----------------------------------------------------------------
class HardwareLint:
    """Live-Check der WLAN-Karte."""

    @classmethod
    def check(cls, iface: str = "wlan0") -> dict:
        out = {
            "iface": iface,
            "exists": Path(f"/sys/class/net/{iface}").is_dir(),
            "mode": "?",
            "channel": 0,
            "txpower": 0,
            "up": False,
            "rx_packets": 0,
            "tx_packets": 0,
            "rx_bytes": 0,
            "tx_bytes": 0,
            "rx_errors": 0,
            "tx_errors": 0,
            "rx_dropped": 0,
            "tx_dropped": 0,
            "speed_mbps": 0,
            "driver": "",
            "usb_speed": "",
            "issues": [],
        }
        if not out["exists"]:
            out["issues"].append("Interface nicht vorhanden")
            return out
        try:
            r = subprocess.run(
                ["iw", "dev", iface, "info"], capture_output=True, text=True, timeout=3
            )
            for line in (r.stdout or "").splitlines():
                ls = line.strip()
                if ls.startswith("type "):
                    out["mode"] = ls.split(None, 1)[1]
                m = re.search(r"channel\s+(\d+)", ls)
                if m:
                    out["channel"] = int(m.group(1))
        except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
            pass
        try:
            r = subprocess.run(
                ["iw", "dev", iface, "get", "txpower"],
                capture_output=True,
                text=True,
                timeout=3,
            )
            m = re.search(r"(\d+(?:\.\d+)?)\s*dBm", r.stdout or "")
            if m:
                out["txpower"] = int(float(m.group(1)))
        except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
            pass
        try:
            r = subprocess.run(
                ["ip", "link", "show", iface], capture_output=True, text=True, timeout=3
            )
            out["up"] = "state UP" in (r.stdout or "")
        except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
            pass
        # Stats
        try:
            base = Path(f"/sys/class/net/{iface}/statistics")
            for k, f in [
                ("rx_packets", "rx_packets"),
                ("tx_packets", "tx_packets"),
                ("rx_bytes", "rx_bytes"),
                ("tx_bytes", "tx_bytes"),
                ("rx_errors", "rx_errors"),
                ("tx_errors", "tx_errors"),
                ("rx_dropped", "rx_dropped"),
                ("tx_dropped", "tx_dropped"),
            ]:
                p = base / f
                if p.exists():
                    out[k] = int(p.read_text().strip() or 0)
        except (OSError, ValueError):
            pass
        # Driver
        try:
            r = subprocess.run(
                ["ethtool", "-i", iface], capture_output=True, text=True, timeout=3
            )
            for line in (r.stdout or "").splitlines():
                if line.startswith("driver:"):
                    out["driver"] = line.split(":", 1)[1].strip()
                elif line.startswith("speed:"):
                    sp = line.split(":", 1)[1].strip()
                    m = re.search(r"(\d+)", sp)
                    if m:
                        out["speed_mbps"] = int(m.group(1))
        except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
            pass
        # USB Speed
        for rel in ("device/speed", "device/../speed"):
            try:
                p = Path(f"/sys/class/net/{iface}") / rel
                if p.exists():
                    out["usb_speed"] = p.read_text().strip()
                    break
            except OSError:
                pass
        # Issues
        if out["mode"] != "monitor":
            out["issues"].append(f"Modus={out['mode']} (nicht Monitor)")
        if out["txpower"] < 15:
            out["issues"].append(f"TX-Power niedrig ({out['txpower']} dBm)")
        if not out["up"]:
            out["issues"].append("Interface DOWN")
        if out["rx_errors"] > 100:
            out["issues"].append(f"RX-Fehler: {out['rx_errors']}")
        if out["usb_speed"] == "480":
            out["issues"].append("USB 2.0 (langsamer)")
        return out


# ----------------------------------------------------------------
# Diagnostic-Tab
# ----------------------------------------------------------------
class DiagnosticTab(QWidget):
    """Diagnose-Tab mit Live-Status."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setMinimumSize(800, 600)
        self._tracker = RuntimeErrorTracker.get()
        self._tracker.install_hook()
        self._build_ui()
        self._timer = QTimer(self)
        self._timer.timeout.connect(self._refresh_health)
        self._timer.start(5000)
        QTimer.singleShot(200, self._refresh_health)

    def _build_ui(self):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(8, 8, 8, 8)

        header = QLabel("🩺  Diagnose  — Selbstüberwachung")
        header.setStyleSheet(
            "font-size:16px;font-weight:bold;color:#2a82da;padding:4px;"
        )
        layout.addWidget(header)

        info = QLabel(
            "Live-Überwachung: Exceptions, Log-Muster, "
            "System-Ressourcen, WLAN-Karte. Plus Log-Analyse der "
            "letzten 24h."
        )
        info.setStyleSheet(
            "background:#2d2d2d;color:#bdc3c7;padding:6px;"
            "border-radius:4px;font-size:9pt;"
        )
        info.setWordWrap(True)
        layout.addWidget(info)

        # Health-Kacheln
        self.health_frame = QFrame()
        self.health_frame.setStyleSheet(
            "background:#1a1a1a;color:#bdc3c7;border:1px solid #444;"
            "border-radius:6px;padding:12px;"
        )
        hf = QGridLayout(self.health_frame)

        def _tile(label, big=True):
            box = QVBoxLayout()
            v = QLabel("—")
            v.setStyleSheet(

                    "font-size:20pt;font-weight:bold;color:#2a82da;"
                    if big
                    else "font-size:10pt;color:#bdc3c7;"

            )
            v.setAlignment(Qt.AlignmentFlag.AlignCenter)
            l = QLabel(label)
            l.setStyleSheet("color:#7f8c8d;font-size:9pt;")
            l.setAlignment(Qt.AlignmentFlag.AlignCenter)
            box.addWidget(v)
            box.addWidget(l)
            return box, v

        box, self.lbl_cpu = _tile("CPU")
        hf.addLayout(box, 0, 0)
        box, self.lbl_ram = _tile("RAM")
        hf.addLayout(box, 0, 1)
        box, self.lbl_disk = _tile("Disk")
        hf.addLayout(box, 0, 2)
        box, self.lbl_err = _tile("Errors")
        hf.addLayout(box, 0, 3)
        box, self.lbl_iface = _tile("WLAN")
        hf.addLayout(box, 0, 4)
        box, self.lbl_uptime = _tile("Uptime")
        hf.addLayout(box, 0, 5)
        layout.addWidget(self.health_frame)

        # Buttons
        row = QHBoxLayout()
        b_ref = QPushButton("🔄 Refresh")
        b_ref.clicked.connect(self._refresh_health)
        row.addWidget(b_ref)

        b_log = QPushButton("📊 Log analysieren (24h)")
        b_log.setStyleSheet(
            "background:#3498db;color:white;font-weight:bold;" "padding:6px;"
        )
        b_log.clicked.connect(self._run_log_analysis)
        row.addWidget(b_log)

        b_crash = QPushButton("📸 Crash-Snapshot")
        b_crash.clicked.connect(self._on_crash_snapshot)
        row.addWidget(b_crash)

        b_clear = QPushButton("🗑 Errors leeren")
        b_clear.clicked.connect(self._on_clear_errors)
        row.addWidget(b_clear)
        row.addStretch()
        layout.addLayout(row)

        # Sub-Tabs
        self.tabs = QTabWidget()

        # Health
        w1 = QWidget()
        l1 = QVBoxLayout(w1)
        self.hw_text = QPlainTextEdit()
        self.hw_text.setReadOnly(True)
        self.hw_text.setStyleSheet(
            "background:#0d1117;color:#d4d4d4;" "font-family:monospace;font-size:10pt;"
        )
        l1.addWidget(self.hw_text)
        self.tabs.addTab(w1, "🖥 Hardware")

        # Errors
        w2 = QWidget()
        l2 = QVBoxLayout(w2)
        self.err_table = QTableWidget(0, 4)
        self.err_table.setHorizontalHeaderLabels(["Zeit", "Quelle", "Typ", "Nachricht"])
        self.err_table.horizontalHeader().setSectionResizeMode(
            QHeaderView.ResizeMode.Stretch
        )
        self.err_table.setColumnWidth(0, 90)
        self.err_table.setColumnWidth(1, 130)
        self.err_table.setColumnWidth(2, 140)
        self.err_table.setStyleSheet(
            "background:#0d1117;color:#d4d4d4;"
            "font-family:monospace;font-size:9pt;"
            "gridline-color:#2a2a2a;"
        )
        self.err_table.horizontalHeader().setStyleSheet(
            "background:#2d2d2d;color:#2a82da;"
        )
        l2.addWidget(self.err_table)
        self.tabs.addTab(w2, "⚠ Exceptions")

        # Log-Analyse
        w3 = QWidget()
        l3 = QVBoxLayout(w3)
        self.log_text = QPlainTextEdit()
        self.log_text.setReadOnly(True)
        self.log_text.setStyleSheet(
            "background:#0d1117;color:#d4d4d4;" "font-family:monospace;font-size:10pt;"
        )
        self.log_text.setPlaceholderText("Klick '📊 Log analysieren' für Report …")
        l3.addWidget(self.log_text)
        self.tabs.addTab(w3, "📊 Log-Analyse")

        layout.addWidget(self.tabs, 1)

        self.status_label = QLabel("Bereit.")
        self.status_label.setStyleSheet(
            "color:#7f8c8d;padding:4px;background:#1a1a1a;"
            "border-radius:4px;font-family:monospace;"
        )
        layout.addWidget(self.status_label)

    def _refresh_health(self):
        # SystemHealth
        h = SystemHealth.check()
        cpu = h["cpu_percent"]
        self.lbl_cpu.setText(f"{cpu:.0f}%")
        self.lbl_cpu.setStyleSheet(
            "font-size:20pt;font-weight:bold;" f"color:{self._color_by(cpu, 70, 90)};"
        )
        ram = h["ram_percent"]
        self.lbl_ram.setText(f"{h['ram_used_mb']}/{h['ram_total_mb']} MB")
        self.lbl_ram.setStyleSheet(
            "font-size:14pt;font-weight:bold;" f"color:{self._color_by(ram, 75, 90)};"
        )
        disk = h["disk_percent"]
        self.lbl_disk.setText(f"{disk:.0f}%")
        self.lbl_disk.setStyleSheet(
            "font-size:20pt;font-weight:bold;" f"color:{self._color_by(disk, 80, 95)};"
        )
        nerr = self._tracker.total()
        self.lbl_err.setText(str(nerr))
        self.lbl_err.setStyleSheet(
            "font-size:20pt;font-weight:bold;"
            f"color:{'#27ae60' if nerr == 0 else ('#f39c12' if nerr < 10 else '#e74c3c')};"
        )

        # Uptime
        up_s = h["uptime_s"]
        if up_s > 3600:
            self.lbl_uptime.setText(f"{up_s/3600:.1f}h")
        else:
            self.lbl_uptime.setText(f"{up_s/60:.0f}m")

        # Hardware
        gui = None
        try:
            app = QApplication.instance()
            if app:
                for w in app.topLevelWidgets():
                    if hasattr(w, "interface_manager"):
                        gui = w
                        break
        except (AttributeError, RuntimeError):
            pass
        iface = "wlan0"
        if gui is not None:
            try:
                ifc = gui.interface_manager.aktives_interface
                if ifc:
                    iface = ifc.name
            except (AttributeError, TypeError):
                pass
        hw = HardwareLint.check(iface)
        self.lbl_iface.setText(
            f"{hw['mode']}/{hw['txpower']}dBm" if hw["exists"] else "—"
        )
        col = (
            "#27ae60"
            if not hw["issues"]
            else ("#f39c12" if len(hw["issues"]) <= 2 else "#e74c3c")
        )
        self.lbl_iface.setStyleSheet(f"font-size:12pt;font-weight:bold;color:{col};")

        # HW-Detail
        lines = []
        lines.append("=" * 60)
        lines.append(f"  WLAN-Interface: {hw['iface']}")
        lines.append("=" * 60)
        lines.append(f"  Vorhanden:      {'✓' if hw['exists'] else '❌'}")
        lines.append(f"  Modus:          {hw['mode']}")
        lines.append(f"  Kanal:          {hw['channel']}")
        lines.append(f"  TX-Power:       {hw['txpower']} dBm")
        lines.append(f"  UP:             {'✓' if hw['up'] else '❌'}")
        lines.append(f"  Treiber:        {hw['driver'] or '?'}")
        lines.append(f"  USB-Speed:      {hw['usb_speed'] or '?'} Mbps")
        lines.append("")
        lines.append(
            f"  RX: {hw['rx_packets']} Pakete / "
            f"{hw['rx_bytes']/1e6:.1f} MB "
            f"(Errors: {hw['rx_errors']}, "
            f"Dropped: {hw['rx_dropped']})"
        )
        lines.append(
            f"  TX: {hw['tx_packets']} Pakete / "
            f"{hw['tx_bytes']/1e6:.1f} MB "
            f"(Errors: {hw['tx_errors']}, "
            f"Dropped: {hw['tx_dropped']})"
        )
        if hw["issues"]:
            lines.append("")
            lines.append("  ⚠ Issues:")
            for i in hw["issues"]:
                lines.append(f"    • {i}")
        else:
            lines.append("")
            lines.append("  ✓ Keine Hardware-Issues")
        self.hw_text.setPlainText("\n".join(lines))

        # Errors
        self.err_table.setRowCount(0)
        for e in reversed(self._tracker.recent(100)):
            row = self.err_table.rowCount()
            self.err_table.insertRow(row)
            t = datetime.fromtimestamp(e["ts"]).strftime("%H:%M:%S")
            self.err_table.setItem(row, 0, QTableWidgetItem(t))
            self.err_table.setItem(row, 1, QTableWidgetItem(e["source"]))
            self.err_table.setItem(row, 2, QTableWidgetItem(e["type"]))
            self.err_table.setItem(row, 3, QTableWidgetItem(e["message"]))

        # Status
        self.status_label.setText(
            f"CPU {cpu:.0f}% | RAM {ram:.0f}% | "
            f"Disk {disk:.0f}% | Exceptions: {nerr}"
        )

    @staticmethod
    def _color_by(v, warn, crit):
        if v >= crit:
            return "#e74c3c"
        if v >= warn:
            return "#f39c12"
        return "#27ae60"

    def _run_log_analysis(self):
        log_dir = Path.home() / ".wlan_ultimate" / "logs"
        main_log = log_dir / "wlan_ultimate.log"
        err_log = log_dir / "wlan_ultimate_errors.log"

        lines = []
        for label, path in (("Main-Log", main_log), ("Error-Log", err_log)):
            lines.append("")
            lines.append("=" * 62)
            lines.append(f"  {label}: {path.name}")
            lines.append("=" * 62)
            if not path.is_file():
                lines.append("  (nicht vorhanden)")
                continue
            r = LogAnalyzer.analyze(path, hours=24)
            lines.append(f"  Zeilen:      {r['total_lines']:,}")
            lines.append(f"  Fehler:      {r['errors']:,}")
            lines.append(f"  Warnungen:   {r['warnings']:,}")
            lines.append(f"  Infos:       {r['infos']:,}")
            lines.append(f"  Zeitraum:    " f"{r['time_span_hours']:.1f} Stunden")
            if r["by_module"]:
                lines.append("")
                lines.append("  Top-Module:")
                for m, c in r["by_module"][:10]:
                    lines.append(f"    {m:<38} {c:>6}")
            if r["top_errors"]:
                lines.append("")
                lines.append("  Top-Fehler:")
                for msg, c in r["top_errors"][:10]:
                    lines.append(f"    {c:>4}× {msg[:120]}")

        self.log_text.setPlainText("\n".join(lines))
        self.status_label.setText("Log-Analyse abgeschlossen")

    def _on_crash_snapshot(self):
        path = CrashReporter.save(self._tracker)
        if path:
            QMessageBox.information(self, "Snapshot", f"Gespeichert:\n{path}")
        else:
            QMessageBox.warning(self, "Fehler", "Konnte nicht speichern")

    def _on_clear_errors(self):
        reply = QMessageBox.question(
            self,
            "Leeren",
            "Error-Tracker leeren?",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
        )
        if reply == QMessageBox.StandardButton.Yes:
            self._tracker.clear()
            self._refresh_health()


