        self.btn_run_diagnostic.clicked.connect(self.run_diagnostic)
        button_layout.addWidget(self.btn_run_diagnostic)
        self.btn_auto_fix = QPushButton("🔧 Automatische Reparatur")
        self.btn_auto_fix.clicked.connect(self.run_auto_fix)
        self.btn_auto_fix.setEnabled(False)
        button_layout.addWidget(self.btn_auto_fix)
        self.btn_show_report = QPushButton("📋 Bericht anzeigen")
