# DEBUG CORE – CommandRunner, DiagnosticEvent, SubsystemLogger,
#              SupportBundle, PreflightCheck
# Version 1.0 – zentrales Debug- und Diagnose-Fundament
# ══════════════════════════════════════════════════════════════════


class DiagSeverity(IntEnum):
    """Strukturierte Schweregrade für Diagnose-Events."""

    TRACE = 5
    DEBUG = 10
    INFO = 20
    SUCCESS = 25
    WARN = 30
    ERROR = 40
    CRITICAL = 50


@dataclass
class DiagnosticEvent:
    """
    Strukturierter Fehler-/Info-Datensatz mit Handlungsanweisung.
    Wird von CommandRunner und PreflightCheck erzeugt.
    """

    severity: DiagSeverity
    subsystem: str
    code: str
    message: str
    detail: str = ""
    cmd: list[str] | None = None
    returncode: int | None = None
    stderr: str = ""
    hint: str = ""
    timestamp: datetime = field(default_factory=datetime.now)

    def format_console(self) -> str:
        icon = {
            DiagSeverity.TRACE: "·",
            DiagSeverity.DEBUG: "·",
            DiagSeverity.INFO: "ℹ",
            DiagSeverity.SUCCESS: "✅",
            DiagSeverity.WARN: "⚠",
            DiagSeverity.ERROR: "✗",
            DiagSeverity.CRITICAL: "💥",
        }.get(self.severity, "?")
        parts = [f"{icon} [{self.subsystem}] {self.code}: {self.message}"]
        if self.cmd:
            parts.append(f"   CMD: {' '.join(self.cmd)}")
        if self.returncode is not None:
            parts.append(f"   RC:  {self.returncode}")
        if self.stderr:
            parts.append(f"   ERR: {self.stderr[:300]}")
        if self.hint:
            parts.append(f"   💡 {self.hint}")
        return "\n".join(parts)

    def to_dict(self) -> dict[str, Any]:
        return {
            "severity": self.severity.name,
            "subsystem": self.subsystem,
            "code": self.code,
            "message": self.message,
            "detail": self.detail,
            "cmd": self.cmd,
            "returncode": self.returncode,
            "stderr": self.stderr,
            "hint": self.hint,
            "timestamp": self.timestamp.isoformat(),
        }


class SubsystemLogger:
    """
    Verwaltet pro Subsystem eine eigene Log-Datei.
    Liegt unter DebugManager.LOG_DIR/<subsystem>.log
    """

    _lock = threading.RLock()
    _handlers: dict[str, logging.Handler] = {}

    SUBSYSTEMS = (
        "main",
        "driver",
        "injection",
        "scan",
        "crack",
        "wps",
        "evil_twin",
        "gps",
        "gui",
        "qt",
        "support",
    )

    @classmethod
    def get_logger(cls, subsystem: str) -> logging.Logger:
        if subsystem not in cls.SUBSYSTEMS:
            subsystem = "main"
        name = f"wlan_ultimate.{subsystem}"
        logger = logging.getLogger(name)

        with cls._lock:
            if name in cls._handlers:
                return logger

            logger.setLevel(DebugLevel.TRACE)
            logger.propagate = True

            log_dir = DebugManager.LOG_DIR
            try:
                log_dir.mkdir(parents=True, exist_ok=True)
            except (OSError, PermissionError):
                return logger

            log_file = log_dir / f"{subsystem}.log"

            try:
                handler = RotatingFileHandler(
                    str(log_file),
                    maxBytes=5 * 1024 * 1024,
                    backupCount=3,
                    encoding="utf-8",
                )
            except (OSError, PermissionError):
                return logger

            handler.setFormatter(
                logging.Formatter(
                    "%(asctime)s [%(levelname)s] %(funcName)s:%(lineno)d – %(message)s"
                )
            )
            handler.setLevel(DebugLevel.TRACE)

            try:
                handler.addFilter(OwnMACRedactionFilter())
            except (NameError, AttributeError):
                pass

            logger.addHandler(handler)
            cls._handlers[name] = handler

        return logger


class CommandRunner:
    """
    Zentrale Ausführung aller externen Kommandos mit vollem Trace.
    Ersetzt direkte subprocess.run-Aufrufe.

    Logging: rc, stdout, stderr, Dauer – alles landet in Subsystem-Log.
    Bei Fehlern: DiagnosticEvent mit Handlungsanweisung (hint).
    """

    _history: deque = deque(maxlen=500)
    _history_lock = threading.RLock()
    _event_bus = None

    HINT_MAP = {
        "operation not permitted": "Root-Rechte erforderlich. Mit 'sudo' starten.",
        "no such device": "Interface existiert nicht. 'iw dev' prüfen.",
        "device or resource busy": "Interface belegt. 'airmon-ng check kill'.",
        "network is down": "Interface down. 'ip link set <iface> up'.",
        "resource temporarily unavailable": "Treiber hängt. 'modprobe -r 88XXau && modprobe 88XXau'.",
        "invalid argument": "Ungültige Parameter – Befehl prüfen.",
        "no space left": "Speicher voll.",
        "not supported": "Nicht unterstützt von Adapter/Treiber.",
        "input/output error": "Hardware-Fehler. Adapter neu einstecken.",
        "permission denied": "Zugriff verweigert. Root oder Dateirechte prüfen.",
        "timed out": "Zeitüberschreitung – Adapter reagiert nicht.",
    }

    @classmethod
    def set_event_bus(cls, bus) -> None:
        cls._event_bus = bus

    @classmethod
    def get_history(cls, limit: int = 50) -> list[dict[str, Any]]:
        with cls._history_lock:
            return list(cls._history)[-limit:]

    @classmethod
    def run(
        cls,
        cmd: list[str],
        timeout: float = 10.0,
        check: bool = False,
        sudo: bool = False,
        subsystem: str = "main",
        tag: str = "",
        env: dict[str, str] | None = None,
        input_data: str | None = None,
        soft_fail: bool = False,
    ) -> tuple[int, str, str]:
        logger = SubsystemLogger.get_logger(subsystem)
        full_cmd = (["sudo"] + list(cmd)) if sudo else list(cmd)
        start = time.time()
        tag_str = f"[{tag}] " if tag else ""

        try:
            with cls._history_lock:
                cls._history.append(
                    {
                        "timestamp": datetime.now().isoformat(),
                        "cmd": full_cmd,
                        "subsystem": subsystem,
                    }
                )

            # v7.2: quiet-tags - Adapter-Polls auf TRACE
            # v11.2: cmd_throttle
            _is_quiet = tag in ("adapter", "tx-v", "ps", "reg", "mon-check", "mon-diag")
            if _is_quiet:
                logger.trace(f"{tag_str}▶ {' '.join(full_cmd)}")
            else:
                logger.debug(f"{tag_str}▶ {' '.join(full_cmd)}")
            proc = subprocess.run(
                full_cmd,
                capture_output=True,
                text=True,
                timeout=timeout,
                check=False,
                env={**os.environ, **(env or {})} if env else None,
                input=input_data,
            )
            duration_ms = (time.time() - start) * 1000

            if proc.returncode != 0:
                if soft_fail:
                    logger.debug(
                        f"{tag_str}~ rc={proc.returncode} (soft) "
                        f"stderr={(proc.stderr or '').strip()[:120]}"
                    )
                else:
                    cls._emit_failure(
                        subsystem=subsystem,
                        code=f"CMD_FAIL_{cmd[0].upper().replace('-', '_')}",
                        message=f"rc={proc.returncode}",
                        cmd=full_cmd,
                        rc=proc.returncode,
                        stderr=(proc.stderr or "").strip(),
                        duration_ms=duration_ms,
                    )
                    logger.warning(
                        f"{tag_str}✗ rc={proc.returncode} ({duration_ms:.0f}ms) "
                        f"stderr={(proc.stderr or '').strip()[:200]}"
                    )
                if check:
                    raise subprocess.CalledProcessError(
                        proc.returncode, full_cmd, proc.stdout, proc.stderr
                    )
            else:
                logger.trace(
                    f"{tag_str}✓ rc=0 ({duration_ms:.0f}ms) "
                    f"out={(proc.stdout or '').strip()[:120]}"
                )
            return proc.returncode, proc.stdout or "", proc.stderr or ""

        except subprocess.TimeoutExpired:
            duration_ms = (time.time() - start) * 1000
            cls._emit_failure(
                subsystem=subsystem,
                code=f"CMD_TIMEOUT_{cmd[0].upper().replace('-', '_')}",
                message=f"Timeout nach {timeout}s",
                cmd=full_cmd,
                rc=-1,
                stderr="",
                duration_ms=duration_ms,
                hint="Timeout erhöhen oder Adapter prüfen.",
            )
            _log = logger.warning if soft_fail else logger.error
            _log(f"{tag_str}✗ TIMEOUT nach {timeout}s")
            return -1, "", f"timeout after {timeout}s"

        except FileNotFoundError:
            cls._emit_failure(
                subsystem=subsystem,
                code=f"CMD_NOT_FOUND_{cmd[0].upper()}",
                message=f"Programm '{cmd[0]}' nicht gefunden",
                cmd=full_cmd,
                rc=-2,
                stderr="",
                duration_ms=0,
                hint=f"Installieren: sudo apt install {cmd[0]}",
            )
            return -2, "", "command not found"

        except PermissionError as exc:
            cls._emit_failure(
                subsystem=subsystem,
                code=f"CMD_PERM_{cmd[0].upper()}",
                message="Zugriff verweigert",
                cmd=full_cmd,
                rc=-3,
                stderr=str(exc),
                duration_ms=0,
                hint="Mit 'sudo' ausführen.",
            )
            return -3, "", str(exc)

        except OSError as exc:
            cls._emit_failure(
                subsystem=subsystem,
                code=f"CMD_OSERR_{cmd[0].upper()}",
                message=f"System-Fehler: {exc}",
                cmd=full_cmd,
                rc=-4,
                stderr=str(exc),
                duration_ms=0,
                hint="dmesg | tail prüfen.",
            )
            return -4, "", str(exc)

    @classmethod
    def _emit_failure(
        cls, subsystem, code, message, cmd, rc, stderr, duration_ms, hint=None
    ):
        if hint is None:
            hint = cls._infer_hint(stderr, cmd)
        event = DiagnosticEvent(
            severity=DiagSeverity.ERROR,
            subsystem=subsystem,
            code=code,
            message=f"{message} ({duration_ms:.0f}ms)",
            cmd=cmd,
            returncode=rc,
            stderr=(stderr or "")[:500],
            hint=hint,
        )
        DebugManager.get_logger("Diag").error(event.format_console())
        try:
            if cls._event_bus is not None:
                cls._event_bus.emit("diagnostic_event", event)
        except Exception:
            pass

    @classmethod
    def _infer_hint(cls, stderr: str, cmd: list[str]) -> str:
        stderr_low = (stderr or "").lower()
        for pattern, hint in cls.HINT_MAP.items():
            if pattern in stderr_low:
                return hint
        if cmd:
            if cmd[0] == "iw":
                joined = " ".join(cmd)
                if "set type monitor" in joined:
                    return (
                        "Monitor-Modus fehlgeschlagen. 'iw phy phy0 info' "
                        "auf 'monitor' prüfen. Sonst anderen Adapter."
                    )
                if "set channel" in joined:
                    return (
                        "Kanal-Setzen fehlgeschlagen. Interface up? "
                        "'ip link set <iface> up'. Für DFS: 'iw reg set BO'."
                    )
            if cmd[0] in ("aireplay-ng", "aircrack-ng"):
                return (
                    "Monitor-Modus aktiv? Injection-Test: "
                    "'aireplay-ng --test <iface>'."
                )
            if cmd[0] == "hcxdumptool":
                return (
                    "hcxdumptool läuft NUR auf physischem Interface "
                    "(wlan0), nicht auf wlan0mon!"
                )
        return "Support-Bundle erstellen: " "'python3 <script> --support-bundle'."


class SupportBundle:
    """
    Erstellt ein ZIP mit Logs, System-Info und Command-History.
    MACs werden anonymisiert.
    """

    def __init__(self, output_dir: Path | None = None):
        self.output_dir = output_dir or (Path.home() / ".wlan_ultimate" / "support")
        self.output_dir.mkdir(parents=True, exist_ok=True)
        self.logger = SubsystemLogger.get_logger("support")

    def create(self) -> Path:
        ts = datetime.now().strftime("%Y%m%d_%H%M%S")
        zip_path = self.output_dir / f"wlan_support_{ts}.zip"
        self.logger.info(f"Erstelle Support-Bundle: {zip_path}")

        with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED) as zf:
            self._add_logs(zf)
            self._add_system_info(zf)
            self._add_wlan_info(zf)
            self._add_usb_info(zf)
            self._add_dmesg(zf)
            self._add_python_env(zf)
            self._add_cmd_history(zf)

        size_mb = zip_path.stat().st_size / (1024 * 1024)
        self.logger.info(f"Bundle: {zip_path} ({size_mb:.2f} MB)")
        return zip_path

    def _add_logs(self, zf):
        log_dir = DebugManager.LOG_DIR
        if not log_dir.exists():
            return
        for log_file in log_dir.glob("*.log*"):
            try:
                zf.write(log_file, f"logs/{log_file.name}")
            except OSError:
                pass

    def _add_system_info(self, zf):
        info = [
            "=== System ===",
            f"Kernel: {platform.release()}",
            f"Arch:   {platform.machine()}",
            f"Python: {sys.version}",
            f"User:   {os.environ.get('USER', 'unknown')}",
            f"UID:    {os.geteuid() if hasattr(os, 'geteuid') else 'n/a'}",
            f"Date:   {datetime.now().isoformat()}",
        ]
        _, out, _ = CommandRunner.run(["uname", "-a"], subsystem="support")
        info.append(f"\n=== uname -a ===\n{out}")
        zf.writestr("system_info.txt", "\n".join(info))

    def _add_wlan_info(self, zf):
        _, out, _ = CommandRunner.run(["iw", "dev"], subsystem="support")
        zf.writestr("wlan/iw_dev.txt", out)
        _, out, _ = CommandRunner.run(["iw", "reg", "get"], subsystem="support")
        zf.writestr("wlan/iw_reg.txt", out)
        _, out, _ = CommandRunner.run(
            [
                "sh",
                "-c",
                "for p in /sys/class/ieee80211/*; do "
                "iw phy $(basename $p) info 2>/dev/null; done",
            ],
            subsystem="support",
            timeout=15,
        )
        zf.writestr("wlan/iw_phy_all.txt", out)

    def _add_usb_info(self, zf):
        _, out, _ = CommandRunner.run(["lsusb"], subsystem="support")
        zf.writestr("usb/lsusb.txt", out)
        _, out, _ = CommandRunner.run(["lsusb", "-t"], subsystem="support")
        zf.writestr("usb/lsusb_tree.txt", out)

    def _add_dmesg(self, zf):
        rc, out, _ = CommandRunner.run(["dmesg"], subsystem="support", timeout=5)
        if rc != 0:
            out = "(dmesg nicht verfügbar – evtl. sudo nötig)"
        keywords = (
            "wlan",
            "usb",
            "8812",
            "88xx",
            "cfg80211",
            "mac80211",
            "firmware",
            "ath",
            "rtl",
            "mt76",
        )
        filtered = [
            l for l in out.splitlines() if any(k in l.lower() for k in keywords)
        ]
        zf.writestr("kernel/dmesg_wlan.txt", "\n".join(filtered))

    def _add_python_env(self, zf):
        _, out, _ = CommandRunner.run(
            [sys.executable, "-m", "pip", "freeze"],
            subsystem="support",
            timeout=20,
        )
        zf.writestr("python/pip_freeze.txt", out)
        mods = [
            "scapy",
            "PyQt6",
            "matplotlib",
            "numpy",
            "netifaces",
            "serial",
            "simplekml",
            "gpxpy",
            "folium",
            "yaml",
            "pynmea2",
            "requests",
            "psutil",
        ]
        info = []
        for mod in mods:
            try:
                spec = importlib.util.find_spec(mod)
                if spec is None:
                    info.append(f"{mod}: NICHT INSTALLIERT")
                else:
                    m = importlib.import_module(mod)
                    info.append(f"{mod}: {getattr(m, '__version__', '?')}")
            except (ImportError, AttributeError, ValueError) as exc:
                info.append(f"{mod}: FEHLER ({exc})")
        zf.writestr("python/modules.txt", "\n".join(info))

    def _add_cmd_history(self, zf):
        hist = CommandRunner.get_history(limit=200)
        zf.writestr("cmd_history.json", json.dumps(hist, indent=2, ensure_ascii=False))


