# ERROR HANDLING – Retry, Circuit-Breaker, Fehlerklassifizierung
# ══════════════════════════════════════════════════════════════════


class ErrorSeverity(Enum):
    """Klassifizierung von Fehlern für die Behandlung."""

    TRANSIENT = "transient"  # Wiederholbar (Netzwerk, USB, Timeout)
    PERMANENT = "permanent"  # Nicht wiederholbar (falsche Konfig, fehlende Rechte)
    FATAL = "fatal"  # Systemabbruch (kein Speicher, Hardware tot)


class CircuitState(Enum):
    """Zustand eines Circuit-Breakers."""

    CLOSED = "closed"  # Normal, Operationen laufen
    OPEN = "open"  # Zu viele Fehler, Operationen blockiert
    HALF_OPEN = "half_open"  # Testweise eine Operation zulassen


class CircuitBreaker:
    """
    Verhindert, dass wiederholt fehlschlagende Operationen das System ausbremsen.
    Nach N Fehlern öffnet der Breaker und blockiert für eine Cooldown-Zeit.
    """

    def __init__(
        self, name: str, failure_threshold: int = 5, recovery_timeout: float = 30.0
    ):
        self.name = name
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self._state = CircuitState.CLOSED
        self._failure_count = 0
        self._last_failure_time = 0.0
        self._lock = threading.RLock()
        self._logger = DebugManager.get_logger(f"CircuitBreaker.{name}")

    @property
    def state(self) -> CircuitState:
        with self._lock:
            if self._state == CircuitState.OPEN:
                if time.time() - self._last_failure_time >= self.recovery_timeout:
                    self._state = CircuitState.HALF_OPEN
                    self._logger.info(f"[{self.name}] Circuit → HALF_OPEN (Test)")
            return self._state

    def call(self, func: Callable, *args, **kwargs) -> Any:
        """
        Führt eine Operation durch. Bei zu vielen Fehlern wird die
        Operation blockiert (Circuit OPEN).
        """
        with self._lock:
            state = self.state
            if state == CircuitState.OPEN:
                raise RuntimeError(
                    f"[{self.name}] Circuit ist OPEN – Operation blockiert. "
                    f"Retry in {self.recovery_timeout - (time.time() - self._last_failure_time):.1f}s"
                )

        try:
            result = func(*args, **kwargs)
            with self._lock:
                if self._state == CircuitState.HALF_OPEN:
                    self._logger.info(f"[{self.name}] Circuit → CLOSED (Erholung)")
                self._state = CircuitState.CLOSED
                self._failure_count = 0
            return result
        except Exception as exc:
            with self._lock:
                self._failure_count += 1
                self._last_failure_time = time.time()
                if self._failure_count >= self.failure_threshold:
                    self._state = CircuitState.OPEN
                    self._logger.error(
                        f"[{self.name}] Circuit → OPEN nach {self._failure_count} Fehlern. "
                        f"Letzter Fehler: {exc}"
                    )
            raise


class ErrorHandler:
    """
    Zentrale Fehlerbehandlung für die Anwendung.

    Bietet:
    - Retry mit exponentiellem Backoff
    - Circuit-Breaker pro Operation
    - Fehlerklassifizierung (transient/permanent/fatal)
    - Automatisches Logging mit Trace
    - Fehlerstatistik pro Typ
    """

    _lock = threading.RLock()
    _circuits: dict[str, CircuitBreaker] = {}
    _stats: dict[str, dict[str, int]] = defaultdict(lambda: defaultdict(int))
    _logger = DebugManager.get_logger("ErrorHandler")

    # Klassifizierung bekannter Exceptions
    TRANSIENT_EXCEPTIONS = (
        TimeoutError,
        ConnectionError,
        ConnectionResetError,
        ConnectionAbortedError,
        BrokenPipeError,
        subprocess.TimeoutExpired,
        OSError,  # ENOENT, EAGAIN, etc.
    )

    PERMANENT_EXCEPTIONS = (
        FileNotFoundError,
        PermissionError,
        ValueError,
        TypeError,
        KeyError,
        AttributeError,
        ImportError,
    )

    @classmethod
    def get_circuit(cls, name: str) -> CircuitBreaker:
        """Holt oder erstellt einen CircuitBreaker."""
        with cls._lock:
            if name not in cls._circuits:
                cls._circuits[name] = CircuitBreaker(name)
            return cls._circuits[name]

    @classmethod
    def classify(cls, exc: BaseException) -> ErrorSeverity:
        """Klassifiziert eine Exception nach Schwere."""
        if isinstance(exc, cls.TRANSIENT_EXCEPTIONS):
            return ErrorSeverity.TRANSIENT
        if isinstance(exc, cls.PERMANENT_EXCEPTIONS):
            return ErrorSeverity.PERMANENT
        return ErrorSeverity.FATAL

    @classmethod
    def retry(
        cls,
        max_attempts: int = 3,
        base_delay: float = 0.5,
        max_delay: float = 8.0,
        backoff_factor: float = 2.0,
        circuit_name: str | None = None,
        exceptions: tuple[type[BaseException], ...] = (Exception,),
    ):
        """
        Decorator für automatisches Retry mit exponentiellem Backoff.

        Beispiel:
            @ErrorHandler.retry(max_attempts=5, circuit_name="wlan_scan")
            def scan_channel(ch):
                ...
        """

        def decorator(func: Callable) -> Callable:
            @functools.wraps(func)
            def wrapper(*args, **kwargs):
                circuit = cls.get_circuit(circuit_name or func.__name__)
                last_exc = None
                delay = base_delay

                for attempt in range(1, max_attempts + 1):
                    try:
                        return circuit.call(func, *args, **kwargs)
                    except exceptions as exc:
                        last_exc = exc
                        severity = cls.classify(exc)

                        with cls._lock:
                            cls._stats[func.__name__]["attempts"] += 1
                            cls._stats[func.__name__][severity.value] += 1

                        if severity == ErrorSeverity.PERMANENT:
                            cls._logger.error(
                                f"{func.__name__}: Permanenter Fehler – kein Retry. {exc}"
                            )
                            break

                        if attempt < max_attempts:
                            cls._logger.warning(
                                f"{func.__name__}: Versuch {attempt}/{max_attempts} "
                                f"fehlgeschlagen ({type(exc).__name__}). "
                                f"Retry in {delay:.1f}s."
                            )
                            time.sleep(delay)
                            delay = min(delay * backoff_factor, max_delay)

                cls._logger.error(
                    f"{func.__name__}: Alle {max_attempts} Versuche fehlgeschlagen. "
                    f"Letzter Fehler: {last_exc}"
                )
                raise last_exc

            return wrapper

        return decorator

    @classmethod
    def guard(cls, default: Any = None, log_level: int = logging.ERROR):
        """
        Decorator, der Exceptions abfängt und einen Default zurückgibt.
        Ideal für nicht-kritische Pfade.

        Beispiel:
            @ErrorHandler.guard(default=[])
            def get_cached_networks():
                ...
        """

        def decorator(func: Callable) -> Callable:
            @functools.wraps(func)
            def wrapper(*args, **kwargs):
                try:
                    return func(*args, **kwargs)
                except Exception as exc:
                    cls._logger.log(
                        log_level,
                        f"{func.__name__}: {type(exc).__name__}: {exc}",
                        exc_info=True,
                    )
                    return default

            return wrapper

        return decorator

    @classmethod
    def get_stats(cls) -> dict[str, dict[str, int]]:
        """Gibt Fehlerstatistiken zurück."""
        with cls._lock:
            return {k: dict(v) for k, v in cls._stats.items()}

    @classmethod
    def get_circuit_states(cls) -> dict[str, str]:
        """Gibt den Zustand aller Circuit-Breaker zurück."""
        with cls._lock:
            return {name: cb.state.value for name, cb in cls._circuits.items()}


