class NetworkToolRunner(QThread):
    """v10.3: Führt Netzwerk-Tools im Hintergrund aus."""

    output_line = pyqtSignal(str)
    finished_ok = pyqtSignal(int)

    def __init__(self, tool: str, target: str, parent=None):
        super().__init__(parent)
        self.tool = tool
        self.target = target

    def run(self):
        try:
            cmd = self._build_cmd()
            if cmd is None:
                self.output_line.emit("❌ Unbekanntes Tool: " + str(self.tool))
                self.finished_ok.emit(-1)
                return
            rc, out, err = CommandRunner.run(
                cmd, subsystem="support", tag=self.tool, soft_fail=True, timeout=120
            )
            if out:
                for line in out.splitlines():
                    self.output_line.emit(line)
            if err:
                for line in err.splitlines()[:20]:
                    self.output_line.emit("stderr: " + line)
            self.finished_ok.emit(rc)
        except Exception as e:
            self.output_line.emit("❌ Fehler: " + str(e))
            self.finished_ok.emit(-2)

    def _build_cmd(self):
        t, tg = self.tool, self.target
        if t == "ping":
            return ["ping", "-c", "4", "-W", "2", tg]
        if t == "ping_flood":
            return ["ping", "-c", "20", "-i", "0.2", "-W", "1", tg]
        if t == "traceroute":
            return ["traceroute", "-m", "15", "-w", "2", tg]
        if t == "mtr":
            if not shutil.which("mtr"):
                return ["traceroute", "-m", "15", "-w", "2", tg]
            return ["mtr", "-c", "10", "--report", "--no-dns", tg]
        if t == "nslookup":
            return ["nslookup", tg]
        if t == "dig":
            return ["dig", "+short", "+time=3", "+tries=2", tg]
        if t == "dig_mx":
            return ["dig", "+short", "MX", tg]
        if t == "dig_txt":
            return ["dig", "+short", "TXT", tg]
        if t == "reverse":
            return ["dig", "+short", "-x", tg]
        if t == "whois":
            return ["whois", tg]
        if t == "portscan":
            if shutil.which("nmap"):
                return ["nmap", "-T4", "-F", "--open", "-sV", tg]
            return [
                "bash",
                "-c",
                "for p in 21 22 23 25 53 80 110 143 443 445 993 995 "
                "1433 3306 3389 5432 5900 8080 8443; do "
                "(echo >/dev/tcp/" + tg + "/$p) >/dev/null 2>&1 && "
                'echo "Open: $p"; done',
            ]
        if t == "portscan_full":
            if shutil.which("nmap"):
                return ["nmap", "-T4", "-p-", "--open", tg]
            return None
        if t == "udp_scan":
            if shutil.which("nmap"):
                return ["nmap", "-T4", "-sU", "--top-ports", "50", tg]
            return None
        if t == "os_detect":
            if shutil.which("nmap"):
                return ["nmap", "-T4", "-O", "--osscan-guess", tg]
            return None
        if t == "ssh_probe":
            return [
                "bash",
                "-c",
                "timeout 5 bash -c 'echo | nc -w 3 " + tg + " 22' 2>/dev/null || "
                "echo 'SSH nicht erreichbar'",
            ]
        if t == "https_cert":
            return [
                "bash",
                "-c",
                "echo | timeout 5 openssl s_client -connect " + tg + ":443 "
                "-servername " + tg + " 2>/dev/null | "
                "openssl x509 -noout -subject -issuer -dates 2>/dev/null || "
                "echo 'Zertifikat nicht abrufbar'",
            ]
        if t == "http_header":
            return ["curl", "-sI", "-m", "5", "http://" + tg]
        if t == "https_header":
            return ["curl", "-sI", "-m", "5", "-k", "https://" + tg]
        if t == "smb_probe":
            if shutil.which("nmap"):
                return ["nmap", "-p", "445", "--script=smb-os-discovery", tg]
            return None
        if t == "arp":
            if shutil.which("arp-scan"):
                return [
                    "arp-scan",
                    "--interface=" + self._guess_iface(),
                    self._guess_subnet(),
                ]
            return ["arp", "-an"]
        if t == "dhcp":
            if shutil.which("nmap"):
                return [
                    "nmap",
                    "--script=broadcast-dhcp-discover",
                    "-e",
                    self._guess_iface(),
                ]
            return None
        return None

    def _guess_iface(self):
        try:
            rc, out, _ = CommandRunner.run(
                ["sh", "-c", "ip route | awk '/default/ {print $5; exit}'"],
                subsystem="support",
                soft_fail=True,
                timeout=3,
            )
            return (out or "").strip() or "eth0"
        except Exception:
            return "eth0"

    def _guess_subnet(self):
        iface = self._guess_iface()
        try:
            rc, out, _ = CommandRunner.run(
                [
                    "sh",
                    "-c",
                    "ip -4 addr show " + iface + " | awk '/inet / {print $2; exit}'",
                ],
                subsystem="support",
                soft_fail=True,
                timeout=3,
            )
            cidr = (out or "").strip()
            if cidr and "/" in cidr:
                import ipaddress

                net = ipaddress.ip_network(cidr, strict=False)
                return str(net)
        except Exception:
            pass
        return "192.168.1.0/24"


class PassiveScanManager:
    """v10.3: iwlist-Scan (kein Monitor-Mode)."""

    def __init__(self, logger=None):
        self.logger = logger or logging.getLogger("wlan_ultimate.PassiveScanManager")

    def scan(self, iface: str, timeout: int = 30) -> list[dict]:
        # v37-R3-FIX: results-Liste entfernt — _parse_scan_output() liefert sie
        try:
            CommandRunner.run(
                ["ip", "link", "set", iface, "up"],
                subsystem="scan",
                tag="passive",
                soft_fail=True,
                timeout=3,
            )
        except Exception:
            pass
        cmds = [["iwlist", iface, "scan"], ["sudo", "iwlist", iface, "scan"]]
        out = ""
        for cmd in cmds:
            rc, out, err = CommandRunner.run(
                cmd, subsystem="scan", tag="passive", soft_fail=True, timeout=timeout
            )
            if rc == 0 and out:
                break
        # v37-R3: robuster iw/iwlist-Parser (WPA3, Transition, Enterprise)
        return _parse_scan_output(out)


class RFKillManager:
    """v10.3: RF-Kill Auto-Check."""

    def __init__(self, logger=None):
        self.logger = logger or logging.getLogger("wlan_ultimate.RFKillManager")

    def check(self) -> dict[str, Any]:
        result = {
            "soft_blocked": False,
            "hard_blocked": False,
            "interfaces": [],
            "available": False,
        }
        if shutil.which("rfkill") is None:
            return result
        result["available"] = True
        try:
            rc, out, _ = CommandRunner.run(
                ["rfkill", "list"],
                subsystem="driver",
                tag="rfkill",
                soft_fail=True,
                timeout=3,
            )
            for line in out.splitlines():
                s = line.strip()
                if "Soft blocked: yes" in s:
                    result["soft_blocked"] = True
                if "Hard blocked: yes" in s:
                    result["hard_blocked"] = True
        except Exception:
            pass
        return result

    def unblock(self) -> bool:
        try:
            rc, _, _ = CommandRunner.run(
                ["rfkill", "unblock", "wifi"],
                subsystem="driver",
                tag="rfkill-fix",
                soft_fail=True,
                timeout=3,
            )
            return rc == 0
        except Exception:
            return False


class EthernetScanner:
    """v10.3: ARP-Scan für LAN."""

    def __init__(self, logger=None):
        self.logger = logger or logging.getLogger("wlan_ultimate.EthernetScanner")

    def guess_subnet(self, iface=None) -> str:
        if not iface:
            try:
                rc, out, _ = CommandRunner.run(
                    ["sh", "-c", "ip route | awk '/default/ {print $5; exit}'"],
                    subsystem="support",
                    soft_fail=True,
                    timeout=3,
                )
                iface = (out or "").strip() or "eth0"
            except Exception:
                iface = "eth0"
        try:
            rc, out, _ = CommandRunner.run(
                [
                    "sh",
                    "-c",
                    "ip -4 addr show " + iface + " | awk '/inet / {print $2; exit}'",
                ],
                subsystem="support",
                soft_fail=True,
                timeout=3,
            )
            cidr = (out or "").strip()
            if cidr and "/" in cidr:
                import ipaddress

                net = ipaddress.ip_network(cidr, strict=False)
                return str(net)
        except Exception:
            pass
        return "192.168.1.0/24"

    def scan_arp(self, subnet: str, iface=None) -> list[dict]:
        results = []
        if shutil.which("arp-scan"):
            cmd = ["arp-scan", "--retry=2", "--timeout=200"]
            if iface:
                cmd.append("--interface=" + iface)
            cmd.append(subnet)
            rc, out, _ = CommandRunner.run(
                cmd, subsystem="support", tag="arp-scan", soft_fail=True, timeout=60
            )
            for line in out.splitlines():
                m = re.match(
                    r"^(\d+\.\d+\.\d+\.\d+)\s+([0-9a-f:]{17})\s*(.*)$",
                    line.strip(),
                    re.IGNORECASE,
                )
                if m:
                    results.append(
                        {
                            "ip": m.group(1),
                            "mac": m.group(2).lower(),
                            "vendor": m.group(3).strip(),
                        }
                    )
        else:
            rc, out, _ = CommandRunner.run(
                ["arp", "-an"],
                subsystem="support",
                tag="arp-fallback",
                soft_fail=True,
                timeout=10,
            )
            for line in out.splitlines():
                m = re.search(
                    r"\((\d+\.\d+\.\d+\.\d+)\)\s+at\s+([0-9a-f:]{17})",
                    line,
                    re.IGNORECASE,
                )
                if m:
                    results.append(
                        {"ip": m.group(1), "mac": m.group(2).lower(), "vendor": ""}
                    )
        return results


class SoundAlerts:
    """v10.3: Sound-Warnungen bei Auffälligkeiten."""

    def __init__(self, enabled: bool = False):
        self.enabled = enabled
        self._last_alert = 0.0
        self._min_interval = 5.0  # nicht öfter als 5s

    def beep(self, count: int = 1):
        if not self.enabled:
            return
        now = time.time()
        if now - self._last_alert < self._min_interval:
            return
        self._last_alert = now
        try:
            import subprocess

            for _ in range(count):
                subprocess.Popen(
                    ["paplay", "/usr/share/sounds/freedesktop/stereo/bell.oga"],
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                )
        except Exception:
            try:
                sys.stdout.write("\a")
                sys.stdout.flush()
            except Exception:
                pass

    def alert_high_severity(self):
        self.beep(3)

    def alert_new_network(self):
        self.beep(1)


class NotesManager:
    """v10.3: Notizen pro BSSID."""

    def __init__(self, notes_dir=None):
        self.notes_dir = (
            Path(notes_dir) if notes_dir else (Path.home() / ".wlan_ultimate" / "notes")
        )
        try:
            self.notes_dir.mkdir(parents=True, exist_ok=True)
        except Exception:
            self.notes_dir = Path(tempfile.gettempdir()) / "wlan_notes"
            self.notes_dir.mkdir(parents=True, exist_ok=True)
        self._notes = {}
        self._load()

    def _key(self, bssid: str) -> str:
        return re.sub(r"[^0-9a-f]", "", str(bssid).lower())

    def get(self, bssid: str) -> str:
        return self._notes.get(self._key(bssid), "")

    def set(self, bssid: str, text: str):
        self._notes[self._key(bssid)] = text
        self._save_single(bssid, text)

    def _save_single(self, bssid, text):
        try:
            f = self.notes_dir / (self._key(bssid) + ".txt")
            f.write_text(text, encoding="utf-8")
        except Exception:
            pass

    def _load(self):
        try:
            for f in self.notes_dir.glob("*.txt"):
                try:
                    self._notes[f.stem] = f.read_text(encoding="utf-8")
                except Exception:
                    pass
        except Exception:
            pass


