        self._auto_scan_timer.setSingleShot(True)
        self._auto_scan_timer.timeout.connect(self._auto_scan_restart)
        self._auto_countdown_timer = QTimer(self)
        self._auto_countdown_timer.timeout.connect(self._auto_countdown_tick)
