                    "🎯 Ziel: "
                    + str(n.ssid)[:30]
                    + " | "
                    + str(n.bssid)
                    + " | CH "
                    + str(n.kanal)
                    + " | "
                    + str(n.verschlüsselung)
                    + " | WPS: "
                    + ("JA" if n.wps_aktiv else "nein")
