            f"<p><b>BSSID:</b> {n.bssid}</p>"
            f"<p><b>Kanal:</b> {n.kanal} ({n.frequenz} MHz)</p>"
            f"<p><b>Signal:</b> {n.signal_stärke} dBm</p>"
            f"<p><b>Verschlüsselung:</b> {n.verschlüsselung}</p>"
