        ctrl.addWidget(QLabel("Scan-Dauer:"))
        self.orch_scan_spin = QSpinBox()
        self.orch_scan_spin.setRange(30, 600)
        self.orch_scan_spin.setValue(90)
        self.orch_scan_spin.setSuffix(" s")
