def _diag_network_cli(bssid: str) -> int:
    """v37-R3: --diag-network BSSID — vollständiger JSON-Report."""
    import json
    import subprocess

    bssid = bssid.lower().strip()
    iface = os.environ.get("WLAN_IFACE", "wlan0")
    print(f"[diag-network] Scanne {iface} ...")
    raw = ""
    for cmd in (["iw", "dev", iface, "scan"], ["iwlist", iface, "scan"]):
        try:
            r = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
            if r.returncode == 0 and r.stdout:
                raw = r.stdout
                break
        except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
            continue
    if not raw:
        print("FEHLER: Kein Scan-Output — läuft iface im managed-Modus?")
        return 1
    nets = _parse_scan_output(raw)
    for n in nets:
        if n.get("bssid") == bssid:
            n["vendor"] = _lookup_oui(bssid)
            # v37-R4: WiFi-Gen + Bandbreite-Schätzung
            ch = n.get("channel", 0)
            if ch > 200:
                n["wifi_gen"] = "WiFi 6E/7"
            elif ch > 14:
                n["wifi_gen"] = "WiFi 5/6"
            else:
                n["wifi_gen"] = "WiFi 4"
            print(json.dumps(n, indent=2, ensure_ascii=False))
            return 0
    print(f"❌ BSSID {bssid} nicht gefunden. {len(nets)} andere Netze:")
    for n in nets[:20]:
        print(
            f"  {n.get('bssid')}  {n.get('ssid')[:24]:<24}  "
            f"ch={n.get('channel'):>3}  enc={n.get('encryption')}"
        )
    return 2


def _diag_crypto_cli(bssid: str) -> int:
    """v37-R3: --diag-crypto BSSID — Krypto-Detail."""
    import subprocess

    bssid = bssid.lower().strip()
    iface = os.environ.get("WLAN_IFACE", "wlan0")
    raw = ""
    for cmd in (["iw", "dev", iface, "scan"], ["iwlist", iface, "scan"]):
        try:
            r = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
            if r.returncode == 0 and r.stdout:
                raw = r.stdout
                break
        except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
            continue
    if not raw:
        print("FEHLER: Kein Scan-Output")
        return 1
    nets = _parse_scan_output(raw)
    print(f"═══ Krypto-Report: {len(nets)} Netze ═══")
    for n in nets:
        mark = " ◄── TARGET" if n.get("bssid") == bssid else ""
        print(
            f"  {n.get('bssid')}  {n.get('ssid')[:22]:<22}  "
            f"enc={n.get('encryption'):<18}  "
            f"vendor={_lookup_oui(n.get('bssid',''))}{mark}"
        )
    return 0


def _trace_beacons_cli(seconds: int) -> int:
    """v37-R3: --trace-beacons N — Beacon-Trace in Logfile."""
    import subprocess

    iface = os.environ.get("WLAN_IFACE", "wlan0")
    log_dir = Path.home() / ".wlan_ultimate" / "logs"
    log_dir.mkdir(parents=True, exist_ok=True)
    ts = time.strftime("%F_%H%M%S")
    out_file = log_dir / f"trace_{ts}.log"
    print(f"[trace-beacons] {seconds}s auf {iface} → {out_file}")
    end = time.time() + max(1, seconds)
    with out_file.open("w", encoding="utf-8") as fh:
        while time.time() < end:
            try:
                r = subprocess.run(
                    ["iw", "dev", iface, "scan"],
                    capture_output=True,
                    text=True,
                    timeout=15,
                )
                fh.write(f"\n=== {time.strftime('%F %T')} ===\n")
                fh.write(r.stdout or "")
                fh.flush()
            except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
                time.sleep(1)
    print(f"✓ Trace gespeichert: {out_file}")
    return 0


_OUI_SYSTEM_DB: dict[str, str] | None = None
_OUI_SYSTEM_PATHS = (
    "/usr/share/ieee-data/oui.txt",
    "/var/lib/ieee-data/oui.txt",
    "/usr/share/wireshark/manuf",
    "/usr/share/misc/oui.txt",
)


def _load_system_oui_db() -> dict[str, str]:
    """v37-R3b: lädt IEEE-OUI-DB aus System-Dateien (~30k Einträge)."""
    global _OUI_SYSTEM_DB
    if _OUI_SYSTEM_DB is not None:
        return _OUI_SYSTEM_DB
    db: dict[str, str] = {}
    for p in _OUI_SYSTEM_PATHS:
        path = Path(p)
        if not path.is_file():
            continue
        try:
            with path.open("r", encoding="utf-8", errors="replace") as fh:
                for line in fh:
                    line = line.strip()
                    if not line or line.startswith("#"):
                        continue
                    parts = line.replace("\t", " ").split(" ", 2)
                    if len(parts) < 2:
                        continue
                    oui_raw = parts[0].replace("-", ":").upper()
                    if len(oui_raw) < 8:
                        continue
                    oui = oui_raw[:8]
                    vendor = parts[-1].strip()
                    if oui and vendor and oui not in db:
                        db[oui] = vendor[:60]
            if db:
                break
        except (OSError, ValueError):
            continue
    _OUI_SYSTEM_DB = db
    return db


def _lookup_oui(mac: str) -> str:
    """v37-R3b: OUI → Hersteller (built-in + System-DB + Random-Detect)."""
    if not mac or len(mac) < 8:
        return "Unbekannt"
    oui = mac[:8].upper()
    if oui in _OUI_DB:
        return _OUI_DB[oui]
    sysdb = _load_system_oui_db()
    if oui in sysdb:
        return _clean_vendor_name(sysdb[oui])
    try:
        first = int(mac[:2], 16)
        if first & 0x02:
            return "Randomized MAC"
    except (ValueError, TypeError):
        pass
    return "Unbekannt"


