def _clean_vendor_name(raw: str) -> str:
    """v37-R3c: entfernt (hex)/(base 16) und kürzt lange Namen."""
    if not raw:
        return "Unbekannt"
    s = raw.strip()
    s = re.sub(r"^\s*\((?:hex|base\s*16)\)\s*", "", s, flags=re.IGNORECASE)
    s = re.sub(r"\s+", " ", s).strip()
    if not s:
        return "Unbekannt"
    low = s.lower().rstrip(".,")
    if low in _VENDOR_ALIASES:
        return _VENDOR_ALIASES[low]
    for suffix in (
        " co.,ltd.",
        " co., ltd.",
        " co ltd",
        " gmbh",
        " inc.",
        " inc",
        " ltd.",
        " ltd",
        " sas",
        " corporation",
        " corp.",
        " corp",
    ):
        if low.endswith(suffix):
            short = s[: len(s) - len(suffix)].strip(" ,.")
            if 2 <= len(short) <= 30:
                return short
            break
    if len(s) > 30:
        parts = s.split()
        if len(parts) >= 2:
            candidate = " ".join(parts[:2]).rstrip(" ,.")
            if len(candidate) >= 4:
                return candidate
    return s[:30]


