import socket as _socket


def _detect_active_ifaces() -> list[tuple[str, str]]:
    """v37-R8b: ermittelt alle UP-Interfaces mit IPv4 (name, ip)."""
    import subprocess as _sp

    ifaces: list[tuple[str, str]] = []
    try:
        r = _sp.run(
            ["ip", "-4", "route", "show", "default"],
            capture_output=True,
            text=True,
            timeout=3,
        )
        for line in (r.stdout or "").splitlines():
            m = re.search(r"dev\s+(\S+)", line)
            if m:
                ip = _ip_of_iface(m.group(1))
                if ip:
                    ifaces.append((m.group(1), ip))
                break
    except (FileNotFoundError, _sp.TimeoutExpired, OSError):
        pass
    try:
        r = _sp.run(
            ["ip", "-4", "addr", "show"], capture_output=True, text=True, timeout=3
        )
        current = None
        for line in (r.stdout or "").splitlines():
            m1 = re.match(r"\d+:\s+(\S+):", line)
            if m1:
                current = m1.group(1).split("@")[0]
                continue
            m2 = re.match(r"\s+inet\s+(\d+\.\d+\.\d+\.\d+)", line)
            if m2 and current and current != "lo":
                if current not in [i[0] for i in ifaces]:
                    ifaces.append((current, m2.group(1)))
    except (FileNotFoundError, _sp.TimeoutExpired, OSError):
        pass
    return ifaces


def _ip_of_iface(iface: str) -> str | None:
    import subprocess as _sp

    try:
        r = _sp.run(
            ["ip", "-4", "addr", "show", iface],
            capture_output=True,
            text=True,
            timeout=3,
        )
        m = re.search(r"inet\s+(\d+\.\d+\.\d+\.\d+)", r.stdout or "")
        return m.group(1) if m else None
    except (FileNotFoundError, _sp.TimeoutExpired, OSError):
        return None


def _subnet_of_iface(iface: str) -> str | None:
    import subprocess as _sp
    import ipaddress as _ip

    try:
        r = _sp.run(
            ["ip", "-4", "addr", "show", iface],
            capture_output=True,
            text=True,
            timeout=3,
        )
        m = re.search(r"inet\s+(\d+\.\d+\.\d+\.\d+)/(\d+)", r.stdout or "")
        if not m:
            return None
        return str(_ip.ip_interface(f"{m.group(1)}/{m.group(2)}").network)
    except (FileNotFoundError, _sp.TimeoutExpired, OSError, ValueError):
        return None


class ServiceDiscovery:
    """v37-R8a: passiv+aktiv Service-Discovery in lokalen Netzen.

    Protokolle:
    - SSDP/UPnP (UDP 1900): Geraete-Broadcasts (Smart-TVs, NAS, Chromecast)
    - mDNS (UDP 5353): .local-Hostnamen + Dienste (AirPlay, RAOP, etc.)
    - LLMNR (UDP 5355): Windows-Namensaufloesung
    - NetBIOS-NS (UDP 137): Windows-Hosts
    - Aktive Probes: M-SEARCH, mDNS Service-Query, kleiner Port-Scan

    Rein passiv durch Zuhoeren. Keine Inhalte, keine Authentifizierung.
    """

    SSDP_ADDR = "239.255.255.250"
    SSDP_PORT = 1900
    MDNS_ADDR = "224.0.0.251"
    MDNS_PORT = 5353
    LLMNR_ADDR = "224.0.0.252"
    LLMNR_PORT = 5355
    NBNS_PORT = 137

    COMMON_PORTS = [
        21,
        22,
        23,
        53,
        80,
        139,
        443,
        445,
        554,
        1883,
        3389,
        5000,
        5900,
        7000,
        8008,
        8009,
        8080,
        8200,
        9100,
        49152,
    ]

    def __init__(
        self, logger=None, iface: str | None = None, ifaces: list[str] | None = None
    ):
        self.logger = logger or logging.getLogger("wlan_ultimate.ServiceDiscovery")
        if ifaces is not None:
            self.ifaces = list(ifaces)
        elif iface:
            self.ifaces = [iface]
        else:
            self.ifaces = [n for n, _ in _detect_active_ifaces()]
            if not self.ifaces:
                self.ifaces = ["eth0", "wlan0"]
        self.iface = self.ifaces[0] if self.ifaces else "wlan0"
        self._running = False
        self._threads: list[threading.Thread] = []
        self._stop = threading.Event()
        self._lock = threading.Lock()
        self.results: dict[tuple[str, str], dict] = {}
        self.ports: dict[str, list[int]] = {}
        self.start_time = 0.0

    def start(self) -> None:
        if self._running:
            return
        self._running = True
        self._stop.clear()
        self.start_time = time.time()
        active_map = dict(_detect_active_ifaces())
        self.logger.info(
            "[DISC] aktive Interfaces: "
            + ", ".join(f"{n}={ip}" for n, ip in active_map.items())
        )
        for iface in self.ifaces:
            ip = active_map.get(iface, "?")
            self.logger.info(f"[DISC] starte Lauscher auf {iface} ({ip})")
            for proto in ("ssdp", "mdns", "llmnr", "nbns"):
                t = threading.Thread(
                    target=_thread_wrap(self._passive_loop, "anon-75745"),
                    args=(proto, iface),
                    daemon=True,
                    name=f"Discovery-{proto}-{iface}",
                )
                t.start()
                self._threads.append(t)

    def stop(self) -> None:
        self._stop.set()
        for t in self._threads:
            t.join(timeout=2.0)
        self._threads.clear()
        self._running = False
        self.logger.info(
            "[DISC] gestoppt nach " + f"{time.time() - self.start_time:.1f}s"
        )

    def is_running(self) -> bool:
        return self._running

    def snapshot(self) -> list[dict]:
        """Sortierte, kompakte Ergebnisliste."""
        with self._lock:
            items = list(self.results.values())
        items.sort(key=lambda r: (r.get("ip", ""), r.get("proto", "")))
        return items

    # ── Passives Lauschen ───────────────────────────────────────
    def _passive_loop(self, proto: str, iface: str) -> None:
        try:
            if proto == "ssdp":
                self._listen_ssdp(iface)
            elif proto == "mdns":
                self._listen_mdns(iface)
            elif proto == "llmnr":
                self._listen_llmnr(iface)
            elif proto == "nbns":
                self._listen_nbns(iface)
        except Exception as exc:
            self.logger.debug(f"[DISC-{proto}-{iface}] {exc}")

    def _make_passive_socket(
        self, port: int, mcast_addr: str | None = None, iface: str | None = None
    ) -> _socket.socket | None:
        try:
            s = _socket.socket(_socket.AF_INET, _socket.SOCK_DGRAM, _socket.IPPROTO_UDP)
            s.setsockopt(_socket.SOL_SOCKET, _socket.SO_REUSEADDR, 1)
            try:
                s.setsockopt(_socket.SOL_SOCKET, _socket.SO_REUSEPORT, 1)
            except (AttributeError, OSError):
                pass
            s.bind(("", port))
            if mcast_addr:
                try:
                    if iface:
                        mreq = _socket.inet_aton(mcast_addr) + _socket.inet_aton(
                            self._iface_ip(iface) or "0.0.0.0"  # noqa: S104
                        )
                    else:
                        mreq = _socket.inet_aton(mcast_addr) + _socket.inet_aton(
                            "0.0.0.0"  # noqa: S104
                        )
                    s.setsockopt(_socket.IPPROTO_IP, _socket.IP_ADD_MEMBERSHIP, mreq)
                except (OSError, AttributeError):
                    pass
            s.settimeout(0.5)
            return s
        except OSError as exc:
            self.logger.debug(f"[DISC] socket bind {port}: {exc}")
            return None

    @staticmethod
    def _iface_ip(iface: str) -> str | None:
        return _ip_of_iface(iface)

    def _listen_ssdp(self, iface: str) -> None:
        s = self._make_passive_socket(self.SSDP_PORT, self.SSDP_ADDR, iface)
        if not s:
            return
        while not self._stop.is_set():
            try:
                data, addr = s.recvfrom(4096)
            except TimeoutError:
                continue
            except OSError:
                break
            try:
                text = data.decode("utf-8", "replace")
            except (UnicodeDecodeError, AttributeError):
                continue
            info: dict = {"proto": "SSDP", "ip": addr[0], "port": addr[1]}
            for line in text.splitlines():
                low = line.lower()
                if low.startswith("server:"):
                    info["model"] = line.split(":", 1)[1].strip()[:80]
                elif low.startswith("location:"):
                    info["location"] = line.split(":", 1)[1].strip()[:120]
                elif low.startswith("st:"):
                    info.setdefault("services", []).append(
                        line.split(":", 1)[1].strip()[:80]
                    )
                elif low.startswith("usn:"):
                    info["usn"] = line.split(":", 1)[1].strip()[:80]
            self._record("SSDP", addr[0], info)
        s.close()

    def _listen_mdns(self, iface: str) -> None:
        s = self._make_passive_socket(self.MDNS_PORT, self.MDNS_ADDR, iface)
        if not s:
            return
        while not self._stop.is_set():
            try:
                data, addr = s.recvfrom(4096)
            except TimeoutError:
                continue
            except OSError:
                break
            names = self._extract_ascii_tokens(data, min_len=4)
            services = [n for n in names if n.startswith("_") and n.endswith("local")]
            hostnames = [
                n for n in names if n.endswith(".local") and not n.startswith("_")
            ]
            info: dict = {"proto": "mDNS", "ip": addr[0], "port": addr[1]}
            if services:
                info["services"] = services[:10]
            if hostnames:
                info["hostname"] = hostnames[0]
            if len(data) >= 4:
                ip_guess = ".".join(str(b) for b in data[-4:])
                if all(0 <= int(x) <= 255 for x in ip_guess.split(".")):
                    info.setdefault("ip_a", ip_guess)
            self._record("mDNS", addr[0], info)
        s.close()

    def _listen_llmnr(self, iface: str) -> None:
        s = self._make_passive_socket(self.LLMNR_PORT, self.LLMNR_ADDR, iface)
        if not s:
            return
        while not self._stop.is_set():
            try:
                data, addr = s.recvfrom(4096)
            except TimeoutError:
                continue
            except OSError:
                break
            names = self._extract_ascii_tokens(data, min_len=3)
            info: dict = {"proto": "LLMNR", "ip": addr[0], "port": addr[1]}
            if names:
                info["hostname"] = names[0]
            self._record("LLMNR", addr[0], info)
        s.close()

    def _listen_nbns(self, iface: str) -> None:
        try:
            s = _socket.socket(_socket.AF_INET, _socket.SOCK_DGRAM)
            s.setsockopt(_socket.SOL_SOCKET, _socket.SO_REUSEADDR, 1)
            try:
                s.setsockopt(_socket.SOL_SOCKET, _socket.SO_REUSEPORT, 1)
            except (AttributeError, OSError):
                pass
            s.bind(("", self.NBNS_PORT))
            s.settimeout(0.5)
        except OSError as exc:
            self.logger.debug(f"[DISC] NBNS bind: {exc}")
            return
        while not self._stop.is_set():
            try:
                data, addr = s.recvfrom(4096)
            except TimeoutError:
                continue
            except OSError:
                break
            info: dict = {"proto": "NetBIOS", "ip": addr[0], "port": addr[1]}
            try:
                if len(data) >= 14:
                    raw = data[13:45].rstrip(b" \x00")
                    if raw:
                        decoded = raw.decode("ascii", "replace").strip()
                        if decoded:
                            info["hostname"] = decoded
            except (UnicodeDecodeError, AttributeError):
                pass
            self._record("NetBIOS", addr[0], info)
        s.close()

    def active_ssdp_probe(self, timeout: float = 2.0) -> int:
        """Sendet SSDP M-SEARCH und sammelt Antworten."""
        msg = (
            "M-SEARCH * HTTP/1.1\r\n"
            f"HOST: {self.SSDP_ADDR}:{self.SSDP_PORT}\r\n"
            'MAN: "ssdp:discover"\r\n'
            "MX: 2\r\n"
            "ST: ssdp:all\r\n\r\n"
        ).encode("ascii")
        got = 0
        try:
            s = _socket.socket(_socket.AF_INET, _socket.SOCK_DGRAM)
            s.setsockopt(_socket.SOL_SOCKET, _socket.SO_REUSEADDR, 1)
            s.setsockopt(_socket.IPPROTO_IP, _socket.IP_MULTICAST_TTL, 2)
            s.settimeout(timeout)
            s.sendto(msg, (self.SSDP_ADDR, self.SSDP_PORT))
            deadline = time.time() + timeout
            while time.time() < deadline:
                try:
                    data, addr = s.recvfrom(4096)
                except TimeoutError:
                    break
                text = data.decode("utf-8", "replace")
                info: dict = {"proto": "SSDP-MSEARCH", "ip": addr[0]}
                for line in text.splitlines():
                    low = line.lower()
                    if low.startswith("server:"):
                        info["model"] = line.split(":", 1)[1].strip()[:80]
                    elif low.startswith("location:"):
                        info["location"] = line.split(":", 1)[1].strip()[:120]
                    elif low.startswith("st:"):
                        info.setdefault("services", []).append(
                            line.split(":", 1)[1].strip()[:80]
                        )
                self._record("SSDP-MSEARCH", addr[0], info)
                got += 1
            s.close()
        except OSError as exc:
            self.logger.debug(f"[DISC] ssdp-probe: {exc}")
        return got

    def probe_ports(
        self,
        ip: str,
        ports: list[int] | None = None,
        timeout: float = 0.3,
        workers: int = 32,
    ) -> list[int]:
        """Schneller TCP-Connect-Scan auf ausgewählte Ports."""
        ports = ports or self.COMMON_PORTS
        open_ports: list[int] = []

        def _try(p: int) -> None:
            s = _socket.socket(_socket.AF_INET, _socket.SOCK_STREAM)
            s.settimeout(timeout)
            try:
                if s.connect_ex((ip, p)) == 0:
                    open_ports.append(p)
            except OSError:
                pass
            finally:
                s.close()

        threads = []
        for p in ports:
            t = threading.Thread(target=_thread_wrap(_try, "anon-75997"), args=(p,), daemon=True)
            t.start()
            threads.append(t)
            if len(threads) >= workers:
                for t2 in threads:
                    t2.join(timeout=1.0)
                threads.clear()
        for t in threads:
            t.join(timeout=1.0)
        with self._lock:
            self.ports[ip] = sorted(set(open_ports))
        return sorted(set(open_ports))

    def _record(self, proto: str, ip: str, info: dict) -> None:
        key = (proto, ip)
        with self._lock:
            existing = self.results.get(key)
            if existing is None:
                info["first_seen"] = time.time()
                info["last_seen"] = info["first_seen"]
                self.results[key] = info
            else:
                for k, v in info.items():
                    if k in ("services",) and isinstance(v, list):
                        merged = set(existing.get(k, []) or []) | set(v)
                        existing[k] = sorted(merged)
                    elif v and not existing.get(k):
                        existing[k] = v
                existing["last_seen"] = time.time()

    @staticmethod
    def _extract_ascii_tokens(data: bytes, min_len: int = 3) -> list[str]:
        tokens = []
        cur = []
        for b in data:
            if 32 <= b < 127:
                cur.append(chr(b))
            else:
                if len(cur) >= min_len:
                    tokens.append("".join(cur))
                cur = []
        if len(cur) >= min_len:
            tokens.append("".join(cur))
        return tokens


def struct_or_bytes(name: str, size: int) -> bytes:
    """Helfer für ioctl SIOCGIFADDR (ohne struct-Import)."""
    return name.encode("ascii") + b"\x00" * (size - len(name))


def _discover_cli(
    duration: int = 30,
    iface: str | None = None,
    active: bool = True,
    scan_ports: bool = False,
) -> int:
    """v37-R8b: --discover — Multi-Interface Service-Discovery."""
    active_ifaces = _detect_active_ifaces()
    if iface:
        iface_list = [iface]
    else:
        iface_list = [n for n, _ in active_ifaces] or ["eth0", "wlan0"]
    print(f"=== Service-Discovery ({duration}s) ===")
    print("Aktive Interfaces:")
    for n, ip in active_ifaces:
        print(f"  {n:<12} {ip}")
    print(f"Lausche auf: {iface_list}")
    disc = ServiceDiscovery(ifaces=iface_list)
    disc.start()
    try:
        if active:
            print("[+] Aktive Probes: SSDP M-SEARCH ...")
            n = disc.active_ssdp_probe(timeout=2.0)
            print(f"    {n} Antwort(en) erhalten.")
        print(f"[+] Lausche passiv für {duration}s ... (Ctrl-C zum Abbrechen)")
        deadline = time.time() + duration
        while time.time() < deadline:
            time.sleep(1.0)
            snap = disc.snapshot()
            print(
                f"    +{int(time.time()-disc.start_time):>3}s  "
                f"Geräte={len(snap)}  Dienste-Einträge="
                f"{sum(len(r.get('services',[])) for r in snap)}"
            )
    except KeyboardInterrupt:
        print("\n[!] Abbruch durch Nutzer")
    finally:
        disc.stop()

    snap = disc.snapshot()
    print()
    print(f"=== Ergebnis: {len(snap)} Geräte-Einträge ===")
    for r in snap:
        ip = r.get("ip", "?")
        proto = r.get("proto", "?")
        host = r.get("hostname") or r.get("ip_a") or ""
        model = r.get("model") or ""
        svcs = ", ".join(r.get("services", [])[:4])
        print(f"  {ip:<15} {proto:<14} {host:<24} {model[:30]:<30} {svcs}")

    if scan_ports and snap:
        ips = sorted({r.get("ip") for r in snap if r.get("ip")})
        print()
        print(f"=== Port-Scan auf {len(ips)} IPs ===")
        for ip in ips:
            ports = disc.probe_ports(ip)
            print(f"  {ip:<15} offen: {ports if ports else '(keine)'}")
    return 0


