class NetworkDiagnostics:
    """v37-R9: Vollstaendige Netzwerk-Diagnose.
    Interfaces, Routen, DNS, ARP, Reachability, VM-Erkennung."""

    @staticmethod
    def report() -> dict:
        import subprocess as _sp
        import json as _json

        result: dict = {
            "timestamp": time.time(),
            "interfaces": [],
            "routes": {},
            "dns": [],
            "arp": [],
            "issues": [],
            "recommendations": [],
            "vm": {},
        }

        try:
            r = _sp.run(
                ["ip", "-j", "-4", "addr", "show"],
                capture_output=True,
                text=True,
                timeout=5,
            )
            if r.returncode == 0:
                ifaces = _json.loads(r.stdout)
                for iface in ifaces:
                    if iface.get("ifname") == "lo":
                        continue
                    addrs = [a.get("local") for a in iface.get("addr_info", [])]
                    result["interfaces"].append(
                        {
                            "name": iface.get("ifname"),
                            "state": iface.get("operstate"),
                            "mac": iface.get("address", ""),
                            "mtu": iface.get("mtu", 0),
                            "ipv4": addrs,
                        }
                    )
        except (FileNotFoundError, _sp.TimeoutExpired, OSError, ValueError):
            pass

        try:
            r = _sp.run(
                ["ip", "-j", "route", "show", "default"],
                capture_output=True,
                text=True,
                timeout=3,
            )
            if r.returncode == 0:
                routes = _json.loads(r.stdout)
                if routes:
                    result["routes"]["default"] = {
                        "gateway": routes[0].get("gateway"),
                        "dev": routes[0].get("dev"),
                    }
        except (FileNotFoundError, _sp.TimeoutExpired, OSError, ValueError):
            pass

        try:
            with open("/etc/resolv.conf", "r", encoding="utf-8") as fh:
                for line in fh:
                    line = line.strip()
                    if line.startswith("nameserver"):
                        parts = line.split()
                        if len(parts) >= 2:
                            result["dns"].append(parts[1])
        except OSError:
            pass

        try:
            r = _sp.run(
                ["ip", "-j", "neigh"], capture_output=True, text=True, timeout=3
            )
            if r.returncode == 0:
                neigh = _json.loads(r.stdout)
                for n in neigh:
                    if n.get("state") in ("REACHABLE", "STALE", "DELAY", "PROBE"):
                        result["arp"].append(
                            {
                                "ip": n.get("dst"),
                                "mac": n.get("lladdr", ""),
                                "dev": n.get("dev", ""),
                                "state": n.get("state", ""),
                            }
                        )
        except (FileNotFoundError, _sp.TimeoutExpired, OSError, ValueError):
            pass

        try:
            r = _sp.run(
                ["systemd-detect-virt"], capture_output=True, text=True, timeout=3
            )
            result["vm"]["type"] = r.stdout.strip() or "none"
        except (FileNotFoundError, _sp.TimeoutExpired, OSError):
            result["vm"]["type"] = "unknown"

        nat_hit = False
        for i in result["interfaces"]:
            nm = i.get("name", "")
            for ip in i.get("ipv4", []):
                if ip.startswith("10.0.2.") and (
                    nm.startswith("eth") or nm.startswith("ens") or nm == "enp0s3"
                ):
                    nat_hit = True
        if nat_hit and result["vm"]["type"] != "none":
            result["vm"]["network_mode"] = "NAT (Bridged nicht aktiv)"
            result["issues"].append(
                "VirtualBox-NAT erkannt. Broadcast-basierte Discovery "
                "(SSDP/mDNS/NetBIOS) erreicht keine Geraete ausserhalb der VM."
            )
            result["recommendations"].append(
                "VM-Netzwerk auf 'Netzwerkbruecke' (Bridged) umstellen — "
                "dann funktioniert Service-Discovery im echten LAN."
            )

        for i in result["interfaces"]:
            if i.get("name", "").startswith("wlan") and not i.get("ipv4"):
                result["issues"].append(
                    f"{i['name']} hat keine IPv4 — Monitor-Mode oder "
                    "nicht mit AP verbunden."
                )

        gw = (result.get("routes", {}).get("default") or {}).get("gateway")
        if gw:
            try:
                r = _sp.run(
                    ["ping", "-c", "1", "-W", "1", gw], capture_output=True, timeout=3
                )
                result["gateway_reachable"] = r.returncode == 0
            except (FileNotFoundError, _sp.TimeoutExpired, OSError):
                result["gateway_reachable"] = False
        else:
            result["gateway_reachable"] = False

        try:
            r = _sp.run(
                ["ping", "-c", "1", "-W", "2", "1.1.1.1"],
                capture_output=True,
                timeout=4,
            )
            result["internet_reachable"] = r.returncode == 0
        except (FileNotFoundError, _sp.TimeoutExpired, OSError):
            result["internet_reachable"] = False

        return result

    @staticmethod
    def format_report(r: dict) -> str:
        lines = ["=" * 72, "NETZWERK-DIAGNOSE", "=" * 72, ""]

        lines.append("-- Interfaces --")
        for i in r.get("interfaces", []):
            ips = ", ".join(i.get("ipv4", [])) or "(keine IPv4)"
            lines.append(
                f"  {i['name']:<10} {i.get('state','?')!s:<8} "
                f"{ips:<20} MAC={i.get('mac','?')} MTU={i.get('mtu','?')}"
            )

        lines.append("")
        lines.append("-- Default-Route --")
        rt = (r.get("routes") or {}).get("default")
        if rt:
            lines.append(f"  Gateway: {rt.get('gateway','?')} via {rt.get('dev','?')}")
        else:
            lines.append("  (keine Default-Route)")

        lines.append("")
        lines.append("-- DNS --")
        for d in r.get("dns", []):
            lines.append(f"  {d}")

        lines.append("")
        lines.append("-- ARP / Nachbarn --")
        arp = r.get("arp", [])
        if arp:
            for a in arp:
                v = ""
                try:
                    v = _lookup_oui(a.get("mac", ""))
                except (NameError, AttributeError):
                    v = "?"
                lines.append(
                    f"  {a['ip']:<15} {a['mac']:<18} {a.get('dev',''):<8} "
                    f"{a.get('state',''):<10} {v}"
                )
        else:
            lines.append("  (keine aktiven Nachbarn)")

        lines.append("")
        lines.append("-- Umgebung --")
        vm = r.get("vm", {})
        lines.append(
            f"  VM: {vm.get('type', 'unknown')}  "
            f"Netzwerk: {vm.get('network_mode', 'unbekannt')}"
        )
        lines.append(
            f"  Gateway erreichbar:  "
            f"{'JA' if r.get('gateway_reachable') else 'NEIN'}"
        )
        lines.append(
            f"  Internet erreichbar: "
            f"{'JA' if r.get('internet_reachable') else 'NEIN'}"
        )

        if r.get("issues"):
            lines.append("")
            lines.append("-- !! Probleme --")
            for issue in r["issues"]:
                lines.append(f"  ! {issue}")

        if r.get("recommendations"):
            lines.append("")
            lines.append("-- Empfehlungen --")
            for rec in r["recommendations"]:
                lines.append(f"  -> {rec}")

        return "\n".join(lines)


class NmapIntegration:
    """v37-R9: nmap-Wrapper mit XML-Parsing + Service-Interpretation."""

    PROFILES = {
        "quick": ["-T4", "-F"],
        "service": ["-T4", "-sV", "-sC", "--top-ports", "100"],
        "os": ["-T4", "-O", "--osscan-guess"],
        "full": ["-T4", "-A", "-p-"],
        "stealth": ["-T4", "-sS", "-Pn"],
    }

    RISKY_PORTS = {
        21: "FTP (Klartext-Login!)",
        23: "Telnet (UNSICHER!)",
        25: "SMTP (Mail-Relay-Check)",
        135: "RPC (Windows)",
        139: "NetBIOS/SMB",
        445: "SMB (WannaCry-Relevant)",
        1433: "MSSQL",
        1521: "Oracle-DB",
        3306: "MySQL",
        3389: "RDP",
        5432: "PostgreSQL",
        5900: "VNC",
        6379: "Redis (oft ungeschuetzt)",
        27017: "MongoDB (oft ungeschuetzt)",
    }

    @staticmethod
    def available() -> bool:
        import shutil as _sh

        return _sh.which("nmap") is not None

    @staticmethod
    def scan(target: str, profile: str = "quick", timeout: int = 180) -> dict:
        import subprocess as _sp
        import xml.etree.ElementTree as _ET

        if not NmapIntegration.available():
            return {
                "error": "nmap nicht installiert (sudo apt install nmap)",
                "target": target,
            }
        args = NmapIntegration.PROFILES.get(profile, NmapIntegration.PROFILES["quick"])
        cmd = ["nmap"] + args + ["-oX", "-", target]
        try:
            r = _sp.run(cmd, capture_output=True, text=True, timeout=timeout)
            if r.returncode != 0 and not r.stdout:
                return {"error": (r.stderr or "nmap-Fehler")[:300], "target": target}
            root = _ET.fromstring(r.stdout)  # noqa: S314
        except (FileNotFoundError, _sp.TimeoutExpired, OSError) as exc:
            return {"error": f"nmap: {exc}", "target": target}
        except _ET.ParseError as exc:
            return {"error": f"XML: {exc}", "target": target}

        hosts = []
        for h in root.findall("host"):
            addr_el = h.find("address")
            host = {
                "ip": addr_el.get("addr") if addr_el is not None else "?",
                "mac": "",
                "vendor": "",
                "hostnames": [],
                "ports": [],
                "os": [],
                "risky": [],
            }
            for a in h.findall("address"):
                if a.get("addrtype") == "mac":
                    host["mac"] = a.get("addr", "")
                    host["vendor"] = a.get("vendor", "")
                    break
            for hn in h.findall(".//hostname"):
                n = hn.get("name")
                if n:
                    host["hostnames"].append(n)
            for p in h.findall(".//port"):
                st = p.find("state")
                if st is None or st.get("state") != "open":
                    continue
                svc = p.find("service")
                port = int(p.get("portid"))
                entry = {
                    "port": port,
                    "proto": p.get("protocol", "tcp"),
                    "service": svc.get("name", "") if svc is not None else "",
                    "version": svc.get("version", "") if svc is not None else "",
                    "product": svc.get("product", "") if svc is not None else "",
                }
                host["ports"].append(entry)
                if port in NmapIntegration.RISKY_PORTS:
                    host["risky"].append(
                        f"{port}/{entry['proto']} — {NmapIntegration.RISKY_PORTS[port]}"
                    )
            for o in h.findall(".//osmatch"):
                name = o.get("name")
                if name:
                    host["os"].append(name)
            hosts.append(host)

        return {"target": target, "profile": profile, "hosts": hosts}

    @staticmethod
    def format_result(res: dict) -> str:
        if "error" in res:
            return f"nmap-Fehler: {res['error']}"
        lines = [f"=== nmap: {res.get('target')} ({res.get('profile')}) ==="]
        for h in res.get("hosts", []):
            lines.append("")
            lines.append(
                f"Host: {h['ip']}  " f"{h.get('mac','')}  {h.get('vendor','')}"
            )
            if h.get("hostnames"):
                lines.append(f"  Hostnames: {', '.join(h['hostnames'])}")
            if h.get("ports"):
                lines.append("  Offene Ports:")
                for p in h["ports"]:
                    extra = " ".join(
                        filter(None, [p.get("product", ""), p.get("version", "")])
                    )
                    lines.append(
                        f"    {p['port']:>5}/{p['proto']:<4} "
                        f"{p['service']:<15} {extra}"
                    )
            if h.get("os"):
                lines.append(f"  OS-Hinweise: {', '.join(h['os'][:3])}")
            if h.get("risky"):
                lines.append("  !! Risiko-Ports:")
                for rp in h["risky"]:
                    lines.append(f"    {rp}")
        return "\n".join(lines)


def _net_diag_cli() -> int:
    """v37-R9: --net-diag."""
    print(NetworkDiagnostics.format_report(NetworkDiagnostics.report()))
    return 0


def _nmap_cli(target: str, profile: str = "quick") -> int:
    """v37-R9: --nmap TARGET."""
    if not NmapIntegration.available():
        print("nmap fehlt. Installieren: sudo apt install nmap")
        return 1
    print(f"nmap-Scan {target} (Profil: {profile}) ...")
    res = NmapIntegration.scan(target, profile)
    print(NmapIntegration.format_result(res))
    return 0


class UnicastDiscovery:
    """v37-R10: Unicast-basierte LAN-Discovery. Funktioniert auch hinter
    VBox-NAT, weil nur Broadcasts blockiert werden, nicht Unicast."""

    TOP_PORTS = [
        21,
        22,
        23,
        25,
        53,
        80,
        110,
        139,
        143,
        443,
        445,
        554,
        587,
        631,
        993,
        995,
        1883,
        3306,
        3389,
        5000,
        5432,
        5900,
        7000,
        8000,
        8008,
        8009,
        8080,
        8200,
        8443,
        8888,
        9100,
        49152,
        50000,
    ]

    def __init__(self, subnet: str | None = None, logger=None):
        self.logger = logger or logging.getLogger("wlan_ultimate.UnicastDiscovery")
        self.subnet = subnet or self._own_subnet()
        self.results: list[dict] = []

    @staticmethod
    def _own_subnet() -> str | None:
        import subprocess as _sp
        import ipaddress as _ip

        try:
            r = _sp.run(
                ["ip", "-4", "route", "show", "default"],
                capture_output=True,
                text=True,
                timeout=3,
            )
            iface = None
            for line in (r.stdout or "").splitlines():
                m = re.search(r"dev\s+(\S+)", line)
                if m:
                    iface = m.group(1)
                    break
            if not iface:
                return None
            r = _sp.run(
                ["ip", "-4", "addr", "show", iface],
                capture_output=True,
                text=True,
                timeout=3,
            )
            m = re.search(r"inet\s+(\d+\.\d+\.\d+\.\d+)/(\d+)", r.stdout or "")
            if not m:
                return None
            net = _ip.ip_interface(f"{m.group(1)}/{m.group(2)}").network
            return str(net)
        except (FileNotFoundError, _sp.TimeoutExpired, OSError, ValueError):
            return None

    def ping(self, ip: str, timeout: float = 1.0) -> bool:
        import subprocess as _sp

        try:
            r = _sp.run(
                ["ping", "-c", "1", "-W", str(int(timeout)), ip],
                capture_output=True,
                timeout=int(timeout) + 1,
            )
            return r.returncode == 0
        except (FileNotFoundError, _sp.TimeoutExpired, OSError):
            return False

    def ping_sweep(
        self, subnet: str | None = None, workers: int = 64, timeout: float = 1.0
    ) -> list[str]:
        import ipaddress as _ip
        import concurrent.futures as _cf

        net = subnet or self.subnet
        if not net:
            return []
        try:
            network = _ip.ip_network(net, strict=False)
        except (ValueError, TypeError):
            return []
        hosts = list(network.hosts())
        if len(hosts) > 512:
            hosts = hosts[:512]
        print(f"[unicast] Ping-Sweep: {len(hosts)} Hosts mit {workers} Workern ...")
        alive: list[str] = []
        with _cf.ThreadPoolExecutor(max_workers=workers) as ex:
            futs = {ex.submit(self.ping, str(h), timeout): str(h) for h in hosts}
            for done, f in enumerate(_cf.as_completed(futs), 1):
                if done % 32 == 0:
                    print(
                        f"    {done}/{len(hosts)} ...  aktiv={len(alive)}", flush=True
                    )
                if f.result():
                    alive.append(futs[f])
        print(f"[unicast] {len(alive)} Hosts antworten auf ICMP.")
        return sorted(alive, key=lambda x: tuple(int(p) for p in x.split(".")))

    def reverse_dns(self, ip: str) -> str | None:
        import socket as _sk

        try:
            _sk.setdefaulttimeout(2.0)
            return _sk.gethostbyaddr(ip)[0]
        except (_sk.herror, _sk.gaierror, OSError):
            return None
        finally:
            _sk.setdefaulttimeout(None)

    def tcp_probe(
        self,
        ip: str,
        ports: list[int] | None = None,
        timeout: float = 0.4,
        workers: int = 32,
    ) -> list[int]:
        import socket as _sk
        import concurrent.futures as _cf

        ports = ports or self.TOP_PORTS
        open_ports: list[int] = []

        def _try(p: int) -> int | None:
            s = _sk.socket(_sk.AF_INET, _sk.SOCK_STREAM)
            s.settimeout(timeout)
            try:
                if s.connect_ex((ip, p)) == 0:
                    return p
            except OSError:
                pass
            finally:
                s.close()
            return None

        with _cf.ThreadPoolExecutor(max_workers=workers) as ex:
            for p in ex.map(_try, ports):
                if p is not None:
                    open_ports.append(p)
        return sorted(open_ports)

    def http_title(self, ip: str, port: int, timeout: float = 2.0) -> str | None:
        import urllib.request as _ur
        import ssl as _ssl

        schemes = ["http", "https"] if port in (443, 8443) else ["http"]
        ctx = _ssl.create_default_context()
        ctx.check_hostname = False
        ctx.verify_mode = _ssl.CERT_NONE
        for scheme in schemes:
            url = f"{scheme}://{ip}:{port}/"
            try:
                req = _ur.Request(  # noqa: S310
                    url,
                    method="GET",
                    headers={"User-Agent": "wlan-ultimate-diag"},
                )
                with _ur.urlopen(  # noqa: S310
                    req, timeout=timeout, context=ctx
                ) as resp:
                    data = resp.read(4096)
                    m = re.search(
                        rb"<title[^>]*>(.*?)</title>", data, re.IGNORECASE | re.DOTALL
                    )
                    if m:
                        return m.group(1).decode("utf-8", "replace").strip()[:100]
                    server = resp.headers.get("Server", "")
                    if server:
                        return f"(Server: {server})"
                    return "(kein Titel)"
            except (_ur.URLError, OSError, ValueError):
                continue
        return None

    def mac_from_arp(self, ip: str) -> str:
        import subprocess as _sp

        try:
            r = _sp.run(
                ["ip", "-j", "neigh", "show", ip],
                capture_output=True,
                text=True,
                timeout=3,
            )
            import json as _json

            data = _json.loads(r.stdout)
            if data:
                return data[0].get("lladdr", "")
        except (FileNotFoundError, _sp.TimeoutExpired, OSError, ValueError):
            pass
        return ""

    def discover(self, deep: bool = False) -> list[dict]:
        """Voller Sweep: Ping → Reverse-DNS → TCP-Probe → HTTP-Titel."""
        own_ips: set[str] = set()
        try:
            import subprocess as _sp
            import json as _json

            r = _sp.run(
                ["ip", "-j", "-4", "addr", "show"],
                capture_output=True,
                text=True,
                timeout=3,
            )
            for iface in _json.loads(r.stdout):
                for a in iface.get("addr_info", []):
                    if a.get("local"):
                        own_ips.add(a["local"])
        except (FileNotFoundError, _sp.TimeoutExpired, OSError, ValueError):
            pass
        alive = self.ping_sweep()
        result: list[dict] = []
        for ip in alive:
            entry: dict = {
                "ip": ip,
                "hostname": None,
                "mac": "",
                "vendor": "",
                "ports": [],
                "http_titles": {},
                "verified": False,
                "is_self": ip in own_ips,
            }
            entry["hostname"] = self.reverse_dns(ip)
            entry["mac"] = self.mac_from_arp(ip)
            if entry["mac"]:
                try:
                    entry["vendor"] = _lookup_oui(entry["mac"])
                except (NameError, AttributeError):
                    pass
            quick_ports = (
                self.tcp_probe(ip)
                if deep
                else self.tcp_probe(ip, ports=[53, 80, 443, 22, 445, 3389])
            )
            entry["ports"] = quick_ports
            for p in quick_ports:
                if p in (80, 443, 8008, 8080, 8443):
                    t = self.http_title(ip, p)
                    if t:
                        entry["http_titles"][p] = t
            entry["verified"] = bool(
                entry["hostname"] or entry["mac"] or entry["http_titles"]
            )
            try:
                _st = get_store()
                if _st is not None:
                    _st.upsert_host(
                        ip=ip,
                        mac=entry.get("mac", ""),
                        vendor=entry.get("vendor", ""),
                        hostname=entry.get("hostname") or "",
                        source="unicast",
                    )
                    for p in entry.get("ports", []):
                        _st.add_port(ip, int(p))
            except (NameError, AttributeError, TypeError, ValueError):
                pass
            result.append(entry)
        self.results = result
        return result

    def format_results(self, results: list[dict] | None = None) -> str:
        results = results or self.results
        if not results:
            return "Keine Hosts gefunden."
        lines = [f"=== LAN-Discovery: {len(results)} Hosts ==="]
        for e in results:
            if e.get("is_self"):
                lines.append("")
                lines.append(f"  [SELF] {e['ip']:<15} (diese VM)")
                continue
            mark = "OK" if e.get("verified") else "??"
            hn = e.get("hostname") or "(kein Reverse-DNS)"
            mac = e.get("mac") or ""
            vendor = e.get("vendor") or ""
            lines.append("")
            lines.append(f"  [{mark}] {e['ip']:<15} {hn}")
            if mac:
                lines.append(f"        MAC: {mac}  {vendor}")
            if e.get("ports"):
                lines.append(f"        Ports: {e['ports']}")
            for p, t in (e.get("http_titles") or {}).items():
                lines.append(f"        HTTP {p}: {t}")
        return "\n".join(lines)


class FritzBoxClient:
    """v37-R10: FritzBox TR-064 API-Client (stdlib only).
    Liest Geraeteliste, externe IP, DSL-Stats.

    Voraussetzung: FritzBox -> Heimnetz -> Netzwerk ->
    'Zugang fuer Anwendungen erlauben' aktivieren und Benutzer anlegen.
    """

    DEFAULT_HOST = "192.168.6.1"
    SOAP_HOSTS = "/upnp/control/hosts"
    SOAP_WANIP = "/upnp/control/wanipconnection1"
    SOAP_DEVINFO = "/upnp/control/deviceinfo"

    def __init__(
        self, host: str | None = None, user: str = "", password: str = "", logger=None
    ):
        self.host = host or self.DEFAULT_HOST
        self.user = user
        self.password = password
        self.logger = logger or logging.getLogger("wlan_ultimate.FritzBoxClient")

    def _build_opener(self):
        """v37-R10cR2: Digest-Auth-Handler fuer FRITZ!Box TR-064."""
        import urllib.request as _ur

        password_mgr = _ur.HTTPPasswordMgrWithDefaultRealm()
        base_url = f"http://{self.host}:49000/"
        password_mgr.add_password(
            None, base_url, self.user or "dslf-config", self.password
        )
        digest = _ur.HTTPDigestAuthHandler(password_mgr)
        basic = _ur.HTTPBasicAuthHandler(password_mgr)
        return _ur.build_opener(digest, basic)

    def _soap(
        self, path: str, service: str, action: str, body: str = "", timeout: float = 5.0
    ) -> str | None:
        import urllib.request as _ur

        envelope = (
            '<?xml version="1.0" encoding="utf-8"?>\n'
            '<s:Envelope xmlns:s="http://schemas.xmlsoap.org/soap/envelope/" '
            's:encodingStyle="http://schemas.xmlsoap.org/soap/encoding/">\n'
            "<s:Body>\n"
            f'<u:{action} xmlns:u="{service}">{body}</u:{action}>\n'
            "</s:Body></s:Envelope>"
        ).encode()
        url = f"http://{self.host}:49000{path}"
        req = _ur.Request(url, data=envelope, method="POST")
        req.add_header("Content-Type", 'text/xml; charset="utf-8"')
        req.add_header("SoapAction", f'"{service}#{action}"')
        try:
            opener = self._build_opener()
            with opener.open(req, timeout=timeout) as resp:
                return resp.read().decode("utf-8", "replace")
        except _ur.HTTPError as he:
            snippet = ""
            try:
                snippet = he.read().decode("utf-8", "replace")[:200]
            except (OSError, ValueError, AttributeError):
                pass
            self.logger.debug(f"[FRITZ] SOAP {action} HTTP {he.code}: {snippet}")
            return None
        except (_ur.URLError, OSError, ValueError) as exc:
            self.logger.debug(f"[FRITZ] SOAP {action}: {exc}")
            return None

    def get_hosts(self) -> list[dict]:
        """Liste aller der FB bekannten Geraete."""
        import xml.etree.ElementTree as _ET

        ns = "urn:dslforum-org:service:Hosts:1"
        r = self._soap(self.SOAP_HOSTS, ns, "GetHostNumberOfEntries")
        if not r:
            return []
        try:
            root = _ET.fromstring(r)  # noqa: S314
            count_el = root.find(".//NewHostNumberOfEntries")
            n = int(count_el.text) if count_el is not None else 0
        except (_ET.ParseError, ValueError, TypeError, AttributeError):
            return []
        print(f"[fritz] FB kennt {n} Geraete.")
        hosts: list[dict] = []
        for i in range(min(n, 200)):
            body = f"<NewIndex>{i}</NewIndex>"
            r = self._soap(self.SOAP_HOSTS, ns, "GetGenericHostEntry", body)
            if not r:
                continue
            try:
                root = _ET.fromstring(r)  # noqa: S314
                entry = {
                    "ip": _txt(root, ".//NewIPAddress"),
                    "mac": _txt(root, ".//NewMACAddress"),
                    "name": _txt(root, ".//NewHostName"),
                    "active": _txt(root, ".//NewActive"),
                    "iface": _txt(root, ".//NewInterfaceType"),
                    "addr": _txt(root, ".//NewAddressSource"),
                }
                if entry["ip"]:
                    try:
                        entry["vendor"] = _lookup_oui(entry["mac"])
                    except (NameError, AttributeError):
                        entry["vendor"] = ""
                hosts.append(entry)
            except (_ET.ParseError, ValueError, TypeError):
                continue
        return hosts

    def get_info(self) -> dict:
        """v37-R10cR2: Geraet-Info (Modell, Firmware, SN)."""
        import xml.etree.ElementTree as _ET

        ns = "urn:dslforum-org:service:DeviceInfo:1"
        r = self._soap(self.SOAP_DEVINFO, ns, "GetInfo")
        if not r:
            return {}
        try:
            root = _ET.fromstring(r)  # noqa: S314
            return {
                "model": _txt(root, ".//NewModelName"),
                "fw": _txt(root, ".//NewSoftwareVersion"),
                "hw": _txt(root, ".//NewHardwareVersion"),
                "serial": _txt(root, ".//NewSerialNumber"),
                "desc": _txt(root, ".//NewDescription"),
            }
        except (_ET.ParseError, ValueError, TypeError):
            return {}

    def get_wan_status(self) -> dict:
        """v37-R10cR2: WAN-Verbindungsstatus."""
        import xml.etree.ElementTree as _ET

        ns = "urn:dslforum-org:service:WANIPConnection:1"
        out: dict = {}
        for action in (
            "GetExternalIPAddress",
            "GetStatusInfo",
            "GetConnectionTypeInfo",
        ):
            r = self._soap(self.SOAP_WANIP, ns, action)
            if not r:
                continue
            try:
                root = _ET.fromstring(r)  # noqa: S314
                for child in root.iter():
                    tag = child.tag.split("}")[-1]
                    if tag.startswith("New") and child.text:
                        out[tag.replace("New", "")] = child.text.strip()
            except (_ET.ParseError, ValueError, TypeError):
                continue
        return out

    def get_external_ip(self) -> str | None:
        import xml.etree.ElementTree as _ET

        ns = "urn:dslforum-org:service:WANIPConnection:1"
        r = self._soap(self.SOAP_WANIP, ns, "GetExternalIPAddress")
        if not r:
            return None
        try:
            root = _ET.fromstring(r)  # noqa: S314
            return _txt(root, ".//NewExternalIPAddress")
        except (_ET.ParseError, ValueError):
            return None

    def format_hosts(self, hosts: list[dict]) -> str:
        if not hosts:
            return (
                "Keine FB-Hosts gelesen. Pruefen: (1) FB-IP korrekt, "
                "(2) TR-064 aktiviert, (3) Benutzer+Passwort gesetzt."
            )
        lines = [f"=== FritzBox-Geraete: {len(hosts)} ==="]
        for h in hosts:
            active = " * " if h.get("active") == "1" else "   "
            lines.append(
                f"{active}{h['ip']:<15} {h.get('mac',''):<18} "
                f"{h.get('name',''):<24} {h.get('vendor','')}"
            )
        return "\n".join(lines)


def _txt(root, path: str) -> str:
    el = root.find(path)
    return (el.text or "").strip() if el is not None else ""


def _scan_lan_cli(subnet: str | None = None, deep: bool = False) -> int:
    """v37-R10: --scan-lan."""
    disc = UnicastDiscovery(subnet=subnet)
    if not disc.subnet:
        print("Kein eigenes Subnetz erkannt. Bitte --scan-subnet angeben.")
        return 1
    print(f"=== LAN-Discovery: {disc.subnet} ===")
    results = disc.discover(deep=deep)
    print(disc.format_results(results))
    return 0


def _fritz_hosts_cli(host: str | None, user: str, password: str) -> int:
    """v37-R10: --fritz-hosts."""
    fb = FritzBoxClient(host=host, user=user, password=password)
    print(f"=== FritzBox: {fb.host} ===")
    ext = fb.get_external_ip()
    if ext:
        print(f"Externe IP: {ext}")
    hosts = fb.get_hosts()
    print(fb.format_hosts(hosts))
    return 0


class HardwareDetector:
    """v37-R10cR2: Hardware- und Software-Status."""

    @staticmethod
    def report() -> str:
        import subprocess as _sp
        import shutil as _sh
        import glob as _glob

        lines = ["=" * 72, "HARDWARE- UND SOFTWARE-STATUS", "=" * 72, ""]
        wlan = []
        try:
            r = _sp.run(["iw", "dev"], capture_output=True, text=True, timeout=3)
            current = None
            for line in (r.stdout or "").splitlines():
                s = line.strip()
                if s.startswith("Interface"):
                    current = {"iface": s.split()[-1], "type": "?"}
                    wlan.append(current)
                elif current is not None:
                    if s.startswith("type"):
                        current["type"] = s.split()[-1]
                    elif s.startswith("txpower"):
                        current["txp"] = s.split()[1]
        except (FileNotFoundError, _sp.TimeoutExpired, OSError):
            pass
        lines.append(f"WLAN-Adapter ({len(wlan)}):")
        for w in wlan:
            lines.append(
                f"  OK  {w['iface']:<10} type={w['type']:<10} " f"tx={w.get('txp','?')}"
            )
        if not wlan:
            lines.append("  --  keine WLAN-Adapter erkannt")
        lines.append("")
        bt_found = False
        for cmd in (["hcitool", "dev"], ["bluetoothctl", "list"]):
            try:
                r = _sp.run(cmd, capture_output=True, text=True, timeout=3)
                for line in (r.stdout or "").splitlines():
                    if "hci" in line.lower() or "controller" in line.lower():
                        lines.append(f"BT-Adapter: {line.strip()}")
                        bt_found = True
                if bt_found:
                    break
            except (FileNotFoundError, _sp.TimeoutExpired, OSError):
                continue
        if not bt_found:
            lines.append("Bluetooth-Adapter (0): -- keine/r erkannt")
            lines.append("      Empfehlung: CSR 4.0 USB-Dongle (~10 EUR)")
        lines.append("")
        gps = (
            _glob.glob("/dev/ttyUSB*")
            + _glob.glob("/dev/ttyACM*")
            + _glob.glob("/dev/gps*")
        )
        lines.append(f"GPS-Empfaenger ({len(gps)}):")
        for g in gps:
            lines.append(f"  OK  {g}")
        if not gps:
            lines.append("  --  keine/r erkannt")
            lines.append("      Empfehlung: u-blox NEO-6M USB (~15-25 EUR)")
        lines.append("")
        tools = [
            "iw",
            "ip",
            "airmon-ng",
            "airodump-ng",
            "aireplay-ng",
            "aircrack-ng",
            "hashcat",
            "hcxdumptool",
            "hcxpcapngtool",
            "kismet",
            "tcpdump",
            "tshark",
            "nmap",
            "ethtool",
            "iwconfig",
            "bluetoothctl",
            "hcitool",
            "gpsd",
            "modprobe",
            "rfkill",
            "nmcli",
            "dmesg",
            "lsusb",
        ]
        found = [t for t in tools if _sh.which(t)]
        missing = [t for t in tools if not _sh.which(t)]
        lines.append(f"Software-Tools: {len(found)}/{len(tools)} vorhanden")
        if missing:
            lines.append(f"  Fehlt: {', '.join(missing)}")
        return "\n".join(lines)


def _hw_status_cli() -> int:
    print(HardwareDetector.report())
    return 0


def _fritz_info_cli(host, user, password) -> int:
    import socket as _sk

    fb = FritzBoxClient(host=host, user=user, password=password)
    print(f"=== FritzBox: {fb.host} ===")
    try:
        s = _sk.socket(_sk.AF_INET, _sk.SOCK_STREAM)
        s.settimeout(2)
        ok = s.connect_ex((fb.host, 49000)) == 0
        s.close()
    except OSError:
        ok = False
    print(f"  Port 49000: {'OFFEN' if ok else 'ZU'}")
    if not ok:
        return 1
    info = fb.get_info()
    if not info:
        print("  Geraet-Info: nicht lesbar (Auth fehlt / TR-064 aus)")
        print("  -> In FB: Heimnetz > Netzwerk > Netzwerkeinstellungen")
        print("     'Zugang fuer Anwendungen erlauben' + Benutzer anlegen")
        return 1
    print("=== Geraet-Info ===")
    for k, v in info.items():
        if v:
            print(f"  {k:<8} {v}")
    return 0


def _fritz_wan_cli(host, user, password) -> int:
    import socket as _sk

    fb = FritzBoxClient(host=host, user=user, password=password)
    print(f"=== FritzBox: {fb.host} ===")
    try:
        s = _sk.socket(_sk.AF_INET, _sk.SOCK_STREAM)
        s.settimeout(2)
        ok = s.connect_ex((fb.host, 49000)) == 0
        s.close()
    except OSError:
        ok = False
    print(f"  Port 49000: {'OFFEN' if ok else 'ZU'}")
    if not ok:
        return 1
    wan = fb.get_wan_status()
    if not wan:
        print("  WAN-Status: nicht lesbar (Auth fehlt?)")
