def _router_normalize_mac(mac: str) -> str:
    """WP-G10c: MAC nach xx:yy:zz:aa:bb:cc normalisieren."""
    t = str(mac or "").strip().replace("-", ":").replace(".", ":")
    if ":" not in t and len(t) == 12:
        t = ":".join(t[i:i+2] for i in range(0, 12, 2))
    parts = [q for q in t.split(":") if q]
    return ":".join(q.zfill(2).lower() for q in parts)


def _router_vendor_from_bssid(bssid: str) -> str:
    """WP-G10c: OUI-Lookup -> Router-Vendor-Key oder ''."""
    mac = _router_normalize_mac(bssid)
    parts = mac.split(":")
    if len(parts) < 3:
        return ""
    return _ROUTER_OUI_MAP.get(":".join(parts[:3]).upper(), "")


def _router_access_cli(vendor: str = "", bssid: str = "") -> int:
    """WP-G10c: --router-access — Admin-Info fuer den EIGENEN Router."""
    key = str(vendor or "").strip().lower()
    if not key and bssid:
        detected = _router_vendor_from_bssid(bssid)
        if detected:
            key = detected
            print(
                f"BSSID {bssid} -> OUI-Lookup ergibt: "
                f"{_ROUTER_RESET_DB[key]['vendor']}"
            )
            print()

    if not key:
        print("Router-Admin-Zugang — Info fuer den EIGENEN Router")
        print("=" * 60)
        print()
        print("Aufruf-Varianten:")
        print("  --router-access --router-vendor fritzbox")
        print("  --router-access --router-bssid 4C:1B:86:xx:xx:xx")
        print()
        print("Verfuegbare Hersteller:")
        for k, v in _ROUTER_RESET_DB.items():
            print(f"  {k:<10}  {v['vendor']}")
        print()
        print("Hinweis: '--router-access' zeigt nur Zugangs-URL,")
        print("Standard-Credentials und Erst-Einrichtung. Fuer Reset-")
        print("Anleitung: '--router-reset-help <vendor>'.")
        return 0

    if key not in _ROUTER_RESET_DB:
        _say(
            f"[router-access] Unbekannter Hersteller: {vendor!r}. "
            f"Verfuegbar: {', '.join(sorted(_ROUTER_RESET_DB))}",
            file=sys.stderr,
        )
        return 1

    r = _ROUTER_RESET_DB[key]
    sep = "=" * 72
    dash = "-" * 72
    print(sep)
    print(f"  Admin-Zugang: {r['vendor']}")
    print(sep)
    print()
    print(dash)
    print("  Admin-Oberflaeche:")
    print(dash)
    print(f"  URL:                 {r['url']}")
    print()
    print(dash)
    print("  Standard-Zugangsdaten (falls nie geaendert):")
    print(dash)
    print(f"  Benutzer:            {r['default_user']}")
    print(f"  Passwort:            {r['default_pass']}")
    print()
    print(dash)
    print("  Erst-Einrichtung nach Reset:")
    print(dash)
    for i, item in enumerate(r["reconfig"], 1):
        print(f"  {i}. {item}")
    print()
    print(dash)
    print("  Wenn Standard-Credentials NICHT funktionieren:")
    print(dash)
    print("  - Geraete-Aufkleber pruefen (Rueckseite/Unterseite)")
    print("  - Ggf. vom Provider gesetztes Passwort erfragen")
    print("  - Wenn Passwort verloren: --router-reset-help <vendor>")
    print()
    print(sep)
    print("  HINWEIS: Diese Info gilt fuer den EIGENEN Router.")
    print("  Kein automatischer Login-Versuch, kein Brute-Force.")
    print(sep)
    return 0


def _generate_psk_cli(words: int = 10, separator: str = "-",
                     count: int = 1, add_number: bool = False,
                     wordfile: str = "") -> int:
    """WP-G10a: --generate-psk — Diceware-Passphrasen.

    Reine lokale Generierung. Kein Netzzugriff. Fuer den Fall,
    dass ein eigenes Netz neu aufgesetzt werden soll und eine
    starke Passphrase benoetigt wird.
    """
    import secrets as _secrets
    import math as _math

    if wordfile:
        try:
            with open(wordfile, encoding="utf-8") as fh:
                word_list = [w.strip() for w in fh.read().splitlines()
                             if w.strip() and not w.startswith("#")]
        except OSError as exc:
            _say(f"[generate-psk] Wortliste nicht lesbar: {exc}",
                 file=sys.stderr)
            return 1
    else:
        word_list = list(_PSK_WORDS)

    if len(word_list) < 32:
        _say(f"[generate-psk] Wortliste zu klein ({len(word_list)}).",
             file=sys.stderr)
        return 1

    words = max(4, min(20, int(words or 10)))
    count = max(1, min(100, int(count or 1)))
    separator = str(separator or "-")[:3]

    bits_per_word = _math.log2(len(word_list))
    total_bits = words * bits_per_word
    if add_number:
        total_bits += _math.log2(1000)

    for _ in range(count):
        chosen = [_secrets.choice(word_list) for _ in range(words)]
        phrase = separator.join(chosen)
        if add_number:
            phrase += separator + f"{_secrets.randbelow(1000):03d}"
        print(phrase)

    _say(
        f"[generate-psk] {count} Passphrase(n) x {words} Woerter, "
        f"Wortliste={len(word_list)}, ~{total_bits:.1f} Bit Entropie",
        file=sys.stderr,
    )
    if total_bits < 60:
        _say(
            "[generate-psk] WARNUNG: < 60 Bit — erhoehe --psk-words.",
            file=sys.stderr,
        )
    return 0


def _pcap_analyze_cli(pcap_path: str = "", out_file: str = "") -> int:
    """WP-F8: --pcap-analyze FILE — tshark-basierte PCAP-Analyse."""
    if not pcap_path:
        _say("[pcap-analyze] Kein --pcap-analyze FILE angegeben.",
             file=sys.stderr)
        return 1

    analyzer = PcapAnalyzer(pcap_path)
    data = analyzer.analyze()

    if not data.get("pcap", {}).get("exists"):
        for e in data.get("errors", []):
            _say(f"[pcap-analyze] {e}", file=sys.stderr)
        return 1

    payload = json.dumps(data, indent=2, default=str, ensure_ascii=False)
    if out_file:
        try:
            with open(out_file, "w", encoding="utf-8") as fh:
                fh.write(payload)
            try:
                os.chmod(out_file, 0o644)
            except OSError:
                pass
            _say(
                f"[pcap-analyze] {data['frames_total']} Frames -> {out_file}",
                file=sys.stderr,
            )
        except OSError as exc:
            _say(f"[pcap-analyze] Schreibfehler: {exc}", file=sys.stderr)
            return 1
    else:
        print(payload)

    for e in data.get("errors", []):
        _say(f"[pcap-analyze] {e}", file=sys.stderr)

    if data.get("anomalies"):
        for a in data["anomalies"]:
            _say(
                f"[pcap-analyze] ANOMALIE {a.get('type')} "
                f"({a.get('severity')}): {a}",
                file=sys.stderr,
            )
    return 0


def _hw_dump_cli(output_path: str = "") -> int:
    """v37-R17: --hw-dump [pfad] - Hardware-Diagnose sammeln.

    Sammelt in EINER Textdatei:
      - Umgebungsinfo (Host, Kernel, Distro, User)
      - USB-Tree + WLAN-Module + DKMS-Status
      - iw dev + iw phy + rfkill
      - dmesg (WLAN-Filter)
      - HardwareScanner-Report (JSON)
      - HardwareVerifier-Report
      - HardwareAdvisor-Audit

    Standard-Pfad: ~/.wlan_ultimate/hw_dump_YYYYMMDD_HHMMSS.txt (0600)
    """
    import platform
    from datetime import datetime as _dt

    parts = []
    sep = "=" * 72
    dash = "-" * 72

    def _section(title):
        parts.append("")
        parts.append(dash)
        parts.append(f"  {title}")
        parts.append(dash)

    def _kv(key, value):
        parts.append(f"  {key:<16} {value}")

    def _run_cmd(cmd, timeout=5):
        try:
            r = subprocess.run(
                cmd, capture_output=True, text=True,
                timeout=timeout, check=False,
            )
            return (r.stdout or "") + (r.stderr or "")
        except (OSError, subprocess.SubprocessError) as e:
            return f"[Fehler: {e}]"

    # Header
    parts.append(sep)
    parts.append("  WLAN Ultimate Security Suite - HARDWARE-DUMP")
    parts.append(sep)
    _kv("Erzeugt:", _dt.now().isoformat(timespec="seconds"))

    # Umgebung
    _section("UMGEBUNG")
    _kv("Hostname:", platform.node())
    _kv("User:", os.environ.get("USER", "?"))
    _kv("Python:", platform.python_version())
    _kv("Kernel:", platform.release())
    _kv("OS:", platform.platform())
    _kv("Distro:", _run_cmd(["cat", "/etc/os-release"]).split("\n")[0:5])
    _kv("EUID:", str(os.geteuid() if hasattr(os, "geteuid") else -1))

    # lsb_release (falls vorhanden)
    try:
        rc, out, _ = HardwareVerifier._run(
            ["lsb_release", "-a"], timeout=3
        )
        if rc == 0 and out:
            _section("LSB_RELEASE")
            for line in out.splitlines():
                parts.append(f"  {line}")
    except Exception:
        pass

    # USB
    _section("USB-GERAETE (lsusb)")
    for line in _run_cmd(["lsusb"]).splitlines():
        parts.append(f"  {line}")

    parts.append("")
    parts.append("USB-TREE (lsusb -t):")
    for line in _run_cmd(["lsusb", "-t"]).splitlines():
        parts.append(f"  {line}")

    # WLAN-Module
    _section("GELADENE WLAN-MODULE")
    for line in _run_cmd(["lsmod"]).splitlines():
        if any(
            kw in line.lower()
            for kw in ("rtl", "mt76", "mt79", "ath9k", "ath10k",
                       "ath11k", "ath12k", "rt2800", "rt73",
                       "iwlwifi", "brcmfmac", "cfg80211",
                       "mac80211", "88xxau", "8187")
        ):
            parts.append(f"  {line}")

    # DKMS
    _section("DKMS-STATUS")
    dkms_out = _run_cmd(["dkms", "status"])
    if "Fehler" not in dkms_out and dkms_out.strip():
        for line in dkms_out.splitlines():
            parts.append(f"  {line}")
    else:
        parts.append("  (dkms nicht verfuegbar oder keine Module)")

    # iw dev
    _section("IW DEV")
    for line in _run_cmd(["iw", "dev"]).splitlines():
        parts.append(f"  {line}")

    # iw reg
    _section("IW REG (Regulatory)")
    for line in _run_cmd(["iw", "reg", "get"]).splitlines()[:15]:
        parts.append(f"  {line}")

    # iw phy pro phy
    _section("IW PHY (Faehigkeiten pro phy)")
    try:
        ifaces = HardwareScanner()._get_wlan_iface_names()
    except Exception:
        ifaces = []
    phy_seen = set()
    for iface in ifaces:
        phy = HardwareVerifier._get_phy(iface)
        if not phy or phy in phy_seen:
            continue
        phy_seen.add(phy)
        parts.append("")
        parts.append(f"  --- {phy} (fuer iface {iface}) ---")
        out = _run_cmd(["iw", "phy", phy, "info"], timeout=8)
        # Nur relevante Zeilen
        want = False
        for line in out.splitlines():
            ls = line.strip()
            if (
                "Supported interface modes" in ls
                or (ls.startswith("*") and want)
                or "Band" in ls
                or "valid interface" in ls.lower()
                or "radar detection" in ls.lower()
                or "software interface modes" in ls.lower()
            ):
                parts.append(f"  {line}")
                want = True
            elif ls.startswith("*") and want:
                parts.append(f"  {line}")
            elif not ls:
                want = False

    # rfkill
    _section("RFKILL")
    for line in _run_cmd(["rfkill", "list"]).splitlines():
        parts.append(f"  {line}")

    # dmesg
    _section("DMESG (WLAN/USB-Filter, letzte 100 Zeilen)")
    dmesg_out = _run_cmd(
        ["bash", "-c",
         "dmesg 2>/dev/null | grep -iE 'wlan|wifi|firmware|usb|"
         "80211|rtl|mt76|ath' | tail -100"],
        timeout=5,
    )
    if dmesg_out.strip():
        for line in dmesg_out.splitlines():
            parts.append(f"  {line}")
    else:
        parts.append("  (leer oder dmesg ohne root nicht lesbar)")

    # HardwareScanner-JSON
    _section("HARDWARE-SCANNER (JSON)")
    try:
        scanner = HardwareScanner()
        report = scanner.full_report()
        json_out = scanner.report_to_json(report, indent=2)
        for line in json_out.splitlines():
            parts.append(f"  {line}")
    except Exception as e:
        parts.append(f"  [Fehler: {str(e)[:200]}]")

    # HardwareVerifier
    _section("HARDWARE-VERIFIKATION")
    try:
        verifier = HardwareVerifier()
        pairs = []
        for a in report.get("wlan_adapters", []):
            usb_id = a.get("usb_id", "")
            claimed = WiFiAdapterCatalog.lookup(usb_id)
            if not claimed:
                claimed = {
                    "model": a.get("catalog_model", a.get("iface", "?")),
                    "monitor": a.get("supports_monitor", False),
                    "injection": a.get("supports_injection", False),
                    "ap_mode": a.get("supports_ap", False),
                    "active_monitor": a.get(
                        "supports_active_monitor", False
                    ),
                    "vif": a.get("supports_vif", False),
                    "driver": a.get("driver", ""),
                }
            pairs.append((a.get("iface", ""), claimed))
        vrep = verifier.verify_all(pairs)
        for line in verifier.format_report(vrep).splitlines():
            parts.append(f"  {line}")
    except Exception as e:
        parts.append(f"  [Fehler: {str(e)[:200]}]")

    # HardwareAdvisor
    _section("HARDWARE-ADVISOR")
    try:
        audit = HardwareAdvisor.audit()
        for line in HardwareAdvisor.format_audit(audit).splitlines():
            parts.append(f"  {line}")
    except Exception as e:
        parts.append(f"  [Fehler: {str(e)[:200]}]")

    parts.append("")
    parts.append(sep)
    parts.append("  ENDE HARDWARE-DUMP")
    parts.append(sep)

    content = "\n".join(parts)

    # Ziel-Pfad
    if not output_path:
        try:
            base = Path.home() / ".wlan_ultimate"
            base.mkdir(parents=True, exist_ok=True, mode=0o700)
        except OSError:
            base = Path.home()
        fname = "hw_dump_" + _dt.now().strftime("%Y%m%d_%H%M%S") + ".txt"
        target = base / fname
    else:
        target = Path(output_path)

    try:
        target.write_text(content, encoding="utf-8")
        try:
            os.chmod(target, 0o600)
        except OSError:
            pass
    except OSError as e:
        print(f"Fehler beim Schreiben: {e}")
        return 1

    size_kb = target.stat().st_size / 1024
    print(f"Hardware-Dump erstellt: {target}")
    print(f"Groesse: {size_kb:.1f} KiB")
    print("")
    print("Diesen Report koennen Sie an Bug-Reports anhaengen.")
    return 0


def _hw_bt_cli() -> int:
    """v37-R16: --hw-bt - Bluetooth-Dongle-Katalog + Live-Status."""
