_LEGACY_SYNC_RAN = False


def _sync_legacy_registries(*, _force: bool = False):
    """Synchronisiert Legacy-Adapter-Registrys mit der SSOT."""
    global _LEGACY_SYNC_RAN
    try:
        if _LEGACY_SYNC_RAN and not _force:
            return
    except NameError:
        pass
    _LEGACY_SYNC_RAN = True
    try:
        cat = WiFiAdapterCatalog
    except NameError:
        return

    try:
        SystemEnvironment.ALFA_USB_IDS = set(cat.alfa_usb_ids())
    except (NameError, AttributeError):
        pass

    try:
        _mod = sys.modules.get(__name__)
        if _mod is not None and hasattr(_mod, "ALFA_USB_IDS"):
            _mod.ALFA_USB_IDS = set(cat.alfa_usb_ids())
    except (NameError, AttributeError):
        pass

    try:
        import sys as _sys

        _mod = _sys.modules.get(__name__)
        if _mod is None:
            return
        _sync_names = {
            "USB_ANTENNA_DB": cat.ANTENNA_INFO,
            "ADAPTER_ANTENNA_DB": cat.ANTENNA_INFO,
            "USB_TO_MODEL": cat.usb_to_model(),
            "USB_TO_CHIPSET": cat.usb_to_chipset(),
            "USB_MODEL_MAP": cat.usb_to_model(),
            "USB_CHIPSET_MAP": cat.usb_to_chipset(),
        }
        for name, value in _sync_names.items():
            if hasattr(_mod, name):
                try:
                    setattr(_mod, name, value)
                except (AttributeError, TypeError):
                    pass
    except (ImportError, NameError, AttributeError):
        pass


def _find_ssot_ranges(lines):
    """v37-R19b: SSOT-Bereiche in w.py.
    Enthält: WiFiAdapterCatalog, HardwareAdvisor, AdapterCompare Klassen
    + alle v37R-Marker-Blöcke (# == v37RXX: ... == ... # end v37RXX ==).
    """
    ranges = []
    for cls_name in (
        "WiFiAdapterCatalog",
        "HardwareAdvisor",
        "AdapterCompare",
        "AdapterVerifier",
    ):
        cls_start = None
        for i, ln in enumerate(lines):
            if ln.startswith(f"class {cls_name}"):
                cls_start = i
                continue
            if cls_start is not None:
                stripped = ln.lstrip()
                if (
                    ln
                    and not ln[0].isspace()
                    and (
                        stripped.startswith("class ")
                        or stripped.startswith("def ")
                        or stripped.startswith("@")
                    )
                ):
                    ranges.append((cls_start, i - 1))
                    cls_start = None
        if cls_start is not None:
            ranges.append((cls_start, len(lines) - 1))
    start = None
    for i, ln in enumerate(lines):
        s = ln.strip()
        if s.startswith("# == v37R") and start is None:
            start = i
        elif start is not None and s.startswith("# end v37R"):
            ranges.append((start, i))
            start = None
    return ranges


def _audit_adapter_registries() -> dict:
    """Durchsucht die eigene w.py-Datei nach USB-ID-Patterns und
    meldet alle Stellen, die Adapter-Daten hart kodiert haben."""
    import re as _re

    try:
        self_path = Path(__file__) if "__file__" in globals() else None
        if self_path is None or not self_path.is_file():
            self_path = Path(sys.argv[0]).resolve()
        text = self_path.read_text(encoding="utf-8", errors="replace")
        lines = text.splitlines()
    except (OSError, NameError):
        return {"error": "w.py nicht lesbar"}

    try:
        usb_ids = WiFiAdapterCatalog.all_usb_ids()
    except NameError:
        usb_ids = set()

    hits: dict = {}
    pat = _re.compile(r'"([0-9a-fA-F]{4}:[0-9a-fA-F]{4})"')
    ssot_ranges = _find_ssot_ranges(lines)

    def _in_ssot(idx0: int) -> bool:
        return any(_a <= idx0 <= _b for _a, _b in ssot_ranges)

    for i, ln in enumerate(lines, start=1):
        if not ln.strip() or ln.lstrip().startswith("#"):
            continue
        if _in_ssot(i - 1):
            continue
        for m in pat.finditer(ln):
            uid = m.group(1).lower()
            if uid in usb_ids:
                hits.setdefault(uid, []).append(i)

    report_lines = []
    report_lines.append("=" * 72)
    report_lines.append("ADAPTER-REGISTRY-AUDIT (v37-R19a)")
    report_lines.append("=" * 72)
    report_lines.append(f"Datei: {self_path}")
    report_lines.append(
        f"Zentrale Registry: WiFiAdapterCatalog " f"({len(usb_ids)} Eintraege)"
    )
    report_lines.append("")
    if not hits:
        report_lines.append("OK: keine Duplikate ausserhalb der SSOT gefunden.")
        return {
            "text": "\n".join(report_lines),
            "hits": {},
            "registry_count": len(usb_ids),
        }

    total = sum(len(v) for v in hits.values())
    report_lines.append(
        f"GEFUNDEN: {len(hits)} Adapter mit "
        f"{total} Fremd-Referenzen ausserhalb der SSOT."
    )
    report_lines.append("")
    for uid in sorted(hits):
        info = WiFiAdapterCatalog.lookup(uid)
        name = info.get("model", uid)
        refs = ", ".join(f"L{n}" for n in hits[uid][:8])
        more = f" (+{len(hits[uid])-8} weitere)" if len(hits[uid]) > 8 else ""
        report_lines.append(f"  {uid}  {name}")
        report_lines.append(f"       Referenzen: {refs}{more}")
    report_lines.append("")
    report_lines.append(
        "Aktion: Bei Bestaetigung koennen diese Referenzen in "
        "R19b entfernt werden. Solange die Runtime-Sync aktiv "
        "ist, sind sie wirkungslos (SSOT gewinnt)."
    )
    return {
        "text": "\n".join(report_lines),
        "hits": hits,
        "registry_count": len(usb_ids),
    }


def _find_duplicates_json(out_path: str = "/tmp/adapter_dups.json") -> int:
    """v37-R19d: findet alle Adapter-Duplikate und speichert sie als JSON.
    Struktur pro Cluster:
      - Zeilenbereich
      - Vorkommende USB-IDs
      - Kontext-Zeilen (10 davor/danach)
      - Erste nicht-leere Codezeile (= Cluster-Identifier)
    """
    import json as _json
    import re as _re

    try:
        self_path = Path(__file__) if "__file__" in globals() else None
        if self_path is None or not self_path.is_file():
            self_path = Path(sys.argv[0]).resolve()
        text = self_path.read_text(encoding="utf-8", errors="replace")
        lines = text.splitlines()
    except (OSError, NameError) as exc:
        print(f"Fehler: {exc}")
        return 1

    try:
        usb_ids = WiFiAdapterCatalog.all_usb_ids()
    except NameError:
        usb_ids = set()

    pat = _re.compile(r'"([0-9a-fA-F]{4}:[0-9a-fA-F]{4})"')

    try:
        ssot_ranges = _find_ssot_ranges(lines)
    except NameError:
        ssot_ranges = []

    def _in_ssot(idx0: int) -> bool:
        return any(_a <= idx0 <= _b for _a, _b in ssot_ranges)

    hit_lines = {}
    for i, ln in enumerate(lines, start=1):
        if not ln.strip() or ln.lstrip().startswith("#"):
            continue
        if _in_ssot(i - 1):
            continue
        found_ids = []
        for m in pat.finditer(ln):
            uid = m.group(1).lower()
            if uid in usb_ids:
                found_ids.append(uid)
        if found_ids:
            hit_lines[i] = {"line": i, "ids": found_ids, "text": ln.rstrip()}

    if not hit_lines:
        print("Keine Duplikate gefunden.")
        try:
            Path(out_path).write_text(
                _json.dumps({"clusters": [], "total": 0}, indent=2), encoding="utf-8"
            )
        except OSError:
            pass
        return 0

    sorted_nums = sorted(hit_lines)
    clusters = []
    cur = [sorted_nums[0]]
    for l in sorted_nums[1:]:
        if l - cur[-1] <= 25:
            cur.append(l)
        else:
            clusters.append(cur)
            cur = [l]
    clusters.append(cur)

    ctx = 12
    out_clusters = []
    for cluster in clusters:
        a = max(1, cluster[0] - ctx)
        b = min(len(lines), cluster[-1] + ctx)
        ids_in_cluster = set()
        for l in cluster:
            ids_in_cluster.update(hit_lines[l]["ids"])
        first_code = ""
        for l in range(cluster[0], min(cluster[-1] + 1, len(lines) + 1)):
            s = lines[l - 1].strip()
            if s and not s.startswith("#"):
                first_code = s[:100]
                break
        out_clusters.append(
            {
                "range": [cluster[0], cluster[-1]],
                "ids": sorted(ids_in_cluster),
                "hit_lines": [hit_lines[l] for l in cluster],
                "context_start": a,
                "context_end": b,
                "first_code": first_code,
                "context_lines": [
                    {"n": i, "text": lines[i - 1]} for i in range(a, b + 1)
                ],
            }
        )

    result = {
        "file": str(self_path),
        "total_lines": len(lines),
        "total_duplicate_references": len(hit_lines),
        "cluster_count": len(out_clusters),
        "ssot_ranges": ssot_ranges,
        "clusters": out_clusters,
    }
    try:
        Path(out_path).write_text(
            _json.dumps(result, indent=2, ensure_ascii=False), encoding="utf-8"
        )
        print(f"JSON-Dump: {out_path}")
        print(f"  {len(hit_lines)} Referenzen in {len(out_clusters)} Clustern")
        print()
        print("Cluster-Übersicht:")
        for i, c in enumerate(out_clusters, 1):
            rng = f"L{c['range'][0]:>6}-L{c['range'][1]:<6}"
            ids_s = ",".join(c["ids"][:3])
            if len(c["ids"]) > 3:
                ids_s += f" (+{len(c['ids'])-3})"
            print(f"  #{i:<2} {rng}  [{ids_s}]  {c['first_code'][:60]}")
        print()
        print("Vollanalyse: cat " + out_path)
        return 0
    except (OSError, ValueError) as exc:
        print(f"Schreibfehler: {exc}")
        return 1


def _find_duplicates_json_cli() -> int:
    return _find_duplicates_json()


def _adapter_registry_dump_cli(around: int = 8) -> int:
    """v37-R19b: Kontext-Dump um echte Duplikat-Referenzen."""
    import re as _re

    try:
        self_path = Path(__file__) if "__file__" in globals() else None
        if self_path is None or not self_path.is_file():
            self_path = Path(sys.argv[0]).resolve()
        text = self_path.read_text(encoding="utf-8", errors="replace")
        lines = text.splitlines()
    except (OSError, NameError) as exc:
        print(f"Fehler: {exc}")
        return 1
    try:
        usb_ids = WiFiAdapterCatalog.all_usb_ids()
    except NameError:
        usb_ids = set()
    pat = _re.compile(r'"([0-9a-fA-F]{4}:[0-9a-fA-F]{4})"')
    ssot_ranges = _find_ssot_ranges(lines)

    def _in_ssot(idx0: int) -> bool:
        return any(_a <= idx0 <= _b for _a, _b in ssot_ranges)

    dup_lines = set()
    for i, ln in enumerate(lines, start=1):
        if not ln.strip() or ln.lstrip().startswith("#"):
            continue
        if _in_ssot(i - 1):
            continue
        for m in pat.finditer(ln):
            if m.group(1).lower() in usb_ids:
                dup_lines.add(i)

    if not dup_lines:
        print("Keine Duplikate ausserhalb der SSOT gefunden.")
        return 0

    sorted_lines = sorted(dup_lines)
    clusters = []
    current = [sorted_lines[0]]
    for l in sorted_lines[1:]:
        if l - current[-1] <= 15:
            current.append(l)
        else:
            clusters.append(current)
            current = [l]
    clusters.append(current)

    out_lines = []
    for cluster in clusters:
        a = max(1, cluster[0] - around)
        b = min(len(lines), cluster[-1] + around)
        out_lines.append("")
        out_lines.append("=" * 72)
        out_lines.append(
            f"CLUSTER: Zeilen {cluster[0]}-{cluster[-1]} "
            f"({len(cluster)} Referenzen)"
        )
        out_lines.append("=" * 72)
        for i in range(a, b + 1):
            marker = " *" if i in dup_lines else "  "
            out_lines.append(f"{marker} L{i:>6}: {lines[i-1]}")

    result = "\n".join(out_lines)
    out_file = Path("/tmp/adapter_registry_dump.txt")
    try:
        out_file.write_text(result, encoding="utf-8")
    except OSError as exc:
        print(f"Schreibfehler: {exc}")
    print(f"Dump: {out_file}")
    print(f"  {len(clusters)} Cluster, {len(dup_lines)} Referenzen")
    print()
    print("Cluster-Übersicht:")
    for idx, c in enumerate(clusters, 1):
        line_preview = lines[c[0] - 1].strip()[:80]
        print(f"  #{idx:<2} L{c[0]:>6}-L{c[-1]:<6}  {line_preview}")
    return 0


def _deep_sync_registries() -> dict:
    """v37-R19c: durchsucht alle Modul-Globals und Klassen-Attribute
    nach USB-ID-Registrys und ersetzt sie mit SSOT-Werten.
    """
    import re as _re
    import sys as _sys

    try:
        cat = WiFiAdapterCatalog
    except NameError:
        return {"error": "WiFiAdapterCatalog fehlt"}
    alfa_ids = set(cat.alfa_usb_ids())
    usb_to_model = dict(cat.usb_to_model())

    usb_pat = _re.compile(r"^[0-9a-fA-F]{4}:[0-9a-fA-F]{4}$")

    stats = {"list_like_patched": 0, "dict_patched": 0, "skipped_ssot": 0, "errors": 0}

    def _is_usb_like(x) -> bool:
        return isinstance(x, str) and bool(usb_pat.match(x))

    def _patch_container(container, label: str) -> None:
        """Patcht ein Container-Objekt (Modul oder Klasse)."""
        if container is cat:
            stats["skipped_ssot"] += 1
            return
        try:
            attrs = dict(vars(container))
        except (TypeError, AttributeError):
            return
        for name, value in attrs.items():
            if name.startswith("__"):
                continue
            if isinstance(value, (list, set, tuple, frozenset)):
                items = list(value)
                usb_like = [x for x in items if _is_usb_like(x)]
                if len(usb_like) >= 2:
                    new_val = set(usb_like) | alfa_ids
                    try:
                        if isinstance(container, type):
                            setattr(container, name, new_val)
                        else:
                            container.__dict__[name] = new_val
                        stats["list_like_patched"] += 1
                    except (AttributeError, TypeError):
                        stats["errors"] += 1
            elif isinstance(value, dict) and len(value) >= 2:
                usb_keys = [k for k in value.keys() if _is_usb_like(k)]
                if len(usb_keys) >= 2:
                    changed = 0
                    for k in usb_keys:
                        if k in usb_to_model:
                            try:
                                old_v = value[k]
                                new_v = usb_to_model[k]
                                if old_v != new_v:
                                    value[k] = new_v
                                    changed += 1
                            except (TypeError, AttributeError):
                                pass
                    if changed:
                        stats["dict_patched"] += 1

    mod = _sys.modules.get(__name__)
    if mod is None:
        return stats

    _patch_container(mod, "module")
    for name, obj in list(vars(mod).items()):
        if isinstance(obj, type) and obj is not cat:
            _patch_container(obj, f"class {name}")

    return stats


def _deep_sync_cli() -> int:
    """v37-R19c: fuehrt Deep-Sync aus und zeigt Statistik."""
    stats = _deep_sync_registries()
    print("=== Deep-Sync-Ergebnis ===")
    for k, v in stats.items():
        print(f"  {k}: {v}")
    return 0


def _adapter_registry_audit_cli() -> int:
    res = _audit_adapter_registries()
    if "text" in res:
        print(res["text"])
        return 0
    print(f"Fehler: {res.get('error', 'unbekannt')}")
    return 1


_DEEP_SYNC_RAN = False


def _run_startup_deep_sync() -> dict:
    """Führt Deep-Sync genau EINMAL aus (idempotent)."""
    global _DEEP_SYNC_RAN
    if _DEEP_SYNC_RAN:
        return {"skipped": "already_ran"}
    _DEEP_SYNC_RAN = True
    try:
        _sync_legacy_registries()
    except (NameError, AttributeError, RuntimeError):
        pass
    try:
        return _deep_sync_registries()
    except (NameError, AttributeError, RuntimeError):
        return {}




@dataclass
class AntennaInfo:
    """Eine WLAN-Antenne mit ihren technischen Daten.

    Anschluss-Konventionen:
      "RP-SMA Male"  -> direkt an Alfa-Adapter (RP-SMA Female) schraubbar
      "RP-SMA Female" -> braucht RP-SMA-Male-Kabel/Adapter
      "N-Male"       -> braucht N-Female-Kupplung oder N-Adapter
      "N-Female"     -> braucht N-Male-Kabel/Adapter
    """
    model: str
    vendor: str = "Alfa"
    gain_2g_dbi: float = 0.0
    gain_5g_dbi: float = 0.0
    gain_6g_dbi: float = 0.0
    antenna_type: str = "omni"  # "omni" | "panel" | "dipole"
    connector: str = "RP-SMA Male"
    indoor: bool = True
    outdoor: bool = False
    length_mm: int = 0
    weight_g: int = 0
    price_eur: float = 0.0
    notes: str = ""
    recommended_for: list = field(default_factory=list)

    def is_dual_band(self) -> bool:
        return self.gain_2g_dbi > 0 and self.gain_5g_dbi > 0

    def is_tri_band(self) -> bool:
        return (
            self.gain_2g_dbi > 0
            and self.gain_5g_dbi > 0
            and self.gain_6g_dbi > 0
        )

    def needs_antenna_adapter(self) -> bool:
        """True, wenn der Anschluss NICHT direkt an Alfa-Adapter passt."""
        return self.connector != "RP-SMA Male"

    def total_gain(self) -> float:
        return self.gain_2g_dbi + self.gain_5g_dbi


